Object.assign(window.TEM8_DICTIONARY, {"o'clock":{"media":{"uk":"media/uk/o_clock_1_gb_1.mp3","us":"media/us/o_clock_1_us_1.mp3"},"oxford":{"phon":"əˈklɒk","pos":"adv.","senses":[{"en":"used with the numbers 1 to 12 when telling the time, to mean an exact hour （","cn":"表示整点）… 点钟"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"…点钟","en":"You use o'clock after numbers from one to twelve to say what time it is. For example, if you say that it is 9 o'clock, you mean that it is nine hours after midnight or nine hours after midday.","ex":{"en":"The trouble began just after ten o'clock last night","cn":"昨晚刚过10点钟麻烦就开始了。"}}]},"examples":[{"en":"He left between five and six o'clock.","cn":"他是五六点钟离开的。"},{"en":"at/after/before eleven o'clock","cn":"十一点整/后/前"}]},"operate":{"oxford":{"phon":"ˈɒpəreɪt","pos":"verb","senses":[{"en":"to work in a particular way","cn":"运转；工作","g":"[intransitive]","lab":"figurative","sc":"machine","ex":{"en":"Most domestic freezers operate at below −18°C.","cn":"多数家用冰柜能制冷到零下 18 摄氏度以下。"}},{"en":"to use or control a machine or make it work","cn":"操作；控制；使运行","g":"[transitive]","sc":"machine","ex":{"en":"What skills are needed to operate this machinery?","cn":"操作这种机器需要什么技能？"}},{"en":"to manage a business, organization or service","cn":"管理一项业务、组织或服务","g":"[transitive]","sc":"business/organization/service","ex":{"en":"The airline currently operates flights to 25 countries.","cn":"这家航空公司目前运营飞往 25 个国家的航班。"}},{"en":"to work, especially in a particular way or from a particular place","cn":"（尤指以某方式或以某地为据点）经营，营业","g":"[intransitive]","sc":"business/organization/service","ex":{"en":"A new late-night service is now operating.","cn":"现在推出一项新的深夜服务。"}},{"en":"to be used or working; to use something or make it work","cn":"（被）使用；（使）运转","g":"[intransitive, transitive]","sc":"system/process","ex":{"en":"The regulation operates in favour of married couples.","cn":"这一规定的实施有利于已婚夫妇。"}},{"en":"to cut open somebody’s body in order to remove a part that has a disease or to repair a part that is damaged","cn":"动手术","g":"[intransitive]","sc":"medical","ex":{"en":"Surgeons operated last night.","cn":"外科医生昨夜做手术了。"}},{"en":"to be involved in military activities in a place","cn":"（在某地）采取军事行动","g":"[intransitive]","sc":"of soldiers","ex":{"en":"Troops are operating from bases in the north.","cn":"部队正从北部基地发动军事行动。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"经营；管理；运营；运作","en":"If you operate a business or organization, you work to keep it running properly. If a business or organization operates, it carries out its work.","ex":{"en":"Until his death in 1986 Greenwood owned and operated an enormous pear orchard.","cn":"到他1986年去世前，格林伍德一直拥有并管理着一片面积广阔的梨园。"}},{"pos":"VERB 动词","cn":"工作；起作用","en":"The way that something operates is the way that it works or has a particular effect.","ex":{"en":"Ceiling and wall lights can operate independently","cn":"吊灯和壁灯可单独开关。"}},{"pos":"V-ERG 及物/不及物动词","cn":"操作，控制，使用（机器、设备等）；（机器等）运转，运行","en":"When you operate a machine or device, or when it operates, you make it work.","ex":{"en":"A massive rock fall trapped the men as they operated a tunnelling machine","cn":"这些工人在操作隧道挖掘机时被大量的落石困住了。"}},{"pos":"VERB 动词","cn":"（对…）动手术","en":"When surgeons operate on a patient in a hospital, they cut open a patient's body in order to remove, replace, or repair a diseased or damaged part.","ex":{"en":"The surgeon who operated on the King released new details of his injuries","cn":"为国王动手术的外科医生通报了其伤势的最新详情。"}},{"pos":"VERB 动词","cn":"（在某一地区）作战，执行任务","en":"If military forces are operating in a particular region, they are in that place in order to carry out their orders.","ex":{"en":"Up to ten thousand Zimbabwean soldiers are operating in Mozambique","cn":"多达1万名津巴布韦士兵正在莫桑比克执行任务。"}}]},"media":{"uk":"media/uk/operate__gb_1.mp3","us":"media/us/operate__us_1.mp3"},"examples":[{"en":"Most domestic freezers operate at below −18 °C.","cn":"多数家用冰柜能制冷到零下 18 摄氏度以下。"},{"en":"The airline operates flights to 25 countries.","cn":"这家航空公司经营飞往 25 个国家的航班。"}]},"order":{"media":{"uk":"media/uk/order__gb_1.mp3","us":"media/us/order__us_1.mp3"},"oxford":{"phon":"ˈɔːdə(r)","pos":"noun","senses":[{"en":"the way in which people or things are placed or arranged in relation to each other","cn":"顺序；次序","g":"[uncountable, countable]","sc":"arrangement","ex":{"en":"The names are listed in alphabetical order.","cn":"姓名是按字母顺序排列的。"}},{"en":"the state of being carefully and neatly arranged","cn":"条理","g":"[uncountable]","sc":"arrangement","ex":{"en":"It was time she put her life in order.","cn":"她到了该好好安排自己生活的时候了。"}},{"en":"the state that exists when people obey laws, rules or authority","cn":"治安；秩序；规矩","g":"[uncountable]","sc":"controlled state","ex":{"en":"The army has been sent to maintain order in the capital.","cn":"军队已被派去维持首都的秩序。"}},{"en":"a request for food or drinks in a restaurant, bar, etc.","cn":"点餐；点单","g":"[countable]","lab":"especially British English","sc":"food/drinks","ex":{"en":"The waiter came to take their orders.","cn":"服务员来给他们点餐。"}},{"en":"food or drinks that you ask for in a restaurant, bar, etc.","cn":"点的餐食","g":"[countable]","sc":"food/drinks","ex":{"en":"The waiter brought my order.","cn":"服务员把我点的餐送来了。"}},{"en":"a request to make or supply goods","cn":"订货；订购；订单","g":"[countable, uncountable]","sc":"goods","ex":{"en":"I would like to place an order for ten copies of this book.","cn":"这本书我想订购十册。"}},{"en":"goods supplied in response to a particular order that somebody has placed","cn":"所订的货物；交付的订货","g":"[countable]","sc":"goods","ex":{"en":"The stationery order has arrived.","cn":"订购的文具到货了。"}},{"en":"something that somebody is told to do by somebody in authority","cn":"指示；命令","g":"[countable]","lab":"informal","sc":"instructions","ex":{"en":"Dogs can be trained to obey orders.","cn":"狗可以训练得听从命令。"}},{"en":"a formal written instruction for somebody to be paid money or to do something","cn":"付款指令（或委托书）；书面指令；汇票","g":"[countable]","sc":"money","ex":{"en":"You can cash the order at any post office.","cn":"你可以在任何一家邮局兑现这张汇票。"}},{"en":"the way that a society, the world, etc. is arranged, with its system of rules and customs","cn":"秩序；结构","g":"[countable, usually singular]","lab":"formal","sc":"system","ex":{"en":"a change in the political and social order","cn":"政治和社会结构的改变"}},{"en":"a social class","cn":"阶级；等级；阶层","g":"[countable, usually plural]","lab":"disapproving or humorous","sc":"social class","ex":{"en":"the lower orders","cn":"底层社会"}},{"en":"a group into which animals, plants, etc. that have similar characteristics are divided, smaller than a class and larger than a family","cn":"（生物分类的）目","g":"[countable]","sc":"biology","ex":{"en":"the order of primates","cn":"灵长目"}},{"en":"a group of people living in a religious community, especially monks or nuns","cn":"（按照一定的规范生活的）宗教团体；（尤指）修会","g":"[countable + singular or plural verb]","sc":"religious community","ex":{"en":"religious orders","cn":"修会"}},{"en":"a group of people who have been given a special honour by a queen, king, president, etc.","cn":"（获国王、女王、总统等）授勋的人；勋位；勋爵士团","g":"[countable + singular or plural verb]","sc":"special honour","ex":{"en":"The Order of the Garter is an ancient order of chivalry.","cn":"嘉德勋位是古老的骑士勋位。"}},{"en":"a badge or ribbon worn by members of an order who have been given a special honour","cn":"勋章；绶带","g":"[countable]","sc":"special honour"},{"en":"a secret society whose members meet for special ceremonies","cn":"（秘密）社团，集团，结社","g":"[countable + singular or plural verb]","sc":"secret society","ex":{"en":"the Ancient Order of Druids","cn":"古德鲁伊特共济会"}},{"en":"to ask for something to eat or drink in a restaurant, bar, etc.","cn":"点（酒菜等）","g":"[transitive, intransitive]","sc":"food/drink","ex":{"en":"I ordered a coffee and a sandwich.","cn":"我点了一杯咖啡和一份三明治。"},"pos":"verb"},{"en":"to ask for goods to be made or supplied; to ask for a service to be provided","cn":"订购；订货；要求提供（服务）","g":"[transitive, intransitive]","sc":"goods/service","ex":{"en":"To order a copy of the report, visit our website.","cn":"如要索取报告副本，请访问我们的网站。"},"pos":"verb"},{"en":"to use your position of authority to tell somebody to do something or say that something must happen","cn":"命令；指挥；要求","g":"[transitive]","lab":"British English also","sc":"give instructions","ex":{"en":"The officer ordered them to fire.","cn":"军官命令他们开火。"},"pos":"verb"},{"en":"to organize or arrange something","cn":"组织；安排；整理","g":"[transitive]","sc":"organize/arrange","ex":{"en":"The list is ordered alphabetically.","cn":"名单是按字母顺序排列的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PHR-CONJ-SUBORD","cn":"为了;以便;目的在于","en":"If you do something in order to achieve a particular thing or in order that something can happen, you do it because you want to achieve that thing.","ex":{"en":"Most schools are extremely unwilling to cut down on staff in order to cut costs.","cn":"大部分学校都很不愿意为减少开支而裁员。"}},{"pos":"PHR-CONJ-SUBORD","cn":"（某人）要想…（必须）…","en":"If someone must be in a particular situation in order to achieve something they want, they cannot achieve that thing if they are not in that situation.","ex":{"en":"We need to get rid of the idea that we must be liked all the time in order to be worthwhile","cn":"我们必须抛弃那种认为要想活得有价值就得始终取悦他人的想法。"}},{"pos":"PHR-CONJ-SUBORD","cn":"（某事必须发生）…才能…","en":"If something must happen in order for something else to happen, the second thing cannot happen if the first thing does not happen.","ex":{"en":"In order for their computers to trace a person's records, they need both the name and address of the individual.","cn":"在他们的电脑上查询个人记录，需要提供被查询人的姓名和地址。"}},{"pos":"VERB 动词","cn":"命令，要求，指示（某人做…）","en":"If a person in authority orders someone to do something, they tell them to do it.","ex":{"en":"Williams ordered him to leave","cn":"威廉斯命令他离开。"}},{"pos":"VERB 动词","cn":"就…下令","en":"If someone in authority orders something, they give instructions that it should be done.","ex":{"en":"The President has ordered a full investigation","cn":"总统已经下令进行全面调查。"}},{"pos":"N-COUNT 可数名词","cn":"命令；要求；指示","en":"If someone in authority gives you an order, they tell you to do something.","ex":{"en":"The activists were shot when they refused to obey an order to halt","cn":"这些激进分子因拒不服从停止前进的命令而被击毙。"}},{"pos":"N-COUNT 可数名词","cn":"（法院的）决议，指令","en":"A court order is a legal instruction stating that something must be done.","ex":{"en":"She has decided not to appeal against a court order banning her from keeping animals","cn":"对于法院禁止她饲养动物的指令，她决定不再上诉。"}},{"pos":"VERB 动词","cn":"点，叫（饭菜等）；订购","en":"When you order something that you are going to pay for, you ask for it to be brought to you, sent to you, or obtained for you.","ex":{"en":"Atanas ordered a shrimp cocktail and a salad","cn":"阿塔纳斯点了一份鸡尾冷虾和一份色拉。"}},{"pos":"N-COUNT 可数名词","cn":"点餐；点单；订购；订单","en":"An order is a request for something to be brought, made, or obtained for you in return for money.","ex":{"en":"British Rail are going to place an order for a hundred and eighty-eight trains.","cn":"英国铁路公司将订购188列火车。"}},{"pos":"N-COUNT 可数名词","cn":"点的餐；订购的货物","en":"Someone's order is what they have asked to be brought, made, or obtained for them in return for money.","ex":{"en":"The waiter returned with their order and Graham signed the bill","cn":"侍者把他们点的餐端了过来，格雷厄姆签了单。"}},{"pos":"PHRASE 短语","cn":"订购中；订制中","en":"Something that is on order at a shop or factory has been asked for but has not yet been supplied.","ex":{"en":"The airlines still have 2,500 new aeroplanes on order.","cn":"这家航空公司尚有2,500架新飞机在订购中。"}},{"pos":"PHRASE 短语","cn":"按照吩咐（或要求）","en":"If you do something to order, you do it whenever you are asked to do it.","ex":{"en":"She now makes wonderful dried flower arrangements to order","cn":"现在她为顾客定做漂亮的干花插花。"}},{"pos":"PHRASE 短语","cn":"遵照命令，按照指示（做）","en":"If you are under orders to do something, you have been told to do it by someone in authority.","ex":{"en":"I am under orders not to discuss his mission or his location with anyone.","cn":"遵照命令，我不能与任何人谈论他执行的任务和他所在的地点。"}},{"pos":"","cn":"","en":"your marching orders→see: ; a tall order→see: ;"},{"pos":"","cn":"","en":"相关词组：order around"},{"pos":"N-UNCOUNT 不可数名词","cn":"顺序；次序","en":"If a set of things are arranged or done in a particular order, they are arranged or done so one thing follows another, often according to a particular factor such as importance.","ex":{"en":"Write down (in order of priority) the qualities you'd like to have","cn":"（按照优先次序）写下你想具有的品质。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"整齐；有条理","en":"Order is the situation that exists when everything is in the correct or expected place, or happens at the correct or expected time.","ex":{"en":"The wish to impose order upon confusion is a kind of intellectual instinct","cn":"想在混乱中理出头绪是一种知性本能。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"秩序；治安","en":"Order is the situation that exists when people obey the law and do not fight or riot.","ex":{"en":"Troops were sent to the islands to restore order last November","cn":"去年11月，军队被派往这些岛屿以恢复秩序。"}},{"pos":"N-SING 单数名词","cn":"（社会的）制度，结构","en":"When people talk about a particular order, they mean the way society is organized at a particular time.","ex":{"en":"The end of the Cold War has produced the prospect of a new world order based on international co-operation","cn":"冷战的结束带来了建立一个以国际合作为基础的世界新秩序的希望。"}},{"pos":"VERB 动词","cn":"组织；安排；整理","en":"The way that something is ordered is the way that it is organized and structured.","ex":{"en":"...a society which is ordered by hierarchy","cn":"按等级划分的社会"}},{"pos":"N-COUNT 可数名词","cn":"种类；类别","en":"If you refer to something of a particular order, you mean something of a particular kind.","ex":{"en":"Another unexpected event, though of quite a different order, occurred one evening in 1973","cn":"1973年的一个夜晚，又发生了一件始料未及的事情，不过这两件事完全不同。"}},{"pos":"N-COUNT 可数名词","cn":"修道会","en":"A religious order is a group of monks or nuns who live according to a particular set of rules.","ex":{"en":"...the Benedictine order of monks.","cn":"本笃会"}},{"pos":"N-COUNT 可数名词","cn":"勋位","en":"People who belong to a particular order have been given a particular honour or rank by the head of their country as a reward for their services or achievements.","ex":{"en":"The highest Order of Knighthood is the Order of the Garter.","cn":"最高骑士勋位是嘉德勋位。"}},{"pos":"CONVENTION 惯用语","cn":"（提醒开会者）安静，肃静","en":"The person in charge of a meeting can say 'Order!' to tell people to stop making a noise."},{"pos":"PHRASE 短语","cn":"整齐；井然有序","en":"If you put or keep something in order, you make sure that it is tidy or properly organized.","ex":{"en":"Now he has a chance to put his life back in order","cn":"现在他有了一个让自己的生活重新步入正轨的机会。"}},{"pos":"PHRASE 短语","cn":"应当发生（或提供）的；自然的；合宜的","en":"If you think something is in order, you think it should happen or be provided.","ex":{"en":"Reforms are clearly in order","cn":"改革势在必行。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（用于数字前）大约，大概","en":"You use in the order of or of the order of when mentioning an approximate figure.","ex":{"en":"They borrowed something in the order of £10 million","cn":"他们借了大约1,000万英镑。"}},{"pos":"PHRASE 短语","cn":"处于良好状态","en":"If something is in good order, it is in good condition.","ex":{"en":"The vessel's safety equipment was not in good order.","cn":"这艘船的安全设备破损失修。"}},{"pos":"PHRASE 短语","cn":"（机器、设备等）处于正常工作状态","en":"A machine or device that is in working order is functioning properly and is not broken.","ex":{"en":"Only half of the spacecraft's six science instruments are still in working order.","cn":"这艘宇宙飞船的6件科学仪器中只有一半还在正常运转。"}},{"pos":"PHRASE 短语","cn":"时下常见的；普遍的；流行的","en":"If a particular way of behaving or doing something is the order of the day, it is very common.","ex":{"en":"These are strange times in which we live, and strange arrangements appear to be the order of the day.","cn":"我们生活在这个光怪陆离的时代，各种奇怪的生活安排如今都司空见惯。"}},{"pos":"PHRASE 短语","cn":"（机器、设备等）出故障，有毛病","en":"A machine or device that is out of order is broken and does not work.","ex":{"en":"Their phone's out of order.","cn":"他们的电话坏了。"}},{"pos":"PHRASE 短语","cn":"令人无法接受的；不得体的；不公平的","en":"If you say that someone or their behaviour is out of order, you mean that their behaviour is unacceptable or unfair.","ex":{"en":"You don't think the paper's a bit out of order in publishing it?","cn":"你不觉得这份报纸发表这篇文章有点不妥吗？"}},{"pos":"","cn":"","en":"to put your house in order→see: ; order of magnitude→see: ;"}]},"examples":[{"en":"All those concerned must work together in order that agreement can be reached on this issue.","cn":"一切有关人员必须通力合作，以便能在这个问题上达成协议。"},{"en":"The argument continued until the chairman called them both to order (= ordered them to obey the formal rules of the meeting).","cn":"争论持续不休，直到主席要求双方遵守议事规则。"}]},"opposing":{"oxford":{"phon":"əˈpəʊzɪŋ","pos":"adjective","senses":[{"en":"playing, fighting, working, etc. against each other","cn":"对立的；相竞争的；对抗的","ex":{"en":"a player from the opposing side","cn":"对方的运动员"}},{"en":"very different from each other","cn":"相反的；极不相同的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（观点、倾向等）对立的，截然相反的","en":"Opposing ideas or tendencies are totally different from each other.","ex":{"en":"I have a friend who has the opposing view and felt that the war was immoral","cn":"我有一位朋友的看法截然不同，他认为这场战争是不道德的。"}},{"pos":"ADJ 形容词","cn":"（群体等）对立的，对抗的","en":"Opposing groups of people disagree about something or are in competition with one another.","ex":{"en":"The Georgian leader said in a radio address that he still favoured dialogue between the opposing sides","cn":"这位格鲁吉亚领导人在广播讲话中称他依然赞成对立双方进行对话。"}}]},"media":{"uk":"media/uk/opposing__gb_1.mp3","us":"media/us/opposing__us_1.mp3"},"examples":[{"en":"It is time for opposing factions to unite and work towards a common goal.","cn":"现在是对立各派联合起来、为共同目标而奋斗的时候了。"},{"en":"a player from the opposing side","cn":"对方的运动员"}],"base":"oppose"},"obvious":{"media":{"uk":"media/uk/obvious__gb_1.mp3","us":"media/us/obvious__us_1.mp3"},"oxford":{"phon":"ˈɒbviəs","pos":"adjective","senses":[{"en":"easy to see or understand","cn":"明显的；显然的；易理解的","ex":{"en":"I know you don't like her but try not to make it so obvious.","cn":"我知道你不喜欢她，但尽量别表现得那么明显。"}},{"en":"that most people would think of or agree to","cn":"公认的；当然的","ex":{"en":"She was the obvious choice for the job.","cn":"她是这一工作的当然人选。"}},{"en":"not interesting, new or showing imagination; unnecessary because it is clear to everyone","cn":"平淡无奇的；无创意的；因显而易见而不必要的","lab":"disapproving","ex":{"en":"The ending was pretty obvious.","cn":"结尾十分平淡。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的；显然的；无疑的","en":"If something is obvious, it is easy to see or understand.","ex":{"en":"...the need to rectify what is an obvious injustice","cn":"矫正明显不公的需要"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不必要的;无新意的；缺乏想象力的","en":"If you describe something that someone says as obvious, you are being critical of it because you think it is unnecessary or shows lack of imagination.","ex":{"en":"There are some very obvious phrases that we all know or certainly should know better than to use.","cn":"我们都知道或是肯定应该知道有些说法已毫无新意，最好避免使用。"}}]},"examples":[{"en":"I may be stating the obvious but without more money the project cannot survive.","cn":"我这话可能多余，但是不投入更多资金，项目就难以为继。"},{"en":"I know you don't like her but try not to make it so obvious.","cn":"我知道你不喜欢她，但尽量别表现得那么明显。"}]},"outweigh":{"oxford":{"phon":"ˌaʊtˈweɪ","pos":"verb","senses":[{"en":"to be greater or more important than something","cn":"重于；大于；超过","ex":{"en":"The advantages far outweigh the disadvantages.","cn":"利远大于弊。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（在重要性、益处、意义等上）重于，大于，超过","en":"If one thing outweighs another, the first thing is of greater importance, benefit, or significance than the second thing.","ex":{"en":"The medical benefits of x-rays far outweigh the risk of having them","cn":"X光在医学上的益处远甚于它带来的风险。"}}]},"media":{"uk":"media/uk/outweigh__gb_1.mp3","us":"media/us/outweigh__us_1.mp3"},"examples":[{"en":"The advantages far outweigh the disadvantages.","cn":"利远大于弊。"},{"en":"The benefits of the scheme outweigh the disadvantages.","cn":"这项计划利大于弊。"}]},"original":{"media":{"uk":"media/uk/original__gb_1.mp3","us":"media/us/original__us_1.mp3"},"oxford":{"phon":"əˈrɪdʒənl","pos":"adjective","senses":[{"en":"existing at the beginning of a particular period, process or activity","cn":"原来的；起初的；最早的","g":"[only before noun]","ex":{"en":"The room still has many of its original features.","cn":"房间还保留着当初的许多特点。"}},{"en":"new and interesting in a way that is different from anything that has existed before; able to produce new and interesting ideas","cn":"首创的；独创的；有独创性的","ex":{"en":"an original idea","cn":"独到的见解"}},{"en":"painted, written, etc. by the artist rather than copied","cn":"原作的；真迹的；非复制的","g":"[usually before noun]","ex":{"en":"an original painting by local artist Graham Tovey","cn":"一幅本土艺术家格雷厄姆·托维的画作原件"}},{"en":"a document, work of art, etc. produced for the first time, from which copies are later made","cn":"原件；正本；原稿；原作","ex":{"en":"This painting is a copy; the original is in Madrid.","cn":"这幅画是复制品，原画在马德里。"},"pos":"noun"},{"en":"a person who thinks, behaves, dresses, etc. in an unusual way","cn":"（思想、行为、衣着等）不同寻常的人，独特的人，怪人","lab":"formal","ex":{"en":"Mark Twain was a true original who possibly did more for American literature than any other writer.","cn":"马克·吐温是一位真正的原创者，他对美国文学的贡献可能比任何其他作家都多。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"起初的；最初的；原先的；原来的","en":"You use original when referring to something that existed at the beginning of a process or activity, or the characteristics that something had when it began or was made.","ex":{"en":"The original plan was to hold an indefinite stoppage","cn":"最初的计划是无限期停工。"}},{"pos":"N-COUNT 可数名词","cn":"原物；原件；原作；原著；原文","en":"If something such as a document, a work of art, or a piece of writing is an original, it is not a copy or a later version.","ex":{"en":"When you have filled in the questionnaire, copy it and send the original to your employer","cn":"填好这份问卷后，复印一份并将原卷交给雇主。"}},{"pos":"ADJ 形容词","cn":"原物的；原件的；原作的；非复制的","en":"An original document or work of art is not a copy.","ex":{"en":"...an original movie poster.","cn":"原版电影海报"}},{"pos":"ADJ 形容词","cn":"新创作的；未发表的；未发行的；未曾演出的","en":"An original piece of writing or music was written recently and has not been published or performed before.","ex":{"en":"...its policy of commissioning original work.","cn":"其委托创作新作品的政策"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"首创的；独创的；新颖的","en":"If you describe someone or their work as original, you mean that they are very imaginative and have new ideas.","ex":{"en":"It is one of the most original works of imagination in the language.","cn":"这是用该语言写成的最具独创性和想象力的作品之一。"}},{"pos":"PHRASE 短语","cn":"以（未经翻译的）原语言","en":"If you read or sing something in the original or, for example, in the original French, you read or sing it in the language it was written in, rather than a translation.","ex":{"en":"He read every book or author it deals with, often in the original","cn":"这方面的每一本书和每一位作家他都读过，而且通常均为原著。"}}]},"examples":[{"en":"an original painting by local artist Graham Tovey","cn":"一幅本土艺术家格雷厄姆 · 托维的绘画创作"},{"en":"I think you should go back to your original plan.","cn":"我认为你应该回头执行你原来的计划。"}]},"oeuvre":{"oxford":{"phon":"ˈɜːvrə","pos":"noun","senses":[{"en":"all the works of a writer, artist, etc.","cn":"（作家、艺术家等的）全部作品","ex":{"en":"Picasso’s oeuvre","cn":"毕加索的全部作品"}}]},"media":{"uk":"media/uk/oeuvre__gb_1.mp3","us":"media/us/oeuvre__us_1.mp3"},"examples":[{"en":"Picasso's oeuvre","cn":"毕加索的全部作品"},{"en":"the oeuvre of Van Gogh","cn":"凡•高的全部画作"}]},"openly":{"media":{"uk":"media/uk/openly__gb_1.mp3","us":"media/us/openly__us_1.mp3"},"oxford":{"phon":"ˈəʊpənli","pos":"adverb","senses":[{"en":"without hiding any feelings, opinions or information","cn":"公开地；毫不隐瞒地","ex":{"en":"Can you talk openly about sex with your parents?","cn":"你可以跟父母敞开谈性的问题吗？"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"公开地；公然地；未加隐瞒地；坦率地","en":"If you do something openly, you do it without hiding any facts or hiding your feelings.","ex":{"en":"We can now talk openly about AIDS which we couldn't before","cn":"现在我们能公开谈论以前讳言不提的艾滋病问题。"}}]},"examples":[{"en":"Can you talk openly about sex with your parents?","cn":"你可以跟父母敞开谈性的问题吗？"},{"en":"The men in prison would never cry openly (= so that other people could see).","cn":"狱中犯人从不当众哭泣。"}]},"oxbridge":{"oxford":{"phon":"ˈɒksbrɪdʒ","pos":"noun","senses":[{"en":"the universities of Oxford and Cambridge, when they are thought of together","cn":"牛津剑桥大学","ex":{"en":"an Oxbridge education","cn":"牛津剑桥的教育"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"牛津大学和剑桥大学","en":"Oxbridge is used to refer to the British universities of Oxford and Cambridge together.","ex":{"en":"Last year Oxbridge graduates accounted for 41% of entrants to the civil service's fast stream to promotion.","cn":"去年加入快速晋职队伍的新公务员中，牛津和剑桥大学的毕业生占了41%。"}}]},"media":{"uk":"media/uk/oxbridge__gb_1.mp3","us":"media/us/oxbridge__us_1.mp3"},"examples":[{"en":"an Oxbridge education","cn":"牛津剑桥的教育"}]},"olives":{"lemma":"olive","media":{"uk":"media/uk/olive__gb_1.mp3","us":"media/us/olive__us_1.mp3"}},"onwards":{"media":{"uk":"media/uk/onwards__gb_1.mp3","us":"media/us/onwards__us_1.mp3"},"oxford":{"phon":"ˈɒnwədz","pos":"adverb","senses":[{"en":"continuing from a particular time","cn":"从（某时）起一直","ex":{"en":"They lived there from the 1980s onwards.","cn":"他们从 20 世纪 80 年代起一直住在那里。"}},{"en":"forward","cn":"向前；前往","lab":"formal","ex":{"en":"We drove onwards towards the coast.","cn":"我们驱车前往海滨。"}}]},"examples":[{"en":"They lived there from the 1980s onwards.","cn":"他们从 1980 年代起一直住在那里。"},{"en":"The pool is open from 7 a.m. onwards.","cn":"游泳池从早上 7 点起开放。"}]},"obsessively":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is obsessed , has an obsession about someone or something","cn":""},{"en":"having an unreasonably strong and continuous interest in someone or something, so that you cannot stop thinking about them and your behaviour is seriously affected","cn":""}]},"examples":[{"en":"an obsessive concern with cleanliness and order","cn":"","src":"ld"},{"en":"I try to stay fit, but I’m not obsessive about it.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obsessively__gb_1.mp3","us":"media/us/obsessively__us_1.mp3"},"oxford":{"phon":"əbˈsesɪvli","pos":"adverb","senses":[{"en":"in a way that shows that you are thinking too much about one particular person or thing, in a way that is not reasonable or normal","cn":"痴迷地；迷恋地；耿耿于怀地","ex":{"en":"obsessively jealous","cn":"妒火中烧"}}]}},"overtook":{"collins":{"senses":[{"pos":"","cn":"","en":"Overtook is the past tense of overtake."}]},"media":{"uk":"media/uk/overtook__gb_1.mp3","us":"media/us/overtook__us_1.mp3"}},"offshore":{"media":{"uk":"media/uk/offshore__gb_1.mp3","us":"media/us/offshore__us_1.mp3"},"oxford":{"phon":"ˌɒfˈʃɔː(r)","pos":"adjective","senses":[{"en":"happening or existing in the sea, not far from the land","cn":"海上的；近海的","ex":{"en":"offshore drilling","cn":"近海钻探"}},{"en":"blowing from the land towards the sea","cn":"向海的；离岸的","ex":{"en":"offshore breezes","cn":"习习陆风"}},{"en":"kept or located in a foreign country that has more generous tax laws than the home country","cn":"离岸的（指设在税制较宽松的境外地区）","lab":"business","ex":{"en":"offshore investments","cn":"境外投资"}},{"en":"to arrange for people in another country to do work for it","cn":"安排另一个国家的人为其工作","ex":{"en":"Thousands of these jobs have been offshored.","cn":"数以千计的此类工作岗位已被外包。"},"pos":"verb"},{"en":"in the sea, not far from the land","cn":"在离陆地不远的海里","ex":{"en":"a ship anchored offshore","cn":"在近海停泊的船"},"pos":"adverb"},{"en":"if the wind is blowing offshore, it is blowing from the land towards the sea","cn":"从陆地吹向海洋","pos":"adverb"},{"en":"in a foreign country that has more generous tax laws than the home country","cn":"在一个税法比本国更宽松的外国","lab":"business","ex":{"en":"profits earned offshore","cn":"境外获取的利润"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"近岸的；近海的","en":"Offshore means situated or happening in the sea, near to the coast.","ex":{"en":"...Britain's offshore oil industry.","cn":"英国的近海石油工业"}},{"pos":"ADJ 形容词","cn":"（风）向海的，离岸的","en":"An offshore wind blows from the land towards the sea.","ex":{"en":"...a strong off-shore wind.","cn":"猛烈的离岸陆风"}},{"pos":"ADJ 形容词","cn":"（投资或公司）设在海外（尤指税制较宽松的岛屿）的,离岸的","en":"Offshore investments or companies are located in a place, usually an island, which has fewer tax regulations than most other countries.","ex":{"en":"The island offers a wide range of offshore banking facilities.","cn":"这座岛上有很多离岸金融机构。"}}]},"examples":[{"en":"a ship anchored offshore","cn":"一艘泊在海上的船"},{"en":"offshore drilling","cn":"近海钻探"}]},"ocher":{"lemma":"ochre"},"owning":{"lemma":"own","media":{"uk":"media/uk/own__gb_1.mp3","us":"media/us/own__us_1.mp3"}},"outdoor":{"media":{"uk":"media/uk/outdoor__gb_1.mp3","us":"media/us/outdoor__us_1.mp3"},"oxford":{"phon":"ˈaʊtdɔː(r)","pos":"adjective","senses":[{"en":"used, happening or located outside rather than in a building","cn":"户外的；室外的","ex":{"en":"outdoor pursuits/recreation/activities","cn":"户外消遣／休闲／活动"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"户外的；室外的；野外的","en":"Outdoor activities or things happen or are used outside and not in a building.","ex":{"en":"If you enjoy outdoor activities, this is the trip for you","cn":"如果你喜欢户外运动，这一旅行很适合你。"}}]},"examples":[{"en":"I'm not really the outdoor type (= I prefer indoor activities).","cn":"我不太喜爱户外活动。"},{"en":"outdoor clothing/activities","cn":"户外穿的衣服/活动"}]},"option":{"media":{"uk":"media/uk/option__gb_1.mp3","us":"media/us/option__us_1.mp3"},"oxford":{"phon":"ˈɒpʃn","pos":"noun","senses":[{"en":"something that you can choose to have or do; the freedom to choose what you do","cn":"可选择的事物；选择；选择权；选择的自由","g":"[countable, uncountable]","ex":{"en":"As I see it, we have two options…","cn":"据我看，我们有两种选择…"}},{"en":"a subject that a student can choose to study, but that they do not have to do","cn":"选修课","g":"[countable]","ex":{"en":"The course offers options in design and computing.","cn":"这一课程开了设计和计算机技术的选修科目。"}},{"en":"the right to buy or sell something at some time in the future","cn":"（未来的）买卖选择权；期权","g":"[countable]","ex":{"en":"share options (= the right to buy shares in a company)","cn":"认股选择权"}},{"en":"one of the choices you can make when using a computer program","cn":"选项；选择","g":"[countable]","lab":"computing","ex":{"en":"Choose the ‘Cut’ option from the Edit menu.","cn":"从编辑菜单上选“剪切”项。"}},{"en":"to buy or sell the right to own or use something at some time in the future","cn":"购买（或出售）…的选择权","ex":{"en":"The novel has been optioned for the screen by his production company.","cn":"这部小说改编成影视作品的权利已经被他的制作公司买下了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"可选择的事物","en":"An option is something that you can choose to do in preference to one or more alternatives.","ex":{"en":"He's argued from the start that America and its allies are putting too much emphasis on the military option","cn":"他从一开始就认为美国及其盟国过于强调军事手段。"}},{"pos":"N-SING 单数名词","cn":"选择；选择权","en":"If you have the option of doing something, you can choose whether to do it or not.","ex":{"en":"Criminals are given the option of going to jail or facing public humiliation","cn":"罪犯可以选择要么坐牢，要么遭受当众羞辱。"}},{"pos":"N-COUNT 可数名词","cn":"（将来的）购买权，出售权；期权","en":"In business, an option is an agreement or contract that gives someone the right to buy or sell something such as property or shares at a future date.","ex":{"en":"Each bank has granted the other an option on 19.9% of its shares.","cn":"两家银行都同意给予对方其19.9%股份的期权。"}},{"pos":"N-COUNT 可数名词","cn":"选修课","en":"An option is one of a number of subjects which a student can choose to study as a part of his or her course.","ex":{"en":"Several options are offered for the student's senior year.","cn":"为毕业班学生开设了几门选修课。"}},{"pos":"PHRASE 短语","cn":"暂不作决定；保留选择权","en":"If you keep your options open or leave your options open, you delay making a decision about something.","ex":{"en":"I am keeping my options open. I have not made a decision on either matter.","cn":"我保留选择权，这两件事我都还没有作出决定。"}},{"pos":"PHRASE 短语","cn":"最容易的选择；最保险的选择","en":"If you take the soft option, you do the thing that is easiest or least likely to cause trouble in a particular situation.","ex":{"en":"We take the soft option. I like to keep the crowd happy because that's what they pay for","cn":"我们决定采取最保险的方案。我希望让观众开心，因为他们就是为这个掏钱的。"}}]},"examples":[{"en":"You can be paid in cash weekly or by cheque monthly: those are the two alternatives.","cn":"你的工资可以按周以现金支取，或按月以支票支取。二者可选其一。"},{"en":"The novel has been optioned for the screen by his production company.","cn":"这部小说改编成影视作品的权利已经被他的制作公司买下了。"}]},"oftentimes":{"media":{"uk":"media/uk/oftentimes__gb_1.mp3","us":"media/us/oftentimes__us_1.mp3"},"oxford":{"phon":"ˈɒfntaɪmz","pos":"adverb","senses":[{"en":"often","cn":"经常"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"常常；经常","en":"If something oftentimes happens, it happens many times or much of the time.","ex":{"en":"Oftentimes, these fossils are not made available to science at all","cn":"科学界常常压根接触不到这些化石。"}}]},"examples":[{"en":"Oftentimes I have to wait more than 20 minutes for a bus.","cn":"我经常得花二十多分钟才等到一辆公共汽车。"}]},"oval":{"media":{"uk":"media/uk/oval__gb_1.mp3","us":"media/us/oval__us_1.mp3"},"oxford":{"phon":"ˈəʊvl","pos":"adjective","senses":[{"en":"like an egg in shape","cn":"椭圆形的；卵形的","ex":{"en":"an oval face","cn":"鹅蛋脸"}},{"en":"an oval shape","cn":"椭圆形；卵形","pos":"noun"},{"en":"a ground for Australian Rules football","cn":"澳大利亚式橄榄球球场","lab":"Australian English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"椭圆形的；卵形的","en":"Oval things have a shape that is like a circle but is wider in one direction than the other.","ex":{"en":"He was a man in his late thirties, with fine, dark hair and a pale oval face.","cn":"他年近四十，头发乌黑亮泽，长着一张苍白的鹅蛋脸。"}}]},"examples":[{"en":"an oval face","cn":"鹅蛋脸"}]},"owns":{"lemma":"own","media":{"uk":"media/uk/own__gb_1.mp3","us":"media/us/own__us_1.mp3"}},"often":{"media":{"uk":"media/uk/often__gb_1.mp3","us":"media/us/often__us_1.mp3"},"oxford":{"phon":"ˈɒfn","pos":"adverb","senses":[{"en":"many times","cn":"时常；常常","ex":{"en":"We often go there.","cn":"我们常去那里。"}},{"en":"in many cases","cn":"往往；大多","ex":{"en":"Old houses are often damp.","cn":"老房子大多都潮湿。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"常常；经常","en":"If something often happens, it happens many times or much of the time.","ex":{"en":"They often spent Christmas at Prescott Hill","cn":"他们经常在普雷斯科特山过圣诞节。"}},{"pos":"ADV 副词","cn":"（用于询问或说明某事发生的频率）（多）常","en":"You use how often to ask questions about frequency. You also use often in reported clauses and other statements to give information about the frequency of something.","ex":{"en":"How often do you brush your teeth?","cn":"你多久刷一次牙？"}},{"pos":"PHRASE 短语","cn":"（有规律地）有时，偶尔","en":"If something happens every so often, it happens regularly, but with fairly long intervals between each occasion.","ex":{"en":"She's going to come back every so often","cn":"她会偶尔回来的。"}},{"pos":"PHRASE 短语","cn":"往往；多半；通常","en":"If you say that something happens as often as not, or more often than not, you mean that it happens fairly frequently, and that this can be considered as typical of the kind of situation you are talking about.","ex":{"en":"Yet, as often as not, they find themselves the target of persecution rather than praise","cn":"然而，他们发现自己往往不是被赞扬而是遭刁难。"}}]},"examples":[{"en":"It is not often that you get such an opportunity.","cn":"你得到这样的机会，可不是常有的事。"},{"en":"All too often the animals die through neglect.","cn":"动物因缺乏照料而死亡的事司空见惯。"}]},"outfitter":{"media":{"uk":"media/uk/outfitter__gb_1.mp3","us":"media/us/outfitter__us_1.mp3"},"oxford":{"phon":"ˈaʊtfɪtə(r)","pos":"noun","senses":[{"en":"a shop that sells men’s clothes or school uniforms","cn":"（出售男装或校服的）服装店","lab":"old-fashioned, British English，，"},{"en":"a shop that sells equipment for camping and other outdoor activities","cn":"户外用品店；露营装备店","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（专门的）服装商店，装备商店","en":"also outfitters. An outfitter or an outfitters is a shop that sells clothes and equipment for a specific purpose.","ex":{"en":"...J. Hepworth, the men's outfitter.","cn":"赫普沃思男装店"}}]}},"organization":{"media":{"uk":"media/uk/organization__gb_1.mp3","us":"media/us/organization__us_1.mp3"},"oxford":{"phon":"ˌɔːɡənaɪˈzeɪʃn","pos":"noun","senses":[{"en":"a group of people who form a business, club, etc. together in order to achieve a particular aim","cn":"组织；团体；机构","g":"[countable]","ex":{"en":"He's the president of a large international organization.","cn":"他是一个大型国际组织的主席。"}},{"en":"the act of making arrangements or preparations for something","cn":"组织工作；筹备工作","g":"[uncountable]","ex":{"en":"I leave most of the organization of these conferences to my assistant.","cn":"我把这些会议的大部分筹备工作留给我的助手。"}},{"en":"the way in which the different parts of something are arranged","cn":"安排；配置；分配","g":"[uncountable]","ex":{"en":"The report studies the organization of labour within the company.","cn":"这个报告研究了公司内部的人力分配问题。"}},{"en":"the quality of being arranged in a neat, careful and logical way","cn":"条理；系统性","g":"[uncountable]","ex":{"en":"She is highly intelligent but her work lacks organization.","cn":"她聪明绝顶，工作却缺乏条理。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"组织；机构；团体","en":"An organization is an official group of people, for example a political party, a business, a charity, or a club.","ex":{"en":"Most of these specialized schools are provided by voluntary organizations.","cn":"这些专业学校大多由志愿组织建立。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"组织；安排；筹备","en":"The organization of an event or activity involves making all the necessary arrangements for it.","ex":{"en":"...the exceptional attention to detail that goes into the organisation of this event","cn":"这次活动的组织筹备中对细节的特别关注"}},{"pos":"N-UNCOUNT 不可数名词","cn":"编排；配置；结构","en":"The organization of something is the way in which its different parts are arranged or relate to each other.","ex":{"en":"I am aware that the organization of the book leaves something to be desired.","cn":"我知道该书的编排还有待改进。"}}]},"examples":[{"en":"I leave most of the organization of these conferences to my assistant.","cn":"我把这些会议的大部分筹备工作留给我的助手。"},{"en":"The report studies the organization of labour within the company.","cn":"这个报告研究了公司内部的人力分配问题。"}]},"overseas":{"media":{"uk":"media/uk/overseas__gb_1.mp3","us":"media/us/overseas__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈsiːz","pos":"adjective","senses":[{"en":"connected with foreign countries, especially those separated from your country by the sea or ocean","cn":"外国的；海外的","ex":{"en":"The firm is expanding into overseas markets.","cn":"该公司正在向海外市场扩张。"}},{"en":"to or in a foreign country, especially those separated from your country by the sea or ocean","cn":"在国外；向海外","ex":{"en":"to live/work/go overseas","cn":"在国外生活／工作；出国"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（在）海外的；（在）国外的","en":"You use overseas to describe things that involve or are in foreign countries, usually across a sea or an ocean.","ex":{"en":"He has returned to South Africa from his long overseas trip.","cn":"他结束了漫长的海外旅行回到南非。"}},{"pos":"ADJ 形容词","cn":"（学生、游客等）来自海外的，来自外国的","en":"An overseas student or visitor comes from a foreign country, usually across a sea or an ocean.","ex":{"en":"Every year nine million overseas visitors come to London.","cn":"每年有900万外国游客来伦敦观光。"}}]},"examples":[{"en":"The product is sold both at home and overseas.","cn":"这个产品行销国内外。"},{"en":"to live/work/go overseas","cn":"在国外生活/工作；出国"}]},"organizes":{"lemma":"organize"},"one-sided":{"oxford":{"phon":"ˌwʌn ˈsaɪdɪd","pos":"adjective","senses":[{"en":"showing only one side of the situation; not balanced","cn":"片面的；偏颇的","lab":"disapproving","ex":{"en":"The press were accused of presenting a very one-sided picture of the issue.","cn":"新闻界被指责对这件事的报道非常片面。"}},{"en":"involving people who have different abilities; involving one person more than another","cn":"实力悬殊的；一边倒的","ex":{"en":"a totally one-sided match","cn":"实力非常悬殊的比赛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不均衡的；一边倒的；悬殊的","en":"If you say that an activity or relationship is one-sided, you think that one of the people or groups involved does much more than the other or is much stronger than the other.","ex":{"en":"The negotiating was completely one-sided","cn":"谈判完全呈一边倒之势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"片面的；偏颇的；不公正的","en":"If you describe someone as one-sided, you are critical of what they say or do because you think it shows that they have considered only one side of an issue or event.","ex":{"en":"The organisation still believes the government is being one sided","cn":"该组织仍然认为政府有失公允。"}}]},"media":{"uk":"media/uk/one_sided_1_gb_1.mp3","us":"media/us/one_sided_1_us_1.mp3"},"examples":[{"en":"The press were accused of presenting a very one-sided picture of the issue.","cn":"新闻界被指责对这件事的报道非常片面。"},{"en":"a one-sided conversation (= in which one person talks most of the time)","cn":"一边倒的交谈"}]},"one-man":{"oxford":{"phon":"ˌwʌn ˈmæn","pos":"adjective","senses":[{"en":"done or controlled by one person only; suitable for one person","cn":"适于一个人的；由一个人操作的","ex":{"en":"a one-man show/business","cn":"独角戏；一个人经营的生意"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"单人表演的","en":"A one-man performance is given by only one man rather than by several people.","ex":{"en":"I saw him do his one-man show in London, which I loved.","cn":"我在伦敦看过他的独角戏，非常喜欢。"}},{"pos":"ADJ 形容词","cn":"一个人经营（或控制）的","en":"A one-man organization, such as a business or type of government, is controlled by one person, rather than by several people.","ex":{"en":"It has grown from a one-man business to a multi-million dollar business with close to $10 million in assets","cn":"它已从一个人经营的生意发展成资产规模近千万、业务额达数百万美元的公司。"}}]},"media":{"uk":"media/uk/one_man_1_gb_1.mp3","us":"media/us/one_man_1_us_1.mp3"},"examples":[{"en":"a one-man show/business","cn":"独角戏；一个人经营的生意"},{"en":"a one-man tent","cn":"单人帐篷"}]},"of":{"media":{"uk":"media/uk/of__gb_1.mp3","us":"media/us/of__us_1.mp3"},"oxford":{"phon":"əv","pos":"preposition","senses":[{"en":"belonging to somebody; relating to somebody","cn":"属于（某人）；关于（某人）","ex":{"en":"a friend of mine","cn":"我的一个朋友"}},{"en":"belonging to something; being part of something; relating to something","cn":"属于（某物）；（某事）部分的；关于（某物）","ex":{"en":"the lid of the box","cn":"盒子盖"}},{"en":"coming from a particular background or living in a place","cn":"出身于（某背景）；住在（某地）","ex":{"en":"a woman of Italian descent","cn":"意大利裔女子"}},{"en":"relating to or showing somebody/something","cn":"关于，反映（某人或某事）","ex":{"en":"a story of passion","cn":"热情洋溢的爱情故事"}},{"en":"used to say what somebody/something is, consists of or contains","cn":"（用于表示性质、组成或涵盖）即，由…组成","ex":{"en":"the city of Dublin","cn":"都柏林市"}},{"en":"used with measurements and expressions of time, age, etc.","cn":"（用于表示计量、时间或年龄等）","lab":"old-fashioned","ex":{"en":"2 kilos of potatoes","cn":"两公斤马铃薯"}},{"en":"used to show somebody/something belongs to a group, often after some, a few, etc.","cn":"（常用在 some、a few 等词语之后，表示人或物的所属）属于…的","ex":{"en":"some of his friends","cn":"他的几位朋友"}},{"en":"used to show the position of something/somebody in space or time","cn":"（表示人或事的时空位置）在，当","lab":"North American English","ex":{"en":"just north of Detroit","cn":"就在底特律以北"}},{"en":"used after nouns formed from verbs. The noun after ‘of’ can be either the object or the subject of the action.","cn":"（用于由动词转化的名词之后，of 之后的名词可以是受动者，也可以是施动者）","ex":{"en":"the arrival of the police (= they arrive)","cn":"警察的到来"}},{"en":"used after some verbs before mentioning somebody/something involved in the action","cn":"（用于某些动词后，后接动作所涉及的人或事）","ex":{"en":"to deprive somebody of something","cn":"剥夺某人的东西"}},{"en":"used after some adjectives before mentioning somebody/something that a feeling relates to","cn":"（用于某些形容词后，后接与感情相关的人或事）因为，由于","ex":{"en":"to be proud of something","cn":"为某事自豪"}},{"en":"used to give your opinion of somebody’s behaviour","cn":"（用于对某人的行为发表看法）","ex":{"en":"It was kind of you to offer.","cn":"感谢你的好意。"}},{"en":"used when one noun describes a second one","cn":"（用于一个名词修饰另一个名词时）","ex":{"en":"Where's that idiot of a boy (= the boy that you think is stupid)?","cn":"那个傻小子在哪儿？"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（用于连接两个名词，其中前者表示后者的特定方面）","en":"You use of to combine two nouns when the first noun identifies the feature of the second noun that you want to talk about.","ex":{"en":"The average age of the women interviewed was only 21.5.","cn":"参加面试的女性平均年龄才21.5岁。"}},{"pos":"PREP 介词","cn":"（用于连接两个名词或名词与现在分词，其中后者对前者进行界定或补充信息）","en":"You use of to combine two nouns, or a noun and a present participle, when the second noun or present participle defines or gives more information about the first noun.","ex":{"en":"Would you say what you felt was a feeling of betrayal?","cn":"你是否觉得有一种被人出卖的感觉？"}},{"pos":"PREP 介词","cn":"（用于指称动作的名词后说明该动作的对象或主体）","en":"You use of after nouns referring to actions to specify the person or thing that is affected by the action or that performs the action. For example, 'the kidnapping of the child' refers to an action affecting a child; 'the arrival of the next train' refers to an action performed by a train.","ex":{"en":"...the reduction of trade union power inside the party.","cn":"党内工会权力的削弱"}},{"pos":"PREP 介词","cn":"（用于指称数量或组群的词和短语后表示计量的对象）","en":"You use of after words and phrases referring to quantities or groups of things to indicate the substance or thing that is being measured.","ex":{"en":"...7.6 litres of pure alcohol.","cn":"7.6升纯酒精"}},{"pos":"PREP 介词","cn":"（用于人或事物的名称后引出其所属或相关的机构或地方）","en":"You use of after the name of someone or something to introduce the institution or place they belong to or are connected with.","ex":{"en":"...the Prince of Wales.","cn":"威尔士亲王"}},{"pos":"PREP 介词","cn":"（用于指称容器的名词后，说明容器及其所含物）","en":"You use of after a noun referring to a container to form an expression referring to the container and its contents.","ex":{"en":"We could all do with a cup of tea","cn":"要是能给我们都来杯茶就好了。"}},{"pos":"PREP 介词","cn":"（用在可数名词后、不可数名词前表示某一单个物品）","en":"You use of after a count noun and before an uncount noun when you want to talk about an individual piece or item.","ex":{"en":"...a blade of grass","cn":"一片草叶"}},{"pos":"PREP 介词","cn":"（表示材料或成分）由…制成（或组成）的","en":"You use of to indicate the materials or things that form something.","ex":{"en":"...local decorations of wood and straw.","cn":"用木头和稻草制成的本地饰品"}},{"pos":"PREP 介词","cn":"（用于名词后表示其为某事物的一部分）","en":"You use of after a noun which specifies a particular part of something, to introduce the thing that it is a part of.","ex":{"en":"...the other side of the square","cn":"广场另一侧"}},{"pos":"PREP 介词","cn":"（用于某些动词后表示动作所涉及的人或事物）关于，由于","en":"You use of after some verbs to indicate someone or something else involved in the action.","ex":{"en":"He'd been dreaming of her","cn":"他一直梦见她。"}},{"pos":"PREP 介词","cn":"（用于某些形容词后表示与情感或特性相关的事物）对，为","en":"You use of after some adjectives to indicate the thing that a feeling or quality relates to.","ex":{"en":"I have grown very fond of Alec","cn":"我越来越喜欢亚力克。"}},{"pos":"PREP 介词","cn":"（用于指称施动者的单词前说明对该动作的看法）出自…，在…一方","en":"You use of before a word referring to the person who performed an action when saying what you think about the action.","ex":{"en":"This has been so nice, so terribly kind of you","cn":"您这么做真是太好心，太令我们感激不尽了。"}},{"pos":"PREP 介词","cn":"（用于描述名词后引出所指的人或事物）","en":"You use of after a noun which describes someone or something, to introduce the person or thing you are talking about.","ex":{"en":"...an awkward, slow-moving giant of a man.","cn":"举止笨拙、行动迟缓的巨人般的男子"}},{"pos":"PREP 介词","cn":"（表示程度）更大/较小程度上的…","en":"If something is more of or less of a particular thing, it is that thing to a greater or smaller degree.","ex":{"en":"Your extra fat may be more of a health risk than you realize","cn":"多余的脂肪对健康的威胁可能比你意识到的要大。"}},{"pos":"PREP 介词","cn":"（表示某人或某事物具有的特点或特性）","en":"You use of to indicate a characteristic or quality that someone or something has.","ex":{"en":"...the worth of their music.","cn":"他们音乐的价值"}},{"pos":"PREP 介词","cn":"（用于be动词后表示某人或某事物具有的特点或特性）","en":"You use of after the verb 'be' to indicate a characteristic or quality that someone or something has.","ex":{"en":"The crisis faced over the next few months is of an entirely different scale","cn":"接下来几个月内将要面临的危机规模将是无法相比的。"}},{"pos":"PREP 介词","cn":"（用于说明数量、价值或年龄）","en":"You use of to specify an amount, value, or age.","ex":{"en":"Last Thursday, Nick announced record revenues of $3.4 billion","cn":"上个星期四，尼克宣布公司收入创下34亿美元的纪录。"}},{"pos":"PREP 介词","cn":"（用于年、月等名词后表示状态或活动的持续时间）","en":"You use of after a noun such as 'month' or 'year' to indicate the length of time that some state or activity continues.","ex":{"en":"...eight bruising years of war","cn":"艰苦卓绝的8年战争"}},{"pos":"PREP 介词","cn":"（表示时间离某一钟点差几分）在…之前","en":"You can use of to say what time it is by indicating how many minutes there are before the hour mentioned.","ex":{"en":"At about a quarter of eight in the evening Joe Urber calls","cn":"大约晚上8点差一刻的时候，乔·乌尔贝尔打来电话。"}}]},"examples":[{"en":"Can't you throw out that old bike of Tommy's?","cn":"难道你就不能把汤米那辆旧自行车给扔掉？"},{"en":"He was cleared of all blame.","cn":"他所受的一切责难都澄清了。"}]},"origin":{"media":{"uk":"media/uk/origin__gb_1.mp3","us":"media/us/origin__us_1.mp3"},"oxford":{"phon":"ˈɒrɪdʒɪn","pos":"noun","senses":[{"en":"the point from which something starts; the cause of something","cn":"起源；源头；起因","ex":{"en":"the origins of life on earth","cn":"地球上生命的起源"}},{"en":"a person’s social and family background","cn":"出身；来历","ex":{"en":"She has risen from humble origins to immense wealth.","cn":"她出身卑微，终成巨富。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"起源；来源；起因；由来","en":"You can refer to the beginning, cause, or source of something as its origin or origins .","ex":{"en":"...theories about the origin of life","cn":"有关生命起源的各种理论"}},{"pos":"N-COUNT 可数名词","cn":"出身；身世；血统","en":"When you talk about a person's origin or origins, you are referring to the country, race, or social class of their parents or ancestors.","ex":{"en":"Thomas has not forgotten his humble origins.","cn":"托马斯没有忘记自己卑微的出身。"}}]},"examples":[{"en":"This particular custom has its origins in Wales.","cn":"这一特殊风俗起源于威尔士。"},{"en":"Most coughs are viral in origin (= caused by a virus).","cn":"咳嗽大多是由病毒引发的。"}]},"owe":{"media":{"uk":"media/uk/owe__gb_1.mp3","us":"media/us/owe__us_1.mp3"},"oxford":{"phon":"əʊ","pos":"verb","senses":[{"en":"to have to pay somebody for something that you have already received or return money that you have borrowed","cn":"欠（债）；欠（账）","lab":"figurative","ex":{"en":"She still owes her father £3 000.","cn":"她还欠她父亲 3 000 英镑。"}},{"en":"to feel that you ought to do something for somebody or give them something, especially because they have done something for you","cn":"欠（情）","ex":{"en":"I owe a debt of gratitude to all my family.","cn":"我很感激我的全家人。"}},{"en":"to exist or be successful because of the help or influence of somebody/something","cn":"归因于；归功于；起源于","ex":{"en":"He owes his success to hard work.","cn":"他的成功是靠勤奋工作。"}},{"en":"to have to obey and support somebody who is in a position of authority or power","cn":"（对位高权重者）忠诚，服从","lab":"formal","ex":{"en":"All serfs owed allegiance to a lord.","cn":"所有农奴都必须效忠领主。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"欠（钱）；欠（债）；欠（账）","en":"If you owe money to someone, they have lent it to you and you have not yet paid it back. You can also say that the money is owing .","ex":{"en":"The company owes money to more than 60 banks","cn":"这家公司欠下60多家银行的债。"}},{"pos":"VERB 动词","cn":"应把…归因（于）；应把…归功（于）","en":"If someone or something owes a particular quality or their success to a person or thing, they only have it because of that person or thing.","ex":{"en":"I always suspected she owed her first job to her friendship with Roger","cn":"我一直怀疑她仗着自己是罗杰的朋友才得到第一份工作。"}},{"pos":"VERB 动词","cn":"欠（情）；感激","en":"If you say that you owe a great deal to someone or something, you mean that they have helped you or influenced you a lot, and you feel very grateful to them.","ex":{"en":"As a professional composer I owe much to Radio 3","cn":"作为一名职业作曲家，我十分感激第三电台。"}},{"pos":"VERB 动词","cn":"应归因；应归功","en":"If you say that something owes a great deal to a person or thing, you mean that it exists, is successful, or has its particular form mainly because of them.","ex":{"en":"The island's present economy owes a good deal to whisky distilling","cn":"该岛当前的经济发展主要归功于蒸馏法酿造威士忌酒行业。"}},{"pos":"VERB 动词","cn":"应该给予（某人感激、尊重、忠诚等）","en":"If you say that you owe someone gratitude, respect, or loyalty, you mean that they deserve it from you.","ex":{"en":"Perhaps we owe these people more respect","cn":"也许我们应该给予这些人更多的尊重。"}},{"pos":"VERB 动词","cn":"应该为（某人做）；有必要为（某人做）","en":"If you say that you owe it to someone to do something, you mean that you should do that thing because they deserve it.","ex":{"en":"I can't go. I owe it to him to stay","cn":"我不能走。看在他的分上我也该留下来。"}},{"pos":"PREP-PHRASE 短语介词","cn":"由于；因为","en":"You use owing to when you are introducing the reason for something.","ex":{"en":"He was out of work owing to a physical injury","cn":"他因为受伤而失业了。"}},{"pos":"","cn":"","en":"the world owes someone a living→see: ;"}]},"examples":[{"en":"You owe it to your staff to be honest with them.","cn":"与下属坦诚相待，这是你对他们应有的态度。"},{"en":"She still owes her father £3 000.","cn":"她还欠她父亲 3 000 英镑。"}]},"opiate":{"oxford":{"phon":"ˈəʊpiət","pos":"noun","senses":[{"en":"a drug made from opium. Opiates are used in medicine to reduce severe pain.","cn":"阿片制剂"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用于镇痛或安眠的）鸦片制剂","en":"An opiate is a drug that contains opium. Opiates are used to reduce pain or to help people to sleep.","ex":{"en":"One woman suffered such severe pain she had to take opiates to control it.","cn":"有一位妇女剧痛难忍，不得不服用鸦片制剂来镇痛。"}},{"pos":"N-COUNT 可数名词","cn":"（使人忽视重要事情的）麻醉品，慰藉物","en":"If you call something an opiate, you disapprove of it because it makes people think less or spend less time on important activities.","ex":{"en":"...the opiate of mass entertainment","cn":"起到麻痹作用的大众娱乐"}}]},"media":{"uk":"media/uk/opiate__gb_1.mp3","us":"media/us/opiate__us_1.mp3"},"examples":[{"en":"Hollywood movies were seen as an opiate for the people.","cn":"好莱坞影片曾被视为人们的精神鸦片。"}]},"organized":{"media":{"uk":"media/uk/organized__gb_1.mp3","us":"media/us/organized__us_1.mp3"},"oxford":{"phon":"ˈɔːɡənaɪzd","pos":"adjective","senses":[{"en":"involving large numbers of people who work together to do something in a way that has been carefully planned","cn":"有组织的；系统的","g":"[only before noun]","ex":{"en":"an organized body of workers","cn":"一个有组织的工人团体"}},{"en":"arranged or planned well or in the way mentioned","cn":"有条理的；安排妥当的；安排得…的","ex":{"en":"a carefully organized campaign","cn":"精心策划的运动"}},{"en":"able to plan your work, life, etc. well and in an efficient way","cn":"有条理的；有效率的","ex":{"en":"a very organized person","cn":"很有条理的人"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有组织的；系统的","en":"An organized activity or group involves a number of people doing something together in a structured way, rather than doing it by themselves.","ex":{"en":"...organised groups of art thieves.","cn":"有组织的艺术品盗窃团伙"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）有条理的，高效的","en":"Someone who is organized plans their work and activities efficiently.","ex":{"en":"These people are very efficient, very organized and excellent time managers.","cn":"这些人做事效率很高，井井有条，并且十分善于管理时间。"}}]},"examples":[{"en":"organized religion (= traditional religion followed by large numbers of people who obey a fixed set of rules)","cn":"组织严密的传统宗教信仰"},{"en":"Isn't it time you started to get organized?","cn":"你该提高点效率了吧？"}],"base":"organize"},"oaks":{"lemma":"oak","media":{"img":["media/pic/deciduous_trees_comp.jpg","media/thumb/oak.jpg"],"uk":"media/uk/oak__gb_1.mp3","us":"media/us/oak__us_1.mp3"}},"overtime":{"media":{"uk":"media/uk/overtime__gb_1.mp3","us":"media/us/overtime__us_1.mp3"},"oxford":{"phon":"ˈəʊvətaɪm","pos":"noun","senses":[{"en":"time that you spend working at your job after you have worked the normal hours","cn":"加班；加班的时间","lab":"British English","ex":{"en":"to do/work overtime","cn":"加班"}},{"en":"the money somebody earns for doing overtime","cn":"加班费","ex":{"en":"They pay $150 a day plus overtime.","cn":"他们支付每天 150 美元的报酬，外加加班费。"}},{"en":"a set period of time that is added to the end of a sports game, etc., if there is no winner at the end of the normal period","cn":"（体育比赛等的）加时，加时赛","lab":"North American English","ex":{"en":"The game went into overtime.","cn":"比赛进入了加时赛。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"加班；加班时间","en":"Overtime is time that you spend doing your job in addition to your normal working hours.","ex":{"en":"He would work overtime, without pay, to finish a job","cn":"他会为了完成工作无偿加班。"}},{"pos":"PHRASE 短语","cn":"投入全力；热情高涨","en":"If you say that someone is working overtime to do something, you mean that they are using a lot of energy, effort, or enthusiasm trying to do it.","ex":{"en":"We had to battle very hard and our defence worked overtime to keep us in the game","cn":"我们不得不奋力搏杀；为保证我们不被淘汰出局，防守队员拼尽了全力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（体育比赛中为决胜负而延长的）加时赛","en":"Overtime is an additional period of time that is added to the end of a sports match in which the two teams are level, as a way of allowing one of the teams to win.","ex":{"en":"Denver had won the championship by defeating the Cleveland Browns 23-20 in overtime.","cn":"丹佛队在加时赛中以23比20击败克利夫兰布朗队夺得冠军。"}}]},"examples":[{"en":"They pay $150 a day plus overtime.","cn":"他们支付每天 150 元的报酬，外加加班费。"},{"en":"There was nothing to worry about. It was just her imagination working overtime.","cn":"没什么可担心的。那只是她的想像力太活跃了。"}]},"olympics":{"lemma":"olympic","media":{"uk":"media/uk/olympic__gb_1.mp3","us":"media/us/olympic__us_1.mp3"}},"overshadow":{"oxford":{"phon":"ˌəʊvəˈʃædəʊ","pos":"verb","senses":[{"en":"to make somebody/something seem less important, or successful","cn":"使显得逊色；使黯然失色","ex":{"en":"He had always been overshadowed by his elder sister.","cn":"他与他姐姐相比总是相形见绌。"}},{"en":"to make an event less pleasant than it should be","cn":"使扫兴；使蒙上阴影","ex":{"en":"News of the accident overshadowed the day's events.","cn":"出事的消息给这一天的活动蒙上了阴影。"}},{"en":"to throw a shadow over something","cn":"掩盖；遮蔽","ex":{"en":"The garden is overshadowed by tall trees.","cn":"花园中大树浓荫密布。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给…蒙上阴影；使扫兴","en":"If an unpleasant event or feeling overshadows something, it makes it less happy or enjoyable.","ex":{"en":"Fears for the President's safety could overshadow his peace-making mission","cn":"对总统安全的担忧可能会给他的调解使命蒙上阴影。"}},{"pos":"VERB 动词","cn":"使黯然失色；使相形见绌；使显得无足轻重","en":"If you are overshadowed by a person or thing, you are less successful, important, or impressive than they are.","ex":{"en":"Hester is overshadowed by her younger and more attractive sister.","cn":"赫斯特在她那年轻而且姿色更胜一筹的妹妹面前黯然失色。"}},{"pos":"VERB 动词","cn":"（楼房、树木、大型建筑物等）遮蔽，遮挡","en":"If one building, tree, or large structure overshadows another, it stands near it, is much taller than it, and casts a shadow over it.","ex":{"en":"He also designed one of the Edinburgh University towers that overshadows George Square","cn":"他还设计了爱丁堡大学一座投影于乔治广场的塔楼。"}}]},"media":{"uk":"media/uk/overshadow__gb_1.mp3","us":"media/us/overshadow__us_1.mp3"},"examples":[{"en":"News of the accident overshadowed the day's events.","cn":"出事的消息给这一天的活动蒙上了阴影。"},{"en":"He had always been overshadowed by his elder sister.","cn":"他与他姐姐相比总是相形见绌。"}]},"organic":{"media":{"uk":"media/uk/organic__gb_1.mp3","us":"media/us/organic__us_1.mp3"},"oxford":{"phon":"ɔːˈɡænɪk","pos":"adjective","senses":[{"en":"produced or practised without using artificial chemicals","cn":"有机的；不使用化肥的；绿色的","ex":{"en":"organic cheese/vegetables/wine, etc.","cn":"有机奶酪、蔬菜、酒等"}},{"en":"produced by or from living things","cn":"有机物的；生物的","ex":{"en":"Improve the soil by adding organic matter.","cn":"加入有机物以改良土壤。"}},{"en":"relating to chemical compounds that contain carbon and mainly or ultimately come from living things","cn":"（化合物）有机的，含碳的","lab":"chemistry","ex":{"en":"organic compounds","cn":"有机化合物"}},{"en":"connected with the organs of the body","cn":"器官的；器质性的；官能的","lab":"specialist","ex":{"en":"organic disease","cn":"器质性疾病"}},{"en":"consisting of different parts that are all connected to each other","cn":"有机的；统一的；关联的","lab":"formal","ex":{"en":"the view of society as an organic whole","cn":"视社会为一有机体的观点"}},{"en":"happening in a slow and natural way, rather than suddenly","cn":"逐渐的；演进的；自然的","lab":"formal","ex":{"en":"the organic growth of foreign markets","cn":"国外市场的逐步发展"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有机的；绿色的；无农害的；不使用化肥的","en":"Organic methods of farming and gardening use only natural animal and plant products to help the plants or animals grow and be healthy, rather than using chemicals.","ex":{"en":"Organic farming is expanding everywhere.","cn":"有机农业正在各地迅速发展起来。"}},{"pos":"ADJ 形容词","cn":"生物体的；有机体的","en":"Organic substances are of the sort produced by or found in living things.","ex":{"en":"Incorporating organic material into chalky soils will reduce the alkalinity.","cn":"在白垩质土壤中添加有机物可降低其碱性。"}},{"pos":"ADJ 形容词","cn":"（变化或发展）逐渐的，自然的，演进的","en":"Organic change or development happens gradually and naturally rather than suddenly.","ex":{"en":"...to manage the company and supervise its organic growth.","cn":"经营公司并指导其逐步发展"}},{"pos":"ADJ 形容词","cn":"（社群或结构）有机的，统一的，不可分割的","en":"If a community or structure is an organic whole, each part of it is necessary and fits well with the other parts.","ex":{"en":"City planning treats the city as a unit, as an organic whole.","cn":"城市规划将城市视为一个单位，一个有机的整体。"}}]},"examples":[{"en":"Doctors could find nothing organically wrong with her.","cn":"医生找不出她的器官有什么毛病。"},{"en":"The organization should be allowed to develop organically.","cn":"应该让这个组织逐步发展。"}]},"opening":{"media":{"uk":"media/uk/opening__gb_1.mp3","us":"media/us/opening__us_1.mp3"},"oxford":{"phon":"ˈəʊpənɪŋ","pos":"noun","senses":[{"en":"a space or hole that somebody/something can pass through","cn":"孔；洞；缺口","g":"[countable]","ex":{"en":"We could see the stars through an opening in the roof.","cn":"我们从屋顶的小洞能看见星星。"}},{"en":"the beginning or first part of something","cn":"开始；开端","g":"[countable, usually singular]","ex":{"en":"The movie has an exciting opening.","cn":"电影的开头非常刺激。"}},{"en":"a ceremony to celebrate the start of a public event or the first time a new building, road, etc. is used","cn":"开幕式；落成典礼","g":"[countable, usually singular]","ex":{"en":"the official opening of the new hospital","cn":"新建医院的落成典礼"}},{"en":"the act or process of making something open or of becoming open","cn":"开；开放；展开","g":"[countable, uncountable]","ex":{"en":"the opening of a flower","cn":"花朵的绽放"}},{"en":"a job that is available","cn":"空缺的职位","g":"[countable]","ex":{"en":"There are several openings in the sales department.","cn":"销售部有几个空缺。"}},{"en":"a good opportunity for somebody","cn":"良机","g":"[countable]","ex":{"en":"Winning the competition was the opening she needed for her career.","cn":"在这次比赛中获胜是她未来事业发展的良好开端。"}},{"en":"part of a piece of clothing that is made to open and close so that it can be put on easily","cn":"开襟；开口","g":"[countable]","ex":{"en":"The skirt has a side opening.","cn":"这裙子是侧面开衩的。"}},{"en":"first; beginning","cn":"开始的；开篇的；第一","ex":{"en":"his opening remarks","cn":"他的开场白"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开始的;开端的;开场的","en":"The opening event, item, day, or week in a series is the first one.","ex":{"en":"They returned to take part in the season's opening game.","cn":"他们回来参加本赛季的开幕赛。"}},{"pos":"N-COUNT 可数名词","cn":"开始；开端；开场","en":"The opening of something such as a book, play, or concert is the first part of it.","ex":{"en":"The opening of the scene depicts Akhnaten and his family in a moment of intimacy.","cn":"这幕戏的开场描绘了埃及法老阿肯那顿和他的家人其乐融融的情景。"}},{"pos":"N-COUNT 可数名词","cn":"孔；洞；缺口","en":"An opening is a hole or empty space through which things or people can pass.","ex":{"en":"He squeezed through a narrow opening in the fence.","cn":"他从围栏上的狭窄缺口里挤了过去。"}},{"pos":"N-COUNT 可数名词","cn":"（林中）空地","en":"An opening in a forest is a small area where there are no trees or bushes.","ex":{"en":"I glanced down at the beach as we passed an opening in the trees.","cn":"我们经过一块林中空地时，我往下扫了一眼海滩。"}},{"pos":"N-COUNT 可数名词","cn":"有利机会；机遇","en":"An opening is a good opportunity to do something, for example to show people how good you are.","ex":{"en":"Her capabilities were always there; all she needed was an opening to show them.","cn":"她一直都很有能力；她需要的只是一次展示才华的机会。"}},{"pos":"N-COUNT 可数名词","cn":"（职位的）空缺","en":"An opening is a job that is available.","ex":{"en":"We don't have any openings now, but we'll call you if something comes up.","cn":"我们现在没有职位空缺，一旦有的话我们会给你打电话。"}}]},"examples":[{"en":"Winning the competition was the opening she needed for her career.","cn":"在这次比赛中获胜是她未来事业发展的良好开端。"},{"en":"Late opening of supermarkets is common in Britain now.","cn":"现在超市营业至很晚在英国司空见惯。"}],"base":"open"},"offence":{"oxford":{"phon":"əˈfens","pos":"noun","senses":[{"en":"an illegal act","cn":"违法行为；犯罪；罪行","g":"[countable]","ex":{"en":"a criminal/serious/minor/sexual offence","cn":"刑事罪；重罪；轻罪；性犯罪"}},{"en":"the feeling of being upset or angry at something that somebody has said or done","cn":"（某人的言行导致的）冒犯，不快，反感","g":"[uncountable]","ex":{"en":"The photo may cause offence to some people.","cn":"这张照片可能会引起一些人的反感。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"违法行为；罪行","en":"An offence is a crime that breaks a particular law and requires a particular punishment.","ex":{"en":"Thirteen people have been charged with treason — an offence which can carry the death penalty","cn":"13人被控犯有叛国罪——一种可处死刑的罪行。"}},{"pos":"N-VAR 可变名词","cn":"冒犯；得罪","en":"Offence or an offence is behaviour which causes people to be upset or embarrassed.","ex":{"en":"The book might be published without creating offense","cn":"出版这本书可能不会引起人们的反感。"}},{"pos":"N-SING 单数名词","cn":"（体育运动中的）进攻队，进攻方","en":"In sports such as American football or basketball, the offense is the team which has possession of the ball and is trying to score.","ex":{"en":"Between plays the coach was talking to the offense in the huddle.","cn":"中场时，这位教练对围拢一圈的进攻队员进行战术指导。"}},{"pos":"PHRASE 短语","cn":"冒犯；得罪；惹恼","en":"If you cause offence or give offence to someone, you say or do something rude which upsets or embarrasses them.","ex":{"en":"It says the photograph is likely cause distress and offence to the public","cn":"上面说这张照片可能引起公众的忧虑和反感。"}},{"pos":"CONVENTION 惯用语","cn":"别见怪；无冒犯之意","en":"Some people say 'no offence' to make it clear that they do not want to upset you, although what they are saying may seem rather rude.","ex":{"en":"Dad, you need a bath. No offence.","cn":"爸爸，别见怪，不过你该洗澡了。"}},{"pos":"PHRASE 短语","cn":"（常指不必要地）(对…)生气，(因…)见怪","en":"If someone takes offence at something you say or do, they feel upset, often unnecessarily, because they think you are being rude to them.","ex":{"en":"She never takes offence at anything","cn":"什么事都不会让她生气。"}}]},"media":{"uk":"media/uk/offence__gb_1.mp3","us":"media/us/offence__us_1.mp3"},"examples":[{"en":"No offence, but I'd really like to be on my own.","cn":"我无意冒犯，但我确实想自己一个人待着。"},{"en":"The photo may cause offence to some people.","cn":"这张照片可能会引起一些人的反感。"}]},"organizational":{"media":{"uk":"media/uk/organizational__gb_1.mp3","us":"media/us/organizational__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"组织的；安排的；筹备的","en":"Organizational abilities and methods relate to the way that work, activities, or events are planned and arranged.","ex":{"en":"Evelyn's excellent organisational skills were soon spotted by her employers","cn":"伊夫琳出色的组织能力很快就被老板发现。"}},{"pos":"ADJ 形容词","cn":"（组织或机构）结构的","en":"Organizational means relating to the structure of an organization.","ex":{"en":"The police now recognise that big organisational changes are needed.","cn":"警方现在意识到需要进行大幅度的机构调整。"}},{"pos":"ADJ 形容词","cn":"有关组织（或机构）的","en":"Organizational means relating to organizations, rather than individuals.","ex":{"en":"This problem needs to be dealt with at an organizational level","cn":"这个问题需要在机构层面上解决。"}}]},"examples":[{"en":"organizational change","cn":"组织上的变化"},{"en":"organizational skills","cn":"组织技巧"}],"oxford":{"phon":"ˌɔːɡənaɪˈzeɪʃənl","pos":"adjective","senses":[{"en":"connected with the way in which the different parts of something are arranged; connected with an organization","cn":"安排的；配置的；组织的；团体的","ex":{"en":"organizational changes within the party","cn":"党内组织结构的变化"}},{"en":"having or showing the ability to arrange or organize things well","cn":"有组织能力的","ex":{"en":"Candidates will require good organizational skills.","cn":"候选人需要有良好的组织能力。"}}]}},"ourselves":{"media":{"uk":"media/uk/ourselves__gb_1.mp3","us":"media/us/ourselves__us_1.mp3"},"oxford":{"phon":"ɑːˈselvz","pos":"pronoun","senses":[{"en":"the reflexive form of we; used when you and another person or other people together cause and are affected by an action","cn":"（we 的反身形式）我们自己","ex":{"en":"We shouldn't blame ourselves for what happened.","cn":"我们不应该为发生的事责怪自己。"}},{"en":"used to emphasize we or us; sometimes used instead of these words","cn":"（用于强调或代替 we 或 us）我们自己，亲自","ex":{"en":"We've often thought of going there ourselves.","cn":"我们常想亲自到那里去一趟。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"我们自己","en":"You use ourselves to refer to yourself and one or more other people as a group.","ex":{"en":"We sat round the fire to keep ourselves warm","cn":"我们围坐在火边取暖。"}},{"pos":"PRON-REFL 反身代词","cn":"（泛指）我们自己，人们自己（当主语和宾语为同一群人时，用作动词或介词的宾语）","en":"A speaker or writer sometimes uses ourselves to refer to people in general. Ourselves is used as the object of a verb or preposition when the subject refers to the same people.","ex":{"en":"We all know that when we exert ourselves our heart rate increases.","cn":"我们都知道太卖命了会导致心跳加速。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于强调第一人称复数主语；在比较正式的英语中，有时代替 us 作动词或介词的宾语以示强调）我们自己，我们本人","en":"You use ourselves to emphasize a first person plural subject. In more formal English, ourselves is sometimes used instead of 'us' as the object of a verb or preposition, for emphasis.","ex":{"en":"Others are feeling just the way we ourselves would feel in the same situation","cn":"别人此时的感受和我们自己在同样的情形下时没什么两样。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"我们自己;我们亲自","en":"If you say something such as 'We did it ourselves', you are indicating that something was done by you and a particular group of other people, rather than anyone else.","ex":{"en":"We villagers built that ourselves, we had no help from anyone.","cn":"那是我们村民自己修建的，没有依靠任何人的帮助。"}}]},"examples":[{"en":"We shouldn't blame ourselves for what happened.","cn":"我们不应该为发生的事责怪自己。"},{"en":"We had the pool all to ourselves.","cn":"这个游泳池完全供我们自己使用。"}]},"oil":{"media":{"uk":"media/uk/oil__gb_1.mp3","us":"media/us/oil__us_1.mp3","img":["media/ldoce/img/vinegar.jpg"]},"oxford":{"phon":"ɔɪl","pos":"noun","senses":[{"en":"a thick liquid that is found in rock underground","cn":"石油；原油","g":"[uncountable]","ex":{"en":"Several companies are drilling for oil in the region.","cn":"数家公司正在该地区钻探石油。"}},{"en":"a form of petroleum that is used as fuel and to make parts of machines move smoothly","cn":"燃油；润滑油","g":"[uncountable]","ex":{"en":"fuel oil","cn":"燃料油"}},{"en":"a smooth thick liquid that is made from plants or animals and is used in cooking","cn":"食用油","g":"[uncountable, countable]","ex":{"en":"Fry the potato in a little sunflower oil.","cn":"用少许葵花籽油煎土豆。"}},{"en":"a smooth thick liquid that is made from plants, minerals, etc. and is used on the skin or hair","cn":"防护油；润肤油；护发油","g":"[uncountable, countable]","ex":{"en":"lavender bath oil","cn":"薰衣草沐浴油"}},{"en":"coloured paint containing oil used by artists","cn":"（绘画用）油彩","g":"[uncountable]","lab":"US English","ex":{"en":"‘Four Women on a Bench’, oil on canvas, 1991","cn":"《长凳上的四个女人》，布面油画，作于1991年"}},{"en":"a picture painted in oil paint","cn":"油画","g":"[countable]","ex":{"en":"Among the more important Turner oils was ‘Venus and Adonis’.","cn":"《维纳斯和阿多尼斯》是透纳比较重要的油画作品之一。"}},{"en":"to put oil onto or into something, for example a machine, in order to protect it or make it work smoothly","cn":"给…加润滑油","ex":{"en":"He oiled his bike and pumped up the tyres.","cn":"他给自己的自行车上了油，给轮胎充了气。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"石油；燃料油；润滑油","en":"Oil is a smooth, thick liquid that is used as a fuel and for making the parts of machines move smoothly. Oil is found underground.","ex":{"en":"The company buys and sells about 600,000 barrels of oil a day.","cn":"该公司每天买卖约60万桶石油。"}},{"pos":"VERB 动词","cn":"给…加润滑油；给…上油","en":"If you oil something, you put oil onto or into it, for example to make it work smoothly or to protect it.","ex":{"en":"A crew of assistants oiled and adjusted the release mechanism until it worked perfectly","cn":"一班助手给排放装置加润滑油并作调试，直到其达至理想工作状态。"}},{"pos":"N-MASS 物质名词","cn":"食用油；植物油","en":"Oil is a smooth, thick liquid made from plants and is often used for cooking.","ex":{"en":"Combine the beans, chopped mint and olive oil in a large bowl","cn":"将菜豆、切碎的薄荷和橄榄油放在大碗里搅拌。"}},{"pos":"N-MASS 物质名词","cn":"润肤油；沐浴油","en":"Oil is a smooth, thick liquid, often with a pleasant smell, that you rub into your skin or add to your bath.","ex":{"en":"Try a hot bath with some relaxing bath oil","cn":"用舒缓沐浴油洗个热水澡吧。"}},{"pos":"N-COUNT 可数名词","cn":"同 oil painting","en":"Oils are oil paintings .","ex":{"en":"Her colourful oils and works on paper have a naive, dreamlike quality.","cn":"她那些色彩斑斓的油画与纸上作品给人一种天真、梦幻般的感觉。"}},{"pos":"N-PLURAL 复数名词","cn":"油彩；油画颜料","en":"When an artist paints in oils, he or she uses oil paints.","ex":{"en":"When she paints in oils she always uses the same range of colours.","cn":"她创作油画时总是使用同一组色彩。"}},{"pos":"PHRASE 短语","cn":"平息风波；调停争端","en":"If you pour oil on troubled waters, you try to calm down a difficult situation."},{"pos":"PHRASE 短语","cn":"使…顺利进行；使…正常运作","en":"If someone or something oils the wheels of a process or system, they help things to run smoothly and successfully.","ex":{"en":"On all such occasions, the king stands in the wings, oiling the wheels of diplomacy.","cn":"在所有这样的场合，国王总是身处幕后确保外交活动的顺利进行。"}},{"pos":"","cn":"","en":"to burn the midnight oil→see: ;"}]},"examples":[{"en":"Among the more important Turner oils was ‘Venus and Adonis’. 《","cn":"维纳斯和阿多尼斯》是透纳比较重要的油画作品之一。"},{"en":"He oiled his bike and pumped up the tyres.","cn":"他给自己的自行车上了油，给轮胎充了气。"}]},"observation":{"media":{"uk":"media/uk/observation__gb_1.mp3","us":"media/us/observation__us_1.mp3"},"oxford":{"phon":"ˌɒbzəˈveɪʃn","pos":"noun","senses":[{"en":"the act of watching somebody/something carefully for a period of time, especially to learn something","cn":"观察；观测；监视","g":"[uncountable, countable]","ex":{"en":"Most information was collected by direct observation of the animals' behaviour.","cn":"大部分信息都是通过直接观察动物的行为收集到的。"}},{"en":"a comment, especially based on something you have seen, heard or read","cn":"（尤指据所见、所闻、所读而作的）评论","g":"[countable]","lab":"formal","ex":{"en":"May I make a personal observation?","cn":"我可以做一下个人观察吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"观察；观测","en":"Observation is the action or process of carefully watching someone or something.","ex":{"en":"...careful observation of the movement of the planets","cn":"对行星运动的仔细观测"}},{"pos":"N-COUNT 可数名词","cn":"观察所得；观察资料；观测数据","en":"An observation is something that you have learned by seeing or watching something and thinking about it.","ex":{"en":"This book contains observations about the causes of addictions.","cn":"该书包括有关成瘾原因的观察发现。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指观察后发表的）评论，言论","en":"If a person makes an observation, they make a comment about something or someone, usually as a result of watching how they behave.","ex":{"en":"'You're an obstinate man,' she said. 'Is that a criticism,' I said, 'or just an observation?'.","cn":"“你是个很执拗的人，”她说道。“你这是批评呢，”我说，“还是只是发表评论而已？”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"观察力","en":"Observation is the ability to pay a lot of attention to things and to notice more about them than most people do.","ex":{"en":"She has good powers of observation.","cn":"她的观察力很敏锐。"}}]},"examples":[{"en":"Most information was collected by direct observation of the animals' behaviour.","cn":"大部分信息都是通过直接观察动物的行为收集到的。"},{"en":"He began by making a few general observations about the report.","cn":"开头他先对这个报告作了几点概括性的评论。"}]},"operates":{"lemma":"operate"},"obey":{"media":{"uk":"media/uk/obey__gb_1.mp3","us":"media/us/obey__us_1.mp3"},"oxford":{"phon":"əˈbeɪ","pos":"verb","senses":[{"en":"to do what you are told or expected to do","cn":"服从；遵守；顺从","lab":"figurative","ex":{"en":"to obey a command/an order/rules/the law","cn":"服从指挥／命令；遵守规章／法律"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"服从；顺从；听从；遵守","en":"If you obey a person, a command, or an instruction, you do what you are told to do.","ex":{"en":"Cissie obeyed her mother without question","cn":"茜茜对她母亲言听计从。"}}]},"examples":[{"en":"to obey a command/an order/rules/the law","cn":"服从指挥/命令；遵守规章/法律"},{"en":"‘Sit down!’ Meekly, she obeyed. “","cn":"坐下！”她乖乖地顺从了。"}]},"occurrence":{"oxford":{"phon":"əˈkʌrəns","pos":"noun","senses":[{"en":"something that happens or exists","cn":"发生的事情；存在的事物","g":"[countable]","ex":{"en":"a common/everyday/frequent/regular occurrence","cn":"屡见不鲜的／每天发生的／经常发生的／定期发生的事情"}},{"en":"the fact of something happening or existing","cn":"发生；出现；存在","g":"[uncountable]","ex":{"en":"a link between the occurrence of skin cancer and the use of computer monitors","cn":"皮肤癌的发生与使用电脑显示器之间的关联"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发生的事情；事件","en":"An occurrence is something that happens.","ex":{"en":"Complaints seemed to be an everyday occurrence","cn":"似乎每天都有投诉。"}},{"pos":"N-COUNT 可数名词","cn":"发生；出现","en":"The occurrence of something is the fact that it happens or is present.","ex":{"en":"The greatest occurrence of coronary heart disease is in those over 65.","cn":"65岁以上者是冠心病的最高发人群。"}}]},"media":{"uk":"media/uk/occurrence__gb_1.mp3","us":"media/us/occurrence__us_1.mp3"},"examples":[{"en":"The program counts the number of occurrences of any word, within the text.","cn":"这个程序可以统计任何单词在文本中出现的次数。"},{"en":"a link between the occurrence of skin cancer and the use of computer monitors","cn":"皮肤癌的发生与使用电脑显示器之间的关联"}]},"oneself":{"media":{"uk":"media/uk/oneself__gb_1.mp3","us":"media/us/oneself__us_1.mp3"},"oxford":{"phon":"wʌnˈself","pos":"pronoun","senses":[{"en":"used as the object of a verb or preposition when ‘one’ is the subject of the verb or is understood as the subject","cn":"（one 作动词的主语时，oneself 作动词或介词的宾语）自己，自身","ex":{"en":"One has to ask oneself what the purpose of the exercise is.","cn":"大家必须问一问自己，这个锻炼的目的是什么。"}},{"en":"used to emphasize one","cn":"（用以强调 one）亲自，自己","ex":{"en":"One likes to do it oneself.","cn":"人都喜欢亲自去做。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"（用作从句中动词或代词的宾语，指代动词主语“我”或“任何人”）自己，自身","en":"A speaker or writer uses oneself as the object of a verb or preposition in a clause where 'oneself' meaning 'me' or 'any person in general' refers to the same person as the subject of the verb.","ex":{"en":"One must apply oneself to the present and keep one's eyes firmly fixed on one's future goals","cn":"人们必须立足现在，目光锁定未来目标。"}},{"pos":"PRON-REFL 反身代词","cn":"（one 虽缺失但可理解为动词主语时，用作动词或介词的宾语）自己，自身","en":"Oneself can be used as the object of a verb or preposition, when 'one' is not present but is understood to be the subject of the verb.","ex":{"en":"The historic feeling of the town makes it a pleasant place to base oneself for summer vacations","cn":"该镇的历史气息让它成为人们夏季度假的好去处。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"独自；亲自；本人","en":"To do something oneself means to do it without any help from anyone else.","ex":{"en":"It is a very rewarding exercise to work this out oneself","cn":"独自解决这个问题是一次受益匪浅的锻炼。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（强调事情发生的对象）自己，自身","en":"You use oneself to emphasize that something happens to you rather than to people in general.","ex":{"en":"It is better to die oneself than to kill.","cn":"宁可自亡，不可行凶。"}}]},"examples":[{"en":"One has to ask oneself what the purpose of the exercise is.","cn":"大家必须问一问自己，这个锻炼的目的是什么。"},{"en":"One cannot choose freedom for oneself without choosing it for others.","cn":"人不能光为了自己的自由而不顾别人的自由。"}]},"oxen":{"lemma":"ox"},"outdoors":{"media":{"uk":"media/uk/outdoors__gb_1.mp3","us":"media/us/outdoors__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈdɔːz","pos":"adverb","senses":[{"en":"outside, rather than in a building","cn":"在户外；在野外","ex":{"en":"The rain prevented them from eating outdoors.","cn":"雨天使他们无法户外用餐。"}},{"en":"the countryside, away from buildings and busy places","cn":"野外；旷野；郊外","lab":"especially North American English","ex":{"en":"They both have a love of the outdoors.","cn":"他们俩都喜爱郊外的环境。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在户外；在室外；在野外","en":"If something happens outdoors, it happens outside in the fresh air rather than in a building.","ex":{"en":"It was warm enough to be outdoors all afternoon","cn":"天气很暖和，整个下午都可以呆在户外。"}},{"pos":"N-SING 单数名词","cn":"户外工作；野外活动；户外休闲","en":"You refer to the outdoors when talking about work or leisure activities which take place outside away from buildings.","ex":{"en":"I'm a lover of the outdoors","cn":"我喜爱户外运动。"}}]},"examples":[{"en":"Come to Canada and enjoy the great outdoors.","cn":"到加拿大来享受蓝天碧野吧！"},{"en":"They both have a love of the outdoors.","cn":"他们俩都喜爱郊外的环境。"}]},"oak":{"media":{"img":["media/pic/deciduous_trees_comp.jpg","media/thumb/oak.jpg"],"uk":"media/uk/oak__gb_1.mp3","us":"media/us/oak__us_1.mp3"},"oxford":{"phon":"əʊk","pos":"noun","senses":[{"en":"a large tree that produces small nuts called acorns. Oaks are common in northern countries and can live to be hundreds of years old.","cn":"栎树；橡树","g":"[countable, uncountable]","ex":{"en":"The forest is famous for its ancient oak trees.","cn":"该森林以其古老的橡树而闻名。"}},{"en":"the hard wood of the oak tree","cn":"栎木；橡木","g":"[uncountable]","ex":{"en":"oak beams","cn":"栎木梁"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"栎（树）；橡（树）","en":"An oak or an oak tree is a large tree that often grows in woods and forests and has strong, hard wood.","ex":{"en":"Many large oaks were felled during the war.","cn":"很多高大的橡树在战争中遭到了砍伐。"}}]},"examples":[{"en":"This table is made of solid oak.","cn":"这张桌子是用实心栎木制作的。"},{"en":"forests of oak and pine","cn":"长有松树和栎树的森林"}]},"object":{"media":{"uk":"media/uk/object__gb_1.mp3","us":"media/us/object__us_1.mp3"},"oxford":{"phon":"ˈɒbdʒɪkt","pos":"noun","senses":[{"en":"a thing that can be seen and touched, but is not alive","cn":"物体；物品；东西","ex":{"en":"everyday objects such as cups and saucers","cn":"诸如杯碟之类的日用品"}},{"en":"a person or thing that somebody desires, studies, pays attention to, etc.","cn":"（极欲得到、研究、注意等的）对象","ex":{"en":"He felt he was nothing more to her than an object of desire.","cn":"他觉得对她来说自己不过是个性欲对象而已。"}},{"en":"an aim or a purpose","cn":"宗旨；目的；目标","ex":{"en":"Her sole object in life is to become a travel writer.","cn":"她人生的唯一目标就是当游记作家。"}},{"en":"a noun, noun phrase or pronoun that refers to a person or thing that is affected by the action of the verb (called the direct object), or that the action is done to or for (called the indirect object)","cn":"宾语（包括直接宾语、间接宾语）","lab":"grammar"},{"en":"to say that you disagree with or oppose something","cn":"不同意；不赞成；反对","g":"[intransitive]","ex":{"en":"If nobody objects, we'll postpone the meeting till next week.","cn":"如果没有人反对，我们就把会议推迟到下周。"},"pos":"verb"},{"en":"to give something as a reason for opposing something","cn":"提出…作为反对的理由；抗辩说","g":"[transitive]","ex":{"en":"He objected that the police had arrested him without sufficient evidence.","cn":"他抗辩说警察没有充分的证据就逮捕了他。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"物体；东西","en":"An object is anything that has a fixed shape or form, that you can touch or see, and that is not alive.","ex":{"en":"He squinted his eyes as though he were studying an object on the horizon.","cn":"他眯起眼睛，就好像在端详地平线上的某一物体。"}},{"pos":"N-COUNT 可数名词","cn":"目的；目标；宗旨","en":"The object of what someone is doing is their aim or purpose.","ex":{"en":"The object of the exercise is to raise money for the charity","cn":"那样做旨在筹集善款。"}},{"pos":"N-COUNT 可数名词","cn":"（情感或反应的）对象","en":"The object of a particular feeling or reaction is the person or thing it is directed towards or that causes it.","ex":{"en":"The object of her hatred was 24-year-old model Ros French","cn":"令她心头生恨的是24岁的模特罗斯·弗伦奇。"}},{"pos":"N-COUNT 可数名词","cn":"（语法中的）宾语","en":"In grammar, the object of a verb or a preposition is the word or phrase which completes the structure begun by the verb or preposition."},{"pos":"VERB 动词","cn":"不喜欢;不赞成;反对","en":"If you object to something, you express your dislike or disapproval of it.","ex":{"en":"A lot of people will object to the book","cn":"很多人都会对这本书表示反感。"}},{"pos":"PHRASE 短语","cn":"钱不成问题/距离不在话下","en":"If you say that money is no object or distance is no object, you are emphasizing that you are willing or able to spend as much money as necessary or travel whatever distance is required.","ex":{"en":"Hugh Johnson's shop in London has a range of superb Swedish crystal glasses that I would have if money were no object","cn":"休·约翰逊伦敦店出售各种美轮美奂的瑞典水晶玻璃杯，不考虑钱的话我都想买。"}}]},"examples":[{"en":"‘What’s a blender?’ ‘It’s an electric machine for mixing soft food or liquid.’ “","cn":"搅拌器是什么？” “是搅和软食物或液汁的电动机器。”"},{"en":"‘Have you got one of those tools for turning screws?’ ‘Do you mean a screwdriver?’ “","cn":"你有拧螺丝钉的工具吗？” “你是指螺丝刀吗？”"}]},"overall":{"media":{"img":["media/pic/overalls_dungarees.jpg","media/thumb/overalls.jpg"],"uk":"media/uk/overall__gb_1.mp3","us":"media/us/overall__us_1.mp3"},"oxford":{"phon":"ˌəʊvərˈɔːl","pos":"adjective","senses":[{"en":"including all the things or people that are involved in a particular situation; general","cn":"全面的；综合的；总体的","ex":{"en":"There will be winners in each of three age groups, and one overall winner.","cn":"三个年龄组将各产生一位优胜者，另有一位总优胜者。"}},{"en":"including everything or everyone; in total","cn":"全部；总计","ex":{"en":"The company will invest $1.6m overall in new equipment.","cn":"这个公司将总计投资 160 万美元购置新设备。"},"pos":"adverb"},{"en":"generally; when you consider everything","cn":"一般来说；大致上；总体上","ex":{"en":"Overall, this is a very useful book.","cn":"总的来说，这是一本很有用的书。"},"pos":"adverb"},{"en":"a loose coat worn over other clothes to protect them from dirt, etc.","cn":"外套；罩衣","g":"[countable]","lab":"British English","ex":{"en":"The lab assistant was wearing a white overall.","cn":"实验室助手穿着一件白罩衣。"},"pos":"noun"},{"en":"a loose piece of clothing like a shirt and trousers in one piece, made of heavy cloth and usually worn over other clothing by workers doing dirty work","cn":"工装服；连身工作服","g":"[plural]","lab":"British English","ex":{"en":"The mechanic was wearing a pair of blue overalls.","cn":"机修工穿着一件蓝色工装连衣裤。"},"pos":"noun"},{"en":"a piece of clothing that consists of trousers with an extra piece of cloth covering the chest, held up by narrow pieces of cloth over the shoulders","cn":"工装裤；工装服","g":"[plural]","lab":"both North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"总的；总体的；全面的","en":"You use overall to indicate that you are talking about a situation in general or about the whole of something.","ex":{"en":"...the overall rise in unemployment","cn":"失业率总体的上升"}},{"pos":"N-PLURAL 复数名词","cn":"（上下连身的）工作服，防护服","en":"Overalls consist of a single piece of clothing that combines trousers and a jacket. You wear overalls over your clothes in order to protect them while you are working.","ex":{"en":"...workers in blue overalls.","cn":"穿着蓝色连身工作服的工人"}},{"pos":"N-PLURAL 复数名词","cn":"（吊带）工装裤","en":"Overalls are trousers that are attached to a piece of cloth which covers your chest and which has straps going over your shoulders.","ex":{"en":"An elderly man dressed in faded overalls took the witness stand.","cn":"一位穿着褪色吊带工装裤的老人上了证人席。"}},{"pos":"N-COUNT 可数名词","cn":"（工作时穿的）罩衣","en":"An overall is a piece of clothing shaped like a coat that you wear over your clothes in order to protect them while you are working."}]},"examples":[{"en":"There will be winners in each of three age groups, and one overall winner.","cn":"三个年龄组将各产生一位优胜者，另有一位总优胜者。"},{"en":"The company will invest $1.6m overall in new equipment.","cn":"这个公司将总计投资 160 万元购置新设备。"}]},"ordinal":{"oxford":{"phon":"ˈɔːdɪnl","pos":"noun","senses":[{"en":"a number that refers to the position of something in a series, for example ‘first’, ‘second’, etc.","cn":"序数词（如第一、第二等）"},{"en":"referring to or connected with the position of something in a series","cn":"序数词（如第一、第二等）","ex":{"en":"the ordinal numbers","cn":"序数词"},"pos":"adjective"}]},"media":{"uk":"media/uk/ordinal__gb_1.mp3","us":"media/us/ordinal__us_1.mp3"}},"opponents":{"lemma":"opponent"},"obedience":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is obedient always does what their parents, teachers, or people in authority tell them to do - use this especially about children","cn":""},{"en":"obedient behaviour","cn":""}]},"media":{"uk":"media/uk/obedience__gb_1.mp3","us":"media/us/obedience__us_1.mp3"},"oxford":{"phon":"əˈbiːdiəns","pos":"noun","senses":[{"en":"the fact of doing what you are told to do or of being willing to obey","cn":"顺从的；忠顺的；唯命是从的","ex":{"en":"blind/complete/unquestioning/total obedience","cn":"盲目的／完全的／不怀疑的／绝对的服从"}}]}},"outpost":{"media":{"uk":"media/uk/outpost__gb_1.mp3","us":"media/us/outpost__us_1.mp3"},"oxford":{"phon":"ˈaʊtpəʊst","pos":"noun","senses":[{"en":"a small military camp away from the main army, used for watching an enemy’s movements, etc.","cn":"前哨（基地）"},{"en":"a small town or group of buildings in a lonely part of a country","cn":"偏远村镇；孤零住区","ex":{"en":"a remote outpost","cn":"偏远的村镇"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贸易站；前哨基地；（设在国外的）军事基地","en":"An outpost is a small group of buildings used for trading or military purposes, either in a distant part of your own country or in a foreign country.","ex":{"en":"...a remote mountain outpost, linked to the outside world by the poorest of roads.","cn":"靠一条崎岖艰险的山路与外界相连的偏远山区哨站"}}]},"examples":[{"en":"the last outpost of civilization","cn":"文明的边缘地区"},{"en":"a remote outpost","cn":"偏远的村镇"}]},"oblivious":{"media":{"uk":"media/uk/oblivious__gb_1.mp3","us":"media/us/oblivious__us_1.mp3"},"oxford":{"phon":"əˈblɪviəs","pos":"adjective","senses":[{"en":"not aware of something","cn":"不知道；未注意；未察觉","ex":{"en":"You eventually become oblivious to the noise.","cn":"你终究会变得不在意吵闹声的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不知道的；未注意的;未觉察的","en":"If you are oblivious to something or oblivious of it, you are not aware of it.","ex":{"en":"She lay motionless where she was, oblivious to pain","cn":"她一动不动地躺在原地，已经感觉不到疼痛。"}}]},"examples":[{"en":"He drove off, oblivious of the damage he had caused.","cn":"他车开走了，没有注意到他所造成的损害。"},{"en":"You eventually become oblivious to the noise.","cn":"你终究会变得不在意吵闹声的。"}]},"onward":{"media":{"uk":"media/uk/onward__gb_1.mp3","us":"media/us/onward__us_1.mp3"},"oxford":{"phon":"ˈɒnwəd","pos":"adjective","senses":[{"en":"continuing or moving forward","cn":"继续的；向前的","ex":{"en":"Ticket prices include your flight and onward rail journey.","cn":"票价包括您的机票和接续的铁路旅费。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"向前的；前进的","en":"Onward means moving forward or continuing a journey.","ex":{"en":"British Airways have two flights a day to Bangkok, and there are onward flights to Phnom Penh.","cn":"英国航空公司每天有两个航班飞往曼谷，那里有前往金边的接续航班。"}},{"pos":"ADJ 形容词","cn":"发展的；进步的；日趋重要的","en":"Onward means developing, progressing, or becoming more important over a period of time.","ex":{"en":"...the onward march of progress in the British aircraft industry.","cn":"英国航空业的稳步发展"}},{"pos":"ADV 副词","cn":"（从某时起）一直","en":"If something happens from a particular time onwards or onward, it begins to happen at that time and continues to happen afterwards.","ex":{"en":"From the turn of the century onward, she shared the life of the aborigines.","cn":"她自世纪之交以来便同土著居民生活在一起。"}}]},"examples":[{"en":"Ticket prices include your flight and onward rail journey.","cn":"票价包括您的飞行航程和接续的铁路旅费。"},{"en":"The company offers flights to Amsterdam with onward travel to The Hague.","cn":"这家公司开设了飞往阿姆斯特丹并续飞海牙的航班。"}]},"offering":{"media":{"uk":"media/uk/offering__gb_1.mp3","us":"media/us/offering__us_1.mp3"},"oxford":{"phon":"ˈɒfərɪŋ","pos":"noun","senses":[{"en":"something that is produced for other people to use, watch, enjoy, etc.","cn":"用品；剧作；作品；供消遣的产品","ex":{"en":"the latest offering from the Canadian-born writer","cn":"在加拿大出生的那位作家的最新作品"}},{"en":"something that is given to a god as part of a religious ceremony","cn":"祭品；供品","ex":{"en":"They made sacrificial offerings to the gods.","cn":"他们向诸神献上了祭品。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"待售品；出售品","en":"An offering is something that is specially produced to be sold.","ex":{"en":"It was very, very good, far better than vegetarian offerings in many a posh restaurant.","cn":"这道菜真是人间美味，远远超过很多豪华餐厅的素食菜品。"}},{"pos":"N-COUNT 可数名词","cn":"祭品；供品","en":"An offering is a gift that people offer to their God or gods as a form of worship.","ex":{"en":"...the holiest of the Shinto rituals, where offerings are made at night to the great Sun.","cn":"神道教仪式中最神圣的时刻，即在晚间祭祀“天照大神”太阳神"}}]},"examples":[{"en":"the latest offering from the Canadian-born writer","cn":"在加拿大出生的那位作家的最新作品"},{"en":"the latest offering from Nanci Griffith","cn":"南希•格里菲思的最新作品"}],"base":"offer"},"override":{"oxford":{"phon":"ˌəʊvəˈraɪd","pos":"verb","senses":[{"en":"to use your authority to reject somebody’s decision, order, etc.","cn":"（以权力）否决，推翻，不理会","ex":{"en":"The chairman overrode the committee's objections and signed the agreement.","cn":"主席不顾委员会的反对，径行签署了协议。"}},{"en":"to be more important than something","cn":"比…更重要；凌驾","ex":{"en":"Considerations of safety override all other concerns.","cn":"对安全的考虑高于一切。"}},{"en":"to interrupt the action of a device that usually works by itself in order to control it yourself","cn":"超控（使自动控制暂时失效，改用手动控制）","ex":{"en":"A special code is needed to override the time lock.","cn":"这定时锁要用特定密码才能打开。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"凌驾于；优先于；比…更重要","en":"If one thing in a situation overrides other things, it is more important than them.","ex":{"en":"The welfare of a child should always override the wishes of its parents","cn":"孩子的幸福安康应该永远比父母的愿望来得更重要。"}},{"pos":"VERB 动词","cn":"（以更大的权力）撤销，推翻，否决","en":"If someone in authority overrides a person or their decisions, they cancel their decisions.","ex":{"en":"The president vetoed the bill, and the Senate failed by a single vote to override his veto","cn":"总统否决了该议案，而参议院以一票之差未能推翻他的否决。"}},{"pos":"N-COUNT 可数名词","cn":"（对决定等的）撤销，推翻，否决","en":"An override is an attempt to cancel someone's decisions by using your authority over them or by gaining more votes than them in an election or contest.","ex":{"en":"The bill now goes to the House where an override vote is expected to fail","cn":"该议案现在提交到众议院，在这里否决投票预计不会获得通过。"}}]},"media":{"uk":"media/uk/override__gb_1.mp3","us":"media/us/override__us_1.mp3"},"examples":[{"en":"The chairman overrode the committee's objections and signed the agreement.","cn":"主席不顾委员会的反对，径行签署了协议。"},{"en":"A special code is needed to override the time lock.","cn":"这定时锁要用特定密码才能打开。"}]},"ok":{"media":{"uk":"media/uk/ok__gb_1.mp3","us":"media/us/ok__us_1.mp3"},"oxford":{"phon":"əʊˈkeɪ","pos":"exclamation","senses":[{"en":"yes; all right","cn":"对；好；行","ex":{"en":"‘Shall we go for a walk?’ ‘OK.’","cn":"“咱们去散散步，好不好？”“好。”"}},{"en":"used to attract somebody’s attention or to introduce a comment","cn":"（用以引起注意或引入话题）好了，对了","ex":{"en":"Okay, let's go.","cn":"好了，咱们走吧。"}},{"en":"used to check that somebody agrees with you or understands you","cn":"（用于弄清别人是否赞同或明白）好吗，行不","ex":{"en":"The meeting's at 2, OK?","cn":"两点开会，明白吗？"}},{"en":"used to stop people arguing with you or criticizing you","cn":"（用以制止对方争辩或批评）得了，行了，好了","ex":{"en":"OK, so I was wrong. I'm sorry.","cn":"行了，是我不对。对不起。"}},{"en":"safe and well; in a calm or happy state","cn":"安然无恙；平安；快活","lab":"especially British English","ex":{"en":"Are you OK?","cn":"你没事吧？"},"pos":"adjective, adverb"},{"en":"all right; acceptable; in an acceptable way","cn":"可以；可行；尚可；不错","lab":"North American English","ex":{"en":"Is it OK if I leave now?","cn":"我现在离开，可以吗？"},"pos":"adjective, adverb"},{"en":"permission","cn":"允许；准许；同意","ex":{"en":"I'm still waiting for the boss to give me the OK.","cn":"我还在等上司点头呢。"},"pos":"noun"},{"en":"to officially agree to something or allow it to happen","cn":"正式批准；同意","ex":{"en":"She filled in an expenses claim and her manager OK'd it.","cn":"她填写了一张费用申请单，她的经理批准了。"},"pos":"verb"}]},"examples":[{"en":"She filled in an expenses claim and her manager OK'd it.","cn":"她填写了一张费用申请单，她的经理批准了。"},{"en":"‘Shall we go for a walk?’ ‘OK.’ “","cn":"咱们去散散步，好不好？” “好。”"}],"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"opal":{"media":{"uk":"media/uk/opal__gb_1.mp3","us":"media/us/opal__us_1.mp3"},"oxford":{"phon":"ˈəʊpl","pos":"noun","senses":[{"en":"a white or almost clear semi-precious stone in which changes of colour are seen, used in jewellery","cn":"欧泊；蛋白石","ex":{"en":"an opal ring","cn":"欧泊戒指"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蛋白石","en":"An opal is a precious stone. Opals are colourless or white, but other colours are reflected in them."}]},"examples":[{"en":"an opal ring","cn":"蛋白石戒指"}]},"organizing":{"lemma":"organize"},"old-fashioned":{"oxford":{"phon":"ˌəʊld ˈfæʃnd","pos":"adjective","senses":[{"en":"not modern; no longer fashionable","cn":"陈旧的；过时的；不时髦的","lab":"sometimes disapproving","ex":{"en":"old-fashioned clothes/styles/methods/equipment","cn":"过时的衣服／式样／方法／设备"}},{"en":"believing in old or traditional ways; having traditional ideas","cn":"保守的；守旧的；迂腐的","lab":"sometimes disapproving","ex":{"en":"My parents are old-fashioned about relationships and marriage.","cn":"我父母对男女关系和婚姻问题思想保守得很。"}},{"en":"simple, traditional and good quality","cn":"经典的；传统的","lab":"approving","ex":{"en":"At heart, it's just a good old-fashioned detective story.","cn":"本质上，这的确是一部优秀的传统侦探小说。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"老式的；过时的；不时髦的","en":"Something such as a style, method, or device that is old-fashioned is no longer used, done, or admired by most people, because it has been replaced by something that is more modern.","ex":{"en":"The house was dull, old-fashioned and in bad condition","cn":"这幢房子死气沉沉、风格过时并且破败不堪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（观点、习俗、价值观等）老派的，守旧的，传统的","en":"Old-fashioned ideas, customs, or values are the ideas, customs, and values of the past.","ex":{"en":"She has some old-fashioned values and can be a strict disciplinarian.","cn":"她的观念比较保守，有时过于严格地奉行纪律。"}}]},"media":{"uk":"media/uk/old_fashioned_1_gb_1.mp3","us":"media/us/old_fashioned_1_us_1.mp3"},"examples":[{"en":"My parents are old-fashioned about relationships and marriage.","cn":"我父母对男女关系和婚姻问题思想保守得很。"},{"en":"old-fashioned clothes/styles/methods/equipment","cn":"过时的衣服/式样/方法/设备"}]},"operational":{"oxford":{"phon":"ˌɒpəˈreɪʃənl","pos":"adjective","senses":[{"en":"connected with the way in which a business, machine, system, etc. works","cn":"操作的；运转的；运营的；业务的","g":"[usually before noun]","ex":{"en":"operational activities/costs/difficulties","cn":"营运活动／成本／困难"}},{"en":"ready or available to be used","cn":"可使用","g":"[not usually before noun]","ex":{"en":"The new airport is now fully operational.","cn":"新机场现在可全面投入运营。"}},{"en":"connected with a military operation","cn":"军事行动的","g":"[only before noun]","ex":{"en":"operational headquarters","cn":"作战指挥部"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（机器、设备等）正常运转的，可使用的","en":"A machine or piece of equipment that is operational is in use or is ready for use.","ex":{"en":"The whole system will be fully operational by December 1995.","cn":"整个系统到1995年12月将可全面投入使用。"}},{"pos":"ADJ 形容词","cn":"操作上的；实施时的；运行中的","en":"Operational factors or problems relate to the working of a system, device, or plan.","ex":{"en":"The nuclear industry was required to prove that every operational and safety aspect had been fully researched.","cn":"核工业被要求证明其在运营与安全各方面都进行过充分的研究。"}}]},"media":{"uk":"media/uk/operational__gb_1.mp3","us":"media/us/operational__us_1.mp3"},"examples":[{"en":"The new airport is now fully operational.","cn":"新机场现在可全面投入运营。"},{"en":"operational activities/costs/difficulties","cn":"营运上的活动/成本/困难"}]},"ochre":{"oxford":{"phon":"ˈəʊkə(r)","pos":"noun","senses":[{"en":"a type of red or yellow earth used in some paints and dyes","cn":"赭土；赭石"},{"en":"the red or yellow colour of ochre","cn":"赭色；土黄色"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"赭色；淡橘黄色","en":"Something that is ochre is a yellowish orange colour.","ex":{"en":"For our dining room I have chosen ochre yellow walls.","cn":"我决定把我们餐厅的墙壁刷成赭黄色。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赭石（用于制作染料或颜料，通常为红色或黄色）","en":"Ochre is coloured earth, usually red or yellow, that is used to make dyes and paints."}]},"media":{"uk":"media/uk/ochre__gb_1.mp3","us":"media/us/ochre__us_1.mp3"}},"obligingly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is a help , they make it easier for you to do something","cn":""},{"en":"someone who is cooperative helps someone who has asked them to help, by working together with them and not causing any problems","cn":""}]},"examples":[{"en":"The shop assistant was very obliging.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obligingly__gb_1.mp3","us":"media/us/obligingly__us_1.mp3"},"oxford":{"phon":"əˈblaɪdʒɪŋli","pos":"adverb","senses":[{"en":"in a way that shows that you are very willing to help","cn":"乐于助人地，热心相助地","ex":{"en":"‘I’ll go for you,’ she said, obligingly.","cn":"“我替你去吧。”她热情地说。"}}]}},"offset":{"media":{"uk":"media/uk/offset__gb_1.mp3","us":"media/us/offset__us_1.mp3"},"oxford":{"phon":"ˈɒfset","pos":"verb","senses":[{"en":"to use one cost, payment or situation in order to cancel or reduce the effect of another","cn":"抵消；弥补；补偿","lab":"British English","ex":{"en":"Prices have risen in order to offset the increased cost of materials.","cn":"为补偿原料成本的增加而提高了价格。"}},{"en":"used to describe a method of printing in which ink (= coloured liquid) is put onto a metal plate, then onto a rubber surface and only then onto the paper","cn":"胶印的","pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抵消；补偿","en":"If one thing is offset by another, the effect of the first thing is reduced by the second, so that any advantage or disadvantage is cancelled out.","ex":{"en":"The increase in pay costs was more than offset by higher productivity","cn":"提高的生产率抵消了增加的工资成本后仍有结余。"}}]},"examples":[{"en":"Prices have risen in order to offset the increased cost of materials.","cn":"为补偿原料成本的增加而提高了价格。"},{"en":"( BrE ) What expenses can you offset against tax?","cn":"什么开支可以获得税项减免？"}]},"opposite":{"media":{"uk":"media/uk/opposite__gb_1.mp3","us":"media/us/opposite__us_1.mp3"},"oxford":{"phon":"ˈɒpəzɪt","pos":"adjective","senses":[{"en":"on the other side of a particular area from somebody/something and usually facing them","cn":"对面的；另一边的","g":"[only before noun]","ex":{"en":"Answers are given on the opposite page.","cn":"答案在对页上。"}},{"en":"facing the speaker or somebody/something that has been mentioned","cn":"对面的","ex":{"en":"I could see smoke coming from the windows of the house directly opposite.","cn":"我能看到烟从正对面的窗户里冒出来。"}},{"en":"as different as possible from something","cn":"相反的；迥然不同的","g":"[usually before noun]","ex":{"en":"I watched them leave and then drove off in the opposite direction.","cn":"我目送他们离开，然后开车向相反的方向驶去。"}},{"en":"a person or thing that is as different as possible from somebody/something else","cn":"对立的人（或物）；对立面；反面","ex":{"en":"Hot and cold are opposites.","cn":"热和冷是对立面。"},"pos":"noun"},{"en":"on the other side of a particular area from somebody/something, and usually facing them","cn":"与…相对；在…对面","ex":{"en":"I sat opposite him during the meal (= on the other side of the table).","cn":"席间我坐在他的对面。"},"pos":"preposition"},{"en":"acting in a film or play as the partner of somebody","cn":"与…合演；与…联袂演出","ex":{"en":"She starred opposite Tom Hanks.","cn":"她与汤姆·汉克斯联袂主演。"},"pos":"preposition"},{"en":"on the other side of a particular area from somebody/something and usually facing them","cn":"对面的；另一边的","ex":{"en":"There's a newly married couple living opposite (= on the other side of the road).","cn":"对面住了一对新婚夫妇。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…的对面","en":"If one thing is opposite another, it is on the other side of a space from it.","ex":{"en":"Jennie had sat opposite her at breakfast.","cn":"珍妮吃早餐时坐在她对面。"}},{"pos":"ADJ 形容词","cn":"另一边的；对面的","en":"The opposite side or part of something is the side or part that is furthest away from you.","ex":{"en":"...the opposite corner of the room.","cn":"房间的对角"}},{"pos":"ADJ 形容词","cn":"（同一类事物）截然相反的，全然不同的","en":"Opposite is used to describe things of the same kind which are completely different in a particular way. For example, north and south are opposite directions, and winning and losing are opposite results in a game.","ex":{"en":"All the cars driving in the opposite direction had their headlights on","cn":"对面开来的车都打着头灯。"}},{"pos":"N-COUNT 可数名词","cn":"对立物；对立面","en":"The opposite of someone or something is the person or thing that is most different from them.","ex":{"en":"Ritter was a very complex man but Marius was the opposite, a simple farmer","cn":"里特城府颇深，而马里厄斯恰恰相反，是个心地淳朴的农民。"}}]},"examples":[{"en":"It's not easy having a relationship when you live at opposite ends of the country.","cn":"人虽同国却各处东西；在这种情况下谈恋爱，谈何容易。"},{"en":"I thought she would be small and blonde but she's the complete opposite.","cn":"我原以为她是一位身材娇小的金发女郎，但她恰恰相反。"}]},"overnight":{"media":{"uk":"media/uk/overnight__gb_1.mp3","us":"media/us/overnight__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈnaɪt","pos":"adverb","senses":[{"en":"during or for the night","cn":"在夜间；在晚上","ex":{"en":"We stayed overnight in London after the theatre.","cn":"我们看完戏后在伦敦住了一晚。"}},{"en":"suddenly or quickly","cn":"突然；一夜之间；旋即","ex":{"en":"Don't expect it to improve overnight.","cn":"不要指望这事一下子就改善了。"}},{"en":"happening during the night; for a night","cn":"夜间的；晚上的；只供一夜的","ex":{"en":"an overnight flight","cn":"夜间飞行"},"pos":"adjective"},{"en":"happening suddenly or quickly","cn":"突然的；很快的；一夜之间的","ex":{"en":"The play was an overnight success.","cn":"这部剧作一夜成名。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在整个夜间；在夜里的某一时刻","en":"If something happens overnight, it happens throughout the night or at some point during the night.","ex":{"en":"The weather remained calm overnight","cn":"整晚都悄然无风。"}},{"pos":"ADV 副词","cn":"突然；一下子；一夜之间","en":"You can say that something happens overnight when it happens very quickly and unexpectedly.","ex":{"en":"The rules are not going to change overnight","cn":"这些规定不会说变就变。"}},{"pos":"ADJ 形容词","cn":"只供一两晚使用的","en":"Overnight bags or clothes are ones that you take when you go and stay somewhere for one or two nights.","ex":{"en":"He realized he'd left his overnight bag at Mary's house.","cn":"他意识到自己把过夜包落在玛丽家了。"}},{"pos":"VERB 动词","cn":"过夜","en":"If you overnight somewhere, you spend the night there.","ex":{"en":"They had told her she would be overnighting in Sydney.","cn":"他们跟她说过她将在悉尼过夜。"}}]},"examples":[{"en":"She took only an overnight bag (= containing the things needed for a night spent away from home).","cn":"她只带了一个外出住宿一晚的用品旅行袋。"},{"en":"We stayed overnight in London after the theatre.","cn":"我们看完戏后在伦敦住了一晚。"}]},"old-time":{"oxford":{"phon":"ˈəʊld taɪm","pos":"adjective","senses":[{"en":"typical of the past","cn":"昔日的；过去的；旧式的","ex":{"en":"old-time dancing","cn":"古典舞蹈"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"老式的；旧式的；过时的","en":"If you describe something as old-time, you mean that it was common or popular in the past but is not common or popular now.","ex":{"en":"...an old-time dance hall which still has a tea dance on Monday afternoons.","cn":"每周一下午依旧举办茶话舞会的老式舞厅"}},{"pos":"ADJ 形容词","cn":"（用于职业名称前）过去的，昔日的","en":"You can use old-time before the name of someone's job to show that they do their job in the way it was done in the past.","ex":{"en":"The effect of that singing, as the old-time reporters used to say, was electrical.","cn":"正如从前的记者常说的那样，歌声直击人心。"}}]},"media":{"uk":"media/uk/old_time_1_gb_1.mp3","us":"media/us/old_time_1_us_1.mp3"},"examples":[{"en":"old-time dancing","cn":"古典舞蹈"},{"en":"old-time remedies","cn":"老式疗法"}]},"only":{"media":{"uk":"media/uk/only__gb_1.mp3","us":"media/us/only__us_1.mp3"},"oxford":{"phon":"ˈəʊnli","pos":"adjective","senses":[{"en":"used to say that no other or others of the same group exist or are there","cn":"仅有的；唯一的","ex":{"en":"She's their only daughter.","cn":"她是他们的独生女。"}},{"en":"used to say that somebody/something is the best and you would not choose any other","cn":"最好的；最适当的","ex":{"en":"She's the only person for the job.","cn":"她是这项工作最合适的人选。"}},{"en":"nobody or nothing except","cn":"只；只有；仅","ex":{"en":"There are only a limited number of tickets available.","cn":"剩下的票数量很有限。"},"pos":"adverb"},{"en":"in no other situation, place, etc.","cn":"仅在…情况下（或地点等）","ex":{"en":"I agreed, but only because I was frightened.","cn":"我当时同意只是因为我很害怕。"},"pos":"adverb"},{"en":"no more important, interesting, serious, etc. than","cn":"只不过；仅…而已","ex":{"en":"It was only a suggestion.","cn":"这只是个提议罢了。"},"pos":"adverb"},{"en":"no more than; no longer than","cn":"只有；仅；刚刚","ex":{"en":"She's only 21 and she runs her own business.","cn":"她只有 21 岁，就经营起自己的企业了。"},"pos":"adverb"},{"en":"not until","cn":"（直到）…才；（只是）…才","lab":"formal","ex":{"en":"We only got here yesterday.","cn":"我们昨天才到这里。"},"pos":"adverb"},{"en":"used to say that somebody can do no more than what is mentioned, although this is probably not enough","cn":"仅此而已；只能","ex":{"en":"We can only guess what happened.","cn":"我们只能猜测发生了什么事。"},"pos":"adverb"},{"en":"used to say that something will have a bad effect","cn":"（用于说明事情的恶果）只会，愈加","ex":{"en":"If you do that, it will only make matters worse.","cn":"如果你那样做，只会乱上加乱。"},"pos":"adverb"},{"en":"used to mention something that happens immediately afterwards, especially something that is surprising, disappointing, etc.","cn":"不料；竟然","ex":{"en":"She turned up the driveway, only to find her way blocked.","cn":"她开上自家车道，不料发现路已被堵。"},"pos":"adverb"},{"en":"except that; but","cn":"不过；但是；可是","ex":{"en":"I'd love to come, only I have to work.","cn":"我很想去，但是我要上班。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（表示比较而言唯一真实、恰当或必要的情况）只，只有","en":"You use only to indicate the one thing that is true, appropriate, or necessary in a particular situation, in contrast to all the other things that are not true, appropriate, or necessary.","ex":{"en":"Only the President could authorize the use of the atomic bomb","cn":"只有总统才能授权使用原子弹。"}},{"pos":"ADV 副词","cn":"（引出发生的必要条件）只有…（才）","en":"You use only to introduce the thing which must happen before the thing mentioned in the main part of the sentence can happen.","ex":{"en":"The lawyer is paid only if he wins","cn":"只有官司赢了才支付律师费。"}},{"pos":"ADJ 形容词","cn":"唯一的；仅有的","en":"If you talk about the only person or thing involved in a particular situation, you mean there are no others involved in it.","ex":{"en":"She was the only woman in Shell's legal department","cn":"她是壳牌公司法律事务部唯一的女性。"}},{"pos":"ADJ 形容词","cn":"（孩子）独生的,仅有的","en":"An only child is a child who has no brothers or sisters."},{"pos":"ADV 副词","cn":"(尤用于想要纠正错误观点时)只不过，仅…而已","en":"You use only to indicate that something is no more important, interesting, or difficult, for example, than you say it is, especially when you want to correct a wrong idea that someone may get or has already got.","ex":{"en":"At the moment it is only a theory","cn":"眼下这只不过是个推测而已。"}},{"pos":"ADV 副词","cn":"（强调数量少或时间短）才，仅仅","en":"You use only to emphasize how small an amount is or how short a length of time is.","ex":{"en":"Child car seats only cost about £10 a week to hire.","cn":"儿童汽车坐椅一周的租金才10英镑。"}},{"pos":"ADV 副词","cn":"（强调是其中的一小部分，而非全部）只，仅仅","en":"You use only to emphasize that you are talking about a small part of an amount or group, not the whole of it.","ex":{"en":"These are only a few of the possibilities","cn":"这些仅仅是其中几种可能。"}},{"pos":"ADV 副词","cn":"（用于 can 或 could 之后，强调除此以外别无可为）只（能）","en":"Only is used after 'can' or 'could' to emphasize that it is impossible to do anything except the rather inadequate or limited action that is mentioned.","ex":{"en":"For a moment I could say nothing. I could only stand and look","cn":"我有那么一会儿一句话都说不出来，只能站在那里看着。"}},{"pos":"ADV 副词","cn":"（强调希望或愿望）唯有，非常","en":"You can use only in the expressions I only wish or I only hope in order to emphasize what you are hoping or wishing.","ex":{"en":"I only wish he were here now that things are getting better for me","cn":"现在我的境况好转了，我真希望他能在这里。"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于表示稍加改动或限定）只是，不过","en":"Only can be used to add a comment which slightly changes or limits what you have just said.","ex":{"en":"It's just as dramatic as a film, only it's real","cn":"这就像电影一样充满戏剧性，不过这是真实发生的。"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于含有 would 的从句后，引出未做某事的原因）要不是，若非","en":"Only can be used after a clause with 'would' to indicate why something is not done.","ex":{"en":"I'd invite you to come with me, only it's such a long way","cn":"要不是路太远，我一定会邀你一同前往。"}},{"pos":"ADV 副词","cn":"（用于不定式前）不料，结果却","en":"You can use only before an infinitive to introduce an event which happens immediately after one you have just mentioned, and which is rather surprising or unfortunate.","ex":{"en":"Ryle tried the Embassy, only to be told that Hugh was in a meeting","cn":"赖尔试着找了大使馆，却被告知休正在开会。"}},{"pos":"ADV 副词","cn":"（强调行动或行为恰当）完全，真正","en":"You can use only to emphasize how appropriate a certain course of action or type of behaviour is.","ex":{"en":"It's only fair to let her know that you intend to apply","cn":"告诉她你打算申请，这才算公平嘛。"}},{"pos":"ADV 副词","cn":"（用于动词前，表示结果令人遗憾或不受欢迎）愈加，只（会）","en":"You can use only in front of a verb to indicate that the result of something is unfortunate or undesirable and is likely to make the situation worse rather than better.","ex":{"en":"The embargo would only hurt innocent civilians","cn":"禁运只会殃及无辜的百姓。"}},{"pos":"PHRASE 短语","cn":"只要（做…）即可","en":"If you say you only have to or have only to do one thing in order to achieve or prove a second thing, you are emphasizing how easily the second thing can be achieved or proved.","ex":{"en":"Any time you want a babysitter, dear, you only have to ask","cn":"亲爱的，你什么时候需要人帮忙照看孩子，只要开口说一声就行。"}},{"pos":"PHRASE 短语","cn":"刚才；刚刚","en":"You can say that something has only just happened when you want to emphasize that it happened a very short time ago.","ex":{"en":"I've only just arrived","cn":"我刚到。"}},{"pos":"PHRASE 短语","cn":"仅仅；勉强","en":"You use only just to emphasize that something is true, but by such a small degree that it is almost not true at all.","ex":{"en":"For centuries farmers there have only just managed to survive","cn":"几个世纪以来，那里的农民只能勉强维持生计。"}},{"pos":"PHRASE 短语","cn":"太；极","en":"You can use only too to emphasize that something is true or exists to a much greater extent than you would expect or like.","ex":{"en":"I know only too well that plans can easily go wrong","cn":"计划很容易出岔子，我太清楚这点了。"}},{"pos":"PHRASE 短语","cn":"（强调乐意）极，非常","en":"You can say that you are only too happy to do something to emphasize how willing you are to do it.","ex":{"en":"I'll be only too pleased to help them out with any queries.","cn":"我非常乐意为他们答疑解惑。"}},{"pos":"","cn":"","en":"if only→see: ; not only→see: ; the one and only→see: ;"}]},"examples":[{"en":"Children can be difficult as we know only too well.","cn":"小孩子往往很难对付，对此我们都非常清楚。"},{"en":"She's only 21 and she runs her own business.","cn":"她只有 21 岁就经营起自己的企业了。"}]},"oh":{"media":{"uk":"media/uk/oh__gb_1.mp3","us":"media/us/oh__us_1.mp3"},"oxford":{"phon":"əʊ","pos":"exclamation","senses":[{"en":"used when you are reacting to something that has been said, especially if you did not know it before","cn":"（表示领悟）哦，唔","ex":{"en":"‘I saw Ben yesterday.’ ‘Oh yes, how is he?’","cn":"“我昨天看见本了。”“哦，他好吗？”"}},{"en":"used to express surprise, fear, joy, etc.","cn":"（表示惊奇、恐惧、高兴等）啊，哈，哎哟","ex":{"en":"Oh, how wonderful!","cn":"啊，真是妙极了！"}},{"en":"used to attract somebody’s attention","cn":"（用以引起注意）喂，嘿，嗨","ex":{"en":"Oh, Sue! Could you help me a moment?","cn":"嘿，休！你帮会儿忙行不行？"}},{"en":"used when you are thinking of what to say next","cn":"（用于思索想说的话时）嗯","ex":{"en":"I've been in this job for, oh, about six years.","cn":"我做这项工作，嗯，有六年左右了吧。"}},{"en":"(especially in text messages, on social media, etc.) other half (a person’s wife, husband or partner)","cn":"另一半，伴侣（全写为 other half，尤用于短信、电邮等）","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（引出答话或评语）哦，噢","en":"You use oh to introduce a response or a comment on something that has just been said.","ex":{"en":"'Had you seen the car before?' — 'Oh yes, it was always in the drive.'","cn":"“之前你见过那辆车吗？”——“哦，见过，它总是停在车道上。”"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊讶、痛苦、恼怒或喜悦等）唉，啊，呀，哈","en":"You use oh to express a feeling such as surprise, pain, annoyance, or happiness.","ex":{"en":"'Oh!' Kenny blinked. 'Has everyone gone?'","cn":"“啊！”肯尼眨了眨眼睛，“人都走了吗？”"}},{"pos":"CONVENTION 惯用语","cn":"（表示犹豫）呃，嗯","en":"You use oh when you are hesitating while speaking, for example because you are trying to estimate something, or because you are searching for the right word.","ex":{"en":"I've been here, oh, since the end of June","cn":"我是，呃，6月底来到这里的。"}}]},"examples":[{"en":"‘Emma has a new job.’ ‘Oh, has she?’ “","cn":"埃玛新找了一份工作。” “噢，是吗？”"},{"en":"‘I saw Ben yesterday.’ ‘Oh yes, how is he?’ “","cn":"我昨天看见本了。” “哦，他好吗？”"}]},"orchid":{"media":{"img":["media/ldoce/img/orchid.jpg","media/pic/flowerlabels_flowers_comp.jpg"],"uk":"media/uk/orchid__gb_1.mp3","us":"media/us/orchid__us_1.mp3"},"oxford":{"phon":"ˈɔːkɪd","pos":"noun","senses":[{"en":"a plant with brightly coloured flowers of unusual shapes. There are many different types of orchid and some of them are very rare.","cn":"兰科植物；兰花"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兰科植物；兰花","en":"Orchids are plants with brightly coloured, unusually shaped flowers."}]}},"ownership":{"media":{"uk":"media/uk/ownership__gb_1.mp3","us":"media/us/ownership__us_1.mp3"},"oxford":{"phon":"ˈəʊnəʃɪp","pos":"noun","senses":[{"en":"the fact of owning something","cn":"所有权；产权；物主身份","ex":{"en":"a growth in home ownership","cn":"拥有房产的人数的增加"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"所有权；产权；物主身份","en":"Ownership of something is the state of owning it.","ex":{"en":"On January 23rd, America decided to relax its rules on the foreign ownership of its airlines.","cn":"1月23日，美国决定放宽对外国持有美国航空公司所有权的管制规定。"}}]},"examples":[{"en":"Ownership of the land is currently being disputed.","cn":"这块土地的所有权现在还有争议。"},{"en":"The restaurant is under new ownership.","cn":"这家餐厅已换了新的经营者。"}]},"outstrip":{"media":{"uk":"media/uk/outstrip__gb_1.mp3","us":"media/us/outstrip__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈstrɪp","pos":"verb","senses":[{"en":"to become larger, more important, etc. than somebody/something","cn":"比…大（或重要等）；超过；胜过","ex":{"en":"Demand is outstripping supply.","cn":"需求快超过供给了。"}},{"en":"to be faster, better or more successful than somebody you are competing against","cn":"超过，超越（竞争对手）","ex":{"en":"Their latest computer outstrips all its rivals.","cn":"他们最新型的计算机超越了所有的对手。"}},{"en":"to run faster than somebody in a race so that you pass them","cn":"比…跑得快；超越","ex":{"en":"She soon outstripped the slower runners.","cn":"她很快超过了跑得慢的选手。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"超过；胜过","en":"If one thing outstrips another, the first thing becomes larger in amount, or more successful or important, than the second thing.","ex":{"en":"In the mid-eighteenth century the production of food far outstripped the rise in population","cn":"18世纪中叶食物的产量远远超过人口的增长。"}}]},"examples":[{"en":"Their latest computer outstrips all its rivals.","cn":"他们最新型的计算机超越了所有的对手。"},{"en":"Demand is outstripping supply.","cn":"需求快超过供应了。"}]},"oscillate":{"oxford":{"phon":"ˈɒsɪleɪt","pos":"verb","senses":[{"en":"to keep changing from one extreme of feeling or behaviour to another, and back again","cn":"（情感或行为）摇摆，波动，变化","g":"[intransitive]","lab":"formal","ex":{"en":"Her moods oscillated between depression and elation.","cn":"她的情绪时而抑郁，时而亢奋。"}},{"en":"to keep moving from one position to another and back again","cn":"振动；摆动","g":"[intransitive]","lab":"physics","ex":{"en":"Watch how the needle on the dial oscillates.","cn":"仔细看仪表盘上的指针如何摆动。"}},{"en":"to change in strength or direction at regular intervals","cn":"振荡；波动","g":"[intransitive]","lab":"physics","ex":{"en":"The current oscillates between magnetic poles.","cn":"电流在磁极间波动。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"摆动；（大小）来回变化","en":"If an object oscillates, it moves repeatedly from one position to another and back again, or keeps getting bigger and smaller.","ex":{"en":"I checked to see if the needle indicating volume was oscillating.","cn":"我查看了那根音量指针是否在摆动。"}},{"pos":"VERB 动词","cn":"（水平、价值等）波动，浮动","en":"If the level or value of something oscillates between one amount and another, it keeps going up and down between the two amounts.","ex":{"en":"The share price has oscillated between a five-year high of 157.25p in 1997 and this year's low of 91.5p","cn":"股价一直在1997年创下的5年间最高点157.25便士和今年的最低点91.5便士之间浮动。"}},{"pos":"VERB 动词","cn":"（情绪、态度或行为）摇摆","en":"If you oscillate between two moods, attitudes, or types of behaviour, you keep changing from one to the other and back again.","ex":{"en":"The president of the Republic oscillated between a certain audacity and a prudent realism.","cn":"该共和国总统施政风格时而大胆冒进，时而谨慎务实。"}}]},"media":{"uk":"media/uk/oscillate__gb_1.mp3","us":"media/us/oscillate__us_1.mp3"},"examples":[{"en":"Watch how the needle on the dial oscillates.","cn":"仔细看仪表盘上的指针如何摆动。"},{"en":"Her moods oscillated between depression and elation.","cn":"她的情绪时而抑郁，时而亢奋。"}]},"obesity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"extremely fat in a way that is dangerous to your health","cn":""},{"en":"the condition of being too fat in a way that is dangerous to your health - used especially in medical contexts","cn":""}]},"media":{"uk":"media/uk/obesity__gb_1.mp3","us":"media/us/obesity__us_1.mp3"},"oxford":{"phon":"əʊˈbiːsəti","pos":"noun","senses":[{"en":"the quality or fact of being very fat, in a way that is not healthy","cn":"肥胖","ex":{"en":"Obesity can increase the risk of heart disease.","cn":"肥胖会增加患心脏病的风险。"}}]}},"overwork":{"media":{"uk":"media/uk/overwork__gb_1.mp3","us":"media/us/overwork__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈwɜːk","pos":"verb","senses":[{"en":"to work too hard; to make a person or an animal work too hard","cn":"（使）过度劳累，过分努力","ex":{"en":"You look tired. Have you been overworking?","cn":"你似乎很疲倦，是不是近来劳累过度了？"}},{"en":"the fact of working too hard","cn":"劳累过度；过分辛苦","ex":{"en":"His illness was brought on by money worries and overwork.","cn":"他的病是因操心钱和劳累过度而造成的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）工作过度；（使）过分劳累","en":"If you overwork or if someone overworks you, you work too hard, and are likely to become very tired or ill.","ex":{"en":"He's overworking and has got a lot on his mind","cn":"他工作太累，而且非常操心。"}}]},"examples":[{"en":"You look tired. Have you been overworking?","cn":"你似乎很疲倦，是不是近来劳累过度了？"},{"en":"His illness was brought on by money worries and overwork.","cn":"他的病是因操心钱和劳累过度而造成的。"}]},"ottoman":{"media":{"uk":"media/uk/ottoman__gb_1.mp3","us":"media/us/ottoman__us_1.mp3"},"oxford":{"phon":"ˈɒtəmən","pos":"noun","senses":[{"en":"a piece of furniture like a large box with a soft top, used for storing things in and sitting on","cn":"褥榻，箱式凳（箱子式的坐凳，有软垫）"},{"en":"a large thick cushion used as a seat or for resting your feet on","cn":"（厚实的）坐垫，脚垫","lab":"both North American English"}]}},"orderly":{"media":{"uk":"media/uk/orderly__gb_1.mp3","us":"media/us/orderly__us_1.mp3"},"oxford":{"phon":"ˈɔːdəli","pos":"adjective","senses":[{"en":"arranged or organized in a neat, careful and logical way","cn":"整洁的；有秩序的；有条理的","ex":{"en":"a calm and orderly life","cn":"平静有序的生活"}},{"en":"behaving well; peaceful","cn":"表现良好的；守秩序的","ex":{"en":"an orderly demonstration","cn":"秩序井然的示威"}},{"en":"a person who works in a hospital, usually doing jobs that do not need any special training","cn":"（医院的）护工，勤杂工","pos":"noun"},{"en":"a soldier who does jobs that do not need any special training","cn":"勤务兵","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有秩序的；按部就班的","en":"If something is done in an orderly fashion or manner, it is done in a well-organized and controlled way.","ex":{"en":"The organizers guided them in orderly fashion out of the building","cn":"组织者引领他们井然有序地走出大楼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"整洁的；有条理的","en":"Something that is orderly is neat or arranged in a neat way.","ex":{"en":"It's a beautiful, clean and orderly city","cn":"这是一座美丽清洁、秩序井然的城市。"}},{"pos":"N-COUNT 可数名词","cn":"（医院的）勤杂工，护理员","en":"An orderly is a person who works in a hospital and does jobs that do not require special medical training."}]},"examples":[{"en":"vegetables planted in orderly rows","cn":"一行行栽种整齐的蔬菜"},{"en":"a calm and orderly life","cn":"平静有序的生活"}]},"october":{"media":{"uk":"media/uk/october__gb_1.mp3","us":"media/us/october__us_1.mp3"},"oxford":{"phon":"ɒkˈtəʊbə(r)","pos":"noun","senses":[{"en":"the 10th month of the year, between September and November","cn":"十月","lab":"British English","ex":{"en":"She was born in October.","cn":"她出生于十月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"十月","en":"October is the tenth month of the year in the Western calendar.","ex":{"en":"Most seasonal hiring is done in early October","cn":"大部分季节性招聘在10月初进行。"}}]}},"off-street":{"oxford":{"phon":"ˈɒf striːt","pos":"adjective","senses":[{"en":"not on the public road","cn":"不在大街上的；大街以外的；路外的；后街的","ex":{"en":"an apartment with off-street parking","cn":"后街街边可停车的公寓"}}]},"media":{"uk":"media/uk/off_street_1_gb_1.mp3","us":"media/us/off_street_1_us_1.mp3"},"examples":[{"en":"an apartment with off-street parking","cn":"有后街街边可停车的公寓"}]},"orchestra":{"media":{"uk":"media/uk/orchestra__gb_1.mp3","us":"media/us/orchestra__us_1.mp3"},"oxford":{"phon":"ˈɔːkɪstrə","pos":"noun","senses":[{"en":"a large group of people who play various musical instruments together, led by a conductor","cn":"管弦乐队","g":"[countable + singular or plural verb]","ex":{"en":"She plays the flute in the school orchestra.","cn":"她在校管弦乐队里吹长笛。"}},{"en":"the seats that are nearest to the stage in a theatre","cn":"（剧场的）正厅前排座位","g":"[singular]","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"管弦乐队","en":"An orchestra is a large group of musicians who play a variety of different instruments together. Orchestras usually play classical music.","ex":{"en":"...the Royal Liverpool Philharmonic Orchestra.","cn":"皇家利物浦爱乐乐团"}},{"pos":"N-SING 单数名词","cn":"（剧院或音乐厅的）正厅前排座位","en":"The orchestra or the orchestra seats in a theatre or concert hall are the seats on the ground floor directly in front of the stage."}]},"examples":[{"en":"She plays the flute in the school orchestra.","cn":"她在校管弦乐队里吹长笛。"},{"en":"the Scottish Symphony Orchestra","cn":"苏格兰交响乐团"}]},"opposed":{"media":{"uk":"media/uk/opposed__gb_1.mp3","us":"media/us/opposed__us_1.mp3"},"oxford":{"phon":"əˈpəʊzd","pos":"adjective","senses":[{"en":"disagreeing strongly with something and trying to stop it","cn":"强烈反对","ex":{"en":"He was strongly opposed to modernism in art.","cn":"他强烈反对艺术中的现代主义。"}},{"en":"very different from something","cn":"截然不同","ex":{"en":"Our views are diametrically opposed on this issue.","cn":"在这个问题上，我们的观点大相径庭。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"反对的；不赞成的","en":"If you are opposed to something, you disagree with it or disapprove of it.","ex":{"en":"I am utterly opposed to any form of terrorism","cn":"我坚决反对任何形式的恐怖主义。"}},{"pos":"ADJ 形容词","cn":"对立的；对抗的；相对的；相反的","en":"You say that two ideas or systems are opposed when they are opposite to each other or very different from each other.","ex":{"en":"...people with policies almost diametrically opposed to his own","cn":"提出与他几乎截然相反的政策的人"}},{"pos":"PHRASE 短语","cn":"而不是","en":"You use as opposed to when you want to make it clear that you are talking about one particular thing and not something else.","ex":{"en":"We ate in the restaurant, as opposed to the bistro.","cn":"我们是在餐厅吃的饭，而不是在小饭馆。"}}]},"examples":[{"en":"200 attended, as opposed to 300 the previous year.","cn":"出席的有 200 人，而前一年是 300 人。"},{"en":"This exercise develops suppleness as opposed to (= rather than) strength.","cn":"这项锻炼不是增强力量，而是增强柔韧性的。"}],"base":"oppose"},"optic":{"media":{"uk":"media/uk/optic__gb_1.mp3","us":"media/us/optic__us_1.mp3"},"oxford":{"phon":"ˈɒptɪk","pos":"adjective","senses":[{"en":"connected with the eye or the sense of sight","cn":"眼的；视觉的","ex":{"en":"the optic nerve (= from the eye to the brain)","cn":"视神经"}},{"en":"a device for measuring out exact amounts of strong alcoholic drinks in a bar","cn":"奥普蒂克量杯（酒吧用以量烈性酒）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"眼的；视力的；视觉的","en":"Optic means relating to the eyes or to sight.","ex":{"en":"The reason for this is that the optic nerve is a part of the brain.","cn":"这其中的原因在于视神经是大脑的一部分。"}}]},"examples":[{"en":"the optic nerve (= from the eye to the brain)","cn":"视神经"},{"en":"the optic nerve","cn":"视神经"}]},"outright":{"media":{"uk":"media/uk/outright__gb_1.mp3","us":"media/us/outright__us_1.mp3"},"oxford":{"phon":"ˈaʊtraɪt","pos":"adjective","senses":[{"en":"complete and total","cn":"完全的；彻底的；绝对的","ex":{"en":"an outright ban/rejection/victory","cn":"完全禁止；断然拒绝；彻底胜利"}},{"en":"open and direct","cn":"公开的；直率的；直截了当的","ex":{"en":"There was outright opposition to the plan.","cn":"该计划遭到公开直接反对。"}},{"en":"in a direct way and without trying to hide anything","cn":"公开地；直率地；毫无保留地","ex":{"en":"Why don't you ask him outright if it's true?","cn":"你为什么不直截了当地问他那是否属实？"},"pos":"adverb"},{"en":"clearly and completely","cn":"完全彻底；干净利落","ex":{"en":"Neither candidate won outright.","cn":"两个候选人谁也没干脆利落地获胜。"},"pos":"adverb"},{"en":"not gradually; immediately","cn":"一下子；骤然间；立即","ex":{"en":"Most of the crash victims were killed outright.","cn":"飞机坠毁的遇难者大都是当场死亡。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"直率的；公开的；直截了当的","en":"You use outright to describe behaviour and actions that are open and direct, rather than indirect.","ex":{"en":"Kawaguchi finally resorted to an outright lie.","cn":"川口最后干脆睁着眼睛说瞎话。"}},{"pos":"ADJ 形容词","cn":"完全的；彻底的；全部的","en":"Outright means complete and total.","ex":{"en":"She had failed to win an outright victory","cn":"她没能大获全胜。"}}]},"examples":[{"en":"We had saved enough money to buy the house outright.","cn":"我们存了足够的钱，能一次付清款项买下这所房子。"},{"en":"Why don't you ask him outright if it's true?","cn":"你为什么不直截了当地问他那是否属实？"}]},"occasional":{"media":{"uk":"media/uk/occasional__gb_1.mp3","us":"media/us/occasional__us_1.mp3"},"oxford":{"phon":"əˈkeɪʒənl","pos":"adjective","senses":[{"en":"happening or done sometimes but not often","cn":"偶尔的；偶然的；临时的","ex":{"en":"He works for us on an occasional basis.","cn":"他在我们这里做临时工。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偶尔的；间或的；有时发生的","en":"Occasional means happening sometimes, but not regularly or often.","ex":{"en":"I've had occasional mild headaches all my life","cn":"间或发作的轻微头疼困扰了我一辈子。"}}]},"examples":[{"en":"He spent five years in Paris, with occasional visits to Italy.","cn":"他在巴黎过了五年，偶尔去一去意大利。"},{"en":"I enjoy the occasional glass of wine.","cn":"我喜欢偶尔喝一杯葡萄酒。"}]},"overlaps":{"lemma":"overlap","media":{"uk":"media/uk/overlap__gb_1.mp3","us":"media/us/overlap__us_1.mp3"}},"olive":{"media":{"uk":"media/uk/olive__gb_1.mp3","us":"media/us/olive__us_1.mp3"},"oxford":{"phon":"ˈɒlɪv","pos":"noun","senses":[{"en":"a small green or black fruit with a strong taste, which is eaten or used for its oil","cn":"油橄榄；齐墩果；橄榄","g":"[countable]"},{"en":"a tree on which olives grow","cn":"橄榄树","g":"[countable]","ex":{"en":"olive groves","cn":"橄榄树丛"}},{"en":"a grey-green colour","cn":"橄榄绿","g":"[uncountable]"},{"en":"grey-green in colour","cn":"橄榄绿的","ex":{"en":"a dark olive green carpet","cn":"深橄榄绿地毯"},"pos":"adjective"},{"en":"yellow-brown in colour","cn":"黄褐色的；淡褐色的","ex":{"en":"an olive complexion","cn":"浅褐色的面容"},"pos":"adjective"},{"en":"a first name for girls","cn":"奥利芙（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"橄榄","en":"Olives are small green or black fruit with a bitter taste. Olives are often pressed to make olive oil."},{"pos":"N-COUNT 可数名词","cn":"橄榄树","en":"An olive tree or an olive is a tree on which olives grow.","ex":{"en":"Olives look romantic on a hillside in Provence.","cn":"普罗旺斯一处山坡上的橄榄林呈现出一派浪漫风情。"}},{"pos":"COLOUR 颜色词","cn":"橄榄色；茶青色；黄绿色","en":"Something that is olive is yellowish-green in colour.","ex":{"en":"...glowing colours such as deep red, olive, saffron and ochre.","cn":"诸如深红色、橄榄色、藏红花色、赭色等鲜艳的颜色"}},{"pos":"ADJ 形容词","cn":"（皮肤）橄榄色的，浅褐色的","en":"If someone has olive skin, the colour of their skin is light brown.","ex":{"en":"They are handsome with dark, shining hair, olive skin and fine brown eyes.","cn":"他们乌黑闪亮的头发、橄榄色的皮肤和迷人的棕色眼睛令他们看上去非常帅气。"}}]},"examples":[{"en":"an olive complexion","cn":"浅褐色的面容"},{"en":"olive groves","cn":"橄榄树丛"}]},"once":{"media":{"uk":"media/uk/once__gb_1.mp3","us":"media/us/once__us_1.mp3"},"oxford":{"phon":"wʌns","pos":"adverb","senses":[{"en":"on one occasion only; one time","cn":"仅一次；一次","lab":"informal","ex":{"en":"I've only been there once.","cn":"我只去过那里一次。"}},{"en":"at some time in the past","cn":"曾；曾经","ex":{"en":"I once met your mother.","cn":"我曾经见过你母亲。"}},{"en":"used in negative sentences and questions, and after if to mean ‘ever’ or ‘at all’","cn":"（用于否定句、疑问句和 if 后）曾，根本","ex":{"en":"He never once offered to help.","cn":"他从没有主动提出过帮忙。"}},{"en":"used with a preposition or another adverb to mean ‘as soon as somebody/something is/was’","cn":"一旦…（就…）；一…（就…）","ex":{"en":"Once inside the gate, Sam hurried up the path.","cn":"一进大门，萨姆就沿着小路匆匆而上。"}},{"en":"as soon as; when","cn":"一…就；一旦；当…时候","ex":{"en":"We didn't know how we would cope once the money had gone.","cn":"一旦钱花光了，我们就不知道该怎么办了。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"一次；一回","en":"If something happens once, it happens one time only.","ex":{"en":"I met Wilma once, briefly","cn":"我曾经和威尔玛有过短短的一面之缘。"}},{"pos":"ADV 副词","cn":"（与后接day, week, month等的a连用）（每…）一次，（每…）一回","en":"You use once with 'a' and words like 'day', 'week', and 'month' to indicate that something happens regularly, one time in each day, week, or month.","ex":{"en":"Lung cells die and are replaced about once a week","cn":"肺细胞约每周新老更替一次。"}},{"pos":"ADV 副词","cn":"（与后接day, week, year等的every连用）（每隔…）一次，（每隔…）一回","en":"You use once with 'every' and words like 'day', 'week', and 'year' to indicate that something happens a specified number of times and on a regular basis.","ex":{"en":"The patient was seen for follow-up visits once every three months","cn":"这位病人每三个月接受一次随访就诊。"}},{"pos":"ADV 副词","cn":"曾经，一度（状况如此）","en":"If something was once true, it was true at some time in the past, but is no longer true.","ex":{"en":"The culture minister once ran a theatre","cn":"这位文化部长曾经经营过一家剧院。"}},{"pos":"ADV 副词","cn":"曾经（做过某事）","en":"If someone once did something, they did it at some time in the past.","ex":{"en":"I once went camping at Lake Darling with a friend","cn":"我曾和一位朋友在达令湖畔露营。"}},{"pos":"CONJ-SUBORD 连词","cn":"一旦…（就…); 一…（就…）","en":"If something happens once another thing has happened, it happens immediately afterwards.","ex":{"en":"The decision had taken about 10 seconds once he'd read a market research study","cn":"在他看过一份市场调研报告后大概10秒钟就作出了决定。"}},{"pos":"PHRASE 短语","cn":"突然；忽然","en":"If something happens all at once, it happens suddenly, often when you are not expecting it to happen.","ex":{"en":"I feel terribly sleepy all at once","cn":"我突然觉得特别困。"}},{"pos":"PHRASE 短语","cn":"立即；马上","en":"If you do something at once, you do it immediately.","ex":{"en":"I have to go, I really must, at once","cn":"我得走了，我真的必须马上就走。"}},{"pos":"PHRASE 短语","cn":"同时；一起","en":"If a number of different things happen at once or all at once, they all happen at the same time.","ex":{"en":"You can't be doing two things at once","cn":"不能一心二用。"}},{"pos":"PHRASE 短语","cn":"就此一次；破例一次","en":"For once is used to emphasize that something happens on this particular occasion, especially if it has never happened before, and may never happen again.","ex":{"en":"For once, dad is not complaining","cn":"爸爸这次破天荒地没有抱怨。"}},{"pos":"PHRASE 短语","cn":"又一次；再次","en":"If something happens once again or once more, it happens again.","ex":{"en":"Amy picked up the hairbrush and smoothed her hair once more","cn":"埃米拿起发梳，再次将头发梳理整齐。"}},{"pos":"PHRASE 短语","cn":"彻底地；一劳永逸地","en":"If something happens once and for all, it happens completely or finally.","ex":{"en":"We have to resolve this matter once and for all","cn":"我们必须彻底解决这一问题。"}},{"pos":"PHRASE 短语","cn":"偶尔；间或","en":"If something happens once in a while, it happens sometimes, but not very often.","ex":{"en":"Earrings need to be taken out and cleaned once in a while.","cn":"耳环要偶尔取出来清洗一下。"}},{"pos":"PHRASE 短语","cn":"一两次；几次","en":"If you have done something once or twice, you have done it a few times, but not very often.","ex":{"en":"I popped my head round the door once or twice","cn":"我有几次头撞到了门上。"}},{"pos":"PHRASE 短语","cn":"（常用于儿童故事的开头）从前，很久以前","en":"Once upon a time is used to indicate that something happened or existed a long time ago or in an imaginary world. It is often used at the beginning of children's stories.","ex":{"en":"'Once upon a time,' he began, 'there was a man who had everything.'","cn":"“很久很久以前，”他开始说道，“有这么一个人，他应有尽有。”"}},{"pos":"","cn":"","en":"once in a blue moon→see: ;"}]},"examples":[{"en":"If she once decides to do something, you won't change her mind.","cn":"她一旦决定干什么，谁也改变不了她的主意。"},{"en":"We didn't know how we would cope once the money had gone.","cn":"一旦钱花光了，我们就不知道该怎么办了。"}]},"outstanding":{"media":{"uk":"media/uk/outstanding__gb_1.mp3","us":"media/us/outstanding__us_1.mp3"},"oxford":{"phon":"aʊtˈstændɪŋ","pos":"adjective","senses":[{"en":"extremely good; excellent","cn":"优秀的；杰出的；出色的","ex":{"en":"an outstanding player/achievement/success","cn":"杰出的运动员／成绩／成就"}},{"en":"not yet paid, done, solved, etc.","cn":"未支付的；未完成的；未解决的","ex":{"en":"She has outstanding debts of over £500.","cn":"她未清偿的债务超过 500 英镑。"}},{"en":"very obvious or important","cn":"突出的；明显的；重要的","g":"[usually before noun]","ex":{"en":"the outstanding features of the landscape","cn":"这一景观的突出特征"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"杰出的；出众的；优秀的","en":"If you describe someone or something as outstanding, you think that they are very remarkable and impressive.","ex":{"en":"Derartu is an outstanding athlete and deserved to win.","cn":"德拉尔图是位优秀的运动员，赢得比赛也是理所当然。"}},{"pos":"ADJ 形容词","cn":"（款项）未支付的，未结清的","en":"Money that is outstanding has not yet been paid and is still owed to someone.","ex":{"en":"The total debt outstanding is $70 billion","cn":"未偿债务总额达700亿美元。"}},{"pos":"ADJ 形容词","cn":"未解决的；未完成的","en":"Outstanding issues or problems have not yet been resolved.","ex":{"en":"We still have some outstanding issues to resolve before we'll have a treaty that is ready to sign.","cn":"我们签协议之前还有一些未尽事宜待解决。"}},{"pos":"ADJ 形容词","cn":"重要的；显著的；突出的","en":"Outstanding means very important or obvious.","ex":{"en":"The company is an outstanding example of a small business that grew into a big one","cn":"该公司是小企业成长为大企业的突出例子。"}}]},"examples":[{"en":"She has outstanding debts of over £500.","cn":"她未清偿的债务超过 500 英镑。"},{"en":"an area of outstanding natural beauty","cn":"自然风景极美的地区"}]},"offend":{"oxford":{"phon":"əˈfend","pos":"verb","senses":[{"en":"to make somebody feel upset because of something you say or do that is rude or embarrassing","cn":"得罪；冒犯","g":"[transitive, often passive, intransitive]","ex":{"en":"They'll be offended if you don't go to their wedding.","cn":"你若不参加他们的婚礼，他们会生气的。"}},{"en":"to seem unpleasant to somebody","cn":"令人不适","g":"[transitive]","ex":{"en":"The smell from the farm offended some people.","cn":"农场散发的气味让一些人闻了不舒服。"}},{"en":"to commit a crime or crimes","cn":"犯罪；犯法","g":"[intransitive]","lab":"formal","ex":{"en":"He started offending at the age of 16.","cn":"他 16 岁就开始犯法。"}},{"en":"to be against what people believe is morally right","cn":"违背（人情）；违反（常理）；有悖于","g":"[intransitive]","lab":"formal","ex":{"en":"comments that offend against people’s religious beliefs","cn":"有悖人民宗教信仰的评论"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"冒犯；得罪；触怒","en":"If you offend someone, you say or do something rude which upsets or embarrasses them.","ex":{"en":"He apologizes for his comments and says he had no intention of offending the community","cn":"他为自己发表的评论道歉并称无意冒犯该社群。"}},{"pos":"VERB 动词","cn":"违反，违犯，违背（法律、规定、原则等）","en":"To offend against a law, rule, or principle means to break it.","ex":{"en":"This bill offends against good sense and against justice","cn":"该法案有悖于理智和公正。"}},{"pos":"VERB 动词","cn":"犯罪；犯法","en":"If someone offends, they commit a crime.","ex":{"en":"In Western countries girls are far less likely to offend than boys.","cn":"在西方国家，女孩的犯罪倾向远低于男孩。"}}]},"media":{"uk":"media/uk/offend__gb_1.mp3","us":"media/us/offend__us_1.mp3"},"examples":[{"en":"They'll be offended if you don't go to their wedding.","cn":"你若不参加他们的婚礼，他们会生气的。"},{"en":"The smell from the farm offended some people.","cn":"农场散发的气味让一些人闻了不舒服。"}]},"occasionally":{"media":{"uk":"media/uk/occasionally__gb_1.mp3","us":"media/us/occasionally__us_1.mp3"},"oxford":{"phon":"əˈkeɪʒnəli","pos":"adverb","senses":[{"en":"sometimes but not often","cn":"偶尔；偶然；有时","ex":{"en":"We occasionally meet for a drink after work.","cn":"我们下班后偶尔相聚小酌。"}}]},"examples":[{"en":"This type of allergy can very occasionally be fatal.","cn":"这类过敏症在极个别情况下有可能是致命的。"},{"en":"We occasionally meet for a drink after work.","cn":"我们下班后偶尔相聚小酌。"}]},"overcome":{"media":{"uk":"media/uk/overcome__gb_1.mp3","us":"media/us/overcome__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈkʌm","pos":"verb","senses":[{"en":"to succeed in dealing with or controlling a problem that has been preventing you from achieving something","cn":"克服；解决","ex":{"en":"She overcame injury to win the Olympic gold medal.","cn":"她战胜了伤痛，赢得了奥运会金牌。"}},{"en":"to defeat somebody","cn":"战胜","ex":{"en":"In the final game Sweden easily overcame France.","cn":"在决赛中，瑞典队轻松战胜了法国队。"}},{"en":"to affect somebody very strongly","cn":"使受巨大影响；使难以承受","g":"[usually passive]","ex":{"en":"Her parents were overcome with grief at the funeral.","cn":"在葬礼上她的父母悲痛欲绝。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"克服；控制；战胜","en":"If you overcome a problem or a feeling, you successfully deal with it and control it.","ex":{"en":"Molly had fought and overcome her fear of flying","cn":"莫莉已经努力克服了对飞行的恐惧。"}},{"pos":"VERB 动词","cn":"（感情上）受到极大影响，承受不起","en":"If you are overcome by a feeling or event, it is so strong or has such a strong effect that you cannot think clearly.","ex":{"en":"The night before the test I was overcome by fear and despair","cn":"考试前的晚上，恐惧和绝望让我内心无比惊慌。"}},{"pos":"VERB 动词","cn":"（烟、毒气等）熏倒，使受不了","en":"If you are overcome by smoke or a poisonous gas, you become very ill or die from breathing it in.","ex":{"en":"The residents were trying to escape from the fire but were overcome by smoke.","cn":"居民试图逃离火场，却被浓烟熏倒了。"}}]},"examples":[{"en":"The two parties managed to overcome their differences on the issue.","cn":"两个政党设法弥合了在这个问题上的分歧。"},{"en":"In the final game Sweden easily overcame France.","cn":"在决赛中，瑞典队轻松战胜了法国队。"}]},"oxford":{"media":{"uk":"media/uk/oxford__gb_1.mp3","us":"media/us/oxford__us_1.mp3"},"oxford":{"phon":"ˈɒksfəd","pos":"noun","senses":[{"en":"leather shoes that fasten with laces","cn":"牛津鞋（一种系鞋带的皮鞋）","g":"[plural]","lab":"especially North American English"},{"en":"a type of heavy cotton cloth used mainly for making shirts","cn":"牛津布（厚棉布，主要做衬衫用）","g":"[uncountable]","lab":"North American English","ex":{"en":"an oxford shirt","cn":"一件牛津布衬衣"}},{"en":"a city in southern England, west of London, and the administrative centre of Oxfordshire. Oxford is famous for its university, the oldest in Britain, established in the middle of the 12th century. The buildings of its many colleges are a major feature of the city, which is a tourist centre as well as an important centre of academic research. It is also an industrial city, and was the home for the Morris car factory.","cn":"牛津（英格兰南部城市，位于伦敦西北，牛津郡的行政中心。牛津以其大学闻名，建于 12 世纪中叶的牛津大学是英国最古老的大学，许多学院的建筑是牛津的一大特色。牛津是旅游胜地、重要的学术研究中心，也是工业城市，曾是莫里斯汽车厂所在地）","pos":""}]},"examples":[{"en":"an oxford shirt","cn":"一件牛津布衬衣"}]},"oyster":{"media":{"img":["media/pic/shellfish_comp.jpg","media/thumb/oyster.jpg"],"uk":"media/uk/oyster__gb_1.mp3","us":"media/us/oyster__us_1.mp3"},"oxford":{"phon":"ˈɔɪstə(r)","pos":"noun","senses":[{"en":"a large flat shellfish. Some types of oyster can be eaten and others produce shiny white jewels called pearls.","cn":"牡蛎；蚝","ex":{"en":"Oyster beds, on the mudflats, are a form of fish farming.","cn":"滩涂牡蛎养殖是一种水产养殖方式。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牡蛎；蚝","en":"An oyster is a large flat shellfish. Some oysters can be eaten and others produce valuable objects called pearls.","ex":{"en":"He had two dozen oysters and enjoyed every one of them.","cn":"他吃了两打牡蛎，每一只都吃得津津有味。"}},{"pos":"PHRASE 短语","cn":"世界是属于…的；尽可做想做之事（或去想去之处）","en":"If you say that the world is someone's oyster, you mean that they can do anything or go anywhere that they want to.","ex":{"en":"You're young, you've got a lot of opportunity. The world is your oyster.","cn":"你还年轻，机会有的是。世界是属于你的。"}}]},"examples":[{"en":"Oyster beds, on the mudflats, are a form of fish farming.","cn":"滩涂牡蛎养殖场是一种水产养殖方式。"}]},"over":{"media":{"uk":"media/uk/over__gb_1.mp3","us":"media/us/over__us_1.mp3"},"oxford":{"phon":"ˈəʊvə(r)","pos":"preposition","senses":[{"en":"resting on the surface of somebody/something and partly or completely covering them/it","cn":"（部分或全部覆盖）在…上面","ex":{"en":"She put a blanket over the sleeping child.","cn":"她给熟睡的孩子盖上毯子。"}},{"en":"in or to a position higher than but not touching somebody/something; above somebody/something","cn":"悬在…上面；向…上方","ex":{"en":"They held a large umbrella over her.","cn":"他们给她撑起一把大伞。"}},{"en":"from one side of something to the other; across something","cn":"从一边到另一边；穿越","ex":{"en":"a bridge over the river","cn":"横跨河面的桥"}},{"en":"so as to cross something and be on the other side","cn":"到另一边；翻越","ex":{"en":"She climbed over the wall.","cn":"她翻过墙去。"}},{"en":"falling from or down from a place","cn":"从…落下","ex":{"en":"The car had toppled over the cliff.","cn":"汽车从山崖上跌落下去了。"}},{"en":"on the far or opposite side of something","cn":"在…的远端（或对面）","ex":{"en":"He lives over the road.","cn":"他住在马路对面。"}},{"en":"in or on all or most parts of something","cn":"遍及","ex":{"en":"Snow is falling all over the country.","cn":"全国各地都在下雪。"}},{"en":"more than a particular time, amount, cost, etc.","cn":"多于（某时间、数量、花费等）","ex":{"en":"over 3 million copies sold","cn":"售出三百多万册"}},{"en":"used to show that somebody has control or authority","cn":"（表示能控制、有权威）","ex":{"en":"She has only the director over her.","cn":"她的上司只有主任一个。"}},{"en":"during something","cn":"在…期间","ex":{"en":"We'll discuss it over lunch.","cn":"我们将在吃午饭时商量此事。"}},{"en":"past a particular difficult stage or situation","cn":"渡过（困难阶段或局面）","ex":{"en":"We're over the worst of the recession.","cn":"我们已渡过了经济衰退的最艰难时期。"}},{"en":"because of or relating to something; about something","cn":"由于；关于","ex":{"en":"an argument over money","cn":"为了钱的争吵"}},{"en":"using something; by means of something","cn":"利用；通过","ex":{"en":"We heard it over the radio.","cn":"我们从广播中听到的。"}},{"en":"louder than something","cn":"声音大于","ex":{"en":"I couldn't hear what he said over the noise of the traffic.","cn":"交通噪声太大，我听不清他说的话。"}},{"en":"across a street, an open space, etc.","cn":"穿过（街道、开阔的空间等）","ex":{"en":"I stopped and crossed over.","cn":"我停下来，走到对面。"},"pos":"adverb"},{"en":"downwards and away from the correct position standing upright","cn":"（从直立位置）翻倒，倒下","ex":{"en":"Try not to knock that vase over.","cn":"小心别把那个花瓶碰倒了。"},"pos":"adverb"},{"en":"from one side to another side","cn":"从一侧到另一侧；翻转","ex":{"en":"She turned over onto her front.","cn":"她翻过身俯卧着。"},"pos":"adverb"},{"en":"so as to cover somebody/something completely","cn":"完全覆盖（某人或某物）","ex":{"en":"The lake was frozen over.","cn":"湖面完全封冻了。"},"pos":"adverb"},{"en":"above; more","cn":"以上；大于；多于","ex":{"en":"children of 14 and over","cn":"14 岁及 14 岁以上的儿童"},"pos":"adverb"},{"en":"not used or needed","cn":"剩余；未用；不需要","ex":{"en":"If there's any food left over, put it in the fridge.","cn":"要是有剩下的饭菜，就放到冰箱里。"},"pos":"adverb"},{"en":"ended","cn":"结束","ex":{"en":"By the time we arrived the meeting was over.","cn":"我们到达时，会议已经结束了。"},"pos":"adverb"},{"en":"again","cn":"又；再；重新","lab":"North American English","ex":{"en":"He repeated it several times over until he could remember it.","cn":"他重复了几遍直到能记住为止。"},"pos":"adverb"},{"en":"used to talk about somebody/something changing position","cn":"（表示位置变换）改变，掉换","ex":{"en":"He's gone over to the enemy (= joined them).","cn":"他已变节投敌。"},"pos":"adverb"},{"en":"used when communicating by radio","cn":"（用于无线通话）完毕","ex":{"en":"Message received. Over (= it is your turn to speak).","cn":"消息收到了。完毕。"},"pos":"adverb"},{"en":"a series of six balls bowled by the same person","cn":"一轮投球（同一个投球手连续投出的六个球）","ex":{"en":"Chadwick dismissed two batsmen in the same over.","cn":"查德威克在同一轮中解雇了两名击球手。"},"pos":"noun"},{"en":"more than usual; too much","cn":"太；过于","ex":{"en":"overproduction","cn":"生产过剩"},"pos":"prefix"},{"en":"completely","cn":"完全；全面；整体地","ex":{"en":"overjoyed","cn":"十分高兴"},"pos":"prefix"},{"en":"upper; outer; extra","cn":"上面；外面；额外","ex":{"en":"overcoat","cn":"长大衣"},"pos":"prefix"},{"en":"over; above","cn":"上方；上空","ex":{"en":"overcast","cn":"阴云密布"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…的上方；在…的上面；在…的上空","en":"If one thing is over another thing or is moving over it, the first thing is directly above the second, either resting on it, or with a space between them.","ex":{"en":"He looked at himself in the mirror over the table.","cn":"他对着桌子上方的镜子照了照。"}},{"pos":"PREP 介词","cn":"搭挂在…的上面","en":"If one thing is over another thing, it is supported by it and its ends are hanging down on each side of it.","ex":{"en":"A grey mackintosh was folded over her arm","cn":"她胳膊上搭着一件灰色雨衣。"}},{"pos":"PREP 介词","cn":"（部分或完全地）覆盖在…的上面","en":"If one thing is over another thing, it covers part or all of it.","ex":{"en":"His hair fell over his brow instead of being brushed straight back","cn":"他的头发没有整齐地往后梳，而是搭在前额。"}},{"pos":"PREP 介词","cn":"（身体上部）俯在…的上面","en":"If you lean over an object, you bend your body so that the top part of it is above the object.","ex":{"en":"They stopped to lean over a gate","cn":"他们停下来，身子探过一扇栅栏门。"}},{"pos":"PREP 介词","cn":"从…上面（看过去）；隔着…（交谈）","en":"If you look over or talk over an object, you look or talk across the top of it.","ex":{"en":"I went and stood beside him, looking over his shoulder.","cn":"我走过去站在他身边，从他的肩头望过去。"}},{"pos":"PREP 介词","cn":"(从…)可以看见;俯瞰","en":"If a window has a view over an area of land or water, you can see the land or water through the window.","ex":{"en":"...a light and airy bar with a wonderful view over the River Amstel","cn":"可将阿姆斯特尔河美景尽收眼底的明亮通风的酒吧"}},{"pos":"PREP 介词","cn":"（穿）过，（跨）过，（越）过（障碍、边界等）","en":"If someone or something goes over a barrier, obstacle, or boundary, they get to the other side of it by going across it, or across the top of it.","ex":{"en":"Policemen jumped over the wall of the Spanish Embassy in pursuit","cn":"警察在追捕中跳过西班牙大使馆的围墙。"}},{"pos":"PREP 介词","cn":"从一边至…的另一边","en":"If someone or something moves over an area or surface, they move across it, from one side to the other.","ex":{"en":"She ran swiftly over the lawn to the gate","cn":"她一溜烟穿过草地跑到了大门口。"}},{"pos":"PREP 介词","cn":"在…的另一边；在…的对面","en":"If something is on the opposite side of a road or river, you can say that it is over the road or river.","ex":{"en":"...Richard Garrick, who lived in the house over the road.","cn":"住在马路对面那所房子里的理查德·加里克"}},{"pos":"ADV 副词","cn":"去，到（某处）","en":"If you go over to a place, you go to that place.","ex":{"en":"I got out the car and drove over to Dervaig","cn":"我把车开出来，驶向德韦格。"}},{"pos":"ADV 副词","cn":"在那边；在近旁","en":"You can use over to indicate a particular position or place a short distance away from someone or something.","ex":{"en":"He noticed Rolfe standing silently over by the window","cn":"他注意到罗尔夫一声不吭地站在窗户旁边。"}},{"pos":"ADV 副词","cn":"（突然或猛力地）（倒）下，（掉）下","en":"You use over to say that someone or something falls towards or onto the ground, often suddenly or violently.","ex":{"en":"If he drinks more than two glasses of wine he falls over","cn":"他喝酒超过两杯就会醉倒在地。"}},{"pos":"ADV 副词","cn":"（翻）转过来","en":"If something rolls over or is turned over, its position changes so that the part that was facing upwards is now facing downwards. →see usage note at:","ex":{"en":"His car rolled over after a tyre was punctured","cn":"一只轮胎被扎破后，他的车翻了个底朝天。"}},{"pos":"PREP-PHRASE 短语介词","cn":"到处；遍及","en":"All over a place means in every part of it.","ex":{"en":"...doctors who work all over the country.","cn":"在全国各地工作的医生"}},{"pos":"PHRASE 短语","cn":"在这边；到这边；在身处国","en":"Over here means near you, or in the country you are in.","ex":{"en":"Why don't you come over here tomorrow evening","cn":"你明天晚上过来吧。"}},{"pos":"PHRASE 短语","cn":"在那边；到那边；在另一国","en":"Over there means in a place a short distance away from you, or in another country.","ex":{"en":"The cafe is just across the road over there","cn":"咖啡馆就在那边马路对面。"}},{"pos":"","cn":"","en":"the world over→see: ;"},{"pos":"PREP 介词","cn":"超过；在…以上","en":"If something is over a particular amount, measurement, or age, it is more than that amount, measurement, or age.","ex":{"en":"Cigarettes kill over a hundred thousand Britons every year","cn":"每年香烟夺去10万多英国人的生命。"}},{"pos":"PREP-PHRASE 短语介词","cn":"多于（正常数量）；除了…之外（还）","en":"Over and above an amount, especially a normal amount, means more than that amount or in addition to it.","ex":{"en":"Expenditure on education has gone up by seven point eight per cent over and above inflation","cn":"扣除通货膨胀因素，教育支出实际增长了7.8%。"}},{"pos":"ADV 副词","cn":"剩余；剩下","en":"If you say that you have some food or money over, you mean that it remains after you have used all that you need.","ex":{"en":"Larsons pay me well enough, but there's not much over for luxuries when there's two of you to live on it","cn":"拉森公司给我的薪水算是不错，但是两个人靠这份工资生活便没有多少闲钱买奢侈品了。"}},{"pos":"ADV 副词","cn":"再一次;又一次；重复地","en":"If you do something over, you do it again or start doing it again from the beginning.","ex":{"en":"She said if she had the chance to do it over, she would have hired a press secretary","cn":"她说如果有机会从头来过，她会雇一位新闻秘书。"}},{"pos":"PHRASE 短语","cn":"（强调发生不止一次）两次/三次","en":"If you say that something happened twice over ,three times over and so on, you are stating the number of times that it happened and emphasizing that it happened more than once.","ex":{"en":"He had to have everything spelled out twice over for him.","cn":"他不得不把所有事项都对他详细说明了两次。"}},{"pos":"PHRASE 短语","cn":"再一次；重新","en":"If you do something over again, you do it again or start doing it again from the beginning.","ex":{"en":"When you realise they are singing the same songs over again, the novelty wears off","cn":"当你意识到他们开始从头演唱同样的歌曲时，新鲜感也就没有了。"}},{"pos":"PHRASE 短语","cn":"（指令人疲倦、厌烦、不快地）再一次，又一次，重新","en":"If you say that something is happening all over again, you are emphasizing that it is happening again, and you are suggesting that it is tiring, boring, or unpleasant.","ex":{"en":"He doesn't want the hassle all over again","cn":"他不想再惹这种麻烦了。"}},{"pos":"PHRASE 短语","cn":"一再；再三；反复","en":"If you say that something happened over and over or over and over again, you are emphasizing that it happened many times.","ex":{"en":"He plays the same songs over and over","cn":"他一遍又一遍地放着同样的歌曲。"}},{"pos":"ADJ 形容词","cn":"结束的；完了的","en":"If an activity is over or all over, it is completely finished.","ex":{"en":"Warplanes that have landed there will be kept until the war is over","cn":"降落在那里的战斗机将一直扣留到战争结束。"}},{"pos":"PREP 介词","cn":"从（某一疾病或经历）中恢复过来","en":"If you are over an illness or an experience, it has finished and you have recovered from its effects.","ex":{"en":"I'm glad that you're over the flu","cn":"你的流感好了，我真高兴。"}},{"pos":"PREP 介词","cn":"（控制或影响）对…起作用","en":"If you have control or influence over someone or something, you are able to control them or influence them.","ex":{"en":"He's never had any influence over her","cn":"他从未对她有过任何影响力。"}},{"pos":"PREP 介词","cn":"关于；由于","en":"You use over to indicate what a disagreement or feeling relates to or is caused by.","ex":{"en":"The women were making a fuss over nothing.","cn":"这些女人是在无谓地小题大做。"}},{"pos":"PREP 介词","cn":"在…期间","en":"If something happens over a particular period of time or over something such as a meal, it happens during that time or during the meal.","ex":{"en":"The number of attacks on the capital had gone down over the past week","cn":"上一周对首都的袭击次数已经减少了。"}},{"pos":"PREP 介词","cn":"通过（电话、广播等）","en":"You use over to indicate that you give or receive information using a telephone, radio, or other piece of electrical equipment.","ex":{"en":"I'm not prepared to discuss this over the telephone","cn":"我不想在电话里讨论这件事。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（广播或电视节目中的主持人用语）下面交给…","en":"The presenter of a radio or television programme says 'over to someone' to indicate the person who will speak next.","ex":{"en":"With the rest of the sports news, over to Colin Maitland.","cn":"下面由科林·梅特兰接着为大家播报其他体育新闻。"}},{"pos":"CONVENTION 惯用语","cn":"（无线电通讯用语）完毕，请回答","en":"When people such as the police or the army are using a radio to communicate, they say 'Over' to indicate that they have finished speaking and are waiting for a reply."},{"pos":"N-COUNT 可数名词","cn":"（板球运动中）一轮6个（未让对方得分的）有效投球","en":"In cricket, an over consists of six correctly bowled balls.","ex":{"en":"At the start of the last over, bowled by Chris Lewis, the Welsh county were favourites.","cn":"在最后一轮由克里斯·刘易斯连续投出6个有效球之前，威尔士郡队本来胜券在握。"}}]},"examples":[{"en":"He did the work so badly that I had to do it all over again myself.","cn":"他活做得太糟糕了，我只好亲自从头再做一次。"},{"en":"They had a wonderful view over the park.","cn":"他们放眼望去，把公园美丽的景色尽收眼底。"}]},"overwhelming":{"media":{"uk":"media/uk/overwhelming__gb_1.mp3","us":"media/us/overwhelming__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈwelmɪŋ","pos":"adjective","senses":[{"en":"very great or very strong; so powerful that you cannot resist it or decide how to react","cn":"巨大的；压倒性的；无法抗拒的","ex":{"en":"The evidence against him was overwhelming.","cn":"对他不利的证据确凿，无法抵赖。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极强烈的；势不可挡的；令人不知所措的","en":"If something is overwhelming, it affects you very strongly, and you do not know how to deal with it.","ex":{"en":"The task won't feel so overwhelming if you break it down into small, easy-to-accomplish steps","cn":"如果将这个任务细分为简单易行的若干步骤来做，便不会感到如此无所适从。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量）巨大的，压倒性的","en":"You can use overwhelming to emphasize that an amount or quantity is much greater than other amounts or quantities.","ex":{"en":"The overwhelming majority of small businesses go broke within the first twenty-four months","cn":"绝大多数小企业在头两年内就破产了。"}}]},"examples":[{"en":"The evidence against him was overwhelming.","cn":"对他不利的证据确凿，无法抵赖。"},{"en":"The overwhelming majority of those present were in favour of the plan.","cn":"绝大多数与会者都赞同这个计划。"}],"base":"overwhelm"},"outer":{"oxford":{"phon":"ˈaʊtə(r)","pos":"adjective","senses":[{"en":"on the outside of something","cn":"外表的；外边的","ex":{"en":"the outer layers of the skin","cn":"皮肤表层"}},{"en":"furthest from the inside or centre of something","cn":"远离中心的；外围的","lab":"figurative","ex":{"en":"I walked along the outer edge of the track.","cn":"我沿着跑道的外缘走。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"外面的；外部的；远离中心的","en":"The outer parts of something are the parts which contain or enclose the other parts, and which are furthest from the centre.","ex":{"en":"He heard a voice in the outer room.","cn":"他听到外屋有人说话。"}}]},"media":{"uk":"media/uk/outer__gb_1.mp3","us":"media/us/outer__us_1.mp3"},"examples":[{"en":"I walked along the outer edge of the track.","cn":"我沿着跑道的外缘走。"},{"en":"( figurative ) to explore the outer (= most extreme) limits of human experience","cn":"探索人类经验的极限"}]},"outline":{"media":{"uk":"media/uk/outline__gb_1.mp3","us":"media/us/outline__us_1.mp3"},"oxford":{"phon":"ˈaʊtlaɪn","pos":"verb","senses":[{"en":"to give a description of the main facts or points involved in something","cn":"概述；略述","ex":{"en":"He outlined his plan to leave St. Petersburg.","cn":"他简单讲述了他离开圣彼得堡的计划。"}},{"en":"to show or mark the outer edge of something","cn":"显示…的轮廓；勾勒…的外形","g":"[usually passive]","ex":{"en":"They saw the huge building outlined against the sky.","cn":"他们看见了在天空的映衬下那座巨大建筑的轮廓。"}},{"en":"a description of the main facts or points involved in something","cn":"概述；梗概","ex":{"en":"This is a brief outline of the events.","cn":"这就是事件的简要情况。"},"pos":"noun"},{"en":"the line that goes around the edge of something, showing its main shape but not the details","cn":"轮廓线；略图","ex":{"en":"At last we could see the dim outline of an island.","cn":"我们终于能看到一座小岛朦胧的轮廓了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"概述；概括","en":"If you outline an idea or a plan, you explain it in a general way.","ex":{"en":"The mayor outlined his plan to clean up the town's image","cn":"市长概述了他整顿市容的计划。"}},{"pos":"N-COUNT 可数名词","cn":"概要；梗概","en":"An outline is a general explanation or description of something.","ex":{"en":"Following is an outline of the survey findings","cn":"以下是调查结果概要。"}},{"pos":"V-PASSIVE 被动动词","cn":"（因背后的光线）显示…的轮廓（或外形）","en":"You say that an object is outlined when you can see its general shape because there is light behind it.","ex":{"en":"The Ritz was outlined against the lights up there","cn":"高悬的灯光映照出里兹饭店的轮廓。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指模糊的）轮廓，外形","en":"The outline of something is its general shape, especially when it cannot be clearly seen.","ex":{"en":"He could see only the hazy outline of the goalposts.","cn":"他只能看见球门柱模糊的轮廓。"}}]},"examples":[{"en":"They saw the huge building outlined against the sky.","cn":"他们看见了在天空的映衬下那座巨大建筑的轮廓。"},{"en":"We outlined our proposals to the committee.","cn":"我们向委员会提纲挈领地讲了讲我们的提案。"}]},"omnibus":{"media":{"uk":"media/uk/omnibus__gb_1.mp3","us":"media/us/omnibus__us_1.mp3"},"oxford":{"phon":"ˈɒmnɪbəs","pos":"noun","senses":[{"en":"a television or radio programme that combines several recent programmes in a series","cn":"（电视、广播）综合节目","lab":"British English","ex":{"en":"the 90-minute Sunday omnibus edition","cn":"90 分钟节目的星期天综合版"}},{"en":"a large book that contains a number of books, for example novels by the same author","cn":"（若干种作品的）汇编，选集"},{"en":"a bus","cn":"公共汽车","lab":"old-fashioned"},{"en":"including many things or different types of thing","cn":"综合性的；选编的","ex":{"en":"an omnibus law","cn":"（含多项法令的）综合法令"},"pos":"adjective"},{"en":"a British television programme about the arts. It was broadcast by the BBC from 1967 to 2003. Each programme was usually about one particular artist.","cn":"（广播、电视）综合节目","pos":""},{"en":"a US cultural television programme broadcast on CBS on Sunday afternoons from 1952 to 1961. It was presented by Alistair Cooke and offered a mixture of plays, music, talks with artistic people, and even comedy.","cn":"公共汽车","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（广播、电视的）汇播节目，综合节目","en":"An omnibus edition of a radio or television programme contains two or more similar programmes that were originally broadcast separately.","ex":{"en":"I enjoy the omnibus edition of Eastenders on Sunday.","cn":"我喜欢看《伦敦东区》的周日连播版。"}},{"pos":"N-COUNT 可数名词","cn":"（某一作家或主题作品的）选集，汇编","en":"An omnibus is a book which contains a large collection of stories or articles, often by a particular person or about a particular subject.","ex":{"en":"...a new omnibus edition of three Ruth Rendell chillers.","cn":"露丝·伦德尔3篇恐怖故事的新选集"}},{"pos":"N-COUNT 可数名词","cn":"同 bus","en":"An omnibus is a bus ."}]},"examples":[{"en":"the 90-minute Sunday omnibus edition","cn":"该节目长达 90 分钟的周日综合版"},{"en":"an omnibus law （","cn":"含多项法令的）综合法令"}]},"outset":{"media":{"uk":"media/uk/outset__gb_1.mp3","us":"media/us/outset__us_1.mp3"},"oxford":{"phon":"ˈaʊtset","pos":"noun","senses":[{"en":"at/from the beginning of sth","cn":"从开始"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"在开始时/ 从一开始","en":"If something happens at the outset of an event, process, or period of time, it happens at the beginning of it. If something happens from the outset it happens from the beginning and continues to happen.","ex":{"en":"Decide at the outset what kind of learning programme you want to follow","cn":"开始时就选定自己的学习方案。"}}]},"examples":[{"en":"I made it clear right from the outset that I disapproved.","cn":"从一开始我就明确地说我不赞成。"},{"en":"It was clear from the outset that there were going to be problems.","cn":"从一开始就很清楚会有问题出现的。"}]},"our":{"media":{"uk":"media/uk/our__gb_1.mp3","us":"media/us/our__us_1.mp3"},"oxford":{"phon":"ɑː(r)","pos":"determiner","senses":[{"en":"belonging to us; connected with us","cn":"我们的","ex":{"en":"our daughter/dog/house","cn":"我们的女儿／狗／房子"}},{"en":"used to refer to or address God or a holy person","cn":"（用于称上帝或圣人）","ex":{"en":"Our Father (= God)","cn":"上帝"}}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"我们的","en":"You use our to indicate that something belongs or relates both to yourself and to one or more other people.","ex":{"en":"We're expecting our first baby","cn":"我们怀上了第一个孩子。"}},{"pos":"DET-POSS 所有格限定词","cn":"（泛指）我们的，人们的","en":"A speaker or writer sometimes uses our to indicate that something belongs or relates to people in general.","ex":{"en":"The quality of our life depends on keeping well","cn":"我们的生活质量取决于健康状况。"}},{"pos":"DET-POSS 所有格限定词","cn":"（与家庭成员的姓名连用）我家的","en":"Speakers sometimes use our with the name of a member of their family.","ex":{"en":"Our Barry had a habit of doing that sort of thing.","cn":"我家巴里就习惯干那种事。"}}]},"examples":[{"en":"We showed them some of our photos.","cn":"我们给他们看了我们的一些照片。"},{"en":"And now, over to our Rome correspondent …","cn":"现在是驻罗马记者的报道 …"}]},"oddly":{"media":{"uk":"media/uk/oddly__gb_1.mp3","us":"media/us/oddly__us_1.mp3"},"oxford":{"phon":"ˈɒdli","pos":"adverb","senses":[{"en":"in a strange or unusual way","cn":"奇怪地；怪异地；反常地","ex":{"en":"She's been behaving very oddly lately.","cn":"她最近行为极其反常。"}},{"en":"used to show that something is surprising","cn":"令人奇怪地；令人惊奇地","ex":{"en":"She felt, oddly, that they had been happier when they had no money.","cn":"她感到奇怪的是，他们没钱时反倒生活得更幸福。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"奇怪的是；说来也怪","en":"You use oddly to indicate that what you are saying is true, but that it is not what you expected.","ex":{"en":"He said no and seemed oddly reluctant to talk about it","cn":"他说没有，而且奇怪的是似乎不愿谈及此事。"}}]},"examples":[{"en":"She felt, oddly, that they had been happier when they had no money.","cn":"她感到奇怪的是，他们没钱时生活得更幸福。"},{"en":"Oddly enough, the most expensive tickets sold fastest.","cn":"奇怪极了，最贵的票居然卖得最快。"}]},"obtaining":{"lemma":"obtain"},"odd":{"oxford":{"phon":"ɒd","pos":"adjective","senses":[{"en":"strange or unusual","cn":"奇怪的；怪异的；反常的","sc":"strange","ex":{"en":"They're very odd people.","cn":"他们那些人都很古怪。"}},{"en":"strange or unusual in the way mentioned","cn":"（某方面）怪异的，奇怪的","sc":"odd-","ex":{"en":"an odd-looking house","cn":"样子怪异的房子"}},{"en":"that cannot be divided exactly by the number two","cn":"奇数的","sc":"numbers","ex":{"en":"1, 3, 5 and 7 are odd numbers.","cn":"1、3、5 和 7 是奇数。"}},{"en":"happening or appearing occasionally; not happening often","cn":"偶然出现的；偶尔发生的；不常见的","g":"[only before noun]","sc":"not regular/often","ex":{"en":"He makes the odd mistake—nothing too serious.","cn":"他偶尔会犯错误，但不怎么严重。"}},{"en":"of no particular type or size; various","cn":"奇形怪状的；各种各样的","g":"[only before noun]","sc":"various","ex":{"en":"decorations made of odd scraps of paper","cn":"用各种各样的纸片做的装饰"}},{"en":"not with the pair or set that it belongs to; not matching","cn":"不成对的；不相配的","g":"[usually before noun]","sc":"not matching","ex":{"en":"You're wearing odd socks!","cn":"你穿的袜子不成双呀！"}},{"en":"available; that somebody can use","cn":"可得到的；可用的","g":"[only before noun]","sc":"available","ex":{"en":"Could I see you when you've got an odd moment?","cn":"你有空时，我能不能见见你？"}},{"en":"approximately or a little more than the number mentioned","cn":"大约；略多","sc":"approximately","ex":{"en":"How old is she—seventy odd?","cn":"她多大年纪？七十出头？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇怪的；古怪的；奇特的；异常的","en":"If you describe someone or something as odd, you think that they are strange or unusual.","ex":{"en":"He'd always been odd, but not to this extent","cn":"他一直比较怪异，不过并没有到这种程度。"}},{"pos":"ADJ 形容词","cn":"（用于名词前）少量的，微小的，不重要的","en":"You use odd before a noun to indicate that you are not mentioning the type, size, or quality of something because it is not important.","ex":{"en":"...moving from place to place where she could find the odd bit of work","cn":"她为了找到点儿零散活计不断地搬来搬去"}},{"pos":"ADV 副词","cn":"（用于数字后）大约，左右，略多","en":"You use odd after a number to indicate that it is only approximate.","ex":{"en":"How many pages was it, 500 odd?","cn":"这有多少页，500来页？"}},{"pos":"ADJ 形容词","cn":"奇数的；单数的","en":"Odd numbers, such as 3 and 17, are those which cannot be divided exactly by the number two.","ex":{"en":"The odd numbers are on the left as you walk up the street","cn":"沿这条街走，在左边的是单号。"}},{"pos":"ADJ 形容词","cn":"不同类的；不成对的；单只的","en":"You say that two things are odd when they do not belong to the same set or pair.","ex":{"en":"I'm wearing odd socks today by the way.","cn":"顺便提一下，我今天穿的袜子不成对。"}},{"pos":"PHRASE 短语","cn":"与集体不合的人；剩下孤零零的一人；异类","en":"The odd man out ,the odd woman out, or the odd one out in a particular situation is a person who is different from the other people in it.","ex":{"en":"Azerbaijan has been the odd man out, the one republic not to hold democratic elections","cn":"阿塞拜疆没有举行民主选举，是这些共和国中的异类。"}}]},"media":{"uk":"media/uk/odd__gb_1.mp3","us":"media/us/odd__us_1.mp3"},"examples":[{"en":"She had the oddest feeling that he was avoiding her.","cn":"她有种异样的感觉，觉得他在躲着她。"},{"en":"Dog, cat, horse, shoe — which is the odd one out?","cn":"狗、猫、马、鞋，哪一个不属同类？"}]},"one's":{"media":{"uk":"media/uk/one_s_1_gb_1.mp3","us":"media/us/one_s_1_us_1.mp3"},"oxford":{"phon":"wʌnz","pos":"det.","senses":[{"en":"the possessive form of one （one","cn":"的所有格）个人的，自己的"}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"人们的；自己的","en":"Speakers and writers use one's to indicate that something belongs or relates to people in general, or to themselves in particular.","ex":{"en":"...a feeling of responsibility for the welfare of others in one's community","cn":"为社群的其他成员谋福利的责任感"}},{"pos":"","cn":"（one is 或尤当 has 为助动词时 one has 的一种口语形式）","en":"One's can be used as a spoken form of 'one is' or 'one has', especially when 'has' is an auxiliary verb. →see: ;","ex":{"en":"No one's going to hurt you. No one. Not any more","cn":"没有人会伤害你了，不会有人了，再也不会有了。"}}]},"examples":[{"en":"One tries one's best.","cn":"一个人尽其所能。"}]},"outfit":{"media":{"uk":"media/uk/outfit__gb_1.mp3","us":"media/us/outfit__us_1.mp3"},"oxford":{"phon":"ˈaʊtfɪt","pos":"noun","senses":[{"en":"a set of clothes that you wear together, especially for a particular occasion or purpose","cn":"全套服装，装束（尤指为某场合或目的）","g":"[countable]","ex":{"en":"She was wearing an expensive new outfit.","cn":"她穿着一身昂贵的新衣裳。"}},{"en":"a group of people working together as an organization, business, team, etc.","cn":"团队；小组；分队","g":"[countable + singular or plural verb]","lab":"informal","ex":{"en":"a market research outfit","cn":"市场调查组"}},{"en":"a set of equipment that you need for a particular purpose","cn":"全套装备；成套工具","g":"[countable]","ex":{"en":"a bicycle repair outfit","cn":"修自行车的整套工具"}},{"en":"to provide somebody/something with equipment or clothes for a special purpose","cn":"装备；配置设备；供给服装","ex":{"en":"The ship was outfitted with a 12-bed hospital.","cn":"这艘船配备了一所有 12 个床位的医院。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"全套服装","en":"An outfit is a set of clothes.","ex":{"en":"She was wearing an outfit she'd bought the previous day","cn":"她穿着前一天买的那套衣服。"}},{"pos":"N-COUNT 可数名词","cn":"机构;组织","en":"You can refer to an organization as an outfit .","ex":{"en":"He works for a private security outfit","cn":"他在一家私人保安公司工作。"}},{"pos":"VERB 动词","cn":"装备；配备；供给","en":"To outfit someone or something means to provide them with equipment for a particular purpose.","ex":{"en":"They outfitted him with artificial legs","cn":"他们为他安了假腿。"}}]},"examples":[{"en":"The ship was outfitted with a 12-bed hospital.","cn":"这艘船上配置了一个有 12 个床位的医疗室。"},{"en":"This was the fourth album by the top rock outfit.","cn":"这是这个顶级摇滚乐队的第四张唱片专辑。"}]},"optimistic":{"oxford":{"phon":"ˌɒptɪˈmɪstɪk","pos":"adjective","senses":[{"en":"expecting good things to happen or something to be successful; showing this feeling","cn":"乐观的；抱乐观看法的","ex":{"en":"We are now taking a more optimistic view.","cn":"我们现在抱较乐观的态度。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐观的","en":"Someone who is optimistic is hopeful about the future or the success of something in particular.","ex":{"en":"The President says she is optimistic that an agreement can be worked out soon","cn":"总统说她对很快达成协议持乐观态度。"}}]},"media":{"uk":"media/uk/optimistic__gb_1.mp3","us":"media/us/optimistic__us_1.mp3"},"examples":[{"en":"They are cautiously optimistic that the reforms will take place.","cn":"他们对是否实行改革表示审慎的乐观。"},{"en":"She's not very optimistic about the outcome of the talks.","cn":"她对会谈的结果不太乐观。"}]},"organs":{"lemma":"organ"},"outlying":{"media":{"uk":"media/uk/outlying__gb_1.mp3","us":"media/us/outlying__us_1.mp3"},"oxford":{"phon":"ˈaʊtlaɪɪŋ","pos":"adjective","senses":[{"en":"far away from the cities of a country or from the main part of a place","cn":"边远的；偏远的；远离市镇的","ex":{"en":"outlying areas","cn":"偏远地区"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"偏僻的；边远的；远离城市的","en":"Outlying places are far away from the main cities of a country.","ex":{"en":"Tourists can visit outlying areas like the Napa Valley Wine Country","cn":"游客可以前往像纳帕谷酒乡这样远离城市喧嚣的地方游览。"}}]},"examples":[{"en":"outlying areas","cn":"偏远地区"},{"en":"one of the outlying suburbs","cn":"边远郊区之一"}]},"onto":{"media":{"uk":"media/uk/onto__gb_1.mp3","us":"media/us/onto__us_1.mp3"},"oxford":{"phon":"ˈɒntə","pos":"preposition","senses":[{"en":"used with verbs to express movement on or to a particular place or position","cn":"（与动词连用，表示朝某处或某位置运动）向，朝","ex":{"en":"Move the books onto the second shelf.","cn":"把书移到第二层架子上。"}},{"en":"used to show that something faces in a particular direction","cn":"朝向，面向（某个方向）","ex":{"en":"The window looked out onto the terrace.","cn":"窗户外对着的是露天平台。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"到…之上；向…之上","en":"If something moves or is put onto an object or surface, it is then on that object or surface.","ex":{"en":"I took my bags inside, lowered myself onto the bed and switched on the TV","cn":"我把包拎进屋，往床上一倒，然后打开了电视机。"}},{"pos":"PREP 介词","cn":"到（某处）","en":"You can sometimes use onto to mention the place or area that someone moves into.","ex":{"en":"The players emerged onto the field","cn":"运动员入场了。"}},{"pos":"PREP 介词","cn":"（光线或视线）朝向,转向","en":"You can use onto to introduce the place towards which a light or someone's look is directed.","ex":{"en":"...the metal part of the door onto which the sun had been shining","cn":"在阳光照耀下闪闪发亮的门的金属部分"}},{"pos":"PREP 介词","cn":"通向（某处）","en":"You can use onto to introduce a place that you would immediately come to after leaving another place that you have just mentioned, because they are next to each other.","ex":{"en":"...windows opening onto carved black-wood balconies","cn":"开向黑檀雕花阳台的窗户"}},{"pos":"PREP 介词","cn":"（重心移动）到（身体某部位）上","en":"When you change the position of your body, you use onto to introduce the part your body which is now supporting you.","ex":{"en":"As he stepped backwards she fell onto her knees, then onto her face","cn":"他向后退时，她双膝跪倒在地，接着迎面倒了下去。"}},{"pos":"PREP 介词","cn":"到（交通工具）上","en":"When you get onto a bus, train, or plane, you enter it in order to travel somewhere.","ex":{"en":"As he got on to the plane, he asked me how I was feeling","cn":"他上飞机时问我感觉如何。"}},{"pos":"PREP 介词","cn":"（用于 hold，hang，cling 等动词后，表示抓紧或牢牢固定）在…上","en":"Onto is used after verbs such as 'hold', 'hang', and 'cling' to indicate what someone is holding firmly or where something is being held firmly.","ex":{"en":"The reflector is held onto the sides of the spacecraft with a frame","cn":"反射器通过支架牢牢地固定在航天器的侧面。"}},{"pos":"PREP 介词","cn":"转到（其他话题）","en":"If people who are talking get onto a different subject, they begin talking about it.","ex":{"en":"Let's get on to more important matters","cn":"咱们谈谈更重要的事吧。"}},{"pos":"PREP 介词","cn":"成为（列表、系统等）的一部分","en":"You can sometimes use onto to indicate that something or someone becomes included as a part of a list or system.","ex":{"en":"The Macedonian question had failed to get on to the agenda","cn":"马其顿问题没能列入议事日程。"}},{"pos":"PREP 介词","cn":"即将发现（重要之事）","en":"If someone is onto something, they are about to discover something important.","ex":{"en":"He leaned across the table and whispered to me, 'I'm really onto something.'","cn":"他从桌上俯过身来对我低声说道：“我真的就快有重大发现了。”"}},{"pos":"PREP 介词","cn":"发现（某人做坏事）；对…觉察；对…知悉","en":"If someone is onto you, they have discovered that you are doing something illegal or wrong.","ex":{"en":"He did not want Pollard to become suspicious that he was now onto him","cn":"他不想让波拉德怀疑他已察觉到其不轨行为。"}}]},"examples":[{"en":"They've been onto me for ages to get a job.","cn":"很久以来，他们一直催促我找份工作。"},{"en":"Scientists believe they are onto something big.","cn":"科学家相信，他们将会有重大发现。"}]},"otherwise":{"media":{"uk":"media/uk/otherwise__gb_1.mp3","us":"media/us/otherwise__us_1.mp3"},"oxford":{"phon":"ˈʌðəwaɪz","pos":"adverb","senses":[{"en":"used to state what the result would be if something did not happen or if the situation were different","cn":"否则；不然","ex":{"en":"My parents lent me the money. Otherwise, I couldn't have afforded the trip.","cn":"我父母借钱给我了。否则，我可付不起这次旅费。"}},{"en":"apart from that","cn":"除此以外","ex":{"en":"There was some music playing upstairs. Otherwise the house was silent.","cn":"楼上有些音乐声。除此以外，房子里静悄悄的。"}},{"en":"in a different way to the way mentioned; differently","cn":"以其他方式；另；亦","ex":{"en":"Bismarck, otherwise known as ‘the Iron Chancellor’","cn":"俾斯麦，亦称为“铁血宰相”"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"否则；不然","en":"You use otherwise after stating a situation or fact, in order to say what the result or consequence would be if this situation or fact was not the case.","ex":{"en":"Make a note of the questions you want to ask. You will invariably forget some of them otherwise","cn":"把想提的问题记下来，否则总是会漏掉其中的一些。"}},{"pos":"ADV 副词","cn":"除此以外；在其他方面","en":"You use otherwise before stating the general condition or quality of something, when you are also mentioning an exception to this general condition or quality.","ex":{"en":"The decorations for the games have lent a splash of colour to an otherwise drab city.","cn":"为运动会所作的装扮给原本毫无生气的城市增添了一抹亮色。"}},{"pos":"ADV 副词","cn":"与之不同地；相反地","en":"You use otherwise to refer in a general way to actions or situations that are very different from, or the opposite to, your main statement.","ex":{"en":"Take approximately 60mg up to four times a day, unless advised otherwise by a doctor","cn":"每次服用大约60毫克，每天最多4次，或遵医嘱。"}},{"pos":"ADV 副词","cn":"以其他方式；用别的方法","en":"You use otherwise to indicate that other ways of doing something are possible in addition to the way already mentioned.","ex":{"en":"The studio could punish its players by keeping them out of work, and otherwise controlling their lives.","cn":"电影公司能通过让艺人坐冷板凳来惩罚他们，并采用其他方式控制他们的生活。"}},{"pos":"PHRASE 短语","cn":"及其他；或相反；或其反面","en":"You use or otherwise or and otherwise to mention something that is not the thing just referred to or is the opposite of that thing.","ex":{"en":"It was for the police to assess the validity or otherwise of the evidence","cn":"应该由警方来判定证据有效与否。"}}]},"examples":[{"en":"We're committed to the project. We wouldn't be here otherwise.","cn":"我们是全心全意投入这项工作的，否则我们就不会到这里来了。"},{"en":"My parents lent me the money. Otherwise, I couldn't have afforded the trip.","cn":"我父母借钱给我了。否则，我可付不起这次旅费。"}]},"ordeal":{"media":{"uk":"media/uk/ordeal__gb_1.mp3","us":"media/us/ordeal__us_1.mp3"},"oxford":{"phon":"ɔːˈdiːl","pos":"noun","senses":[{"en":"a difficult or unpleasant experience","cn":"磨难；折磨；煎熬；严酷的考验","ex":{"en":"They had survived a terrifying ordeal.","cn":"他们遭受过一场可怕的磨难后幸存了下来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"煎熬；磨难；折磨","en":"If you describe an experience or situation as an ordeal, you think it is difficult and unpleasant.","ex":{"en":"...the painful ordeal of the last eight months","cn":"过去8个月的痛苦煎熬"}}]},"examples":[{"en":"The hostages spoke openly about the terrible ordeal they had been through.","cn":"人质公开陈述了他们所遭受的非人的折磨。"},{"en":"The interview was less of an ordeal than she'd expected.","cn":"面试并非如她想像的那样可怕。"}]},"oranges":{"lemma":"orange","media":{"img":["media/ldoce/img/oranges.jpg"]}},"outcome":{"media":{"uk":"media/uk/outcome__gb_1.mp3","us":"media/us/outcome__us_1.mp3"},"oxford":{"phon":"ˈaʊtkʌm","pos":"noun","senses":[{"en":"the result or effect of an action or event","cn":"结果；效果","lab":"formal","ex":{"en":"The likely outcome is a compromise.","cn":"结果可能是妥协。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结果；结局；后果","en":"The outcome of an activity, process, or situation is the situation that exists at the end of it.","ex":{"en":"Mr. Singh said he was pleased with the outcome","cn":"辛格先生说他对这一结果感到满意。"}}]},"examples":[{"en":"These costs are payable whatever the outcome of the case.","cn":"无论讼案结果如何，这些费用都应照付。"},{"en":"We are waiting to hear the final outcome of the negotiations.","cn":"我们在等待谈判的最终结果。"}]},"observer":{"media":{"uk":"media/uk/observer__gb_1.mp3","us":"media/us/observer__us_1.mp3"},"oxford":{"phon":"əbˈzɜːvə(r)","pos":"noun","senses":[{"en":"a person who watches somebody/something","cn":"观察者；观测者；目击者","ex":{"en":"According to observers, the plane exploded shortly after take-off.","cn":"据目击者说，飞机起飞后不久就爆炸了。"}},{"en":"a person who attends a meeting, lesson, etc. to listen and watch but not to take part","cn":"观察员；旁听者","ex":{"en":"A team of British officials were sent as observers to the conference.","cn":"一组英国官员被派去做大会观察员。"}},{"en":"a person who watches and studies particular events, situations, etc. and is therefore considered to be an expert on them","cn":"观察家；观察员；评论员","ex":{"en":"a royal observer","cn":"王室观察家"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观察者；观测者；目击者","en":"You can refer to someone who sees or notices something as an observer .","ex":{"en":"A casual observer would have taken them to be three men out for an evening stroll","cn":"乍一看的话，还以为他们三人是晚上出来散步的。"}},{"pos":"N-COUNT 可数名词","cn":"观察家;评论员","en":"An observer is someone who studies current events and situations, especially in order to comment on them and predict what will happen next.","ex":{"en":"Observers say the events of the weekend seem to have increased support for the opposition","cn":"观察家说周末发生的事件似乎为反对派赢得了更多支持。"}},{"pos":"N-COUNT 可数名词","cn":"（监督重大事件或局势的）观察员","en":"An observer is a person who is sent to observe an important event or situation, especially in order to make sure it happens as it should, or so that they can tell other people about it.","ex":{"en":"The president suggested that a UN observer should attend the conference.","cn":"总统建议联合国应派一名观察员参加本次会议。"}}]},"examples":[{"en":"According to observers, the plane exploded shortly after take-off.","cn":"据目击者说，飞机起飞后不久就爆炸了。"},{"en":"To the casual observer (= somebody who does not pay much attention), the system appears confusing.","cn":"乍看起来，这个系统好像条理不清。"}]},"o":{"media":{"uk":"media/uk/o__gb_1.mp3","us":"media/us/o__us_1.mp3"},"oxford":{"phon":"əʊ","pos":"noun","senses":[{"en":"the 15th letter of the English alphabet","cn":"英语字母表的第 15 个字母","g":"[countable, uncountable]","ex":{"en":"‘Orange’ begins with (an) O/‘O’.","cn":"orange 一词以字母 o 开头。"}},{"en":"used to mean ‘zero’ when saying phone numbers, etc.","cn":"（说电话号码等时表示）零","ex":{"en":"My number is six o double three (= 6033).","cn":"我的号码是六零三三。"}},{"en":"an old spelling of oh","cn":"哦的旧拼写","pos":"exclamation"},{"en":"used before a name when speaking to somebody in a prayer or poem","cn":"（说电话号码等时表示）零","ex":{"en":"O Lord, save thy people.","cn":"主啊，请拯救你的子民。"},"pos":"exclamation"},{"en":"the symbol for the chemical element oxygen","cn":"（化学元素）氧","pos":"symbol"},{"en":"used in written English to represent an informal way of saying of","cn":"（用于书面英语中，代替 of 的非正式说法）","ex":{"en":"a couple o’ times","cn":"几次"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"","cn":"英语字母表的第15个字母","en":"O is the fifteenth letter of the English alphabet."},{"pos":"","cn":"零","en":"O is used to mean zero, for example when you are telling someone a telephone number, or mentioning a year such as 1908."},{"pos":"See also:","cn":"（尤用于表示强烈感情）哎呀，啊，唉，哟","en":"O is used in exclamations, especially when you are expressing strong feelings.","ex":{"en":"O how mistaken you are!","cn":"哎呀，你可大错特错了！"}},{"pos":"","cn":"(用于首字母为o的一些单词的缩写，如 old或organization)","en":"O is used as an abbreviation for words beginning with o, such as 'old' or 'organization'."}]},"examples":[{"en":"‘Orange’ begins with (an) O/‘O’. * orange","cn":"一词以字母 o 开头。"},{"en":"My number is six o double three (= 6033).","cn":"我的号码是六零三三。"}]},"over-":{"lemma":"over","media":{"uk":"media/uk/over__1_gb_1.mp3","us":"media/us/over__1_us_1.mp3"}},"optimist":{"oxford":{"phon":"ˈɒptɪmɪst","pos":"noun","senses":[{"en":"a person who always expects good things to happen or things to be successful","cn":"乐观的人；乐天派","ex":{"en":"I'm an eternal optimist—I'm sure things will get better.","cn":"我是一个永远的乐观主义者。我相信情况会变得更好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乐观者","en":"An optimist is someone who is hopeful about the future.","ex":{"en":"Optimists reckon house prices will move up with inflation this year.","cn":"乐观人士认为今年的房价将会随通货膨胀而上涨。"}}]},"media":{"uk":"media/uk/optimist__gb_1.mp3","us":"media/us/optimist__us_1.mp3"},"examples":[{"en":"He’s an eternal optimist (= he always believes that good things will happen ) .","cn":"他是个永远的乐观主义者。"}]},"official":{"media":{"uk":"media/uk/official__gb_1.mp3","us":"media/us/official__us_1.mp3"},"oxford":{"phon":"əˈfɪʃl","pos":"adjective","senses":[{"en":"agreed to, said, done, etc. by somebody who is in a position of authority","cn":"正式的；官方的；官方授权的","g":"[usually before noun]","ex":{"en":"an official announcement/decision/statement","cn":"官方公告／决定／声明"}},{"en":"connected with the job of somebody who is in a position of authority","cn":"公务的；公职的；公事的","g":"[only before noun]","ex":{"en":"official duties/responsibilities","cn":"公务"}},{"en":"formal and attended by people in authority","cn":"正式的；公务的；官方场合的","g":"[only before noun]","ex":{"en":"an official function/reception","cn":"官方活动／招待会"}},{"en":"that is told to the public but may not be true","cn":"公开的；公布的；据官方的","g":"[only before noun]","ex":{"en":"I only knew the official version of events.","cn":"我对事情的了解仅限于官方的版本。"}},{"en":"a person who is in a position of authority in a large organization","cn":"要员；官员；高级职员","ex":{"en":"She is the government official in charge of the project.","cn":"她是负责该项目的政府官员。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"官方的；正式的","en":"Official means approved by the government or by someone in authority.","ex":{"en":"According to the official figures, over one thousand people died during the revolution","cn":"根据官方数字，1,000多人在这场革命中丧生。"}},{"pos":"ADJ 形容词","cn":"公务的；公职的；公事的","en":"Official activities are carried out by a person in authority as part of their job.","ex":{"en":"The President is in Brazil for an official two-day visit.","cn":"总统正在巴西进行为期两天的正式访问。"}},{"pos":"ADJ 形容词","cn":"官员（因职务使用）的","en":"Official things are used by a person in authority as part of their job.","ex":{"en":"...the official residence of the Head of State.","cn":"国家元首的官邸"}},{"pos":"ADJ 形容词","cn":"（解释、理由等）冠冕堂皇的，桌面上的","en":"If you describe someone's explanation or reason for something as the official explanation, you are suggesting that it is probably not true, but is used because the real explanation is embarrassing.","ex":{"en":"The official explanation for the cancellation of the party conference is that there are no premises available","cn":"官方对取消此次政党会议作出的解释是没有场地。"}},{"pos":"N-COUNT 可数名词","cn":"官员；行政人员；高级职员","en":"An official is a person who holds a position of authority in an organization.","ex":{"en":"A senior UN official hopes to visit Baghdad this month.","cn":"一位联合国高级官员希望于本月访问巴格达。"}},{"pos":"N-COUNT 可数名词","cn":"（体育比赛中的）裁判员，执法人","en":"An official at a sports event is a referee, umpire, or other person who checks that the players follow the rules."}]},"examples":[{"en":"He made an official visit to Tokyo in March.","cn":"他于三月到东京进行了一次公务访问。"},{"en":"I only knew the official version of events.","cn":"我对事情的了解仅限于官方的版本。"}]},"outcry":{"media":{"uk":"media/uk/outcry__gb_1.mp3","us":"media/us/outcry__us_1.mp3"},"oxford":{"phon":"ˈaʊtkraɪ","pos":"noun","senses":[{"en":"a reaction of anger or strong protest shown by people in public","cn":"呐喊；怒吼；强烈的抗议","ex":{"en":"an outcry over the proposed change","cn":"对拟议的改革所发出的强烈抗议"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"强烈的抗议（或反对）","en":"An outcry is a reaction of strong disapproval and anger shown by the public or media about a recent event.","ex":{"en":"The killing caused an international outcry","cn":"这起谋杀引起了国际社会的强烈抗议。"}}]},"examples":[{"en":"an outcry over the proposed change","cn":"对拟议的改革所发出的强烈抗议"},{"en":"The new tax provoked a public outcry.","cn":"新税项引起了公众的强烈抗议。"}]},"out":{"media":{"uk":"media/uk/out__gb_1.mp3","us":"media/us/out__us_1.mp3"},"oxford":{"phon":"aʊt","pos":"adverb, preposition","senses":[{"en":"away from the inside of a place or thing","cn":"（从…里）出来","lab":"informal","ex":{"en":"She ran out into the corridor.","cn":"她跑出来，冲进走廊。"}},{"en":"away from or not at home or their place of work","cn":"不在家；不在工作地点；外出","ex":{"en":"I called Liz but she was out.","cn":"我打电话给利兹，但她不在家。"}},{"en":"outside; not in a building","cn":"在外面；在户外","ex":{"en":"It's cold out.","cn":"外面很冷。"}},{"en":"used to show that something/somebody is removed from a place, job, etc.","cn":"除掉；清除","ex":{"en":"This detergent is good for getting stains out.","cn":"这种洗涤剂能清除斑渍。"}},{"en":"away from the edge of a place","cn":"出去；离开（某地）边缘","ex":{"en":"The boy dashed out into the road.","cn":"男孩子向路中间冲去。"}},{"en":"used to show where something comes from","cn":"从；来自","ex":{"en":"He drank his beer out of the bottle.","cn":"他从瓶口直接喝啤酒。"}},{"en":"used to show what something is made from","cn":"用…制作","ex":{"en":"a statue made out of bronze","cn":"一尊青铜像"}},{"en":"used to show that somebody/something does not have any of something","cn":"没有；缺少","ex":{"en":"We're out of milk.","cn":"我们没有牛奶了。"}},{"en":"used to show that somebody/something is not or no longer in a particular state or condition","cn":"（表示不在原状态）脱离，离开","ex":{"en":"Try and stay out of trouble.","cn":"尽量别惹麻烦。"}},{"en":"used to show that somebody is no longer involved in something","cn":"（表示不再参与某事）脱离","ex":{"en":"It was an awful job and I'm glad to be out of it.","cn":"那件差事简直是受罪，我很高兴摆脱掉了。"}},{"en":"from a particular number or set","cn":"从（某个数目或集）中","ex":{"en":"You scored six out of ten.","cn":"总分十分你得了六分。"}},{"en":"clearly and loudly so that people can hear","cn":"大声地","ex":{"en":"to call/cry/shout out","cn":"大声叫／哭／喊"}},{"en":"a long or a particular distance away from a place or from land","cn":"远离（某地或陆地）；离（某地或陆地）","ex":{"en":"She's working out in Australia.","cn":"她远在澳大利亚工作。"}},{"en":"available to everyone; known to everyone","cn":"公开；发行","ex":{"en":"When does her new book come out?","cn":"她的新书什么时候出版？"}},{"en":"used to show the reason why something is done","cn":"（表示原因）因为，出于","ex":{"en":"I asked out of curiosity.","cn":"我因为好奇问了问。"}},{"en":"not in the library; borrowed by somebody else","cn":"不在图书馆；已借出","ex":{"en":"The book you wanted is out on loan.","cn":"你要的那本书借出去了。"}},{"en":"at or towards its lowest point on land","cn":"在退潮期；退潮","ex":{"en":"I like walking on the wet sand when the tide is out.","cn":"我喜欢退潮后走在湿润的沙滩上。"}},{"en":"if the sun, moon or stars are or come out, they can be seen from the earth and are not hidden by clouds","cn":"（日、月、星辰）出现，未被云遮住"},{"en":"fully open","cn":"开放","ex":{"en":"There should be some snowdrops out by now.","cn":"现在应该有雪花莲开放了。"}},{"en":"if a team or team member is out, it is no longer their turn with the bat","cn":"出局","ex":{"en":"The West Indies were all out for 364 (= after scoring 364 runs in cricket).","cn":"西印度群岛队以 364 分全队出局。"}},{"en":"if a player is out, they can no longer take part in the game","cn":"（玩家）出局","ex":{"en":"If you have no more cards, you are out. The winner is the one with the most cards.","cn":"没牌即出局。牌最多的为赢家。"}},{"en":"if the ball is out, it landed outside the line","cn":"出界","ex":{"en":"The umpire said the ball was out.","cn":"裁判员判球出界。"}},{"en":"not correct or exact; wrong","cn":"错误；不准确","ex":{"en":"I was slightly out in my calculations.","cn":"我的计算出了点小错。"}},{"en":"not possible or not allowed","cn":"不可能；不允许","ex":{"en":"Swimming is out until the weather gets warmer.","cn":"天气转暖前，游泳是不可能的。"}},{"en":"not fashionable","cn":"过时","ex":{"en":"Black is out this year.","cn":"今年黑色不时兴了。"}},{"en":"not or no longer burning or lit","cn":"熄灭","ex":{"en":"Suddenly all the lights went out.","cn":"突然间所有的灯光都灭了。"}},{"en":"at an end","cn":"结束","ex":{"en":"It was summer and school was out.","cn":"夏天，学校放假了。"}},{"en":"unconscious","cn":"无知觉；昏迷","ex":{"en":"He was out for more than an hour and came round in the hospital.","cn":"他昏迷了一个多小时，在医院才苏醒过来。"}},{"en":"on strike","cn":"罢工","lab":"British English, informal，，","ex":{"en":"The dockers stayed out for several months.","cn":"码头工人罢工了数月。"}},{"en":"to the end; completely","cn":"到底；完全地","ex":{"en":"Hear me out before you say anything.","cn":"你听我说完再讲话。"}},{"en":"a way of avoiding having to do something","cn":"回避的方法；托辞；出路","ex":{"en":"She was desperately looking for an out.","cn":"她在拼命找一条脱身之计。"},"pos":"noun"},{"en":"having told other people that you are gay or lesbian","cn":"已公开同性恋身份的；出柜的","ex":{"en":"an out gay man","cn":"已公开同性恋身份的男子"},"pos":"adjective"},{"en":"to say publicly that somebody is gay or lesbian, especially when they would prefer to keep this information private","cn":"揭露，公布（同性恋者）","ex":{"en":"He is the latest politician to be outed by the media.","cn":"他是最新一位被媒体揭露的政客。"},"pos":"verb"},{"en":"to say something publicly about somebody/something that they would prefer to keep secret","cn":"揭露，公布（别人想要保守的秘密）","ex":{"en":"The man who claimed to have found the diaries has been outed as a fraud.","cn":"声称找到日记的人被揭露是个骗子。"},"pos":"verb"},{"en":"greater, better, further, longer, etc.","cn":"超越；超过","ex":{"en":"outnumber","cn":"在数量上压倒"},"pos":"prefix"},{"en":"outside; outward; away from","cn":"在外面；向外；离开","ex":{"en":"outbuildings","cn":"附属建筑物"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（拿）出；（取）出","en":"When something is in a particular place and you take it out, you remove it from that place.","ex":{"en":"Carefully pull out the centre pages","cn":"小心翼翼地抽出中间的几页。"}},{"pos":"ADV 副词","cn":"在外；在室外","en":"You can use out to indicate that you are talking about the situation outside, rather than inside buildings.","ex":{"en":"It's hot out — very hot, very humid.","cn":"外面很热——非常炎热而且非常潮湿。"}},{"pos":"ADV 副词","cn":"不在家；不在工作地点","en":"If you are out, you are not at home or not at your usual place of work.","ex":{"en":"I tried to get in touch with you yesterday evening, but I think you were out","cn":"我昨晚想要和你联系，但好像你不在家里。"}},{"pos":"ADV 副词","cn":"在他处；（通常指）在远处","en":"If you say that someone is out in a particular place, you mean that they are in a different place, usually one far away.","ex":{"en":"The police tell me they've finished their investigations out there","cn":"警方告诉我他们已完成了在那儿的调查工作。"}},{"pos":"ADV 副词","cn":"（海水或潮水）离岸","en":"When the sea or tide goes out, the sea moves away from the shore.","ex":{"en":"The tide was out and they walked among the rock pools.","cn":"潮水已经退去，他们走过岩石区的潮水潭。"}},{"pos":"ADV 副词","cn":"缺少，不足，损失（某一数量的钱）","en":"If you are out a particular amount of money, you have that amount less than you should or than you did.","ex":{"en":"Me and my friends are out ten thousand dollars, with nothing to show for it!","cn":"我和朋友亏了1万美金，还一无所得！"}},{"pos":"ADJ 形容词","cn":"（灯、火）熄灭的","en":"If a light or fire is out or goes out, it is no longer shining or burning.","ex":{"en":"All the lights were out in the house","cn":"屋里的灯全都灭了。"}},{"pos":"ADJ 形容词","cn":"（花）盛开的，吐蕊的","en":"If flowers are out, their petals have opened.","ex":{"en":"Well, the daffodils are out in the gardens and they're always a beautiful show.","cn":"哎呀，花园里的黄水仙开了，它们永远都是一道亮丽的风景。"}},{"pos":"ADJ 形容词","cn":"面世；问世；发行","en":"If something such as a book or CD is out, it is available for people to buy.","ex":{"en":"...cover versions of 40 British Number Ones — out now.","cn":"40首英国头榜歌曲的翻唱版现在上市"}},{"pos":"ADJ 形容词","cn":"罢工的","en":"If workers are out, they are on strike.","ex":{"en":"We've been out for two and a half months and we're not going back until we get what we're asking for.","cn":"我们已经罢工两个半月了，除非要求得到满足，否则我们不会复工。"}},{"pos":"ADJ 形容词","cn":"无法参赛的；淘汰的","en":"In a game or sport, if someone is out, they can no longer take part either because they are unable to or because they have been defeated."},{"pos":"ADJ 形容词","cn":"（棒球比赛中选手）出局的","en":"In baseball, a player is out if they do not reach a base safely. When three players in a team are out in an inning, then the team is out."},{"pos":"ADJ 形容词","cn":"（提议或建议）不能接受的，不值得考虑的","en":"If you say that a proposal or suggestion is out, you mean that it is unacceptable.","ex":{"en":"That's right out, I'm afraid.","cn":"那恐怕根本行不通。"}},{"pos":"ADJ 形容词","cn":"不时髦的；不流行的；过时的","en":"If you say that a particular thing is out, you mean that it is no longer fashionable at the present time.","ex":{"en":"Romance is making a comeback. Reality is out.","cn":"浪漫主义正重新流行起来，而现实主义过时了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计算或测量）不准确的，错误的","en":"If you say that a calculation or measurement is out, you mean that it is incorrect.","ex":{"en":"When the two ends of the tunnel met in the middle they were only a few inches out.","cn":"隧道两端在中间相接时，仅有几英寸的误差。"}},{"pos":"ADJ 形容词","cn":"打算的；试图的","en":"If someone is out to do something, they intend to do it.","ex":{"en":"Most companies these days are just out to make a quick profit.","cn":"如今，大多数公司只想能迅速获利。"}},{"pos":"VERB 动词","cn":"公开揭露（公众人物、名人等）的同性恋身份","en":"If a group of people out a public figure or famous person, they reveal that person's homosexuality against their wishes.","ex":{"en":"The New York gay action group 'Queer Nation' recently outed an American Congressman.","cn":"纽约的同性恋行动组织“酷儿国度”最近揭露一位美国国会议员为同性恋。"}},{"pos":"PREP-PHRASE 短语介词","cn":"从（某处）离开","en":"If you go out of a place, you leave it.","ex":{"en":"She let him out of the house.","cn":"她让他出了屋子。"}},{"pos":"PREP-PHRASE 短语介词","cn":"从…里面（拿、取）出来","en":"If you take something out of the container or place where it has been, you remove it so that it is no longer there.","ex":{"en":"I always took my key out of my bag and put it in my pocket.","cn":"我总是将钥匙从包里取出来放进口袋。"}},{"pos":"PREP-PHRASE 短语介词","cn":"向（窗）外","en":"If you look or shout out of a window, you look or shout away from the room where you are towards the outside.","ex":{"en":"He went on staring out of the window","cn":"他继续凝视着窗外。"}},{"pos":"PREP-PHRASE 短语介词","cn":"避开，未暴露于（太阳、雨或风）","en":"If you are out of the sun, the rain, or the wind, you are sheltered from it.","ex":{"en":"People can keep out of the sun to avoid skin cancer.","cn":"人们可以通过避免阳光照射来预防皮肤癌。"}},{"pos":"PREP-PHRASE 短语介词","cn":"摆脱，脱离（尤指令人不快的事）","en":"If someone or something gets out of a situation, especially an unpleasant one, they are then no longer in it. If they keep out of it, they do not start being in it.","ex":{"en":"In the past army troops have relied heavily on air support to get them out of trouble","cn":"过去，陆军部队在很大程度上依赖空中支援来摆脱困境。"}},{"pos":"PREP-PHRASE 短语介词","cn":"离开（机构）","en":"You can use out of to say that someone leaves an institution.","ex":{"en":"You come out of university and find there are no jobs available","cn":"从大学毕业后却找不到工作。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…之外；超过…界限","en":"If you are out of range of something, you are beyond the limits of that range.","ex":{"en":"Shaun was in the bedroom, out of earshot, watching television","cn":"肖恩在卧室里看电视，听不见。"}},{"pos":"PREP-PHRASE 短语介词","cn":"出于；由于","en":"You use out of to say what feeling or reason causes someone to do something. For example, if you do something out of pity, you do it because you pity someone.","ex":{"en":"He took up office out of a sense of duty","cn":"他就任公职是出于一种责任感。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（通常指在对方不情愿的情况下）从（某人）身上（获得信息或工作成果）","en":"If you get something such as information or work out of someone, you manage to make them give it to you, usually when they are unwilling to give it.","ex":{"en":"'Where is she being held prisoner?' I asked. 'Did you get it out of him?'","cn":"“她被囚禁在什么地方？”我问道，“你从他口里套出来没有？”"}},{"pos":"PREP-PHRASE 短语介词","cn":"由…（引起）；从…中（得到）","en":"If you get pleasure or an advantage out of something, you get it as a result of being involved with that thing or making use of it.","ex":{"en":"We all had a lot of fun out of him","cn":"他给我们带来很多快乐。"}},{"pos":"PREP-PHRASE 短语介词","cn":"缺乏；没有","en":"If you are out of something, you no longer have any of it.","ex":{"en":"I can't find the sugar — and we're out of milk.","cn":"我找不到糖——而且我们也没牛奶了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"用…（制成）；由…（建成）","en":"If something is made out of a particular material, it consists of that material because it has been formed or constructed from it.","ex":{"en":"Would you advise people to make a building out of wood or stone?","cn":"你会建议人们用木材还是石头建房子呢？"}},{"pos":"PREP-PHRASE 短语介词","cn":"（表示比例）每…中","en":"You use out of to indicate what proportion of a group of things something is true of. For example, if something is true of one out of five things, it is true of one fifth of all things of that kind.","ex":{"en":"Two out of five thought the business would be sold privately on their retirement or death","cn":"五个人之中有两个认为公司会在他们退休或去世时被私下卖掉。"}}]},"examples":[{"en":"He is the latest politician to be outed by gay activists.","cn":"他是被同性恋维权人士新近揭露的同性恋政治人物。"},{"en":"We've only just moved here so we feel a little out of it.","cn":"我们刚搬到这里，所以心里觉得有点不适应。"}]},"organ":{"oxford":{"phon":"ˈɔːɡən","pos":"noun","senses":[{"en":"a part of the body that has a particular purpose, such as the heart or the brain; part of a plant with a particular purpose","cn":"（人体或动植物的）器官","lab":"British English","ex":{"en":"the internal organs","cn":"内脏"}},{"en":"a penis","cn":"阴茎；阳物","lab":"especially humorous","ex":{"en":"the male organ","cn":"雄性性器官"}},{"en":"a large musical instrument with keys like a piano. Sounds are produced by air forced through pipes.","cn":"管风琴","ex":{"en":"She plays the organ in church.","cn":"她在教堂负责弹奏管风琴。"}},{"en":"a musical instrument similar to a pipe organ, but without pipes","cn":"风琴","ex":{"en":"an electric organ","cn":"电子琴"}},{"en":"an official organization that is part of a larger organization and has a special purpose","cn":"（官方的）机构，机关","lab":"formal","ex":{"en":"the organs of government","cn":"政府机关"}},{"en":"a newspaper or magazine that gives information about a particular group or organization; a means of communicating the views of a particular group","cn":"机关报刊；（某团体的）宣传工具","lab":"formal","ex":{"en":"The People's Daily is the official organ of the Chinese Communist Party.","cn":"《人民日报》是中国共产党的官方报纸。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"器官","en":"An organ is a part of your body that has a particular purpose or function, for example your heart or lungs.","ex":{"en":"...damage to the muscles and internal organs.","cn":"对肌肉与内脏的损伤"}},{"pos":"N-COUNT 可数名词","cn":"风琴；管风琴","en":"An organ is a large musical instrument with pipes of different lengths through which air is forced. It has keys and pedals rather like a piano."},{"pos":"N-COUNT 可数名词","cn":"（政府、集团等的）喉舌，机构","en":"You refer to a newspaper or organization as the organ of the government or another group when it is used by them as a means of giving information or getting things done.","ex":{"en":"The Security Service is an important organ of the State","cn":"军情五处是国家的重要机构。"}}]},"media":{"img":["media/pic/internal_organs_comp.jpg","media/thumb/organ.jpg"],"uk":"media/uk/organ__gb_1.mp3","us":"media/us/organ__us_1.mp3"},"examples":[{"en":"The People's Daily is the official organ of the Chinese Communist Party. 《","cn":"人民日报》是中国共产党的官方报纸。"},{"en":"She plays the organ in church.","cn":"她在教堂负责弹奏管风琴。"}]},"opinion":{"media":{"uk":"media/uk/opinion__gb_1.mp3","us":"media/us/opinion__us_1.mp3"},"oxford":{"phon":"əˈpɪnjən","pos":"noun","senses":[{"en":"your feelings or thoughts about somebody/something, rather than a fact","cn":"意见；想法；看法","g":"[countable]","lab":"formal","ex":{"en":"He has very strong political opinions.","cn":"他的政见颇为坚定。"}},{"en":"the beliefs or views of a group of people","cn":"（群体的）观点，信仰","g":"[uncountable]","ex":{"en":"legal/medical/political opinion (= the beliefs of people working in the legal, etc. profession)","cn":"法学界／医学界／政界的观点"}},{"en":"advice from a professional person","cn":"专家意见","g":"[countable]","ex":{"en":"The couple sought the opinions of other doctors who confirmed the diagnosis.","cn":"这对夫妇征求了其他确认了这一诊断的医生的意见。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意见；看法；主张；见解","en":"Your opinion about something is what you think or believe about it.","ex":{"en":"I wasn't asking for your opinion, Dick","cn":"我并不是在征求你的意见，迪克。"}},{"pos":"N-SING 单数名词","cn":"（对某人的）评价，印象","en":"Your opinion of someone is your judgment of their character or ability.","ex":{"en":"That improved Mrs Goole's already favourable opinion of him.","cn":"那件事更加深了古尔太太对他的好印象。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"舆论；（群体的）信仰，观点","en":"You can refer to the beliefs or views that people have as opinion .","ex":{"en":"Some, I suppose, might even be in positions to influence opinion","cn":"有的人，我认为，甚至有可能影响舆论。"}},{"pos":"N-COUNT 可数名词","cn":"专家意见；鉴定","en":"An opinion from an expert is the advice or judgment that they give you in the subject that they know a lot about.","ex":{"en":"Even if you have had a regular physical check-up recently, you should still seek a medical opinion.","cn":"即使近期做过一次常规体检，也应当征求医生的意见。"}},{"pos":"PHRASE 短语","cn":"在…看来；据…的意见","en":"You add expressions such as 'in my opinion' or 'in their opinion' to a statement in order to indicate that it is what you or someone else thinks, and is not necessarily a fact.","ex":{"en":"The book is, in Henry's opinion, the best book on the subject","cn":"依照亨利的看法，这本书是关于该主题的最佳著述。"}},{"pos":"PHRASE 短语","cn":"持…观点；认为；相信","en":"If someone is of the opinion that something is the case, that is what they believe.","ex":{"en":"Frank is of the opinion that the 1934 yacht should have won.","cn":"弗兰克认为本该是那艘1934年的帆船获胜。"}},{"pos":"","cn":"","en":"a matter of opinion→see: ;"}]},"examples":[{"en":"If you want my opinion, I think you'd be crazy not to accept.","cn":"既然要我说嘛，我认为你不接受那才傻呢。"},{"en":"There is a difference of opinion (= people disagree) as to the merits of the plan.","cn":"关于这个计划的优缺点，大家意见分歧。"}]},"offer":{"media":{"uk":"media/uk/offer__gb_1.mp3","us":"media/us/offer__us_1.mp3"},"oxford":{"phon":"ˈɒfə(r)","pos":"verb","senses":[{"en":"to say that you are willing to give something to somebody","cn":"主动提供，主动给予（某事物）","g":"[transitive, intransitive]","lab":"British English or formal, North American English，，","ex":{"en":"Josie had offered her services as a guide.","cn":"乔西曾表示愿意当向导。"}},{"en":"to say that you are willing to do something for somebody","cn":"主动提出，主动分担（做某事）","g":"[transitive, intransitive]","ex":{"en":"The kids offered to do the dishes.","cn":"孩子们主动要求洗盘子。"}},{"en":"to make something available for sale or use","cn":"提供，供应（产品、服务等）","g":"[transitive]","ex":{"en":"The hotel offers excellent facilities for families.","cn":"本旅馆提供适合家庭的优良设施。"}},{"en":"to provide the opportunity for something; to provide access to something","cn":"提供（机会或权利）","g":"[transitive]","ex":{"en":"The job didn't offer any prospects for promotion.","cn":"这份工作没有任何升迁的希望。"}},{"en":"to show that you are ready to resist or attack somebody/something","cn":"表现出抵抗力（或攻击力）","g":"[transitive]","ex":{"en":"Universities offered little resistance to these changes.","cn":"大学对这些变化几乎毫无抵抗力。"}},{"en":"to give something to God","cn":"奉献，祭献（给上帝）","g":"[transitive]","lab":"formal","ex":{"en":"We offered up our prayers for the men's safe return.","cn":"我们祈求上苍保佑他们平安归来。"}},{"en":"an act of saying that you are willing to do something for somebody or give something to somebody","cn":"主动提议；建议","ex":{"en":"to receive a job offer","cn":"收到聘用邀约"},"pos":"noun"},{"en":"an amount of money that somebody is willing to pay for something","cn":"出价；报价","ex":{"en":"I've had an offer of $2 500 for the car.","cn":"有人向我出价 2 500 美元买这辆汽车。"},"pos":"noun"},{"en":"a reduction in the normal price of something, usually for a short period of time","cn":"（通常为短期的）减价，削价；处理价；特价","ex":{"en":"This special offer is valid until the end of the month.","cn":"这个特价优惠月底前有效。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提供；给予","en":"If you offer something to someone, you ask them if they would like to have it or use it.","ex":{"en":"He has offered seats at the conference table to the Russian leader and the president of Kazakhstan","cn":"他已邀请俄罗斯领导人和哈萨克斯坦总统参加会谈。"}},{"pos":"VERB 动词","cn":"（主动）表示愿意（做某事）；提议","en":"If you offer to do something, you say that you are willing to do it.","ex":{"en":"Peter offered to teach them water-skiing","cn":"彼得主动提出教他们滑水。"}},{"pos":"N-COUNT 可数名词","cn":"提供（物）；给予（物）；提议","en":"An offer is something that someone says they will give you or do for you.","ex":{"en":"The offer of talks with Moscow marks a significant change from the previous western position","cn":"提议与莫斯科举行会谈标志着西方立场的重大转变。"}},{"pos":"VERB 动词","cn":"提供（信息、建议等）；作出（表扬）","en":"If you offer someone information, advice, or praise, you give it to them, usually because you feel that they need it or deserve it.","ex":{"en":"They manage a company offering advice on mergers and acquisitions","cn":"他们经营着一家为兼并收购业务提供咨询的公司。"}},{"pos":"VERB 动词","cn":"给予，表示（爱、友谊等）","en":"If you offer someone something such as love or friendship, you show them that you feel that way towards them.","ex":{"en":"The President has offered his sympathy to the Georgian people","cn":"总统对格鲁吉亚人民表示了同情。"}},{"pos":"VERB 动词","cn":"（向上帝或神）奉献（祈祷、赞美），祭献（牺牲）","en":"If people offer prayers, praise, or a sacrifice to God or a god, they speak to or give something to their god.","ex":{"en":"Church leaders offered prayers and condemned the bloodshed","cn":"教会领袖向上帝祈祷并谴责流血事件。"}},{"pos":"VERB 动词","cn":"（机构等）提供，给予（服务、产品等）","en":"If an organization offers something such as a service or product, it provides it.","ex":{"en":"We have been successful because we are offering a quality service","cn":"我们因提供的服务水准一流一直经营得很成功。"}},{"pos":"N-COUNT 可数名词","cn":"（商品的）特价，特惠","en":"An offer in a shop is a specially low price for a specific product or something extra that you get if you buy a certain product.","ex":{"en":"This month's offers include a shirt, trousers and bed covers","cn":"本月的特价商品包括一款衬衫、裤子和多种床罩。"}},{"pos":"VERB 动词","cn":"（买方）出（价），开（价）","en":"If you offer a particular amount of money for something, you say that you will pay that much to buy it.","ex":{"en":"Whitney has offered $21.50 a share in cash for 49.5 million Prime shares","cn":"惠特尼公司开出每股21.50美元的现金价收购4,950 万股普赖姆公司的股票。"}},{"pos":"N-COUNT 可数名词","cn":"（买方的）报价，开价；赔偿金","en":"An offer is the amount of money that someone says they will pay to buy something or give to someone because they have harmed them in some way.","ex":{"en":"The lawyers say no one else will make me an offer","cn":"律师说不会再有人给我出价了。"}},{"pos":"PHRASE 短语","cn":"具有某种品质（或能力）","en":"If you have something to offer, you have a quality or ability that makes you important, attractive, or useful.","ex":{"en":"In your free time, explore all that this incredible city has to offer.","cn":"您可以在闲暇时间探索这座美妙城市的各种风情。"}},{"pos":"PHRASE 短语","cn":"提供的；供使用的；待售的","en":"If there is something on offer, it is available to be used or bought.","ex":{"en":"Savings schemes are the best retail investment products on offer.","cn":"储蓄方案是现有的最佳零售投资产品。"}},{"pos":"PHRASE 短语","cn":"愿意考虑买方出价；愿意接受合理报价","en":"If you are open to offers, you are willing to do something if someone will pay you an amount of money that you think is reasonable.","ex":{"en":"It seems that while the Kiwis are keen to have him, he is still open to offers.","cn":"看来尽管新西兰几维队很想与他签约，他仍然欢迎其他球队开价。"}},{"pos":"","cn":"","en":"相关词组：offer up"}]},"examples":[{"en":"I don't think they need help, but I think I should offer anyway.","cn":"我想他们不需要帮助，但我认为我还是应该主动提出来。"},{"en":"The original price was £3 000, but I'm open to offers (= willing to consider offers that are less than that).","cn":"原价为 3 000 英镑，但价钱还可以商量。"}]},"ounce":{"media":{"uk":"media/uk/ounce__gb_1.mp3","us":"media/us/ounce__us_1.mp3"},"oxford":{"phon":"aʊns","pos":"noun","senses":[{"en":"a unit for measuring weight, 116 of a pound, equal to 28.35 grams","cn":"盎司（重量单位，¹⁄₁₆ 磅，等于 28.35 克）","g":"[countable]"},{"en":"a very small quantity of something","cn":"少许；少量；一点点；丝毫","g":"[singular]","lab":"informal","ex":{"en":"There's not an ounce of truth in her story.","cn":"她所说的一点儿都不真实。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盎司（英国和美国的重量单位，1磅合16盎司，1盎司等于28.35克）","en":"An ounce is a unit of weight used in Britain and the USA. There are sixteen ounces in a pound and one ounce is equal to 28.35 grams.","ex":{"en":"...four ounces of sugar.","cn":"4盎司糖"}},{"pos":"N-SING 单数名词","cn":"少许；少量；一点点","en":"You can refer to a very small amount of something, such as a quality or characteristic, as an ounce .","ex":{"en":"If only my father had possessed an ounce of business sense","cn":"要是我父亲有一点点经商的头脑就好了。"}}]},"examples":[{"en":"There's not an ounce of truth in her story.","cn":"她所说的一点都不真实。"},{"en":"If you had an ounce of sense you wouldn’t believe him!","cn":"你要是有一点头脑就不会相信他！"}]},"oxygen":{"oxford":{"phon":"ˈɒksɪdʒən","pos":"noun","senses":[{"en":"a chemical element. Oxygen is a gas that is present in air and water and is necessary for people, animals and plants to live.","cn":"氧；氧气","ex":{"en":"The patient didn't seem to be getting enough oxygen.","cn":"病人似乎缺氧。"}},{"en":"a US 24-hour digital cable and satellite television channel that started in 2000. It is aimed especially at women and since 2017 has mainly shown programmes about real-life crimes, as well as police dramas.","cn":"氧气：美国的24小时数字有线电视和卫星电视频道，始于2000年。该频道特别针对女性，自2017年以来，主要播放有关现实生活犯罪和警察戏剧的节目。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"氧；氧气","en":"Oxygen is a colourless gas that exists in large quantities in the air. All plants and animals need oxygen in order to live.","ex":{"en":"The human brain needs to be without oxygen for only four minutes before permanent damage occurs.","cn":"人的大脑缺氧4分钟后便会造成永久性损伤。"}}]},"media":{"uk":"media/uk/oxygen__gb_1.mp3","us":"media/us/oxygen__us_1.mp3"}},"operating":{"lemma":"operate"},"overcrowded":{"media":{"uk":"media/uk/overcrowded__gb_1.mp3","us":"media/us/overcrowded__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈkraʊdɪd","pos":"adjective","senses":[{"en":"with too many people or things in it","cn":"过于拥挤的","ex":{"en":"overcrowded cities/prisons","cn":"拥挤不堪的城市／监狱"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方）过度拥挤的","en":"An overcrowded place has too many things or people in it.","ex":{"en":"...one of the most overcrowded prisons in the country.","cn":"该国最拥挤的监狱之一"}}]},"examples":[{"en":"Too many poor people are living in overcrowded conditions.","cn":"有太多贫民的居住环境十分拥挤。"},{"en":"overcrowded cities/prisons","cn":"拥挤不堪的城市/监狱"}]},"on":{"media":{"uk":"media/uk/on__gb_1.mp3","us":"media/us/on__us_1.mp3"},"oxford":{"phon":"ɒn","pos":"preposition","senses":[{"en":"in or into a position covering, touching or forming part of a surface","cn":"（覆盖、附着）在…上（意指接触物体表面或构成物体表面的一部分）","ex":{"en":"a picture on a wall","cn":"墙上的画"}},{"en":"supported by somebody/something","cn":"由…支撑着","ex":{"en":"She was standing on one foot.","cn":"她单脚站立着。"}},{"en":"used to show a means of transport","cn":"在（交通工具）上","ex":{"en":"He was on the plane from New York.","cn":"他在从纽约来的飞机上。"}},{"en":"by means of something; using something","cn":"通过；使用；借助于","ex":{"en":"She played a tune on her guitar.","cn":"她用她的吉他弹了一支曲子。"}},{"en":"used to show a day or date","cn":"在（某一天）","ex":{"en":"He came on Sunday.","cn":"他是星期天来的。"}},{"en":"used to describe an activity or a state","cn":"（用于说明活动或状态）","ex":{"en":"to be on business/holiday/vacation","cn":"在工作／度假中"}},{"en":"used to show direction","cn":"（表示方向）在，向，对","ex":{"en":"on the left/right","cn":"在左边／右边"}},{"en":"at or near a place","cn":"在，接近（某地）","ex":{"en":"a town on the coast","cn":"沿海的城镇"}},{"en":"used to show the basis or reason for something","cn":"根据；由于","ex":{"en":"a story based on fact","cn":"基于事实的小说"}},{"en":"immediately after something","cn":"就在…之后；一…就","ex":{"en":"On arriving home I discovered they had gone.","cn":"我一到家就发现他们已经离开了。"}},{"en":"about something/somebody","cn":"关于（事或人）","ex":{"en":"a book on South Africa","cn":"一本关于南非的书"}},{"en":"used to show that somebody belongs to a group or an organization","cn":"为（某团体或组织）的一员","ex":{"en":"to be on the committee/staff/jury/panel","cn":"为委员会／全体职员／陪审团／专家组的成员"}},{"en":"eating or drinking something; using a drug or a medicine regularly","cn":"吃；喝；按时服用（药物）","ex":{"en":"He lived on a diet of junk food.","cn":"他把垃圾食品当饭吃。"}},{"en":"paid for by something","cn":"以…支付；由…支付","ex":{"en":"to live on a pension/a student grant","cn":"靠养老金／助学金生活"}},{"en":"used when giving a phone number","cn":"（提供电话号码时用）","ex":{"en":"You can get me on 020 7946 0887.","cn":"你找我可以拨打 020 7946 0887。"}},{"en":"used with some nouns or adjectives to say who or what is affected by something","cn":"（与某些名词或形容词连用，表示影响到）","ex":{"en":"a ban on smoking","cn":"对吸烟的禁令"}},{"en":"being carried by somebody; in the possession of somebody","cn":"（身上）带着；有","ex":{"en":"Have you got any money on you?","cn":"你带钱了没有？"}},{"en":"compared with somebody/something","cn":"与…相比","ex":{"en":"Sales are up on last year.","cn":"销售量比去年增长了。"}},{"en":"on somebody’s body; being worn","cn":"穿在身上；穿着；戴着","ex":{"en":"Put your coat on.","cn":"把外衣穿上。"},"pos":"adverb"},{"en":"covering, touching or forming part of something","cn":"（表示覆盖、接触某物或成为某物的一部分）","ex":{"en":"Make sure the lid is on.","cn":"要注意盖上盖子。"},"pos":"adverb"},{"en":"in or into a vehicle","cn":"登上（车辆）","ex":{"en":"The bus stopped and four people got on.","cn":"公共汽车停下来，四个人上了车。"},"pos":"adverb"},{"en":"connected or operating; being used","cn":"（表示已连接、处于工作状态或使用中）","ex":{"en":"The lights were all on.","cn":"灯都亮着。"},"pos":"adverb"},{"en":"used to show that somebody/something moves or is sent forward","cn":"向前（移动）","ex":{"en":"She stopped for a moment, then walked on.","cn":"她停了一会儿，然后又向前走。"},"pos":"adverb"},{"en":"used to show that something continues","cn":"（表示持续性）","ex":{"en":"He worked on without a break.","cn":"他毫不停歇地继续工作。"},"pos":"adverb"},{"en":"happening","cn":"（表示发生）","ex":{"en":"There was a war on at the time.","cn":"当时正值战争。"},"pos":"adverb"},{"en":"planned to take place in the future","cn":"（预先安排的事）将发生","ex":{"en":"The game is still on (= it has not been cancelled).","cn":"比赛仍将举行。"},"pos":"adverb"},{"en":"on duty; working","cn":"值班；执行任务中","ex":{"en":"I'm on now till 8 tomorrow morning.","cn":"我正在值班，要值到明早 8 点钟。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（表示支承）在…上","en":"If someone or something is on a surface or object, the surface or object is immediately below them and is supporting their weight.","ex":{"en":"He is sitting beside her on the sofa","cn":"他挨着她坐在沙发上。"}},{"pos":"PREP 介词","cn":"（表示粘贴或附着）在…上","en":"If something is on a surface or object, it is stuck to it or attached to it.","ex":{"en":"I admired the peeling paint on the ceiling","cn":"我“观赏”着天花板上正在剥落的油漆。"}},{"pos":"PREP 介词","cn":"（放、扔或掉）在…上面","en":"If you put, throw, or drop something on a surface, you move it or drop it so that it is then supported by the surface.","ex":{"en":"He got his winter jacket from the closet and dropped it on the sofa","cn":"他从衣橱里取出冬天穿的夹克，把它扔到沙发上。"}},{"pos":"PREP 介词","cn":"（身体重量）由（某部位）支撑","en":"You use on to say what part of your body is supporting your weight.","ex":{"en":"He continued to lie on his back and look at clouds","cn":"他仍旧仰卧着，望着天上的云彩。"}},{"pos":"PREP 介词","cn":"（表示接触到身体某部位）在…上","en":"You use on to say that someone or something touches a part of a person's body.","ex":{"en":"He leaned down and kissed her lightly on the mouth","cn":"他俯下身去，在她嘴唇上轻轻一吻。"}},{"pos":"PREP 介词","cn":"（某种表情）在（脸）上","en":"If someone has a particular expression on their face, their face has that expression.","ex":{"en":"The maid looked at him, a nervous smile on her face","cn":"女服务员看着他，脸上带着一丝局促不安的微笑。"}},{"pos":"ADV 副词","cn":"（穿或戴）上，在身上","en":"When you put a piece of clothing on, you place it over part of your body in order to wear it. If you have it on, you are wearing it.","ex":{"en":"He put his coat on while she opened the front door","cn":"她打开前门时，他穿上了大衣。"}},{"pos":"PREP 介词","cn":"带在…身上","en":"You can say that you have something on you if you are carrying it in your pocket or in a bag.","ex":{"en":"I didn't have any money on me","cn":"我身上一分钱也没有。"}},{"pos":"PREP 介词","cn":"（视线）落在…身上","en":"If someone's eyes are on you, they are looking or staring at you.","ex":{"en":"Everyone's eyes were fixed on him","cn":"每个人都盯着他看。"}},{"pos":"PREP 介词","cn":"（碰）上…（而受伤）","en":"If you hurt yourself on something, you accidentally hit a part of your body against it and that thing causes damage to you.","ex":{"en":"Mr Pendle hit his head on a wall as he fell","cn":"彭德尔先生摔倒时头磕到了墙上。"}},{"pos":"PREP 介词","cn":"在（某）地","en":"If you are on an area of land, you are there.","ex":{"en":"He was able to spend only a few days at a time on the island","cn":"他每次去岛上都只能呆几天。"}},{"pos":"PREP 介词","cn":"是（道路、海岸等）的一部分；在…边上","en":"If something is situated on a place such as a road or coast, it forms part of it or is by the side of it.","ex":{"en":"Bergdorf Goodman has opened a men's store on Fifth Avenue","cn":"波道夫·古德曼在第五大道上开了一家男装店。"}},{"pos":"PREP 介词","cn":"上，乘（公共汽车、火车或飞机）","en":"If you get on a bus, train, or plane, you go into it in order to travel somewhere. If you are on it, you are travelling in it.","ex":{"en":"We waited till twelve and we finally got on the plane","cn":"我们一直等到12点才终于上了飞机。"}},{"pos":"PREP 介词","cn":"（写或印刷）在…上","en":"If there is something on a piece of paper, it has been written or printed there.","ex":{"en":"The writing on the back of the card was cramped but scrupulously neat","cn":"这张卡片的背面写满了密密麻麻但却十分工整的字。"}},{"pos":"PREP 介词","cn":"在（名单）上；包括在…内","en":"If something is on a list, it is included in it.","ex":{"en":"I've seen your name on the list of deportees","cn":"我看见你的名字在被驱逐出境者名单之列。"}},{"pos":"PREP 介词","cn":"（书、讨论或观点）关于，涉及","en":"Books, discussions, or ideas on a particular subject are concerned with that subject.","ex":{"en":"The longest chapter in almost any book on baby care is on feeding","cn":"几乎所有关于婴儿护理的书籍中内容最多的一章都是喂养。"}},{"pos":"PREP 介词","cn":"以，凭，靠（某一方法、原则或系统）","en":"You use on to introduce the method, principle, or system which is used to do something.","ex":{"en":"...a television that we bought on credit two months ago.","cn":"我们两个月前赊购的电视机"}},{"pos":"PREP 介词","cn":"通过，借助于（某一器械或机器）","en":"If something is done on an instrument or a machine, it is done using that instrument or machine.","ex":{"en":"...songs that I could just sit down and play on the piano","cn":"我坐下来就可以在钢琴上弹出的歌曲"}},{"pos":"PREP 介词","cn":"以…方式（储存信息）","en":"If information is, for example, on tape or on computer, that is the way that it is stored.","ex":{"en":"'I thought it was a load of rubbish.' — 'Right we've got that on tape.'","cn":"“我觉得那是一派胡言。”——“没错，我们已经把它录在磁带上了。”"}},{"pos":"PREP 介词","cn":"在（广播或电视）上播出","en":"If something is being broadcast, you can say that it is on the radio or television.","ex":{"en":"Every sporting event on television and satellite over the next seven days is listed","cn":"未来7天通过电视和卫星转播的每一项体育赛事都列在节目预告单上。"}},{"pos":"ADJ 形容词","cn":"正在发生的","en":"When an activity is taking place, you can say that it is on .","ex":{"en":"There's a marvellous match on at Wimbledon at the moment","cn":"此刻在温布尔登正进行着一场精彩的比赛。"}},{"pos":"ADV 副词","cn":"（表示某人忙碌程度）忙得很/没什么可忙","en":"You use on in expressions such as 'have a lot on' and 'not have very much on' to indicate how busy someone is.","ex":{"en":"I have a lot on in the next week.","cn":"我下周特别忙。"}},{"pos":"PREP 介词","cn":"（引出所进行的活动，特别是旅行）处于…情况中，在从事…中","en":"You use on to introduce an activity that someone is doing, particularly travelling.","ex":{"en":"I've always wanted to go on a cruise","cn":"我一直想坐游轮旅游。"}},{"pos":"ADV 副词","cn":"（机器、电灯等）开着，工作着，使用中","en":"When something such as a machine or an electric light is on, it is functioning or in use. When you switch it on, it starts functioning.","ex":{"en":"The light was on and the door was open","cn":"灯亮着，门也敞开着。"}},{"pos":"PREP 介词","cn":"是…的成员；供职于","en":"If you are on a committee or council, you are a member of it.","ex":{"en":"Claire and Beryl were on the organizing committee","cn":"克莱尔和贝丽尔是组委会成员。"}},{"pos":"PREP 介词","cn":"在（某一日子或日期）（发生）","en":"You can indicate when something happens by saying that it happens on a particular day or date.","ex":{"en":"This year's event will take place on June 19th, a week earlier than usual","cn":"今年的活动将于6月19日举行，比往年提前一周。"}},{"pos":"PREP 介词","cn":"在…后立即；一…就","en":"You use on when mentioning an event that was followed by another one.","ex":{"en":"She waited in her hotel to welcome her children on their arrival from London","cn":"她在宾馆里等候，准备第一时间迎接孩子们从伦敦过来。"}},{"pos":"ADV 副词","cn":"（继续）下去","en":"You use on to say that someone is continuing to do something.","ex":{"en":"They walked on in silence for a while","cn":"他们继续默默无语地走了一会儿。"}},{"pos":"ADV 副词","cn":"不停地（数落、抱怨、纠缠）","en":"If you say that someone goes on at you, you mean that they continually criticize you, complain to you, or ask you to do something.","ex":{"en":"She's been on at me for weeks to show her round the stables","cn":"她缠了我好几个星期了，要我带她去马厩看看。"}},{"pos":"ADV 副词","cn":"从…时候起；自…以后","en":"You use on in expressions such as from now on and from then on to indicate that something starts to happen at the time mentioned and continues to happen afterwards.","ex":{"en":"Perhaps it would be best not to see much of you from now on","cn":"也许从现在起我们最好少见面。"}},{"pos":"ADV 副词","cn":"（常用在副词early，late，far及其比较级之后，尤置于句首、句尾或介词之前）","en":"You often use on after the adverbs 'early', 'late', 'far', and their comparative forms, especially at the beginning or end of a sentence, or before a preposition.","ex":{"en":"The market square is a riot of colour and animation from early on in the morning","cn":"从大清早起这个市集广场就色彩缤纷，生机勃勃。"}},{"pos":"PREP 介词","cn":"定期服用；服…成瘾","en":"Someone who is on a drug takes it regularly.","ex":{"en":"She was on antibiotics for an eye infection that wouldn't go away","cn":"由于眼睛感染一直不见好，她在服用抗生素。"}},{"pos":"PREP 介词","cn":"以…（为食）；（机器）用（某种动力或燃料运转）","en":"If you live on a particular kind of food, you eat it. If a machine runs on a particular kind of power or fuel, it uses it in order to function.","ex":{"en":"The caterpillars feed on a wide range of trees, shrubs and plants","cn":"毛虫以各类树木、灌木和植物为食。"}},{"pos":"PREP 介词","cn":"以…（为收入）","en":"If you are on a particular income, that is the income that you have.","ex":{"en":"...young people who are unemployed or on low wages","cn":"失业或低收入的年轻人"}},{"pos":"PREP 介词","cn":"（税收或利润）获自…，来自…","en":"Taxes or profits that are obtained from something are referred to as taxes or profits on it.","ex":{"en":"...a general strike to protest a tax on food and medicine last week","cn":"上周抗议对食品和药品征税的大罢工"}},{"pos":"PREP 介词","cn":"在…方面（花钱）","en":"When you buy something or pay for something, you spend money on it.","ex":{"en":"I resolved not to waste money on a hotel","cn":"我决心不在住旅馆方面浪费钱。"}},{"pos":"PREP 介词","cn":"在…方面（花时间或精力）","en":"When you spend time or energy on a particular activity, you spend time or energy doing it.","ex":{"en":"People complain about how children spend so much time on computer games","cn":"人们常抱怨孩子花太多时间玩电脑游戏。"}},{"pos":"PHRASE 短语","cn":"无法接受的；行不通的","en":"If you say that something is not on or is just not on, you mean that it is unacceptable or impossible.","ex":{"en":"I'm not having children who don't like cheese. It's not on","cn":"我可不要不爱吃奶酪的孩子，那可不行。"}},{"pos":"PHRASE 短语","cn":"不停地；继续不断地","en":"If you say that something happens on and on, you mean that it continues to happen for a very long time.","ex":{"en":"...designers, builders, fitters — the list goes on and on","cn":"设计师、建筑工人、装配工——这个单子可以没完没了"}},{"pos":"PHRASE 短语","cn":"（表示困惑）在谈论什么","en":"If you ask someone what they are on about or what they are going on about, you are puzzled because you cannot understand what they are talking about.","ex":{"en":"What on earth are you going on about?","cn":"你到底在说些什么呀？"}},{"pos":"PHRASE 短语","cn":"（表示有信心）知道自己在说些什么，了解情况","en":"If you say that someone knows what they are on about, you are confident that what they are saying is true or makes sense, for example because they are an expert.","ex":{"en":"It looks like he knows what he's on about.","cn":"他看起来很在行。"}},{"pos":"PHRASE 短语","cn":"掌握不利于（某人）的证据；抓住（某人）的把柄","en":"If someone has something on you, they have evidence that you have done something wrong or bad. If they have nothing on you, they cannot prove that you have done anything wrong or bad.","ex":{"en":"He may have something on her. He may have supplied her with drugs, and then threatened to tell if she didn't do this","cn":"他或许抓住了她的什么把柄。可能是给她提供了毒品，然后威胁她如果不这样做的话就告发她。"}},{"pos":"","cn":"","en":"on behalf of→see: ; on and off→see: ; and so on→see: ; on top of→see: ;"}]},"examples":[{"en":"You can get me on 020 7946 0887.","cn":"你找我可以拨打 020 7946 0887。"},{"en":"I didn't know what he was on about. It didn't make sense.","cn":"我不知道他说的是什么，他说得不清不楚的。"}]},"outwards":{"media":{"uk":"media/uk/outwards__gb_1.mp3","us":"media/us/outwards__us_1.mp3"},"oxford":{"phon":"ˈaʊtwədz","pos":"adverb","senses":[{"en":"towards the outside; away from the centre or from a particular point","cn":"向外；朝外","ex":{"en":"The door opens outwards.","cn":"这个门向外开。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向外;朝外","en":"If something moves or faces outwards, it moves or faces away from the place you are in or the place you are talking about.","ex":{"en":"The top door opened outwards","cn":"顶上的门朝外开。"}},{"pos":"ADV 副词","cn":"（注意力）向外地，对外地","en":"If you say that a person or a group of people, such as a government, looks outwards, you mean that they turn their attention to another group that they are interested in or would like greater involvement with.","ex":{"en":"Other poor countries looked outward, strengthening their ties to the economic superpowers","cn":"其他贫穷国家将目光投向国外，加强与经济强国的联系。"}}]},"examples":[{"en":"Factories were spreading outwards from the old heart of the town.","cn":"工厂从旧城中心逐渐向外扩展。"},{"en":"The door opens outwards.","cn":"这个门向外开。"}]},"outlook":{"oxford":{"phon":"ˈaʊtlʊk","pos":"noun","senses":[{"en":"the attitude to life and the world of a particular person, group or culture","cn":"观点；见解；世界观；人生观","ex":{"en":"Travel broadens your outlook.","cn":"旅行可以开阔眼界。"}},{"en":"the likely future for somebody/something; what is likely to happen","cn":"前景；可能性","ex":{"en":"the country’s economic outlook","cn":"国家的经济前景"}},{"en":"a view from a particular place","cn":"景色；景致；景观","lab":"formal","ex":{"en":"The house has a pleasant outlook over the valley.","cn":"房子俯瞰山谷，景色宜人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"世界观；人生观；（对生活的）观点，看法","en":"Your outlook is your general attitude towards life.","ex":{"en":"The illness had a profound effect on his outlook","cn":"这场病对他的人生观产生了深刻的影响。"}},{"pos":"N-SING 单数名词","cn":"展望；前景；可能性","en":"The outlook for something is what people think will happen in relation to it.","ex":{"en":"The economic outlook is one of rising unemployment","cn":"展望未来的经济，失业率将会上升。"}}]},"media":{"uk":"media/uk/outlook__gb_1.mp3","us":"media/us/outlook__us_1.mp3"},"examples":[{"en":"Most Western societies are liberal in outlook.","cn":"西方社会大多思想观念开放。"},{"en":"The house has a pleasant outlook over the valley.","cn":"房子俯瞰山谷，景色宜人。"}]},"openings":{"lemma":"open","media":{"uk":"media/uk/opening__gb_1.mp3","us":"media/us/opening__us_1.mp3"}},"office":{"media":{"img":["media/pic/office_labels_comp.jpg","media/thumb/office.jpg"],"uk":"media/uk/office__gb_1.mp3","us":"media/us/office__us_1.mp3"},"oxford":{"phon":"ˈɒfɪs","pos":"noun","senses":[{"en":"a room, set of rooms or building where people work, usually sitting at desks","cn":"办公室；办公楼","g":"[countable]","lab":"British English","sc":"room/building","ex":{"en":"The company is moving to new offices on the other side of town.","cn":"公司要迁往城另一边的新办公楼。"}},{"en":"a room in which a particular person works, usually at a desk","cn":"（某人的）办公室","g":"[countable]","sc":"room/building","ex":{"en":"Some people have to share an office.","cn":"有些人只好合用一间办公室。"}},{"en":"a place where a doctor, dentist or vet sees patients","cn":"诊室；门诊处","g":"[countable]","lab":"North American English","sc":"room/building","ex":{"en":"a doctor’s/dentist’s office","cn":"诊室；牙医诊所"}},{"en":"a room or building used for a particular purpose, especially to provide information or a service","cn":"办事处；（尤指）问询处，服务处","g":"[countable]","sc":"room/building","ex":{"en":"a ticket office","cn":"售票处"}},{"en":"used in the names of some British government departments","cn":"（用于英国某些政府部门的名称中）","g":"[countable]","sc":"government department","ex":{"en":"the Home Office","cn":"内政部"}},{"en":"an important position of authority, especially in government; the work and duties connected with this","cn":"要职；重要官职；重要职务","g":"[uncountable, countable]","lab":"especially North American English","sc":"important position","ex":{"en":"She held office as a cabinet minister for ten years.","cn":"她担任内阁部长长达十年。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"办公室","en":"An office is a room or a part of a building where people work sitting at desks.","ex":{"en":"He had an office big enough for his desk and chair, plus his VDU","cn":"他有一间足以容纳书桌、椅子和视频显示器的办公室。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（尤指政府的）部，局，厅","en":"An office is a department of an organization, especially the government, where people deal with a particular kind of administrative work.","ex":{"en":"Thousands have registered with unemployment offices.","cn":"已有数千人在失业管理处作了登记。"}},{"pos":"N-COUNT 可数名词","cn":"（问询、购票或提供服务的）处，所","en":"An office is a small building or room where people can go for information, tickets, or a service of some kind.","ex":{"en":"The tourist office operates a useful room-finding service.","cn":"这家旅游办事处提供十分实用的住宿查询服务。"}},{"pos":"N-COUNT 可数名词","cn":"诊所","en":"A doctor's or dentist's office is a place where a doctor or dentist sees their patients."},{"pos":"N-UNCOUNT 不可数名词","cn":"要职；公职；官职","en":"If someone holds office in a government, they have an important job or position of authority.","ex":{"en":"The events to mark the President's ten years in office went ahead as planned","cn":"总统任职10周年的庆祝活动按计划进行。"}},{"pos":"PHRASE 短语","cn":"帮助；协助","en":"Someone's good offices are the help that they give to other people who are trying to achieve something.","ex":{"en":"She sought the good offices of the President for the smooth passage of the Bill.","cn":"为了使该法案顺利通过，她寻求总统的帮助。"}}]},"examples":[{"en":"The present government took office in 2009.","cn":"现政府于 2009 年上台执政。"},{"en":"The company is moving to new offices on the other side of town.","cn":"公司要迁往城另一边的新办公楼。"}]},"opera":{"media":{"uk":"media/uk/opera__gb_1.mp3","us":"media/us/opera__us_1.mp3"},"oxford":{"phon":"ˈɒprə","pos":"noun","senses":[{"en":"a dramatic work in which all or most of the words are sung to music; works of this type as an art form or entertainment","cn":"歌剧；歌剧剧本；歌剧艺术","g":"[countable, uncountable]","ex":{"en":"Puccini’s operas","cn":"普契尼的歌剧"}},{"en":"a company that performs opera; a building in which operas are performed","cn":"歌剧团；歌剧院","g":"[countable]","ex":{"en":"the Vienna State Opera","cn":"维也纳国家歌剧院"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"歌剧","en":"An opera is a play with music in which all the words are sung.","ex":{"en":"...a one-act opera about contemporary women in America.","cn":"关于当代美国女性的独幕歌剧"}}]},"examples":[{"en":"operatic arias/composers","cn":"歌剧咏叹调/作曲家"},{"en":"the Vienna State Opera","cn":"维也纳国家歌剧院"}]},"oft":{"media":{"uk":"media/uk/oft__gb_1.mp3","us":"media/us/oft__us_1.mp3"},"oxford":{"phon":"ɒft","pos":"adverb","senses":[{"en":"often","cn":"经常"},{"en":"often","cn":"经常","ex":{"en":"an oft-repeated claim","cn":"一再重复的说法"},"pos":"prefix"}]}},"operation":{"media":{"uk":"media/uk/operation__gb_1.mp3","us":"media/us/operation__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈreɪʃn","pos":"noun","senses":[{"en":"the process of cutting open a part of a person’s body in order to remove or repair a damaged part","cn":"手术","g":"[countable]","lab":"also British English, informal，，","sc":"medical","ex":{"en":"Will I need to have an operation?","cn":"我需要动手术吗？"}},{"en":"an organized activity that involves several people","cn":"（有组织的）活动，行动","g":"[countable]","sc":"organized activity","ex":{"en":"Weather conditions were too bad to mount a rescue operation.","cn":"天气条件太恶劣，无法开展救援行动。"}},{"en":"a business or company, usually one that involves many parts","cn":"（通常有多个部门的）企业，公司","g":"[countable]","sc":"business","ex":{"en":"a huge multinational operation","cn":"庞大的跨国公司"}},{"en":"the activity or work done in a company, or in an area of business or industry","cn":"（企业或工商业）活动，业务","g":"[countable, usually plural]","sc":"business","ex":{"en":"The firm is looking to expand its operations overseas.","cn":"该公司正寻求扩大其海外业务。"}},{"en":"the department in a company that manages the way it produces goods or delivers services and makes sure its business practices are efficient","cn":"公司中负责生产商品或提供服务的方式并确保其业务实践高效的部门","g":"[plural]","lab":"informal","sc":"business","ex":{"en":"He works in operations.","cn":"他从事运营工作。"}},{"en":"an act performed by a machine, especially a computer","cn":"运算；运作","g":"[countable, uncountable]","sc":"computer","ex":{"en":"The whole operation is performed in less than three seconds.","cn":"全部运算在三秒内完成。"}},{"en":"the way that parts of a machine or a system work; the process of making something work","cn":"运转；运行；操作","g":"[uncountable]","sc":"machine/system","ex":{"en":"Regular servicing guarantees the smooth operation of the engine.","cn":"定期维修可保持发动机的顺畅运转。"}},{"en":"the action of functioning; the fact of being used or active or having an effect","cn":"正常工作；运作；使用中；生效","g":"[uncountable]","sc":"machine/system","ex":{"en":"The factory will cease operation at the end of the year.","cn":"工厂将于年底停止运营。"}},{"en":"military activity","cn":"军事行动","g":"[countable, usually plural]","sc":"military activity","ex":{"en":"joint military/combat operations","cn":"联合军事／联合作战行动"}},{"en":"a process in which a number or quantity is changed by adding, multiplying, etc.","cn":"运算","g":"[countable]","sc":"mathematics"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（由大量人员参与、具有高度组织性的）活动，行动，工作","en":"An operation is a highly organized activity that involves many people doing different things.","ex":{"en":"The rescue operation began on Friday afternoon","cn":"救援行动于星期五下午开始。"}},{"pos":"N-COUNT 可数名词","cn":"企业；公司","en":"A business or company can be referred to as an operation .","ex":{"en":"Thorn's electronics operation employs around 5,000 people","cn":"索恩的电子公司雇用了约5,000名员工。"}},{"pos":"N-COUNT 可数名词","cn":"手术","en":"When a patient has an operation, a surgeon cuts open their body in order to remove, replace, or repair a diseased or damaged part.","ex":{"en":"Charles was at the clinic recovering from an operation on his arm.","cn":"查尔斯的胳膊动了手术，正在这家诊所进行康复治疗。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"使用；运作","en":"If a system is in operation, it is being used.","ex":{"en":"Until the rail links are in operation, passengers can only travel through the tunnel by coach.","cn":"在铁路连线开通之前，乘客只能乘坐长途客车穿越隧道。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（机器、设备等的）运转，运行","en":"If a machine or device is in operation, it is working.","ex":{"en":"There are three ski lifts in operation.","cn":"有3台滑雪缆车在运行。"}},{"pos":"PHRASE 短语","cn":"（使）施行；（使）实行；（使）生效","en":"When a rule, system, or plan comes into operation or you put it into operation, you begin to use it.","ex":{"en":"The Financial Services Act came into operation four years ago","cn":"《金融服务法》于4年前开始实施。"}}]},"examples":[{"en":"The police have launched a major operation against drug suppliers.","cn":"警方展开了一次打击毒贩的大规模行动。"},{"en":"Doctors performed an emergency operation for appendicitis last night.","cn":"医生昨天夜里做了紧急阑尾炎手术。"}]},"off":{"media":{"uk":"media/uk/off__gb_1.mp3","us":"media/us/off__us_1.mp3"},"oxford":{"phon":"ɒf","pos":"adverb","senses":[{"en":"used to say that something has been removed or become separated","cn":"（用以表示除去了某物）","ex":{"en":"He's had his beard shaved off.","cn":"他把胡子刮掉了。"}},{"en":"not connected or functioning","cn":"未连接；不工作","ex":{"en":"The water is off.","cn":"停水了。"}},{"en":"away from a place; at a distance in space or time","cn":"离开（某处）；（在空间或时间上）距，离","ex":{"en":"I called him but he ran off.","cn":"我喊他，可他跑开了。"}},{"en":"away from work or duty","cn":"休假；休息","ex":{"en":"She's off today.","cn":"她今天休假。"}},{"en":"starting a race","cn":"起跑","ex":{"en":"They're off (= the race has begun).","cn":"他们起跑了。"}},{"en":"taken from the price","cn":"减价的；削价的","ex":{"en":"shoes with $20 off","cn":"减价 20 美元的鞋"}},{"en":"no longer going to happen; cancelled","cn":"不再会发生；被取消","ex":{"en":"The wedding is off.","cn":"婚礼被取消了。"}},{"en":"no longer available or being served","cn":"没有；不再供应","lab":"especially British English","ex":{"en":"Sorry, the duck is off.","cn":"对不起，鸭子卖光了。"}},{"en":"behind or at the sides of the stage in a theatre","cn":"在剧院舞台的后面（或旁边）"},{"en":"down or away from a place or at a distance in space or time","cn":"从（某处）落下；离开；（时空上）离，距","ex":{"en":"I fell off the ladder.","cn":"我从梯子上跌了下来。"},"pos":"preposition"},{"en":"used to say that something has been removed","cn":"从…去掉；从…移开","ex":{"en":"You need to take the top off the bottle first!","cn":"你得先把瓶盖子打开！"},"pos":"preposition"},{"en":"away from work or duty","cn":"休假；休息","ex":{"en":"He's had ten days off school.","cn":"他有十天没上学了。"},"pos":"preposition"},{"en":"away from a price","cn":"偏离…价格；削价；杀价","ex":{"en":"They knocked £500 off the car.","cn":"他们对这辆汽车杀价 500 英镑。"},"pos":"preposition"},{"en":"leading away from something, for example a road or room","cn":"离开；偏离","ex":{"en":"We live off Main Street.","cn":"我们住在大街附近。"},"pos":"preposition"},{"en":"from a person or place","cn":"从某人（或某地）","lab":"informal","ex":{"en":"I got this off a website somewhere.","cn":"这是我从某个网站上找到的。"},"pos":"preposition"},{"en":"off; from","cn":"离开；来源于；从","lab":"non-standard or North American English, informal，，","ex":{"en":"She jumped off of the wall.","cn":"她从墙上跳了下来。"},"pos":"preposition"},{"en":"not wanting or liking something that you usually eat or use","cn":"不想；戒除","ex":{"en":"I'm off (= not drinking) alcohol for a week.","cn":"我有一星期没喝酒了。"},"pos":"preposition"},{"en":"no longer fresh enough to eat or drink","cn":"不新鲜；变质","lab":"British English","ex":{"en":"This fish has gone off.","cn":"这条鱼已变质了。"},"pos":"adjective"},{"en":"not polite or friendly","cn":"不礼貌；不热情；冷淡","lab":"informal, especially British English，，","ex":{"en":"He was a bit off with me this morning.","cn":"他今天早晨对我有点冷淡。"},"pos":"adjective"},{"en":"not acceptable","cn":"不能接受；难以容忍；不行","lab":"informal, especially British English，，","ex":{"en":"It's a bit off expecting us to work on Sunday.","cn":"让我们星期天上班工作，那可不太行吧。"},"pos":"adjective"},{"en":"the start of a race","cn":"起跑","ex":{"en":"They're ready for the off.","cn":"他们准备起跑了。"},"pos":"noun"},{"en":"to kill somebody","cn":"杀死（某人）","pos":"verb"},{"en":"not on; away from","cn":"不在…上；离开；去掉","ex":{"en":"offstage","cn":"幕后的"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"从…移开；从…脱离","en":"If something is taken off something else or moves off it, it is no longer touching that thing.","ex":{"en":"He took his feet off the desk","cn":"他把脚从桌上移开。"}},{"pos":"PREP 介词","cn":"从（交通工具）上下来","en":"When you get off a bus, train, or plane, you come out of it or leave it after you have been travelling on it.","ex":{"en":"Don't try to get on or off a moving train!","cn":"火车运行时请勿上下车！"}},{"pos":"PREP 介词","cn":"不去,不涉足（某处）","en":"If you keep off a street or piece of land, you do not step on it or go there.","ex":{"en":"Locking up men does nothing more than keep them off the streets","cn":"把这些人关起来只是做到了不让他们上街而已。"}},{"pos":"PREP 介词","cn":"离（某地）不远；在…附近","en":"If something is situated off a place such as a coast, room, or road, it is near to it or next to it, but not exactly in it.","ex":{"en":"The boat was anchored off the northern coast of the peninsula","cn":"这艘船停泊在离该半岛北部海岸不远的地方。"}},{"pos":"ADV 副词","cn":"离开","en":"If you go off, you leave a place.","ex":{"en":"He was just about to drive off when the secretary came running out","cn":"他正打算驾车离开，这时秘书跑了出来。"}},{"pos":"ADV 副词","cn":"（用于非正式及有时具冒犯性的短语动词）（走）开，（滚）开","en":"Off is used in a number of informal and sometimes offensive phrasal verbs, such as buzz off ,clear off, or in British English bugger off, which are used to tell someone angrily to go away."},{"pos":"ADV 副词","cn":"（脱）掉（衣服）；（取）下（首饰）","en":"When you take off clothing or jewellery that you are wearing, you remove it from your body.","ex":{"en":"He took off his spectacles and rubbed frantically at the lens","cn":"他摘下眼镜，疯狂地擦着镜片。"}},{"pos":"ADV 副词","cn":"（因生病、放假等等）休息，不工作","en":"If you have time off or a particular day off, you do not go to work or school, for example because you are ill or it is a day when you do not usually work.","ex":{"en":"The rest of the men had the day off","cn":"其他人这天没上班。"}},{"pos":"PREP 介词","cn":"避开（某话题）","en":"If you keep off a subject, you deliberately avoid talking about it.","ex":{"en":"Keep off the subject of politics","cn":"勿谈政治。"}},{"pos":"ADV 副词","cn":"取消；中止","en":"If something such as an agreement or a sporting event is off, it is cancelled.","ex":{"en":"Until Pointon is completely happy, however, the deal's off","cn":"但是，在波因顿完全满意之前，这一协议不再作数。"}},{"pos":"PREP 介词","cn":"停服，停用（药物等）；戒…","en":"If someone is off something harmful such as a drug, they have stopped taking or using it.","ex":{"en":"She felt better and the psychiatrist took her off drug therapy","cn":"她感觉好些了，那位精神科医生让她停止了药物治疗。"}},{"pos":"PREP 介词","cn":"不再喜欢；不再想","en":"If you are off something, you have stopped liking it.","ex":{"en":"I'm off coffee at the moment","cn":"我眼下不再嗜咖啡了。"}},{"pos":"ADV 副词","cn":"（机器、电灯等）关掉，停掉，不再运转","en":"When something such as a machine or electric light is off, it is not functioning or in use. When you switch it off, you stop it functioning.","ex":{"en":"As he pulled into the driveway, he saw her bedroom light was off","cn":"当他把车开进车道时，他看到她卧室的灯已经熄了。"}},{"pos":"PREP 介词","cn":"（价格）减掉，降低","en":"If there is money off something, its price is reduced by the amount specified.","ex":{"en":"...Simons Leatherwear, 37 Old Christchurch Road. 20 per cent off all jackets this Saturday.","cn":"本周六老基督堂路37号的西蒙斯皮衣店所有夹克降价20％。"}},{"pos":"ADV 副词","cn":"（空间上）离，距","en":"If something is a long way off, it is a long distance away from you.","ex":{"en":"Florida was a long way off","cn":"佛罗里达离这儿很远。"}},{"pos":"ADV 副词","cn":"（时间上）离，距","en":"If something is a long time off, it will not happen for a long time.","ex":{"en":"An end to the crisis seems a long way off","cn":"这场危机看来远未结束。"}},{"pos":"PREP 介词","cn":"从…（获得）","en":"If you get something off someone, you obtain it from them.","ex":{"en":"I don't really get a lot of information, and if I do I get it off Mark","cn":"我得到的信息其实不多，即使有也是马克告诉我的。"}},{"pos":"COMB in ADJ-GRADED","cn":"（与well,badly,worse等副词连用构成形容词）表示“处于…境况的”","en":"Off combines with adverbs such as 'well', 'badly', and 'worse' to form adjectives that indicate how poor or rich someone is.","ex":{"en":"Most of these people aren't very well off","cn":"这些人大都不算太富裕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物）腐坏的，变质的，变味的","en":"If food has gone off, it tastes and smells bad because it is no longer fresh enough to be eaten.","ex":{"en":"Don't eat that! It's mouldy. It's gone off!","cn":"别吃那个！它已经发霉变质了！"}},{"pos":"PREP 介词","cn":"依靠（食物、钱等生存）","en":"If you live off a particular kind of food, you eat it in order to live. If you live off a particular source of money, you use it to live.","ex":{"en":"Her husband's memories are of living off roast chicken and drinking whisky","cn":"她丈夫只记得过去吃烤鸡、喝威士忌的日子。"}},{"pos":"PREP 介词","cn":"（机器）靠（某种燃料或动力运转）","en":"If a machine runs off a particular kind of fuel or power, it uses that power in order to function.","ex":{"en":"The Auto Compact Disc Cleaner can run off batteries or mains.","cn":"这种光盘自动清洗机可用电池或电源两种方式驱动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为）过头的，不当的，无法接受的","en":"If you say that someone's behaviour is a bit off, you mean that you find it unacceptable or wrong.","ex":{"en":"...coming home with make-up all over his clothes — it's a bit off isn't it","cn":"衣服上到处沾着化妆品回到家——他这样有点过分了，是不是。"}},{"pos":"PHRASE 短语","cn":"偶尔；有时；断断续续地","en":"If something happens on and off, or off and on, it happens occasionally, or only for part of a period of time, not in a regular or continuous way.","ex":{"en":"I was still working on and off as a waitress to support myself","cn":"我为了糊口仍然间或去做服务员。"}}]},"examples":[{"en":"Families will be better off under the new law (= will have more money).","cn":"这项新法律将使每个家庭的经济较前宽裕。"},{"en":"The weather was so bad we'd have been better off staying at home.","cn":"天气太糟了，我们要是待在家里就好了。"}]},"orange":{"oxford":{"phon":"ˈɒrɪndʒ","pos":"noun","senses":[{"en":"a round citrus fruit with thick skin of a colour between red and yellow and a lot of sweet juice","cn":"橙子；柑橘","ex":{"en":"orange peel/zest/rind","cn":"橘皮"}},{"en":"orange juice, or a drink made from or tasting of oranges","cn":"橙汁；橘汁饮料","lab":"British English","ex":{"en":"Would you like some orange?","cn":"您想喝点橙汁吗？"}},{"en":"a bright colour between red and yellow","cn":"橙红色；橘黄色","ex":{"en":"I like bright colours—orange and yellow are my favourites.","cn":"我喜欢鲜艳的颜色——橙色和黄色是我的最爱。"}},{"en":"between red and yellow in colour","cn":"橙红色的；橘黄色的","ex":{"en":"yellow and orange flames","cn":"黄色和橙色的火焰"},"pos":"adjective"},{"en":"related to or belonging to a Protestant political group which believes that Northern Ireland should remain part of the UK","cn":"奥兰治党的，奥兰治社团的（新教政治团体，主张北爱尔兰继续隶属英国）","ex":{"en":"an Orange march","cn":"奥兰治党的游行"},"pos":"adjective"},{"en":"a former mobile phone company that was started in Britain in 1994. It had a well-known advertising slogan: “The future's bright. The future's Orange.” In 2010 Orange joined with T-Mobile UK to form EE.","cn":"一家前手机公司，于1994年在英国成立。它有一个著名的广告口号：","pos":""}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"橙色；橙黄色","en":"Something that is orange is of a colour between red and yellow.","ex":{"en":"...men in bright orange uniforms.","cn":"身着亮橙色制服的人"}},{"pos":"N-VAR 可变名词","cn":"橙；甜橙","en":"An orange is a round juicy fruit with a thick, orange coloured skin.","ex":{"en":"An orange a day will give you all the vitamin C you need.","cn":"每天吃一个橙子能充分摄取所需的维生素C。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"橙汁；橘子水","en":"Orange is a drink that is made from or tastes of oranges.","ex":{"en":"...vodka and orange.","cn":"橙汁伏特加酒"}}]},"media":{"img":["media/pic/citrus_fruits_comp.jpg","media/thumb/orange.jpg"],"uk":"media/uk/orange__gb_1.mp3","us":"media/us/orange__us_1.mp3"},"examples":[{"en":"A vodka and orange, please.","cn":"请来一份橙汁伏特加酒。"},{"en":"Would you like some orange?","cn":"您想喝点橙汁吗？"}]},"occurrences":{"lemma":"occurrence"},"organize":{"oxford":{"phon":"ˈɔːɡənaɪz","pos":"verb","senses":[{"en":"to make all the arrangements for something to happen or be provided","cn":"组织；筹备","g":"[transitive]","ex":{"en":"He helped to organize various events.","cn":"他协助组织了各种活动。"}},{"en":"to arrange something or the parts of something into a particular order or structure","cn":"安排；处理；分配","g":"[transitive]","ex":{"en":"Modern computers can organize large amounts of data very quickly.","cn":"现代计算机能迅速处理大量的信息资料。"}},{"en":"to plan your/somebody’s work and activities in an efficient way","cn":"规划；管理；照料","g":"[transitive]","ex":{"en":"I'm sure you don't need me to organize you.","cn":"我相信你用不着我为你安排。"}},{"en":"to form a group of people with a shared aim, especially a union or political party","cn":"（使）成立，组建，建立（联盟、党派等）","g":"[transitive, intransitive]","ex":{"en":"the right of workers to organize themselves into unions","cn":"工人自行组织工会的权利"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"组织；安排；筹备","en":"If you organize an event or activity, you make sure that the necessary arrangements are made.","ex":{"en":"In the end, we all decided to organize a concert for Easter.","cn":"最终，我们一致决定组织一场复活节音乐会。"}},{"pos":"VERB 动词","cn":"提供，准备（想要或所需之物）","en":"If you organize something that someone wants or needs, you make sure that it is provided.","ex":{"en":"I will organize transport","cn":"我来安排交通。"}},{"pos":"VERB 动词","cn":"整理；使有条理；使具结构","en":"If you organize a set of things, you arrange them in an ordered way or give them a structure.","ex":{"en":"He began to organize his materials","cn":"他开始整理材料。"}},{"pos":"VERB 动词","cn":"规划（自己）；使有序高效","en":"If you organize yourself, you plan your work and activities in an ordered, efficient way.","ex":{"en":"...changing the way you organize yourself","cn":"改变自我规划的方式"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）组织起来","en":"If someone organizes workers or if workers organize, they form a group or society such as a trade union in order to have more power.","ex":{"en":"...helping to organize women working abroad","cn":"帮助组织在国外工作的妇女"}}]},"media":{"uk":"media/uk/organize__gb_1.mp3","us":"media/us/organize__us_1.mp3"},"examples":[{"en":"Modern computers can organize large amounts of data very quickly.","cn":"现代计算机能迅速处理大量的信息资料。"},{"en":"I'll invite people if you can organize food and drinks.","cn":"如果你能备办饮食，我就负责邀请人。"}]},"ours":{"media":{"uk":"media/uk/ours__gb_1.mp3","us":"media/us/ours__us_1.mp3"},"oxford":{"phon":"ɑːz","pos":"pronoun","senses":[{"en":"the one or ones that belong to us","cn":"我们的","ex":{"en":"Their house is very similar to ours, but ours is bigger.","cn":"他们的房子和我们的十分相像，但我们的要大些。"}},{"en":"our home","cn":"我们的住处","lab":"British English, informal，，","ex":{"en":"Do you fancy coming to ours for Sunday dinner?","cn":"周日来我们家吃晚饭怎么样？"}}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"我们的","en":"You use ours to refer to something that belongs or relates both to yourself and to one or more other people.","ex":{"en":"Japanese democracy is certainly different from ours","cn":"日本的民主制度无疑与我们的不同。"}}]},"examples":[{"en":"Their house is very similar to ours, but ours is bigger.","cn":"他们的房子和我们的十分相像，但我们的要大些。"},{"en":"No, those are Ellie's kids. Ours are upstairs.","cn":"不，那些是埃利的孩子。我们的都在楼上。"}]},"obese":{"media":{"uk":"media/uk/obese__gb_1.mp3","us":"media/us/obese__us_1.mp3"},"oxford":{"phon":"əʊˈbiːs","pos":"adjective","senses":[{"en":"very fat, in a way that is not healthy","cn":"臃肿的；虚胖的；病态肥胖的","lab":"British English","ex":{"en":"Obese patients are given dietary advice.","cn":"给过于肥胖的病人提了饮食方面的建议。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过分肥胖的；臃肿的；虚胖的","en":"If someone is obese, they are extremely fat.","ex":{"en":"The tendency to become obese is at least in part hereditary","cn":"发胖至少有一部分是源于遗传。"}}]},"examples":[{"en":"Obesity can increase the risk of heart disease.","cn":"肥胖会增加患心脏病的危险。"}]},"outweighs":{"lemma":"outweigh"},"obtained":{"lemma":"obtain"},"ominous":{"media":{"uk":"media/uk/ominous__gb_1.mp3","us":"media/us/ominous__us_1.mp3"},"oxford":{"phon":"ˈɒmɪnəs","pos":"adjective","senses":[{"en":"suggesting that something bad is going to happen in the future","cn":"不祥的；恶兆的；不吉利的","ex":{"en":"There were ominous dark clouds gathering overhead.","cn":"不祥的黑云在头顶上汇聚。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不祥的；恶兆的；不吉利的","en":"If you describe something as ominous, you mean that it worries you because it makes you think that something unpleasant is going to happen.","ex":{"en":"There was an ominous silence at the other end of the phone","cn":"电话那头出现了不祥的沉默。"}}]},"examples":[{"en":"She picked up the phone but there was an ominous silence at the other end.","cn":"她拿起电话，但对方只有不祥的沉默。"},{"en":"There were ominous dark clouds gathering overhead.","cn":"不祥的黑云在头顶上汇聚。"}]},"overland":{"oxford":{"phon":"ˈəʊvəlænd","pos":"adverb","senses":[{"en":"across the land; by land, not by sea or by air","cn":"横跨陆地的；通过陆路的","ex":{"en":"to travel overland","cn":"经陆路前往"}},{"en":"across the land; by land, not by sea or by air","cn":"横跨陆地的；通过陆路的","ex":{"en":"an overland route","cn":"陆上路线"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"经由陆路的；横跨陆地的","en":"An overland journey is made across land rather than by ship or aeroplane.","ex":{"en":"...an overland journey through Iraq, Turkey, Iran and Pakistan","cn":"途径伊拉克、土耳其、伊朗和巴基斯坦的陆路旅程"}}]},"media":{"uk":"media/uk/overland__gb_1.mp3","us":"media/us/overland__us_1.mp3"},"examples":[{"en":"to travel overland","cn":"作陆上旅行"},{"en":"an overland route","cn":"陆上路线"}]},"ordered":{"media":{"uk":"media/uk/ordered__gb_1.mp3","us":"media/us/ordered__us_1.mp3"},"oxford":{"phon":"ˈɔːdəd","pos":"adjective","senses":[{"en":"carefully arranged or organized","cn":"精心安排的；组织有序的","ex":{"en":"an ordered existence","cn":"井井有条的生活"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（社会、制度等）组织有序的，结构井然的","en":"An ordered society or system is well-organized and has a clear structure.","ex":{"en":"An objective set of rules which we all agree to accept is necessary for any ordered society.","cn":"任何井然有序的社会都需要一套客观公正、为大家所接受的规则。"}}]},"examples":[{"en":"an ordered existence","cn":"井井有条的生活"},{"en":"a well-ordered society","cn":"井然有序的社会"}],"base":"order"},"opener":{"oxford":{"phon":"ˈəʊpənə(r)","pos":"noun","senses":[{"en":"a tool that is used to open things","cn":"开启的工具","ex":{"en":"a can opener","cn":"罐头起子"}},{"en":"the first in a series of things such as sports games; the first action in an event, a game, etc.","cn":"揭幕赛；开场戏","ex":{"en":"They won the opener 4–2.","cn":"他们以 4:2 赢了揭幕赛。"}},{"en":"either of the two batsmen who start play","cn":"开球员；首位击球员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"开罐器；开瓶器；开启工具","en":"An opener is a tool which is used to open containers such as tins or bottles.","ex":{"en":"...a tin opener.","cn":"开罐器"}}]},"media":{"uk":"media/uk/opener__gb_1.mp3","us":"media/us/opener__us_1.mp3"},"examples":[{"en":"They won the opener 4–2.","cn":"他们以 4:2 赢了揭幕赛。"},{"en":"Jones scored the opener.","cn":"琼斯首先得分。"}]},"oppressed":{"media":{"uk":"media/uk/oppressed__gb_1.mp3","us":"media/us/oppressed__us_1.mp3"},"oxford":{"phon":"əˈprest","pos":"adjective","senses":[{"en":"treated in a cruel and unfair way and not given the same freedom, rights, etc. as other people","cn":"被压迫的；受迫害的","ex":{"en":"oppressed minorities","cn":"被压迫的少数群体"}},{"en":"people who are oppressed","cn":"被压迫者","g":"[plural]","ex":{"en":"His sympathies were always with the poor and the oppressed.","cn":"他始终同情穷人和受压迫者。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受压迫的；受压制的","en":"People who are oppressed are treated cruelly or are prevented from having the same opportunities, freedom, and benefits as others.","ex":{"en":"Before they took power, they felt oppressed by the white English speakers who controlled things","cn":"他们在执政之前感到遭受了那些控制一切的说英语的白人的压迫。"}}]},"examples":[{"en":"oppressed minorities","cn":"被压迫的少数群体"}]},"opposition":{"media":{"uk":"media/uk/opposition__gb_1.mp3","us":"media/us/opposition__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈzɪʃn","pos":"noun","senses":[{"en":"the act of strongly disagreeing with somebody/something, especially with the aim of preventing something from happening","cn":"（强烈的）反对，反抗，对抗","g":"[uncountable, singular]","ex":{"en":"Opposition came primarily from students.","cn":"反对意见主要来自学生。"}},{"en":"the act of competing against somebody in a contest","cn":"（比赛中的）对抗；竞争","g":"[uncountable]","ex":{"en":"She won against determined opposition from last year's champion.","cn":"她顶住了去年冠军的顽强抵抗，获得了胜利。"}},{"en":"the people you are competing against in business, a competition, a game, etc.","cn":"（商业、竞赛、游戏等的）对手，敌手，竞争者","g":"[singular + singular or plural verb]","ex":{"en":"He's gone to work for the opposition.","cn":"他去为竞争对手工作了。"}},{"en":"the main political party that is opposed to the government; the political parties that are in a parliament but are not part of the government","cn":"反对党；在野党","g":"[singular + singular or plural verb]","lab":"North American English","ex":{"en":"the leader of the Opposition","cn":"反对党领袖"}},{"en":"the state of being as different as possible; two things that are as different as possible","cn":"对立；对立的事物","g":"[uncountable, countable]","lab":"formal","ex":{"en":"the opposition between good and evil","cn":"善与恶的对立"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（强烈的）反对，不赞成","en":"Opposition is strong, angry, or violent disagreement and disapproval.","ex":{"en":"The government is facing a new wave of opposition in the form of a student strike","cn":"政府面临着学生通过罢课掀起的新一轮反对浪潮。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（与政府意见相左的）反对党，在野党，反对派","en":"The opposition is the political parties or groups that are opposed to a government.","ex":{"en":"The main opposition parties boycotted the election, saying it would not be conducted fairly.","cn":"主要反对党联合抵制这次选举，认为该选举将缺乏公正性。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（议会或立法机构中的）反对党，在野党，反对派","en":"In a country's parliament or legislature, the opposition refers to the politicians or political parties that form part of the parliament or legislature, but are not the government.","ex":{"en":"...the Leader of the Opposition.","cn":"反对党领袖"}},{"pos":"N-SING-COLL 单数集合名词","cn":"（体育比赛中的）对手，竞争者，竞争队伍","en":"The opposition is the person or team you are competing against in a sports event.","ex":{"en":"Poland provide the opposition for the Scots' last warm-up match at home.","cn":"苏格兰队在国内最后一场热身赛的对手是波兰队。"}}]},"examples":[{"en":"Liverpool couldn't match the opposition in the final and lost 2–0.","cn":"利物浦队在决赛中不敌对手，以 0:2 输掉比赛。"},{"en":"He spent five years in prison for his opposition to the regime.","cn":"他因为反对那个政权而过了五年的铁窗生活。"}]},"output":{"oxford":{"phon":"ˈaʊtpʊt","pos":"noun","senses":[{"en":"the amount of something that a person, a machine or an organization produces","cn":"（人、机器、机构的）产量，输出量","ex":{"en":"Manufacturing output has increased by 8 per cent.","cn":"制造业产量增长了 8%。"}},{"en":"the information, results, etc. produced by a computer","cn":"输出","lab":"computing","ex":{"en":"data output","cn":"数据输出"}},{"en":"the power, energy, etc. produced by a piece of equipment","cn":"输出功率；输出量","ex":{"en":"an output of 100 watts","cn":"输出功率 100 瓦"}},{"en":"a place where energy, power, information, etc. leaves a system","cn":"输出端","ex":{"en":"Connect a cable to the output.","cn":"把缆线接到输出端上。"}},{"en":"to supply or produce information, results, etc.","cn":"输出","ex":{"en":"Computers can now output data much more quickly.","cn":"现在计算机能更快地输出数据。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"产量；输出量；排出量","en":"Output is used to refer to the amount of something that a person or thing produces.","ex":{"en":"Manual workers need a good breakfast for high-energy output","cn":"体力劳动者身体消耗巨大，早餐要丰盛一些。"}},{"pos":"N-VAR 可变名词","cn":"（计算机、文字处理器等的）输出信息，输出文件","en":"The output of a computer or word processor is the information that it displays on a screen or prints on paper as a result of a particular program.","ex":{"en":"You run the software, you look at the output, you make modifications.","cn":"运行该软件，查看输出结果并进行修正。"}}]},"media":{"uk":"media/uk/output__gb_1.mp3","us":"media/us/output__us_1.mp3"},"examples":[{"en":"Computers can now output data much more quickly.","cn":"现在计算机能更快地输出数据。"},{"en":"Manufacturing output has increased by 8%.","cn":"工业产量增长了 8%。"}]},"objective":{"media":{"uk":"media/uk/objective__gb_1.mp3","us":"media/us/objective__us_1.mp3"},"oxford":{"phon":"əbˈdʒektɪv","pos":"noun","senses":[{"en":"something that you are trying to achieve","cn":"目标；目的","ex":{"en":"the primary/principal/key objective","cn":"首要／主要／关键目标"}},{"en":"the lens in a telescope or microscope that is nearest to the object being looked at","cn":"（望远镜或显微镜的）物镜","lab":"specialist"},{"en":"not influenced by personal feelings or opinions; considering only facts","cn":"客观的；就事论事的；不带个人感情的","ex":{"en":"an objective assessment of the situation","cn":"对形势的客观评估"},"pos":"adjective"},{"en":"existing outside the mind; based on facts that can be proved","cn":"客观存在的；基于事实的","lab":"philosophy","ex":{"en":"objective reality","cn":"客观现实"},"pos":"adjective"},{"en":"the objective case is the one which is used for the object of a sentence","cn":"宾格的","g":"[only before noun]","lab":"grammar","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"目的；目标；宗旨","en":"Your objective is what you are trying to achieve.","ex":{"en":"Our main objective was the recovery of the child safe and well","cn":"我们的主要目标是将孩子安然无恙地找回来。"}},{"pos":"ADJ 形容词","cn":"（信息）客观的，基于事实的","en":"Objective information is based on facts.","ex":{"en":"He had no objective evidence that anything extraordinary was happening.","cn":"他没有客观证据表明正在发生什么不同寻常之事。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（观点）客观的，不带个人感情的，没有个人偏见的","en":"If someone is objective, they base their opinions on facts rather than on their personal feelings.","ex":{"en":"I believe that a journalist should be completely objective","cn":"我认为新闻记者不应当有丝毫偏见。"}}]},"examples":[{"en":"The main objective of this meeting is to give more information on our plans.","cn":"这次会议的主要目的是进一步介绍我们的计划。"},{"en":"You must set realistic aims and objectives for yourself.","cn":"你必须给自己确定切实可行的目的和目标。"}]},"objecting":{"lemma":"object","media":{"uk":"media/uk/object__gb_1.mp3","us":"media/us/object__us_1.mp3"}},"other":{"media":{"uk":"media/uk/other__gb_1.mp3","us":"media/us/other__us_1.mp3"},"oxford":{"phon":"ˈʌðə(r)","pos":"adjective, pronoun","senses":[{"en":"used to refer to people or things that are additional or different to people or things that have been mentioned or are known about","cn":"另外；其他","ex":{"en":"Mr Harris and Mrs Bate and three other teachers were there.","cn":"哈里斯老师、贝特老师和其他三位老师在场。"}},{"en":"used to refer to the second of two people or things","cn":"（指两个人或事物中的第二个）那个，另一个","ex":{"en":"My other sister is a doctor.","cn":"我的另一个妹妹是医生。"}},{"en":"used to refer to the people or things that remain in a group","cn":"其余的；另外的","ex":{"en":"I'll wear my other shoes—these are dirty.","cn":"这双鞋脏了，我要穿别的鞋。"}},{"en":"used to refer to a place, direction, etc. that is the opposite to where you are, are going, etc.","cn":"（指与说话人所在位置等相反的方向或地点）另一边，对面，相反的方向","ex":{"en":"I work on the other side of town.","cn":"我在城的另一边工作。"}},{"en":"to view or treat a person or group of people as different from yourself and from most people","cn":"将一个人或一群人视为与您自己和大多数人不同的人","ex":{"en":"Racism can take the form of othering people we perceive as different and dismissing their concerns.","cn":"种族主义可以表现为我们认为与其他人不同并忽视他们的担忧。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（表示在与已提及或已知的人或事物同一类中）别的，其他的，另外的，额外的","en":"You use other to refer to an additional thing or person of the same type as one that has been mentioned or is known about.","ex":{"en":"They were just like any other young couple","cn":"他们同别的年轻夫妇没什么两样。"}},{"pos":"ADJ 形容词","cn":"（表示与已提及的人或事物不同）别的，其他的","en":"You use other to indicate that a thing or person is not the one already mentioned, but a different one.","ex":{"en":"The authorities insist that the discussions must not be linked to any other issue","cn":"当局坚持此次讨论不得涉及其他任何问题。"}},{"pos":"ADJ 形容词","cn":"（两个中）另一的","en":"You use the other to refer to the second of two things or people when the identity of the first is already known or understood, or has already been mentioned.","ex":{"en":"The Captain was at the other end of the room","cn":"船长在房间的另一头。"}},{"pos":"ADJ 形容词","cn":"（用于列举之后）其他类似的","en":"You use other at the end of a list or a group of examples, to refer generally to people or things like the ones just mentioned.","ex":{"en":"Queensway Quay will incorporate shops, restaurants and other amenities","cn":"女王道码头将会融商店、餐馆以及其他生活便利设施为一体。"}},{"pos":"ADJ 形容词","cn":"（一组人或事物中）其余的，剩下的","en":"You use the other to refer to the rest of the people or things in a group, when you are talking about one particular person or thing.","ex":{"en":"When the other pupils were taken to an exhibition, he was left behind.","cn":"当其余学生被带去参观展览时，他被留了下来。"}},{"pos":"ADJ 形容词","cn":"（泛指）别（人）的，他（人）的","en":"Other people are people in general, as opposed to yourself or a person you have already mentioned.","ex":{"en":"The suffering of other people appals me","cn":"人们的苦难让我无比震惊。"}},{"pos":"ADJ 形容词","cn":"最近的；前不久的","en":"You use other in informal expressions of time such as the other day ,the other evening, or the other week to refer to a day, evening, or week in the recent past.","ex":{"en":"I rang her the other day and she said she'd like to come round","cn":"我前几天给她打电话，她说想过来玩。"}},{"pos":"PHRASE 短语","cn":"除了别的以外；其中；包括","en":"You use expressions like among other things or among others to indicate that there are several more facts, things, or people like the one or ones mentioned, but that you do not intend to mention them all.","ex":{"en":"He moved to England in 1980 where, among other things, he worked as a journalist","cn":"他1980年移居英格兰，期间从事过包括记者在内的很多工作。"}},{"pos":"PHRASE 短语","cn":"每隔一天/每隔一月","en":"If something happens, for example, every other day or every other month, there is a day or month when it does not happen between each day or month when it happens.","ex":{"en":"Their food is adequate. It includes meat at least every other day, vegetables and fruit","cn":"他们的伙食足够丰富了，有蔬菜、水果，而且至少每隔一天吃一次肉。"}},{"pos":"PHRASE 短语","cn":"（用于强调，表示一组人或事物中）其余的，剩下的","en":"You use every other to emphasize that you are referring to all the rest of the people or things in a group.","ex":{"en":"The same will apply in every other country.","cn":"这也适用于其他任何国家。"}},{"pos":"PHRASE 短语","cn":"就是；不是别的而正是","en":"You use none other than and no other than to emphasize the name of a person or thing when something about that person or thing is surprising in a particular situation.","ex":{"en":"He called together all his employees and announced that the manager was none other than his son.","cn":"他把所有的员工召集到一起，宣布经理不是别人，正是他的儿子。"}},{"pos":"PHRASE 短语","cn":"只有；除…外没有","en":"You use nothing other than and no other than when you are going to mention a course of action, decision, or description and emphasize that it is the only one possible in the situation.","ex":{"en":"Nothing other than an immediate custodial sentence could be justified","cn":"只有判决即时监禁才算合理。"}},{"pos":"PHRASE 短语","cn":"（表示无法或不想确切说明）某一，某些","en":"You use or other in expressions like somehow or other and someone or other to indicate that you cannot or do not want to be more precise about the information that you are giving.","ex":{"en":"I was going to have him called away from the house on some pretext or other","cn":"我准备找个什么借口把他从屋里支出去。"}},{"pos":"PHRASE 短语","cn":"（用于否定陈述后）除了…以外","en":"You use other than after a negative statement to say that the person, item, or thing that follows is the only exception to the statement.","ex":{"en":"She makes no reference to any feminist work other than her own","cn":"除了自己的之外，她没有提及其他女权主义著作。"}},{"pos":"","cn":"","en":"each other→see: ; your other half→see: ; one after the other→see: ; one or other→see: ; one or other→see: ; this→see: ; in other words→see: ;"}]},"examples":[{"en":"Two buildings were destroyed and many others damaged in the blast.","cn":"在这次爆炸中，两座建筑物被摧毁，还有许多建筑物遭损坏。"},{"en":"One son went to live in Australia and the other one was killed in a car crash.","cn":"一个儿子移居澳大利亚，另一个在撞车事故中身亡。"}]},"owing":{"media":{"uk":"media/uk/owing__gb_1.mp3","us":"media/us/owing__us_1.mp3"},"oxford":{"phon":"ˈəʊɪŋ","pos":"adjective","senses":[{"en":"money that is owing has not been paid yet","cn":"拖欠；未付；未偿还","ex":{"en":"£100 is still owing on the loan.","cn":"还有 100 英镑贷款未还。"}}]},"examples":[{"en":"£100 is still owing on the loan.","cn":"还有 100 英镑贷款未还。"},{"en":"You need to pay the amount owing, plus the interest.","cn":"你需要付清欠款﹐外加利息。"}],"base":"owe"},"obscurely":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all famous","cn":""},{"en":"someone or something that is obscure is known about only by a few people, because they belong to a group, place, or subject that not many people know about or are interested in","cn":""}]},"examples":[{"en":"The details of his life remain obscure .","cn":"","src":"ld"},{"en":"For some obscure reason , the group is very popular.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obscurely__gb_1.mp3","us":"media/us/obscurely__us_1.mp3"},"oxford":{"phon":"əbˈskjʊəli","pos":"adverb","senses":[{"en":"without being well known","cn":"无名的；鲜为人知的","ex":{"en":"He lived obscurely for the remainder of his life.","cn":"他的余生都过着默默无闻的生活。"}},{"en":"in a way that is difficult to understand","cn":"费解的；难以理解的","ex":{"en":"an obscurely titled song","cn":"一首名字晦涩的歌曲"}}]}},"outdated":{"oxford":{"phon":"ˌaʊtˈdeɪtɪd","pos":"adjective","senses":[{"en":"no longer useful because of being old-fashioned","cn":"过时的；陈旧的","ex":{"en":"outdated equipment","cn":"过时的设备"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的；陈旧的；老式的；废弃的","en":"If you describe something as outdated, you mean that you think it is old-fashioned and no longer useful or relevant to modern life.","ex":{"en":"...outdated and inefficient factories","cn":"陈旧、低效的工厂"}}]},"media":{"uk":"media/uk/outdated__gb_1.mp3","us":"media/us/outdated__us_1.mp3"},"examples":[{"en":"These figures are now outdated.","cn":"这些数字现在已经过时。"},{"en":"outdated equipment","cn":"过时的设备"}]},"olympic":{"media":{"uk":"media/uk/olympic__gb_1.mp3","us":"media/us/olympic__us_1.mp3"},"oxford":{"phon":"əˈlɪmpɪk","pos":"adjective","senses":[{"en":"connected with the Olympic Games","cn":"奥林匹克运动会的","ex":{"en":"an Olympic athlete/medallist","cn":"奥林匹克运动员／奖牌获得者"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"奥林匹克运动会的；奥运会的","en":"Olympic means relating to the Olympic Games.","ex":{"en":"...the reigning Olympic champion.","cn":"现任奥运会冠军"}},{"pos":"N-PROPER 专有名词","cn":"奥林匹克运动会；奥运会","en":"The Olympics are the Olympic Games.","ex":{"en":"I will be in Atlanta for the next Olympics","cn":"我将参加在亚特兰大举行的下届奥运会。"}}]},"examples":[{"en":"an Olympic athlete/medallist","cn":"奥林匹克运动员/奖牌获得者"},{"en":"an Olympic gold medal","cn":"奥运会金牌"}]},"offline":{"media":{"uk":"media/uk/offline__gb_1.mp3","us":"media/us/offline__us_2.mp3"},"oxford":{"phon":"ˌɒfˈlaɪn","pos":"adjective","senses":[{"en":"not directly controlled by or connected to a computer or to the internet","cn":"未联机的；未连线的；脱机的；离线的","ex":{"en":"For offline orders, call this number.","cn":"离线订货请拨打这个号码。"}},{"en":"without being directly controlled by or connected to a computer or to the internet","cn":"未联机的；未连线的；脱机的；离线的","ex":{"en":"How do I write an email offline?","cn":"我如何在离线时写电子邮件？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"脱机的；离线的","en":"If a computer is offline, it is not connected to the Internet. →see: ;","ex":{"en":"Most software programs allow you to compose emails offline.","cn":"大部分软件程序允许用户在脱机状态下写电子邮件。off line"}}]},"examples":[{"en":"For offline orders, call this number.","cn":"离线订货请拨打这个号码。"},{"en":"How do I write an email offline?","cn":"如何在离线时写电子邮件？"}]},"owner":{"media":{"uk":"media/uk/owner__gb_1.mp3","us":"media/us/owner__us_1.mp3"},"oxford":{"phon":"ˈəʊnə(r)","pos":"noun","senses":[{"en":"a person who owns something","cn":"物主；所有权人；主人","ex":{"en":"a dog/pet/gun owner","cn":"狗／宠物／枪的主人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"物主；业主；所有人；主人","en":"The owner of something is the person to whom it belongs.","ex":{"en":"The owner of the store was sweeping his floor when I walked in","cn":"我进去的时候这家商店的店主正在扫地。"}}]},"examples":[{"en":"He's now the proud owner of a cottage in Wales.","cn":"现在他很得意自己在威尔士有一座小别墅。"},{"en":"The painting has been returned to its rightful owner.","cn":"这幅画已归还给合法所有权人。"}]},"opaque":{"media":{"uk":"media/uk/opaque__gb_1.mp3","us":"media/us/opaque__us_1.mp3"},"oxford":{"phon":"əʊˈpeɪk","pos":"adjective","senses":[{"en":"not clear enough to see through or allow light through","cn":"不透明的；不透光的；浑浊的","ex":{"en":"opaque glass","cn":"不透明的玻璃"}},{"en":"difficult to understand; not clear","cn":"难懂；模糊；隐晦；不清楚","ex":{"en":"The jargon in his talk was opaque to me.","cn":"他谈话中使用的行话对我是一团迷雾。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不透明的;不透光的","en":"If an object or substance is opaque, you cannot see through it.","ex":{"en":"You can always use opaque glass if you need to block a street view.","cn":"如果不想从室内看到街景，可以使用不透明玻璃。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费解的；难懂的；晦涩的","en":"If you say that something is opaque, you mean that it is difficult to understand.","ex":{"en":"...the opaque language of the inspector's reports.","cn":"巡视员报告中晦涩难懂的语言"}}]},"examples":[{"en":"The jargon in his talk was opaque to me.","cn":"他谈话中使用的行话对我是一团迷雾。"},{"en":"opaque tights","cn":"不透明的连裤袜"}]},"oppression":{"media":{"uk":"media/uk/oppression__gb_1.mp3","us":"media/us/oppression__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"压迫；压制","en":"Oppression is the cruel or unfair treatment of a group of people.","ex":{"en":"...an attempt to escape political oppression.","cn":"企图逃避政治压迫的努力"}}]},"examples":[{"en":"victims of oppression","cn":"受压迫者"}],"oxford":{"phon":"əˈpreʃn","pos":"noun","senses":[{"en":"cruel and unfair treatment of people, especially by not giving them the same freedom, rights, etc. as other people","cn":"压迫；欺压；压制","ex":{"en":"victims of oppression","cn":"受压迫者"}}]}},"oregano":{"oxford":{"phon":"ˌɒrɪˈɡɑːnəʊ","pos":"noun","senses":[{"en":"a plant with leaves that have a sweet smell and are used in cooking as a herb","cn":"牛至（叶可用于调味）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"牛至（可用于调味的一种香草）","en":"Oregano is a herb that is used in cooking."}]},"media":{"img":["media/pic/herbs_comp.jpg","media/thumb/oregano.jpg"],"uk":"media/uk/oregano__gb_1.mp3","us":"media/us/oregano__us_1.mp3"}},"ostensibly":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if something is ostensibly true, people say that it is true but it is not really true","cn":"表面地﹐假装地﹐谎称地"}]},"examples":[{"en":"She stayed behind at the office, ostensibly to work.","cn":"她留在办公室里不走﹐假装要工作。","src":"ld"}],"media":{"uk":"media/uk/ostensibly__gb_1.mp3","us":"media/us/ostensibly__us_1.mp3"},"oxford":{"phon":"ɒˈstensəbli","pos":"adverb","senses":[{"en":"according to what seems or is stated to be real or true, when this is perhaps not the case","cn":"表面的；宣称的；假托的","ex":{"en":"Troops were sent in, ostensibly to protect the civilian population.","cn":"军队以保护平民的名义被派入。"}}]}},"online":{"media":{"uk":"media/uk/online__gb_1.mp3","us":"media/us/online__us_1.mp3"},"oxford":{"phon":"ˌɒnˈlaɪn","pos":"adjective","senses":[{"en":"available on or done using the internet or other computer network","cn":"线上的；网上的","ex":{"en":"Online shopping is both cheap and convenient.","cn":"网上购物既便宜又方便。"}},{"en":"connected to the internet; able to connect to the internet","cn":"联网的；可上网的","ex":{"en":"You can see which of your friends are online and send them messages.","cn":"你可以查看哪些朋友在线并给他们发讯息。"}},{"en":"onto the internet; using the internet or other computer network","cn":"在网上；利用网络","ex":{"en":"Many children would rather go online than watch television.","cn":"许多孩子宁愿上网也不看电视。"},"pos":"adverb"},{"en":"in or into operation or existence","cn":"在运行；开始运作；投入使用","ex":{"en":"The new system will go online this month.","cn":"新系统将于本月开始运行。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（公司服务）网上开通的，网上经营的","en":"If a company goes online, its services become available on the Internet.","ex":{"en":"...the first bank to go online.","cn":"第一家开通网上业务的银行"}},{"pos":"ADJ 形容词","cn":"联机的；在线的","en":"If you are online, your computer is connected to the Internet. →see: ;","ex":{"en":"You can chat to other people who are online.","cn":"你可以和其他在线的人聊天。"}}]},"examples":[{"en":"The majority of small businesses now do their banking online.","cn":"大多数小企业现在都在网上办理银行业务。"},{"en":"Online shopping is both cheap and convenient.","cn":"网上购物既便宜又方便。"}]},"officially":{"media":{"uk":"media/uk/officially__gb_1.mp3","us":"media/us/officially__us_1.mp3"},"oxford":{"phon":"əˈfɪʃəli","pos":"adverb","senses":[{"en":"publicly and by somebody who is in a position of authority","cn":"正式地；官方地；公开地","ex":{"en":"The library will be officially opened by the local MP.","cn":"图书馆将由当地下院议员正式揭幕。"}},{"en":"according to a particular set of rules, laws, etc.","cn":"依据法规等","ex":{"en":"Many of those living on the streets are not officially homeless.","cn":"根据法律定义，许多流浪街头的人并非无家可归者。"}},{"en":"according to information that has been told to the public but that may not be true","cn":"据传；据公布","ex":{"en":"Officially, he resigned because of bad health.","cn":"据官方说法，他是因健康状况不佳而辞职的。"}}]},"examples":[{"en":"Many of those living on the streets are not officially homeless.","cn":"根据法律定义，许多流浪街头的人并非无家可归者。"},{"en":"Officially, he resigned because of bad health.","cn":"据官方说法，他是因健康状况不佳而辞职的。"}]},"oven":{"oxford":{"phon":"ˈʌvn","pos":"noun","senses":[{"en":"the part of a cooker that is like a box with a door on the front, in which food is cooked or heated","cn":"烤箱；烤炉","ex":{"en":"Take the cake out of the oven.","cn":"把蛋糕从烤箱中取出来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烤箱；烤炉","en":"An oven is a device for cooking that is like a box with a door. You heat it and cook food inside it.","ex":{"en":"Put the onions and ginger in the oven and let them roast for thirty minutes.","cn":"将洋葱和姜放进烤箱烘烤30分钟。"}}]},"media":{"uk":"media/uk/oven__gb_1.mp3","us":"media/us/oven__us_1.mp3"},"examples":[{"en":"Open a window, it's like an oven in here!","cn":"打开窗户。这儿热得像火炉！"},{"en":"Take the cake out of the oven.","cn":"把蛋糕从烤箱中取出来。"}]},"occupation":{"media":{"uk":"media/uk/occupation__gb_1.mp3","us":"media/us/occupation__us_1.mp3"},"oxford":{"phon":"ˌɒkjuˈpeɪʃn","pos":"noun","senses":[{"en":"a job or profession","cn":"工作；职业","g":"[countable]","ex":{"en":"Please state your name, age and occupation below.","cn":"请在下面写明姓名、年龄和职业。"}},{"en":"the way in which you spend your time, especially when you are not working","cn":"消遣；业余活动","g":"[countable]","ex":{"en":"Her main occupation seems to be shopping.","cn":"逛商店购物似乎是她的主要消遣。"}},{"en":"the act of moving into a country, town, etc. and taking control of it using military force; the period of time during which a country, town, etc. is controlled in this way","cn":"侵占；占领；占领期","g":"[uncountable]","ex":{"en":"the Roman occupation of Britain","cn":"罗马人对不列颠的占领"}},{"en":"the act of living in or using a building, room, piece of land, etc.","cn":"（房屋、土地等的）占用，使用，居住","g":"[uncountable]","lab":"formal","ex":{"en":"The offices will be ready for occupation in June.","cn":"办公室将于六月交付使用。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"职业;工作","en":"Your occupation is your job or profession.","ex":{"en":"I suppose I was looking for an occupation which was going to be an adventure","cn":"我想我在找的是一份具有冒险性的工作。"}},{"pos":"N-COUNT 可数名词","cn":"消遣；日常需做的事务","en":"An occupation is something that you spend time doing, either for pleasure or because it needs to be done.","ex":{"en":"Parachuting is a dangerous occupation.","cn":"跳伞是一项危险的消遣运动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"占领;占据;侵占","en":"The occupation of a country happens when it is entered and controlled by a foreign army.","ex":{"en":"Prii had become fluent in German during the Wehrmacht's occupation of Estonia in 1942","cn":"在1942年德军侵占爱沙尼亚期间，普里学得了一口流利的德语。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对建筑物的）占用,居住,使用","en":"The occupation of a building is the act or fact of someone living or working in it.","ex":{"en":"...people who sell their home and buy another one for their own occupation.","cn":"出售房屋再另购一套自住的人"}}]},"examples":[{"en":"The following applies only to tenants in occupation after January 1 2010.","cn":"以下规定仅适用于从 2010 年 1 月 1 日起入住的房客。"},{"en":"The level of owner occupation (= people owning their homes) has increased rapidly in the last 30 years.","cn":"拥有住房的人数在过去 30 年间急剧攀升。"}]},"outpouring":{"oxford":{"phon":"ˈaʊtpɔːrɪŋ","pos":"noun","senses":[{"en":"a strong and sudden expression of feeling","cn":"（感情的）迸发，倾泻","g":"[usually plural]","ex":{"en":"spontaneous outpourings of praise","cn":"一片自然迸发的赞美声"}},{"en":"a large amount of something produced in a short time","cn":"涌现；喷涌","ex":{"en":"a remarkable outpouring of new ideas","cn":"新思想的大量涌现"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（感情、反应等的）迸发，爆发，倾泻","en":"An outpouring of something such as an emotion or a reaction is the expression of it in an uncontrolled way.","ex":{"en":"The news of his death produced an instant outpouring of grief.","cn":"他死亡的消息立即引发了强烈的悲痛。"}}]},"media":{"uk":"media/uk/outpouring__gb_1.mp3","us":"media/us/outpouring__us_1.mp3"},"examples":[{"en":"a remarkable outpouring of new ideas","cn":"新思想的大量涌现"},{"en":"spontaneous outpourings of praise","cn":"一片自然迸发的赞美声"}]},"optics":{"oxford":{"phon":"ˈɒptɪks","pos":"noun","senses":[{"en":"the scientific study of sight and light","cn":"光学"},{"en":"the way in which an action or event is seen and understood by the public","cn":"公众认知","g":"[plural]","lab":"especially North American English","ex":{"en":"In politics, optics matter.","cn":"在政治上，公众认知很重要。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"光学","en":"Optics is the branch of science concerned with vision, sight, and light."}]},"media":{"uk":"media/uk/optics__gb_1.mp3","us":"media/us/optics__us_1.mp3"},"examples":[{"en":"Optics is a branch of physics.","cn":""}],"base":"optic"},"outrageous":{"media":{"uk":"media/uk/outrageous__gb_1.mp3","us":"media/us/outrageous__us_1.mp3"},"oxford":{"phon":"aʊtˈreɪdʒəs","pos":"adjective","senses":[{"en":"offensive and unacceptable","cn":"令人发指的；骇人听闻的","ex":{"en":"outrageous behaviour","cn":"极端无礼的行为"}},{"en":"very unusual and intended to shock people slightly","cn":"怪诞的；怪异吓人的","ex":{"en":"She says the most outrageous things sometimes.","cn":"她有时候尽说些耸人听闻的事。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人无法容忍的；骇人的","en":"If you describe something as outrageous, you are emphasizing that it is unacceptable or very shocking.","ex":{"en":"I must apologise for my outrageous behaviour","cn":"我必须为自己极端无礼的行为道歉。"}}]},"examples":[{"en":"She says the most outrageous things sometimes.","cn":"她有时候尽说些耸人听闻的事。"},{"en":"They behaved outrageously.","cn":"他们的行为表现让人难以容忍。"}]},"occasion":{"media":{"uk":"media/uk/occasion__gb_1.mp3","us":"media/us/occasion__us_1.mp3"},"oxford":{"phon":"əˈkeɪʒn","pos":"noun","senses":[{"en":"a particular time when something happens","cn":"某次；…的时候","g":"[countable]","ex":{"en":"on this/that occasion","cn":"这次；那次"}},{"en":"a special event, ceremony or celebration","cn":"特别的事情（或仪式、庆典）","g":"[countable]","ex":{"en":"a great/memorable/happy/momentous occasion","cn":"一个伟大／难忘／快乐／重要的时刻"}},{"en":"a suitable time for something","cn":"适当的机会；时机","g":"[singular]","ex":{"en":"It should have been an occasion for rejoicing, but she could not feel any real joy.","cn":"原本应该是高兴的时刻，她却丝毫未感到快乐。"}},{"en":"a reason or cause","cn":"理由；原因","g":"[uncountable, singular]","lab":"formal","ex":{"en":"I've had no occasion to visit him recently.","cn":"我最近无缘去拜访他。"}},{"en":"to cause something","cn":"使发生；造成；导致","ex":{"en":"The flight delay was occasioned by the need for a further security check.","cn":"这次航班的延误是由于必须做进一步的安全检查。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"时刻；时候；时节；场合","en":"An occasion is a time when something happens, or a case of it happening.","ex":{"en":"I often think fondly of an occasion some years ago at Covent Garden","cn":"我时常愉快地回想起几年前在科文特花园的一个时刻。"}},{"pos":"N-COUNT 可数名词","cn":"重大活动；仪式；庆典","en":"An occasion is an important event, ceremony, or celebration.","ex":{"en":"Taking her with me on official occasions has been a challenge","cn":"带着她出席正式场合对我来说一直是个挑战。"}},{"pos":"N-COUNT 可数名词","cn":"机会；时机","en":"An occasion for doing something is an opportunity for doing it.","ex":{"en":"It is an occasion for all the family to celebrate","cn":"这是个值得举家庆祝的时刻。"}},{"pos":"VERB 动词","cn":"导致；引起；使发生","en":"To occasion something means to cause it.","ex":{"en":"He argued that the release of hostages should not occasion a change in policy.","cn":"他认为释放人质不应造成政策的改变。"}},{"pos":"PHRASE 短语","cn":"有必要（做）；需要（做）","en":"If you have occasion to do something, it is necessary for you to do it.","ex":{"en":"We have had occasion to deal with members of the group on a variety of charges.","cn":"我们有必要以多项罪名起诉该组织的成员。"}},{"pos":"PHRASE 短语","cn":"偶尔；间或；有时","en":"If something happens on occasion, it happens sometimes, but not very often.","ex":{"en":"He treated them seriously and, on occasion, entertained them hilariously","cn":"他对待他们严肃认真，偶尔又逗得他们捧腹不已。"}},{"pos":"PHRASE 短语","cn":"成功应付困难局面；关键时刻发挥作用","en":"If you say that someone rose to the occasion, you mean that they did what was necessary to successfully overcome a difficult situation.","ex":{"en":"Inverness, however, rose to the occasion in the second half, producing some of the best football they have played for some time.","cn":"然而，因弗内斯队在下半场经受住了考验，踢出了很长一段时间以来的最佳水平。"}}]},"examples":[{"en":"I can remember very few occasions when he had to cancel because of ill health.","cn":"我记得他因为健康不佳而被迫取消的情况绝无仅有。"},{"en":"The flight delay was occasioned by the need for a further security check.","cn":"这次航班的延误是由于必须做进一步的安全检查。"}]},"opportunity":{"media":{"uk":"media/uk/opportunity__gb_1.mp3","us":"media/us/opportunity__us_1.mp3"},"oxford":{"phon":"ˌɒpəˈtjuːnəti","pos":"noun","senses":[{"en":"a time when a particular situation makes it possible to do or achieve something","cn":"机会；时机","ex":{"en":"Don't miss this opportunity!","cn":"勿失良机！"}},{"en":"the third Mars Rover vehicle which landed on the planet Mars in 2004 and sent pictures of the planet back to NASA","cn":"机会：第三辆火星探测器车于2004年降落在火星上并将该行星的照片发送回了NASA","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"机会；时机","en":"An opportunity is a situation in which it is possible for you to do something that you want to do.","ex":{"en":"I had an opportunity to go to New York and study","cn":"我曾经有一个去纽约学习的机会。"}}]},"examples":[{"en":"At least give him the opportunity of explaining what happened.","cn":"至少要给他机会解释一下发生了什么事。"},{"en":"You'll have the opportunity to ask any questions at the end.","cn":"你们最后将有机会提问任何问题。"}]},"offensive":{"oxford":{"phon":"əˈfensɪv","pos":"adjective","senses":[{"en":"rude in a way that causes somebody to feel upset or annoyed because it shows a lack of respect","cn":"冒犯的；得罪人的；无礼的","ex":{"en":"offensive remarks","cn":"冒犯的言论"}},{"en":"extremely unpleasant","cn":"极其讨厌的；令人不适的","lab":"formal","ex":{"en":"The problem is how to eliminate offensive smells from the processing plant.","cn":"问题在于怎样才能消除加工厂那刺鼻的气味。"}},{"en":"connected with the act of attacking somebody/something","cn":"攻击性的；进攻性的","g":"[only before noun]","ex":{"en":"an offensive war","cn":"侵略战争"}},{"en":"connected with the team that has control of the ball; connected with the act of scoring points","cn":"攻方的；进攻型的；攻击型的","lab":"North American English, sport，，","ex":{"en":"offensive play","cn":"进攻打法"}},{"en":"a military operation in which large numbers of soldiers, etc. attack another country","cn":"进攻；攻击；侵犯","ex":{"en":"an air offensive","cn":"空中攻击"},"pos":"noun"},{"en":"a series of actions aimed at achieving something in a way that attracts a lot of attention","cn":"（引人注意的）系列行动；运动；攻势","ex":{"en":"The government has launched a new offensive against crime.","cn":"政府发动了新的打击犯罪攻势。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冒犯的；得罪人的；唐突的;无礼的","en":"Something that is offensive upsets or embarrasses people because it is rude or insulting.","ex":{"en":"Some friends of his found the play horribly offensive.","cn":"他的一些朋友觉得该剧非常让人反感。"}},{"pos":"N-COUNT 可数名词","cn":"进攻","en":"A military offensive is a carefully planned attack made by a large group of soldiers.","ex":{"en":"Its latest military offensive against rebel forces is aimed at reopening important trade routes","cn":"它对叛军的最新一轮军事进攻旨在重新打开重要的贸易通道。"}},{"pos":"N-COUNT 可数名词","cn":"（表示愤怒或反对的）强硬行动","en":"If you conduct an offensive, you take strong action to show how angry you are about something or how much you disapprove of something.","ex":{"en":"Republicans acknowledged that they had little choice but to mount an all-out offensive on the Democratic nominee.","cn":"共和党人承认他们别无选择，只有对获提名的民主党人展开全面攻击。"}},{"pos":"ADJ 形容词","cn":"（体育运动中球队）进攻的，攻方的","en":"In sports such as American football or basketball, the offensive team is the team which has possession of the ball and is trying to score.","ex":{"en":"The worst-ever defeat of this team proved once again that Stanford can be one of the most explosive offensive teams in the country.","cn":"该队前所未有的惨败再次证明斯坦福队是国内最具爆发力的进攻型队伍之一。"}},{"pos":"PHRASE 短语","cn":"采取强势行动；采取攻势","en":"If you go on the offensive ,go over to the offensive, or take the offensive, you begin to take strong action against people who have been attacking you.","ex":{"en":"The West African forces went on the offensive in response to attacks on them","cn":"西非部队对袭击者展开全力还击。"}}]},"media":{"uk":"media/uk/offensive__gb_1.mp3","us":"media/us/offensive__us_1.mp3"},"examples":[{"en":"The public seems unconvinced by their latest charm offensive (= their attempt to make people like them).","cn":"公众似乎并不相信他们最近所表演的一连串笑脸攻势。"},{"en":"The programme contains language which some viewers may find offensive.","cn":"节目里使用了某些观众可能认为是犯忌的语言。"}]},"overlap":{"media":{"uk":"media/uk/overlap__gb_1.mp3","us":"media/us/overlap__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈlæp","pos":"verb","senses":[{"en":"if one thing overlaps another, or the two things overlap, part of one thing covers part of the other","cn":"（物体）部分重叠，交叠","g":"[transitive, intransitive]","ex":{"en":"A fish’s scales overlap each other.","cn":"鱼鳞一片片上下交叠。"}},{"en":"to make two or more things overlap","cn":"使部分重叠","g":"[transitive]","ex":{"en":"You will need to overlap the pieces of wood slightly.","cn":"你得使这些木片像鱼鳞片似的搭叠起来。"}},{"en":"if two events overlap or overlap each other, the second one starts before the first one has finished","cn":"（时间上）部分重叠","g":"[intransitive, transitive]"},{"en":"to cover part of the same area of interest, knowledge, responsibility, etc.","cn":"（范围方面）部分重叠","g":"[intransitive, transitive]","ex":{"en":"Our jobs overlap slightly, which sometimes causes difficulties.","cn":"我们的工作略有重叠，所以有时引起一些困难。"}},{"en":"a shared area of interest, knowledge, responsibility, etc.","cn":"（范围方面的）重叠部分","g":"[countable, uncountable]","ex":{"en":"There is (a) considerable overlap between the two subjects.","cn":"两门科目之间有相当多的共通之处。"},"pos":"noun"},{"en":"the amount by which one thing covers another thing","cn":"（物体的）重叠部分，重叠量","g":"[countable, uncountable]","ex":{"en":"an overlap of 5 cm on each roof tile","cn":"每片房瓦上 5 厘米的重叠度"},"pos":"noun"},{"en":"a period of time in which two events or activities happen together","cn":"（两事发生的）重叠时间，交接时期","g":"[uncountable, singular]","ex":{"en":"There will be an overlap of a week while John teaches Ann the job.","cn":"将有一周的交接期可以让约翰教导安如何接手工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"与…互搭；与…复叠；（使）相叠","en":"If one thing overlaps another, or if you overlap them, a part of the first thing occupies the same area as a part of the other thing. You can also say that two things overlap .","ex":{"en":"When the bag is folded flat, the bag bottom overlaps one side of the bag","cn":"袋子平整折起后，底面与一侧交叠。"}},{"pos":"V-RECIP 相互动词","cn":"（在主题、人物、时间等上）（与…）部分相同，（与…）部分交叉","en":"If one idea or activity overlaps another, or overlaps with another, they involve some of the same subjects, people, or periods of time.","ex":{"en":"Elizabeth met other Oxford intellectuals some of whom overlapped Naomi's world","cn":"伊丽莎白结识了其他一些牛津大学的学者，其中有几位娜奥米也认识。"}}]},"examples":[{"en":"There will be an overlap of a week while John teaches Ann the job.","cn":"将有一周的交接期可以让约翰教导安如何接手工作。"},{"en":"Our jobs overlap slightly, which sometimes causes difficulties.","cn":"我们的工作略有重叠，所以有时引起一些困难。"}]},"orientation":{"media":{"uk":"media/uk/orientation__gb_1.mp3","us":"media/us/orientation__us_1.mp3"},"oxford":{"phon":"ˌɔːriənˈteɪʃn","pos":"noun","senses":[{"en":"a person’s basic beliefs or feelings about a particular subject","cn":"（个人的）基本信仰，态度，观点","g":"[uncountable, countable]","ex":{"en":"religious/political orientation","cn":"宗教信仰；政治取向"}},{"en":"the type of aims or interests that a person or an organization has; the act of directing your aims towards a particular thing","cn":"方向；目标；定向","g":"[uncountable, countable]","ex":{"en":"The course is essentially theoretical in orientation.","cn":"该课程的定位是以理论为主。"}},{"en":"training or information that you are given before starting a new job, course, etc.","cn":"（任职等前的）培训，训练；迎新会","g":"[uncountable]","ex":{"en":"an orientation session/program/course","cn":"入职培训班"}},{"en":"the direction in which an object faces","cn":"方向","g":"[countable]","lab":"specialist","ex":{"en":"The orientation of the planet's orbit is changing continuously.","cn":"该行星轨道的方向不断变化。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（组织、国家等的）方向，目标，定位","en":"If you talk about the orientation of an organization or country, you are talking about the kinds of aims and interests it has.","ex":{"en":"...a marketing orientation","cn":"营销定位"}},{"pos":"N-VAR 可变名词","cn":"（某人在信仰或偏好上基本的）态度，取向","en":"Someone's orientation is their basic beliefs or preferences.","ex":{"en":"...legislation that would have made discrimination on the basis of sexual orientation illegal.","cn":"本来会将性取向歧视定为非法的法规"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（岗前、学前、课前等的）情况介绍，培训，训练","en":"Orientation is basic information or training that is given to people starting a new job, school, or course.","ex":{"en":"They give their new employees a day or two of perfunctory orientation.","cn":"他们对新员工进行了一两天例行公事的培训。"}},{"pos":"N-COUNT 可数名词","cn":"（建筑物等的）朝向","en":"The orientation of a structure or object is the direction it faces.","ex":{"en":"Farnese had the orientation of the church changed so that the front would face a square.","cn":"法尔内塞改变了教堂的朝向，这样它的正面就可以对着广场。"}}]},"examples":[{"en":"Companies have been forced into a greater orientation to the market.","cn":"各公司不得不转变，更加面向市场。"},{"en":"The course is essentially theoretical in orientation.","cn":"该课程的定位是以理论为主。"}]},"oral":{"media":{"uk":"media/uk/oral__gb_1.mp3","us":"media/us/oral__us_1.mp3"},"oxford":{"phon":"ˈɔːrəl","pos":"adjective","senses":[{"en":"spoken rather than written","cn":"口头的","g":"[usually before noun]","ex":{"en":"a test of both oral and written French","cn":"法语口试和笔试"}},{"en":"connected with the mouth","cn":"用口的；口腔的；口服的","g":"[only before noun]","ex":{"en":"oral hygiene","cn":"口腔卫生"}},{"en":"produced by allowing air to flow through the mouth but not the nose","cn":"口腔发声的；口腔的","lab":"phonetics"},{"en":"a spoken exam, especially in a foreign language","cn":"（尤指外语考试中的）口试","lab":"especially British English","ex":{"en":"a French oral","cn":"法语口试"},"pos":"noun"},{"en":"a spoken exam in a university","cn":"（大学里的）口试","lab":"North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"口头的；口述的","en":"Oral communication is spoken rather than written.","ex":{"en":"...the written and oral traditions of ancient cultures.","cn":"通过文字记载和口头传诵留存下来的古代文化传统"}},{"pos":"N-COUNT 可数名词","cn":"（尤指外语)口试","en":"An oral is an examination, especially in a foreign language, that is spoken rather than written.","ex":{"en":"I spoke privately to the candidate after the oral.","cn":"口试后，我私下里与那位考生谈了谈。"}},{"pos":"ADJ 形容词","cn":"用口的；口的；口腔的","en":"You use oral to indicate that something is done with a person's mouth or relates to a person's mouth.","ex":{"en":"...good oral hygiene.","cn":"良好的口腔卫生"}},{"pos":"ADJ 形容词","cn":"（药物）口服的","en":"Oral medicines are taken by mouth.","ex":{"en":"...oral contraceptives.","cn":"口服避孕药"}}]},"examples":[{"en":"Answers can be written or presented orally on tape.","cn":"答案可以写下来或口述录在磁带上。"},{"en":"He was interested in oral history (= history that is collected from interviews with people who have personal knowledge of past events).","cn":"他对口述历史感兴趣。"}]},"overview":{"oxford":{"phon":"ˈəʊvəvjuː","pos":"noun","senses":[{"en":"a general description or an outline of something","cn":"概述；纵览；概论；概况","ex":{"en":"The second chapter will provide an overview of the issues involved.","cn":"第二章将对相关议题作出概述。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"概观；概览；概述","en":"An overview of a situation is a general understanding or description of it as a whole.","ex":{"en":"The central section of the book is a historical overview of drug use.","cn":"该书的核心部分对毒品的使用作了历史概述。"}}]},"media":{"uk":"media/uk/overview__gb_1.mp3","us":"media/us/overview__us_1.mp3"}},"overhead":{"media":{"uk":"media/uk/overhead__gb_1.mp3","us":"media/us/overhead__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈhed","pos":"adverb","senses":[{"en":"above your head; in the sky","cn":"在头上方；在空中","ex":{"en":"Planes flew overhead constantly.","cn":"飞机不断从头顶上飞过。"}},{"en":"above your head; raised above the ground","cn":"头上方的；地面以上的；高架的","ex":{"en":"overhead power lines","cn":"架空电力线"},"pos":"adjective"},{"en":"connected with the general costs of running a business or an organization, for example paying for rent or electricity","cn":"经费的；管理费用的","g":"[only before noun]","ex":{"en":"overhead costs","cn":"营运开支"},"pos":"adjective"},{"en":"regular costs that you have when you are running a business or an organization, such as rent, electricity, wages, etc.","cn":"经费；营运费用；经常性开支","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"在头顶上的；在上面的；高架的","en":"You use overhead to indicate that something is above you or above the place that you are talking about.","ex":{"en":"She turned on the overhead light and looked around the little room.","cn":"她打开头顶上方的灯，环视了一圈这个小房间。"}}]},"examples":[{"en":"Planes flew overhead constantly.","cn":"飞机不断从头顶上飞过。"},{"en":"Thunder boomed in the sky overhead.","cn":"雷声在天空中隆隆作响。"}]},"outside":{"media":{"uk":"media/uk/outside__gb_1.mp3","us":"media/us/outside__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈsaɪd","pos":"adverb","senses":[{"en":"not in a room, building or container but on or to the outside of it","cn":"在外面；向外面","ex":{"en":"I'm seeing a patient—please wait outside.","cn":"我正在给病人看病，请在外面等候。"}},{"en":"not inside a building","cn":"在户外；露天","ex":{"en":"It's warm enough to eat outside.","cn":"天气暖和了，可以露天吃饭了。"}},{"en":"on or to a place on the outside of something","cn":"在…外面；向…外面","ex":{"en":"You can park your car outside our house.","cn":"你可以把汽车停在我们家屋外。"},"pos":"preposition"},{"en":"away from or not in a particular place","cn":"离开；不在","ex":{"en":"It's the biggest theme park outside the United States.","cn":"这是美国以外最大的主题游乐园。"},"pos":"preposition"},{"en":"not part of something","cn":"不在…范围内；不属于","ex":{"en":"The matter is outside my area of responsibility.","cn":"此事不属于我的职责范围。"},"pos":"preposition"},{"en":"more than the amount of time mentioned","cn":"（时间）超出，多于","ex":{"en":"The winning time was just nine seconds outside the world record.","cn":"第一名所用的时间只比世界纪录多 9 秒。"},"pos":"preposition"},{"en":"apart from","cn":"除了","ex":{"en":"There was nothing they could do, outside of hoping things would get better.","cn":"除了盼望情况好转，他们无能为力。"},"pos":"preposition"},{"en":"the outer side or surface of something","cn":"外部；外表","g":"[countable, usually singular]","ex":{"en":"The outside of the house needs painting.","cn":"房子的外墙需要油漆一下。"},"pos":"noun"},{"en":"the area that is near or around a building, etc.","cn":"（建筑物等的）周围，外围","g":"[singular]","ex":{"en":"I walked around the outside of the building.","cn":"我绕着这座建筑四周散步。"},"pos":"noun"},{"en":"the part of a road nearest to the middle","cn":"（靠近路中央的）外侧，外手","g":"[singular]","ex":{"en":"Always overtake on the outside.","cn":"超车务必走外侧道。"},"pos":"noun"},{"en":"the part of a curving road or track furthest from the inner or shorter side of the curve","cn":"（弯曲路面或轨道的）外道，外缘","g":"[singular]","pos":"noun"},{"en":"of, on or facing the outer side","cn":"外部的；在外面的；向外的","ex":{"en":"The outside walls are damp.","cn":"外墙潮湿。"},"pos":"adjective"},{"en":"not located in the main building; going out of the main building","cn":"主建筑物以外的；向外面的","ex":{"en":"an outside toilet","cn":"户外厕所"},"pos":"adjective"},{"en":"not included in or connected with your group, organization, country, etc.","cn":"不属于本团体（或机构、国家等）的；外部的；不相关的","ex":{"en":"We plan to use an outside firm of consultants.","cn":"我们计划利用外面的咨询公司。"},"pos":"adjective"},{"en":"used to say that something is very unlikely","cn":"不可能的；可能性极小的","ex":{"en":"They have only an outside chance of winning.","cn":"他们的胜算极小。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外面；外部；外表","en":"The outside of something is the part which surrounds or encloses the rest of it.","ex":{"en":"...the outside of the building","cn":"建筑物的外部"}},{"pos":"ADV 副词","cn":"在外面；在室外；在建筑物近旁","en":"If you are outside, you are not inside a building but are quite close to it.","ex":{"en":"'Was the car inside the garage?' — 'No, it was still outside.'","cn":"“车在车库里吗？”——“不，还在外面。”"}},{"pos":"PREP 介词","cn":"在（房间）的外面","en":"If you are outside a room, you are not in it but are in the passage or area next to it.","ex":{"en":"She'd sent him outside the classroom","cn":"她让他到教室外面去。"}},{"pos":"ADJ 形容词","cn":"外部（世界）的；外界的","en":"When you talk about the outside world, you are referring to things that happen or exist in places other than your own home or community.","ex":{"en":"...a side of Morris's character she hid carefully from the outside world","cn":"莫里斯小心隐藏不让外人知晓的性格中的一面"}},{"pos":"PREP 介词","cn":"不在…；在（某地）之外","en":"People or things outside a country, town, or region are not in it.","ex":{"en":"...an old castle outside Budapest","cn":"布达佩斯城外的古堡"}},{"pos":"ADJ 形容词","cn":"（车道）靠近路中间的，快车道的","en":"On a road with two separate carriageways, the outside lanes are the ones which are closest to its centre.","ex":{"en":"It was travelling in the outside lane at 78mph.","cn":"它正以78英里的时速在快车道上疾驶。"}},{"pos":"ADJ 形容词","cn":"（人员、机构等）外部的","en":"Outside people or organizations are not part of a particular organization or group.","ex":{"en":"The company now makes much greater use of outside consultants.","cn":"该公司现在对外聘顾问的利用更加充分。"}},{"pos":"PREP 介词","cn":"在（…领域）以外","en":"Outside a particular institution or field of activity means in other fields of activity or in general life.","ex":{"en":"The condition is practically unknown outside psychiatry clinics.","cn":"除了医院的精神病科外，这种病几乎不为人知。"}},{"pos":"PREP 介词","cn":"在…范围以外","en":"Something that is outside a particular range of things is not included within it.","ex":{"en":"She is a beautiful boat, but way, way outside my price range","cn":"这条船很漂亮，但价格却远远超出我能承受的范围。"}},{"pos":"PREP 介词","cn":"在（某段时间）以外","en":"Something that happens outside a particular period of time happens at a different time from the one mentioned.","ex":{"en":"They are open outside normal daily banking hours.","cn":"它们在银行正常营业时间以外开放。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除了…之外；不包括","en":"Outside of is used to introduce the only thing or person that prevents your main statement from being completely true.","ex":{"en":"Every single relationship I've had with a man, outside of my husband, has ended in disaster.","cn":"除了我丈夫之外，我与所有男人的感情都以悲剧收场。"}},{"pos":"PHRASE 短语","cn":"最多；充其量；最晚","en":"You use at the outside to say that you think that a particular amount is the largest possible in a particular situation, or that a particular time is the latest possible time for something to happen.","ex":{"en":"Give yourself forty minutes at the outside.","cn":"最多给自己留40分钟。"}}]},"examples":[{"en":"I didn't go into the temple — I only saw it from the outside.","cn":"我没有走进庙宇，只是从外面看了一下。"},{"en":"We live in a small village just outside Leeds.","cn":"我们就住在利兹市外的一个小村子里。"}]},"oily":{"media":{"uk":"media/uk/oily__gb_1.mp3","us":"media/us/oily__us_1.mp3"},"oxford":{"phon":"ˈɔɪli","pos":"adjective","senses":[{"en":"containing or covered with oil","cn":"含油的；油污的；涂油的","ex":{"en":"oily fish","cn":"含油多的鱼"}},{"en":"feeling, tasting, smelling or looking like oil","cn":"（质地、味道、气味、形态）像油的","ex":{"en":"an oily substance","cn":"油状物质"}},{"en":"trying to be too polite, in a way that is annoying","cn":"油滑的；油腔滑调的；奉迎的","lab":"disapproving","ex":{"en":"an oily smile","cn":"谄媚的微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"涂油的；含油的；油腻的","en":"Something that is oily is covered with oil or contains oil.","ex":{"en":"He was wiping his hands on an oily rag","cn":"他在用一块油乎乎的抹布擦手。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"似油的；油状的；油味的","en":"Oily means looking, feeling, tasting, or smelling like oil.","ex":{"en":"...traces of an oily substance.","cn":"少许油状物质"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"油滑的；谄媚的；逢迎的","en":"If you describe someone as oily, you dislike them because you think they are too polite or say exaggeratedly nice things, and are insincere.","ex":{"en":"He had behaved with undue and oily familiarity","cn":"他表现得过于亲热，媚态毕现。"}}]},"examples":[{"en":"oily fish","cn":"含油多的鱼"},{"en":"an oily rag","cn":"油污的抹布"}]},"ox":{"oxford":{"phon":"ɒks","pos":"noun","senses":[{"en":"a bull (= a male cow) that has been castrated (= had part of its sex organs removed), used, especially in the past, for pulling farm equipment, etc.","cn":"（阉割的）公牛；犍牛"},{"en":"any cow or bull on a farm","cn":"饲养的牛","lab":"old-fashioned"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阉牛；去势公牛","en":"An ox is a bull that has been castrated. Oxen are used in some countries for pulling vehicles or carrying things."}]},"media":{"uk":"media/uk/ox__gb_1.mp3","us":"media/us/ox__us_1.mp3"}},"open":{"media":{"uk":"media/uk/open__gb_1.mp3","us":"media/us/open__us_1.mp3"},"oxford":{"phon":"ˈəʊpən","pos":"adjective","senses":[{"en":"allowing things or people to go through; not closed or blocked","cn":"开放的；敞开的","sc":"not closed","ex":{"en":"A wasp flew in the open window.","cn":"一只黄蜂飞进了开着的窗子。"}},{"en":"with eyelids or lips apart","cn":"张开的；张着的","sc":"not closed","ex":{"en":"She had difficulty keeping her eyes open (= because she was very tired).","cn":"她连睁开眼睛的力气都没有了。"}},{"en":"spread out; with the edges apart","cn":"展开的；开放的","sc":"not closed","ex":{"en":"The flowers are all open now.","cn":"花现在都开了。"}},{"en":"not fastened or covered, so that things can easily come out or be put in","cn":"敞口的；未封的","sc":"not fastened","ex":{"en":"Leave the envelope open.","cn":"别封上信封。"}},{"en":"not fastened","cn":"未系着","sc":"not fastened","ex":{"en":"Her coat was open.","cn":"她的外衣敞着。"}},{"en":"not surrounded by anything; not closed in","cn":"开阔的；未围上的","sc":"not enclosed","ex":{"en":"open country/countryside (= without forests, buildings, etc.)","cn":"空旷的田野"}},{"en":"with no cover or roof on","cn":"敞开的；露天的；裸露的","lab":"North American English","sc":"not covered","ex":{"en":"an open drain","cn":"一条明沟"}},{"en":"if a shop, bank, business, etc. is open, it is ready for business and will allow customers or visitors to come in","cn":"开放；营业中","g":"[not usually before noun]","sc":"for customers/visitors","ex":{"en":"Is the museum open on Sundays?","cn":"博物馆每星期天都开放吗？"}},{"en":"if a competition, meeting, etc. is open, anyone can enter, attend it, etc.","cn":"对大众开放的；公开的；人人可以参加的","sc":"of competition/building","ex":{"en":"an open debate/championship/scholarship","cn":"公开的辩论会；人人可以参加的锦标赛；人人均可申请的奖学金"}},{"en":"if a competition, building, etc. is open to particular people, those people can enter it","cn":"（比赛、建筑物等）对特定群体开放","g":"[not before noun]","sc":"of competition/building","ex":{"en":"The competition is open to young people under the age of 18.","cn":"这项比赛的参赛对象是 18 岁以下的青少年。"}},{"en":"to be available and ready to use","cn":"可得到；可使用","g":"[not before noun]","sc":"available","ex":{"en":"Is the offer still open?","cn":"这个报价还有效吗？"}},{"en":"if a phone line or other channel of communication is open, it is ready to take calls, receive requests, etc.","cn":"（电话线或其他沟通渠道）开放，畅通","g":"[not before noun]","sc":"available","ex":{"en":"Lines are open 8 am to 7 pm weekdays.","cn":"电话线路的开放时间是工作日的上午 8 点至晚上 7 点。"}},{"en":"likely to suffer something such as criticism, injury, etc.","cn":"易受损害；脆弱","sc":"not protected","ex":{"en":"The system is open to abuse.","cn":"这项制度容易被滥用。"}},{"en":"known to everyone; not kept hidden","cn":"人人皆知的；不保密的；公开的","sc":"not hidden","ex":{"en":"an open quarrel","cn":"公开的争吵"}},{"en":"honest; not keeping thoughts and feelings hidden","cn":"诚恳；坦诚；直率","sc":"honest","ex":{"en":"a frank and open discussion","cn":"开诚布公的讨论"}},{"en":"willing to listen to and think about new ideas","cn":"思想开明的；不固执己见的","sc":"honest","ex":{"en":"He was in an open frame of mind.","cn":"他思想开明。"}},{"en":"not yet finally decided or settled","cn":"未决定的；待决定的","sc":"not yet decided","ex":{"en":"The race is still wide open (= anyone could win).","cn":"赛跑胜负未定。"}},{"en":"allowing something; making something possible","cn":"允许的；留有余地的","sc":"making something possible","ex":{"en":"The price is not open to negotiation.","cn":"价格不容商议。"}},{"en":"that does not have to be used on a particular day","cn":"（使用）日期未定的；不定日期的","sc":"ticket","ex":{"en":"I have an open ticket, so I can travel any day I like.","cn":"我有一张不定日期机票，所以我可以随便哪天去旅行。"}},{"en":"with wide spaces between the threads","cn":"稀疏的；不密的","sc":"cloth","ex":{"en":"an open weave","cn":"稀疏织法"}},{"en":"produced with the tongue in the lowest possible position","cn":"开的；舌位低的","sc":"phonetics"},{"en":"to move a door, window, lid, etc. into a position that is no longer closed; to get into this position","cn":"开；打开；开启","g":"[transitive, intransitive]","sc":"door/window/lid","ex":{"en":"Mr Chen opened the car door for his wife.","cn":"陈先生为妻子打开车门。"},"pos":"verb"},{"en":"to remove or undo the top, cover, etc. of a container or package in order to see or get what is inside","cn":"打开，开启（瓶盖、封口等）","g":"[transitive]","sc":"container/package","ex":{"en":"Shall I open another bottle?","cn":"要不要我再开一瓶？"},"pos":"verb"},{"en":"if you open your eyes or your eyes open, you move your eyelids upwards so that you can see","cn":"睁开","g":"[transitive, intransitive]","sc":"eyes","ex":{"en":"When I opened my eyes a nurse was standing over me.","cn":"当我睁开眼睛时，一名护士站在我身边。"},"pos":"verb"},{"en":"if you open your mouth or your mouth opens, you move your lips, for example in order to speak","cn":"张开","g":"[transitive, intransitive]","sc":"mouth","ex":{"en":"He hardly ever opens his mouth (= speaks).","cn":"他几乎从不开口。"},"pos":"verb"},{"en":"to turn the cover or the pages of a book, newspaper, etc. so that it is no longer closed","cn":"打开；翻开","g":"[transitive]","sc":"book","ex":{"en":"Open your books at page 25.","cn":"把书翻到第 25 页。"},"pos":"verb"},{"en":"to start a computer program or file so that you can use it on the screen; to become available on a computer screen","cn":"启动，打开（计算机程序或文件）；（计算机程序等）开启","g":"[transitive, intransitive]","sc":"computing","ex":{"en":"Open the camera app and tap ‘Options’.","cn":"打开相机应用程序并点击“选项”。"},"pos":"verb"},{"en":"to spread out or unfold; to spread something out or unfold it","cn":"展开；打开","g":"[intransitive, transitive]","sc":"spread out","ex":{"en":"What if the parachute doesn't open?","cn":"降落伞打不开怎么办？"},"pos":"verb"},{"en":"to make it possible for people, cars, goods, etc. to pass through a place","cn":"让（行人、车辆、货物等）通行；开放","g":"[transitive]","sc":"border/road","ex":{"en":"When did the country open its borders?","cn":"这个国家是何时开放边界的？"},"pos":"verb"},{"en":"to start business for the day; to start business for the first time","cn":"开始营业；开业；开门","g":"[intransitive, transitive]","sc":"for customers/visitors","ex":{"en":"What time does the bank open?","cn":"这家银行什么时候开门？"},"pos":"verb"},{"en":"to be ready for people to go to","cn":"开始接待","g":"[intransitive]","sc":"for customers/visitors","ex":{"en":"The new hospital opens on July 1st.","cn":"这家新医院七月一日开诊。"},"pos":"verb"},{"en":"to start an activity or event; to begin using or doing something","cn":"开始进行；着手做","g":"[transitive]","lab":"British English","sc":"start something","ex":{"en":"You need just one pound to open an account with us.","cn":"你只需一英镑就可在我行开立一个账户。"},"pos":"verb"},{"en":"to start in a particular way; to make something start in a particular way","cn":"以…开篇；以…开头","g":"[intransitive, transitive]","sc":"start something","ex":{"en":"How does the play open?","cn":"这部剧怎么开场呢？"},"pos":"verb"},{"en":"to perform a ceremony showing that a building can start being used","cn":"为（建筑物）揭幕；宣布启用","g":"[transitive]","sc":"with ceremony","ex":{"en":"The Queen officially opened the bridge in March.","cn":"女王在三月为大桥开通揭幕。"},"pos":"verb"},{"en":"to make it possible to reach, have, use or do something","cn":"开放；使可以达到（或取得、使用等）","sc":"make something possible","ex":{"en":"This decision opens the possibility of a fresh election.","cn":"这一决定使新一轮选举成为可能。"},"pos":"verb"},{"en":"outdoors; the countryside","cn":"户外；野外；旷野","sc":"outdoors","ex":{"en":"Children need to play out in the open.","cn":"孩子需要在户外玩耍。"},"pos":"noun"},{"en":"not hidden or secret","cn":"公开；非秘密","sc":"not hidden","ex":{"en":"Government officials do not want these comments in the open.","cn":"政府官员不想公开这些评论。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"打开（门、窗、盖等）","en":"If you open something such as a door, window, or lid, or if it opens, its position is changed so that it no longer covers a hole or gap.","ex":{"en":"He opened the window and looked out","cn":"他打开窗户往外看。"}},{"pos":"VERB 动词","cn":"将（瓶、盒等）开封；拆开（包裹、信封等）","en":"If you open something such as a bottle, box, parcel, or envelope, you move, remove, or cut part of it so you can take out what is inside.","ex":{"en":"The Inspector opened the packet of cigarettes","cn":"检查员撕开了那包香烟。"}},{"pos":"V-ERG 及物/不及物动词","cn":"翻开；张开；展开","en":"If you open something such as a book, an umbrella, or your hand, or if it opens, the different parts of it move away from each other so that the inside of it can be seen.","ex":{"en":"He opened the heavy Bible","cn":"他翻开那本厚厚的《圣经》。"}},{"pos":"VERB 动词","cn":"打开（计算机文件）","en":"If you open a computer file, you give the computer an instruction to display it on the screen.","ex":{"en":"Double click on the icon to open the file.","cn":"双击图标打开文件。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使)(眼睛）睁开","en":"When you open your eyes or your eyes open, you move your eyelids upwards, for example when you wake up, so that you can see.","ex":{"en":"When I opened my eyes I saw a man with an axe standing at the end of my bed","cn":"我睁开眼睛时，看见一个手持斧头的男人站在床尾。"}},{"pos":"VERB 动词","cn":"敞开（双臂）","en":"If you open your arms, you stretch them wide apart in front of you, usually in order to put them round someone.","ex":{"en":"She opened her arms and gave me a big hug.","cn":"她张开双臂，紧紧地拥抱了我。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（身前）无遮挡的；（姿势）端正的","en":"If you stand or sit in an open way, the front of your body is fully exposed and you are not bending forward or at an angle to someone.","ex":{"en":"Good listeners even sit in an open way: relaxed, arms loose","cn":"善于倾听的人甚至坐姿也很坦荡端正：身体放松，双臂自然下垂。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦率的；诚恳的；不作伪的","en":"If you describe a person or their character as open, you mean they are honest and do not want or try to hide anything or to deceive anyone.","ex":{"en":"He had always been open with her and she always felt she would know if he lied","cn":"他对她总是坦诚相待，她也一直觉得如果他说谎，自己一定能察觉。"}},{"pos":"ADJ 形容词","cn":"公开的；不加掩饰的","en":"If you describe a situation, attitude, or way of behaving as open, you mean it is not kept hidden or secret.","ex":{"en":"The action is an open violation of the Vienna Convention","cn":"该行为公然违背了《维也纳公约》。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愿意接受（建议、观点等）的；虚怀若谷的","en":"If you are open to suggestions or ideas, you are ready and willing to consider or accept them.","ex":{"en":"They are open to suggestions on how working conditions might be improved.","cn":"他们愿意就如何改善工作条件听取各种意见。"}},{"pos":"ADJ 形容词","cn":"容易招致（滥用、批评等）的；易受（攻击）的","en":"If you say that a system, person, or idea is open to something such as abuse or criticism, you mean they might receive abuse or criticism because of their qualities, effects, or actions.","ex":{"en":"The system, though well-meaning, is open to abuse","cn":"该制度动机虽好，却易遭滥用。"}},{"pos":"ADJ 形容词","cn":"悬而未决的；尚未决定的","en":"If you say that a fact or question is open to debate, interpretation, or discussion, you mean that people are uncertain whether it is true, what it means, or what the answer is.","ex":{"en":"The truth of the facts produced may be open to doubt","cn":"所摆出事实的真实性仍然值得怀疑。"}},{"pos":"V-ERG 及物/不及物动词","cn":"开放（被封的道路、边界等）；开通","en":"If people open something such as a blocked road or a border, or if it opens, people can then pass along it or through it.","ex":{"en":"The rebels have opened the road from Monrovia to the Ivory Coast","cn":"叛乱分子已经开放了从蒙罗维亚到象牙海岸的道路。"}},{"pos":"VERB 动词","cn":"通向（更大的地方）","en":"If a place opens into another, larger place, you can move from one directly into the other.","ex":{"en":"The corridor opened into a low smoky room.","cn":"这条走廊通向一间烟雾弥漫的低矮房间。"}},{"pos":"ADJ 形容词","cn":"开阔的；空旷的","en":"An open area is a large area that does not have many buildings or trees in it.","ex":{"en":"Officers will also continue their search of nearby open ground.","cn":"警察还将继续在附近的开阔地带搜寻。"}},{"pos":"ADJ 形容词","cn":"敞开的；无遮盖的；无围挡的","en":"An open structure or object is not covered or enclosed.","ex":{"en":"Don't leave a child alone in a room with an open fire.","cn":"房间里有裸露的明火时，不要让孩子独处其中。"}},{"pos":"ADJ 形容词","cn":"（伤口）外露的，裸露的，流血的","en":"An open wound is one from which a liquid such as blood is coming."},{"pos":"VERB 动词","cn":"把（衣服）解开；把…的拉链拉开","en":"If you open your shirt or coat, you undo the buttons or pull down the zip.","ex":{"en":"I opened my coat and let him see the belt.","cn":"我解开外衣，让他看那条皮带。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）开始营业；（使）开门","en":"When a shop, office, or public building opens or is opened, its doors are unlocked and the public can go in.","ex":{"en":"Banks closed on Friday afternoon and did not open again until Monday morning.","cn":"银行星期五下午关门，直到星期一上午才营业。"}},{"pos":"V-ERG 及物/不及物动词","cn":"为（大楼、工厂、公司等）举行揭幕典礼；开设；开办；开张","en":"When a public building, factory, or company opens or when someone opens it, it starts operating for the first time.","ex":{"en":"The original station opened in 1754","cn":"最初的车站于1754年落成。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（会议、会谈）开始；召开","en":"If something such as a meeting or series of talks opens, or if someone opens it, it begins.","ex":{"en":"...an emergency session of the Russian Parliament due to open later this morning","cn":"将于今天上午晚些时候召开的俄罗斯议会紧急会议"}},{"pos":"V-ERG及物/不及物动词","cn":"（以…）开始","en":"If an event such as a meeting or discussion opens with a particular activity or if a particular activity opens an event, that activity is the first thing that happens or is dealt with. You can also say that someone such as a speaker or singer opens by doing a particular thing.","ex":{"en":"The service opened with a hymn","cn":"礼拜仪式从唱圣歌开始。"}},{"pos":"VERB 动词","cn":"（股市）开盘，开市","en":"On the stock exchange, the price at which currencies, shares, or commodities open is their value at the start of that day's trading.","ex":{"en":"Gold declined $2 in Zurich to open at 385.50","cn":"苏黎世的金价下挫2美元，以385.50元开盘。"}},{"pos":"VERB 动词","cn":"上映；开演；开幕","en":"When a film, play, or other public event opens, it begins to be shown, be performed, or take place for a limited period of time.","ex":{"en":"A photographic exhibition opens at the Royal College of Art on Wednesday","cn":"星期三一个摄影展在皇家艺术学院开幕。"}},{"pos":"VERB 动词","cn":"（在银行等处）开立（账户）","en":"If you open an account with a bank or a commercial organization, you begin to use their services.","ex":{"en":"He tried to open an account at the branch of his bank nearest to his workplace.","cn":"他想在自己银行离工作单位最近的网点开一个账户。"}},{"pos":"ADJ 形容词","cn":"（机会、选择等）可利用的，可得到的","en":"If an opportunity or choice is open to you, you are able to do a particular thing if you choose to.","ex":{"en":"There are a wide range of career opportunities open to young people.","cn":"年轻人有各种职业选择机会。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（机会、可能性等）出现;（使）产生","en":"To open opportunities or possibilities means the same as to open them up.","ex":{"en":"The chief of naval operations wants to open opportunities for women in the Navy","cn":"美国海军作战部长希望能为女兵提供机会。"}},{"pos":"ADJ 形容词","cn":"人人可以参加（或接受）的；开放的","en":"You can use open to describe something that anyone is allowed to take part in or accept.","ex":{"en":"A recent open meeting of College members revealed widespread dissatisfaction","cn":"最近的一次学会成员公开会上，大家普遍流露出不满情绪。"}},{"pos":"ADJ 形容词","cn":"（提议等）有效的；（职位等）空缺的，可申请的","en":"If something such as an offer or job is open, it is available for someone to accept or apply for.","ex":{"en":"The offer will remain open until further notice.","cn":"该提议仍然有效，直到另行通知。"}},{"pos":"PHRASE 短语","cn":"在露天；在户外；在野外","en":"If you do something in the open, you do it out of doors rather than in a house or other building.","ex":{"en":"Many are sleeping in the open because they have no shelter.","cn":"很多人因为没有栖身之所，只好露宿在外。"}},{"pos":"PHRASE 短语","cn":"公开的；众人皆知的","en":"If an attitude or situation is in the open or out in the open, people know about it and it is no longer kept secret.","ex":{"en":"The medical service had advised us to keep it a secret, but we wanted it in the open.","cn":"这家医疗机构建议我们保密，而我们却想公开此事。"}},{"pos":"PHRASE 短语","cn":"大开的；敞开的；（眼睛）睁大的","en":"If something is wide open, it is open to its full extent.","ex":{"en":"The child had left the inner door wide open.","cn":"这个孩子将里面的门大敞着。"}},{"pos":"PHRASE 短语","cn":"（比赛、选举等）结果不确定的，胜负难定的","en":"If you say that a competition, race, or election is wide open, you mean that anyone could win it, because there is no competitor who seems to be much better than the others.","ex":{"en":"The competition has been thrown wide open by the absence of the world champion.","cn":"由于世界冠军缺阵，这场比赛变得胜负难定。"}},{"pos":"","cn":"","en":"with open arms→see: ; to open the door→see: ; to keep your eyes open→see: ; with your eyes open→see: ; to open your eyes→see: ; to open fire→see: ; to open your heart→see: ; the heavens open→see: ; an open mind→see: ; to open your mind→see: ; to keep your options open→see: ;"},{"pos":"","cn":"","en":"相关词组：open out open up"}]},"examples":[{"en":"It helps to discuss your problems but I find it hard to open up.","cn":"与人谈谈自己面对的问题固然有益，但我觉得有些话很难说得出口。"},{"en":"The road will be opened again in a few hours after police have cleared it.","cn":"待警察清理完以后，道路在几小时内就会重新开放。"}]},"obsession":{"media":{"uk":"media/uk/obsession__gb_1.mp3","us":"media/us/obsession__us_1.mp3"},"oxford":{"phon":"əbˈseʃn","pos":"noun","senses":[{"en":"the state in which a person’s mind is completely filled with thoughts of one particular thing or person in a way that is not reasonable or normal","cn":"痴迷；着魔；困扰","g":"[uncountable, countable]","ex":{"en":"Her fear of flying is bordering on obsession.","cn":"她怕乘飞机几乎到了不可救药的地步。"}},{"en":"a person or thing that somebody thinks about too much","cn":"使人痴迷的人（或物）","g":"[countable]","ex":{"en":"Fitness has become an obsession with him.","cn":"他迷上了健身。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"着迷；困扰；强迫观念","en":"If you say that someone has an obsession with a person or thing, you think they are spending too much time thinking about them.","ex":{"en":"She would try to forget her obsession with Christopher","cn":"她会努力忘记对克里斯托弗的迷恋。"}}]},"examples":[{"en":"The media's obsession with the young prince continues.","cn":"新闻媒体继续对年轻的王子作连篇累牍的报道。"},{"en":"Her fear of flying is bordering on obsession.","cn":"她怕乘飞机几乎到了不可救药的地步。"}]},"obviously":{"media":{"uk":"media/uk/obviously__gb_1.mp3","us":"media/us/obviously__us_1.mp3"},"oxford":{"phon":"ˈɒbviəsli","pos":"adverb","senses":[{"en":"used when giving information that you expect other people to know already or agree with","cn":"（用于陈述认为别人已知道或希望别人同意的事）显然，明显地","ex":{"en":"Obviously, we don't want to spend too much money.","cn":"很明显，我们不想花太多的钱。"}},{"en":"used to say that a particular situation or fact is easy to see or understand","cn":"（用于说明某种情况或事实）显而易见，明显，不言而喻","ex":{"en":"He was obviously upset.","cn":"他显然很不高兴。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（用于陈述认为听者已经知道的事）显然地，无疑地","en":"You use obviously when you are stating something that you expect the person who is listening to know already.","ex":{"en":"Obviously, they've had sponsorship from some big companies","cn":"很显然，他们已经得到某些大公司的赞助。"}},{"pos":"ADV-GRADED 副词","cn":"明显地;显而易见地","en":"You use obviously to indicate that something is easily noticed, seen, or recognized.","ex":{"en":"They obviously appreciate you very much","cn":"他们显然对你十分感激。"}}]},"examples":[{"en":"‘I didn't realise it was a formal occasion.’ ‘Obviously!’ (= I can see by the way you are dressed) “","cn":"我没想到这是个正式场合。” “看得出来！”（看你的衣着就知道）"},{"en":"Obviously, we don't want to spend too much money.","cn":"很明显，我们不想花太多的钱。"}]},"observe":{"media":{"uk":"media/uk/observe__gb_1.mp3","us":"media/us/observe__us_1.mp3"},"oxford":{"phon":"əbˈzɜːv","pos":"verb","senses":[{"en":"to see or notice somebody/something","cn":"看到；注意到；观察到","g":"[transitive]","lab":"formal","ex":{"en":"Have you observed any changes lately?","cn":"最近你注意到什么变化没有？"}},{"en":"to watch somebody/something carefully, especially to learn more about them","cn":"观察；注视；监视","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"He observes keenly, but says little.","cn":"他观察敏锐，但言语寥寥。"}},{"en":"to make a remark","cn":"说话；评论","g":"[transitive]","lab":"formal","ex":{"en":"She observed that it was getting late.","cn":"她说天色晚了。"}},{"en":"to obey rules, laws, etc.","cn":"遵守（规则、法律等）","g":"[transitive]","ex":{"en":"Will the rebels observe the ceasefire?","cn":"叛乱者会遵守停火协议吗？"}},{"en":"to celebrate festivals, birthdays, etc.","cn":"庆祝；庆贺；欢度","g":"[transitive]","lab":"formal","ex":{"en":"Do they observe Christmas?","cn":"他们过不过圣诞节？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指为了解而）观察，观测","en":"If you observe a person or thing, you watch them carefully, especially in order to learn something about them.","ex":{"en":"Stern also studies and observes the behaviour of babies","cn":"斯特恩还研究观察婴儿的行为。"}},{"pos":"VERB 动词","cn":"看到；注意到","en":"If you observe someone or something, you see or notice them.","ex":{"en":"In 1664 Hooke observed a reddish spot on the surface of the planet.","cn":"1664年，胡克注意到这颗行星表面有一块微红的斑点。"}},{"pos":"VERB 动词","cn":"（尤指就注意到或深思熟虑之事）说，评论，评述","en":"If you observe that something is the case, you make a remark or comment about it, especially when it is something you have noticed and thought about a lot.","ex":{"en":"We observe that the first calls for radical transformation did not begin until the period of the industrial revolution","cn":"我们认为直到工业革命时期才出现了要求彻底变革的第一波呐喊。"}},{"pos":"VERB 动词","cn":"遵守，奉行（法律、习俗等）","en":"If you observe something such as a law or custom, you obey it or follow it.","ex":{"en":"Imposing speed restrictions is easy, but forcing motorists to observe them is trickier","cn":"限制车速容易，但强制司机遵守这些限速规定就难办多了。"}}]},"examples":[{"en":"I felt he was observing everything I did.","cn":"我觉得他正在注视着我做的每一件事。"},{"en":"The police observed a man enter the bank.","cn":"警察注意到一个男人走进了银行。"}]},"orders":{"lemma":"order","media":{"uk":"media/uk/order__gb_1.mp3","us":"media/us/order__us_1.mp3"}},"offends":{"lemma":"offend"},"observational":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指为获取新信息)观察的，观测的","en":"Observational means relating to the watching of people or things, especially in order to learn something new.","ex":{"en":"...observational humour","cn":"依靠观察发掘的幽默"}}]},"media":{"uk":"media/uk/observational__gb_1.mp3","us":"media/us/observational__us_1.mp3"},"examples":[{"en":"Bloomfield’s approach to linguistics was based on observation of the language.","cn":""},{"en":"He spent two nights under close observation in hospital.","cn":""}],"oxford":{"phon":"ˌɒbzəˈveɪʃənl","pos":"adjective","senses":[{"en":"connected with or based on the activity of watching somebody/something carefully for a period of time, especially to learn something","cn":"观察；观测；监视","ex":{"en":"The course helps drivers to improve their observational skills.","cn":"该课程帮助驾驶员提高观察能力。"}}]}},"onset":{"media":{"uk":"media/uk/onset__gb_1.mp3","us":"media/us/onset__us_1.mp3"},"oxford":{"phon":"ˈɒnset","pos":"noun","senses":[{"en":"the beginning of something, especially something unpleasant","cn":"开端，发生，肇始（尤指不快的事件）","ex":{"en":"the onset of disease/old age/winter","cn":"疾病的发作；老年的开始；冬天的来临"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（尤指不快之事的）开始，开端，肇始","en":"The onset of something is the beginning of it, used especially to refer to something unpleasant.","ex":{"en":"Most of the passes have been closed with the onset of winter","cn":"冬天来临，大部分关口均已关闭。"}}]},"examples":[{"en":"the onset of disease/old age/winter","cn":"疾病的发作；老年的开始；冬天的来临"},{"en":"the onset of winter","cn":"冬天的来临"}]},"opponent":{"oxford":{"phon":"əˈpəʊnənt","pos":"noun","senses":[{"en":"a person that you are playing or fighting against in a game, competition, argument, etc.","cn":"对手；竞争者","ex":{"en":"a political opponent","cn":"政敌"}},{"en":"a person who is against something and tries to change or stop it","cn":"反对者；阻止者","ex":{"en":"opponents of abortion","cn":"反对堕胎的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（政治上的）对手，敌手","en":"A politician's opponents are other politicians who belong to a different party or who have different aims or policies.","ex":{"en":"...Mr Kennedy's opponent in the leadership contest","cn":"与肯尼迪先生争夺领导权的对手"}},{"pos":"N-COUNT 可数名词","cn":"（体育竞赛中的）对手，竞争者","en":"In a sporting contest, your opponent is the person who is playing against you.","ex":{"en":"Norris twice knocked down his opponent in the early rounds of the fight","cn":"诺里斯在前几个回合中两次击倒对手。"}},{"pos":"N-COUNT 可数名词","cn":"（观点、政策等的）反对者","en":"The opponents of an idea or policy do not agree with it and do not want it to be carried out.","ex":{"en":"...opponents of the spread of nuclear weapons","cn":"反对核武器扩散的人士"}}]},"media":{"uk":"media/uk/opponent__gb_1.mp3","us":"media/us/opponent__us_1.mp3"},"examples":[{"en":"The team's opponents are unbeaten so far this season.","cn":"该队的竞争对手本赛季尚无败绩。"},{"en":"a dangerous/worthy/formidable opponent","cn":"危险的/可敬的/强大的对手"}]},"occur":{"media":{"uk":"media/uk/occur__gb_1.mp3","us":"media/us/occur__us_1.mp3"},"oxford":{"phon":"əˈkɜː(r)","pos":"verb","senses":[{"en":"to happen","cn":"发生；出现","g":"[intransitive]","ex":{"en":"When exactly did the incident occur?","cn":"这一事件究竟是什么时候发生的？"}},{"en":"to exist or be found somewhere","cn":"存在（于）；出现（在）","g":"[intransitive]","ex":{"en":"Sugar occurs naturally in fruit.","cn":"水果天然含糖分。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发生","en":"When something occurs, it happens.","ex":{"en":"If headaches only occur at night, lack of fresh air and oxygen is often the cause","cn":"如果只是在晚上头疼，那常常是由于缺乏新鲜空气和氧气的缘故。"}},{"pos":"VERB 动词","cn":"存在；出现；有","en":"When something occurs in a particular place, it exists or is present there.","ex":{"en":"The cattle disease occurs more or less anywhere in Africa where the fly occurs","cn":"在非洲凡是有这种蝇虫的地方，几乎都会出现这一牛病。"}},{"pos":"VERB 动词","cn":"（想法或主意）被想到，被想起，浮现于脑海中","en":"If a thought or idea occurs to you, you suddenly think of it or realize it.","ex":{"en":"It did not occur to me to check my insurance policy","cn":"我没有想到要核实我的保险单条款。"}}]},"examples":[{"en":"When exactly did the incident occur?","cn":"这一事件究竟是什么时候发生的？"},{"en":"It didn't occur to him that his wife was having an affair.","cn":"他没有想到自己的妻子有婚外情。"}]},"or":{"media":{"uk":"media/uk/or__gb_1.mp3","us":"media/us/or__us_1.mp3"},"oxford":{"phon":"ɔː(r)","pos":"conjunction","senses":[{"en":"used to introduce another possibility","cn":"（用以引出另一种可能性）或，或者，还是","ex":{"en":"Is your sister older or younger than you?","cn":"你有姐姐还是妹妹？"}},{"en":"used in negative sentences when mentioning two or more things","cn":"（用于否定句，提出两种或多种事物时）也不","ex":{"en":"He can't read or write.","cn":"他不会读，也不会写。"}},{"en":"used to warn or advise somebody that something bad could happen; otherwise","cn":"（用于警告或忠告）否则，不然","ex":{"en":"Turn the heat down or it'll burn.","cn":"把炉火开小一些，不然就烧焦了。"}},{"en":"used between two numbers to show approximately how many","cn":"（用于两个数字之间表示约略数目）大约","ex":{"en":"There were six or seven of us there.","cn":"我们约有六七个人在场。"}},{"en":"used to introduce a word or phrase that explains or means the same as another","cn":"（用于引出解释性词语）或者说","ex":{"en":"geology, or the science of the earth’s crust","cn":"地质学，或者说地壳的科学"}},{"en":"used to say why something must be true","cn":"（用于说明原因）不然，否则","ex":{"en":"He must like her, or he wouldn't keep calling her.","cn":"他一定喜欢她，不然他不会老给她打电话。"}},{"en":"used to introduce a different or opposite idea","cn":"（用于引出不同或相反的看法）","ex":{"en":"He was lying—or was he?","cn":"他在说谎，还是没有说谎？"}},{"en":"a person or thing that performs the action","cn":"做某个动作的人（或物）","ex":{"en":"actor","cn":"演员"},"pos":"suffix"}]},"collins":{"senses":[{"pos":"CONJ-COORD 连词","cn":"（连接两个或两个以上选择的可能性）或，或者，还是","en":"You use or to link two or more alternatives.","ex":{"en":"'Tea or coffee?' John asked","cn":"“喝茶还是喝咖啡？”约翰问道。"}},{"pos":"CONJ-COORD 连词","cn":"（与 either 或 whether 连用，给出另一个选择项）或，还是，就是","en":"You use or to give another alternative, when the first alternative is introduced by 'either' or 'whether'.","ex":{"en":"Items like bread, milk and meat were either unavailable or could be obtained only on the black market","cn":"像面包、牛奶和肉之类的东西要么是买不到，要么就是只能去黑市买。"}},{"pos":"CONJ-COORD 连词","cn":"（用于两个数字之间表示概数）或，大约","en":"You use or between two numbers to indicate that you are giving an approximate amount.","ex":{"en":"Everyone benefited from limiting their intake of tea to just three or four cups a day","cn":"每天只喝三四杯茶对身体有益。"}},{"pos":"CONJ-COORD 连词","cn":"（用于对刚说过的话进行更正或补充）或者说","en":"You use or to introduce a comment which corrects or modifies what you have just said.","ex":{"en":"The man was a fool, he thought, or at least incompetent","cn":"他想道，那人是个傻瓜，或者说，至少很无能。"}},{"pos":"CONJ-COORD 连词","cn":"（用于警告）否则，要不然","en":"If you say that someone should do something or something unpleasant will happen, you are warning them that if they do not do it, the unpleasant thing will happen.","ex":{"en":"She had to have the operation, or she would die.","cn":"她必须动手术，要不然就没命了。"}},{"pos":"CONJ-COORD 连词","cn":"（用于证明刚刚所作陈述的真实性）否则，要不然","en":"You use or to introduce something which is evidence for the truth of a statement you have just made.","ex":{"en":"He must have thought Jane was worth it or he wouldn't have wasted time on her, I suppose.","cn":"我想，他一定认为简值得他这么做，否则他不会在她身上浪费时间。"}},{"pos":"PHRASE 短语","cn":"（表示某事物对即将发生的事没有影响）不管是不是…","en":"You use or no or or not to emphasize that a particular thing makes no difference to what is going to happen.","ex":{"en":"Chairman or no, if I want to stop the project, I can","cn":"不管我是不是主席，只要我想停止这个项目，我就能做到。"}},{"pos":"PHRASE 短语","cn":"（用于重复的同一名词之间，表示某事物是否真实对情形没有影响）不管是否有…，无论有没有…","en":"You use or no between two occurrences of the same noun in order to say that whether something is true or not makes no difference to a situation.","ex":{"en":"The next day, rain or no rain, it was business as usual","cn":"第二天是否下雨都没有差别，一切照常进行。"}},{"pos":"","cn":"","en":"or else→see: ; or other→see: ; or so→see: ; or something→see: ;"}]},"examples":[{"en":"‘Who said so?’ ‘Oh, somebody or other. I can't remember who it was.’ “","cn":"这是谁说的？” “啊，某一个人吧，我记不清是谁了。”"},{"en":"He must like her, or he wouldn't keep calling her.","cn":"他一定喜欢她，不然他不会老给她打电话。"}]},"old":{"media":{"uk":"media/uk/old__gb_1.mp3","us":"media/us/old__us_1.mp3"},"oxford":{"phon":"əʊld","pos":"adjective","senses":[{"en":"of a particular age","cn":"具体年龄；（多少）岁；年纪","sc":"age","ex":{"en":"The baby was only a few hours old.","cn":"婴儿才出生几个小时。"}},{"en":"having lived for a long time; no longer young","cn":"老的；年纪大的；不年轻的","sc":"not young","ex":{"en":"to get/grow old","cn":"上年纪"}},{"en":"old people","cn":"老年人","g":"[plural]","sc":"not young","ex":{"en":"The old feel the cold more than the young.","cn":"老年人比年轻人怕冷。"}},{"en":"having existed or been used for a long time","cn":"存在（或使用）时间长的；陈旧的；古老的","lab":"British English","sc":"not new","ex":{"en":"old habits","cn":"旧习惯"}},{"en":"former; belonging to past times or a past time in your life","cn":"过去的；从前的","g":"[only before noun]","sc":"not new","ex":{"en":"Things were different in the old days.","cn":"从前的情况可不一样。"}},{"en":"used to refer to something that has been replaced by something else","cn":"（用于指称被替代的东西）原来的，原先的","g":"[only before noun]","sc":"not new","ex":{"en":"We had more room in our old house.","cn":"我们原先的房子比较宽敞。"}},{"en":"known for a long time","cn":"相识时间长的；结识久的","g":"[only before noun]","sc":"not new","ex":{"en":"She's an old friend of mine (= I have known her for a long time).","cn":"她是我的一个老朋友。"}},{"en":"used to show kind feelings or a lack of respect","cn":"（表示亲昵或不敬）","g":"[only before noun]","lab":"informal","sc":"good old/poor old","ex":{"en":"Good old Dad!","cn":"可爱的老爸！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"年老的；年纪大的；不年轻的","en":"Someone who is old has lived for many years and is no longer young.","ex":{"en":"...a white-haired old man","cn":"白发老人"}},{"pos":"ADJ 形容词","cn":"（人）…岁的；（事物）存在…久的","en":"You use old to talk about how many days, weeks, months, or years someone or something has lived or existed.","ex":{"en":"He was abandoned by his father when he was three months old","cn":"他3个月大的时候被父亲遗弃了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古老的；长久的；历史悠久的","en":"Something that is old has existed for a long time.","ex":{"en":"She loved the big old house","cn":"她喜欢这幢古老的大房子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陈旧的；破旧的","en":"Something that is old is no longer in good condition because of its age or because it has been used a lot.","ex":{"en":"He took a bunch of keys from the pocket of his old corduroy trousers.","cn":"他从破旧的灯芯绒裤子口袋里掏出一串钥匙。"}},{"pos":"ADJ 形容词","cn":"旧时的；过去的；从前的；过时的","en":"You use old to refer to something that is no longer used, that no longer exists, or that has been replaced by something else.","ex":{"en":"The old road had disappeared under grass and heather","cn":"从前的那条路已经消失在杂草和欧石南丛中。"}},{"pos":"ADJ 形容词","cn":"原来（属于自己）的；原先（生活中）的","en":"You use old to refer to something that used to belong to you, or to a person or thing that used to have a particular role in your life.","ex":{"en":"I'll make up the bed in your old room","cn":"我会把你原来房间的床铺整理好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（朋友）相识已久的；（敌人）结有宿怨的；（对手）长期竞争的","en":"An old friend, enemy, or rival is someone who has been your friend, enemy, or rival for a long time.","ex":{"en":"I called my old friend John Horner","cn":"我给老朋友约翰·霍纳打了电话。"}},{"pos":"ADJ 形容词","cn":"（表示亲昵）老…","en":"You can use old to express affection when talking to or about someone you know.","ex":{"en":"Are you all right, old chap?","cn":"你还好吗，老家伙？"}},{"pos":"PHRASE 短语","cn":"随便哪个/不是随便哪个","en":"You use any old to emphasize that the quality or type of something is not important. If you say that a particular thing is not any old thing, you are emphasizing how special or famous it is.","ex":{"en":"Any old paper will do","cn":"随便一张旧报纸就行。"}},{"pos":"PHRASE 短语","cn":"以前；从前","en":"In the old days means in the past, before things changed.","ex":{"en":"In the old days we got a visit from the vet maybe once a year.","cn":"以前，兽医大概每年来我们这里出诊一次。"}},{"pos":"PHRASE 短语","cn":"往昔的好日子；过去的好时光","en":"When people refer to the good old days, they are referring to a time in the past when they think that life was better than it is now.","ex":{"en":"He remembers the good old days when everyone in his village knew him and you could leave your door open at night.","cn":"他还记得村里人互相熟识、可以夜不闭户的美好往昔。"}},{"pos":"PHRASE 短语","cn":"昔日的；往日的；古时的","en":"If you talk about people or things of old, you are referring to people or things that existed long ago but which no longer exist, or no longer exist in the same form.","ex":{"en":"...the warrior knights of old.","cn":"旧时骁勇善战的骑士"}},{"pos":"","cn":"","en":"you can't teach an old dog new tricks→see: ; good old→see: ; of the old school→see: ; to settle an old score→see: ; up to one's old tricks→see: ;"}]},"examples":[{"en":"At thirty years old, he was already earning £40 000 a year.","cn":"他三十岁时已拿到 4 万英镑的年薪了。"},{"en":"It's the same old story of a badly managed project with inadequate funding.","cn":"又是一桩资金短缺、经营不善的老故事。"}]},"outs":{"lemma":"out","media":{"uk":"media/uk/out__gb_1.mp3","us":"media/us/out__us_1.mp3"}},"ordinary":{"media":{"uk":"media/uk/ordinary__gb_1.mp3","us":"media/us/ordinary__us_1.mp3"},"oxford":{"phon":"ˈɔːdnri","pos":"adjective","senses":[{"en":"not unusual or different in any way","cn":"普通的；平常的；一般的；平凡的","g":"[usually before noun]","ex":{"en":"an ordinary sort of day","cn":"平平常常的一天"}},{"en":"having no unusual or interesting features","cn":"平庸的；平淡无奇的","lab":"disapproving","ex":{"en":"The meal was very ordinary.","cn":"这顿饭平常得很。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平常的；普通的；一般的；平凡的","en":"Ordinary people or things are normal and not special or different in any way.","ex":{"en":"I strongly suspect that most ordinary people would agree with me","cn":"我坚定地认为绝大部分老百姓会赞同我的观点。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平庸的；平淡无奇的","en":"If you describe someone or something as ordinary, you mean they are not special or interesting in any way and may be rather dull.","ex":{"en":"I'm just a very ordinary, boring normal guy","cn":"我只是一个颇为平庸无趣的普通人。"}},{"pos":"PHRASE 短语","cn":"不寻常的；非凡的；特殊的","en":"Something that is out of the ordinary is unusual or different.","ex":{"en":"The boy's knowledge was out of the ordinary","cn":"这个男孩懂得的知识非比寻常。"}}]},"examples":[{"en":"In the ordinary way, she's not a nervous person.","cn":"一般而言，她是个不爱紧张的人。"},{"en":"I'm looking for something a little more out of the ordinary.","cn":"我正在找些稍不寻常的东西。"}]},"originally":{"media":{"uk":"media/uk/originally__gb_1.mp3","us":"media/us/originally__us_1.mp3"},"oxford":{"phon":"əˈrɪdʒənəli","pos":"adverb","senses":[{"en":"used to describe the situation that existed at the beginning of a particular period or activity, especially before something was changed","cn":"原来；起初","ex":{"en":"The school was originally very small.","cn":"这所学校当初很小。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"起初；原来","en":"When you say what happened or was the case originally, you are saying what happened or was the case when something began or came into existence, often to contrast it with what happened later.","ex":{"en":"The plane has been kept in service far longer than originally intended","cn":"这架飞机已经超期服役很长时间了。"}}]},"examples":[{"en":"Originally, we had intended to go to Italy, but then we won the trip to Greece.","cn":"我们本来打算去意大利，但后来赢得机会去了希腊。"},{"en":"The school was originally very small.","cn":"这所学校当初很小。"}]},"ocean":{"media":{"uk":"media/uk/ocean__gb_1.mp3","us":"media/us/ocean__us_1.mp3"},"oxford":{"phon":"ˈəʊʃn","pos":"noun","senses":[{"en":"the mass of salt water that covers most of the earth’s surface","cn":"大海；海洋","g":"[singular]","lab":"especially North American English","ex":{"en":"The ship was dredged from the depths of the ocean.","cn":"这艘船是从大洋深处打捞出来的。"}},{"en":"one of the five large areas that the ocean is divided into","cn":"（五大洋之一的）洋","g":"[countable]","lab":"British English","ex":{"en":"the Antarctic/Arctic/Atlantic/Indian/Pacific Ocean","cn":"南极海；北冰洋；大西洋；印度洋；太平洋"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"海洋；大海","en":"The ocean is the sea.","ex":{"en":"There were few sights as beautiful as the calm ocean on a warm night.","cn":"鲜有景致能与温暖夜色下风平浪静的大海媲美。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（五大洋之一的）洋","en":"An ocean is one of the five very large areas of sea on the Earth's surface.","ex":{"en":"They spent many days cruising the northern Pacific Ocean.","cn":"他们在北太平洋航行了很多天。"}},{"pos":"N-COUNT 可数名词","cn":"许多；大量","en":"If you say that there is an ocean of something, you are emphasizing that there is a very large amount of it.","ex":{"en":"I had cried oceans of tears","cn":"我泪流成河。"}},{"pos":"PHRASE 短语","cn":"沧海一粟;九牛一毛","en":"If you say that something is a drop in the ocean, you mean that it is a very small amount which is unimportant compared to the cost of other things or is so small that it has very little effect on something.","ex":{"en":"His fee is a drop in the ocean compared with the real cost of broadcasting.","cn":"同播出的实际开支相比较，他那点酬金不过是九牛一毛。"}}]},"examples":[{"en":"People were swimming in the ocean despite the hurricane warning.","cn":"尽管有飓风警报，人们仍然在大海里游泳。"},{"en":"The plane hit the ocean several miles offshore.","cn":"飞机在距离海岸数英里处坠入大海。"}]},"obtain":{"oxford":{"phon":"əbˈteɪn","pos":"verb","senses":[{"en":"to get something, especially by making an effort","cn":"（尤指经努力）获得，赢得","g":"[transitive]","ex":{"en":"to obtain information/data/results","cn":"获取信息／数据／结果"}},{"en":"to exist","cn":"存在；流行；沿袭","g":"[intransitive]","ex":{"en":"These conditions no longer obtain.","cn":"这些条件不再适用。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"得到；获得;实现","en":"To obtain something means to get it or achieve it.","ex":{"en":"Evans was trying to obtain a false passport and other documents","cn":"埃文斯正试图取得一本假护照和其他证件。"}},{"pos":"VERB 动词","cn":"存在；流行；通行","en":"If a situation obtains, it exists.","ex":{"en":"The longer this situation obtains, the more extensive the problems become.","cn":"这种局面持续的时间越长，问题波及的范围就越广。"}}]},"media":{"uk":"media/uk/obtain__gb_1.mp3","us":"media/us/obtain__us_1.mp3"},"examples":[{"en":"To obtain the overall score, add up the totals in each column.","cn":"要得出总计得分，就把各栏的小计加起来。"},{"en":"I finally managed to obtain a copy of the report.","cn":"我终于设法弄到了这份报告的一个副本。"}]},"offshoot":{"media":{"uk":"media/uk/offshoot__gb_1.mp3","us":"media/us/offshoot__us_1.mp3"},"oxford":{"phon":"ˈɒfʃuːt","pos":"noun","senses":[{"en":"a thing that develops from something, especially a small organization that develops from a larger one","cn":"分支；（尤指）分支机构","ex":{"en":"commercial offshoots of universities","cn":"大学附属的商业机构"}},{"en":"a new stem that grows on a plant","cn":"蘗枝；分枝","lab":"specialist"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分支；衍生物","en":"If one thing is an offshoot of another, it has developed from that other thing.","ex":{"en":"Psychology began as a purely academic offshoot of natural philosophy","cn":"心理学最初是自然哲学一个纯粹的学术分支。"}}]},"examples":[{"en":"The company was originally an offshoot of Bell Telephones.","cn":"该公司原本是贝尔电话公司的一家分支机构。"},{"en":"the Mafia and its offshoots","cn":"黑手党组织及其分支"}]},"operated":{"lemma":"operate"},"own":{"media":{"uk":"media/uk/own__gb_1.mp3","us":"media/us/own__us_1.mp3"},"oxford":{"phon":"əʊn","pos":"adjective, pronoun","senses":[{"en":"used to emphasize that something belongs to or is connected with somebody","cn":"（用于强调）自己的，本人的","ex":{"en":"It was her own idea.","cn":"那是她自己的主意。"}},{"en":"done or produced by and for yourself","cn":"自己做的；为自己的","ex":{"en":"She makes all her own clothes.","cn":"她的衣服都是自己做。"}},{"en":"to have something that belongs to you, especially because you have bought it","cn":"拥有，有（尤指买来的东西）","g":"[transitive]","ex":{"en":"Do you own your house or do you rent it?","cn":"你的房子是自己的，还是租的？"},"pos":"verb"},{"en":"to manage and take responsibility for something","cn":"承担；负责","g":"[transitive]","lab":"business","ex":{"en":"The successful candidate will be responsible for owning and achieving sales targets.","cn":"获聘者将负责承担并实现销售目标。"},"pos":"verb"},{"en":"to be completely successful, especially in a competition; to completely defeat somebody","cn":"拥有：要完全成功，尤其是在比赛中；完全击败某人自己的东西","g":"[transitive]","lab":"especially US English, informal，，","ex":{"en":"She owned the stage, performing a medley of hit songs.","cn":"她占据了舞台，表演了一系列热门歌曲。"},"pos":"verb"},{"en":"to admit that something is true","cn":"承认","g":"[intransitive, transitive]","lab":"old-fashioned","ex":{"en":"He owned to a feeling of guilt.","cn":"他承认有歉疚感。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自己的；属于自己的","en":"You use own to indicate that something belongs to a particular person or thing.","ex":{"en":"My wife decided I should have my own shop","cn":"我妻子决定让我自己开店。"}},{"pos":"ADJ 形容词","cn":"自己所用的；具有自己特点的；特有的","en":"You use own to indicate that something is used by, or is characteristic of, only one person, thing, or group.","ex":{"en":"Jennifer insisted on her own room","cn":"珍妮弗坚持要有自己的房间。"}},{"pos":"ADJ 形容词","cn":"自己做的；单独干的；独立完成的","en":"You use own to indicate that someone does something without any help from other people.","ex":{"en":"They enjoy making their own decisions","cn":"他们喜欢自己作决定。"}},{"pos":"VERB 动词","cn":"有；拥有","en":"If you own something, it is your property.","ex":{"en":"His father owns a local pub","cn":"他父亲在当地有一家酒馆。"}},{"pos":"PHRASE 短语","cn":"为自己所有","en":"If you have something you can call your own, it belongs only to you, rather than being controlled by or shared with someone else.","ex":{"en":"They don't yet have a country to call their own","cn":"他们还没有自己的国家。"}},{"pos":"PHRASE 短语","cn":"（因情况适宜而）开始取得成功，开始进入（良好）状态","en":"If someone or something comes into their own, they become very successful or start to perform very well because the circumstances are right.","ex":{"en":"The goalkeeper came into his own with a series of brilliant saves","cn":"守门员开始进入状态，作出了一连串精彩的扑救。"}},{"pos":"PHRASE 短语","cn":"报复","en":"If you get your own back on someone, you have your revenge on them because of something bad that they have done to you.","ex":{"en":"Renshaw reveals 20 bizarre ways in which women have got their own back on former loved ones.","cn":"伦肖揭示了20种女性用来报复旧情人的离奇手段。"}},{"pos":"PHRASE 短语","cn":"使只与自己相关；使为自己所有","en":"If you make something your own, you become involved in it in such a way that people think of it as being related only to you or belonging only to you, rather than to anyone else.","ex":{"en":"Here again is the song that Pavarotti has made his own.","cn":"下面再次为您播放这首帕瓦罗蒂的标志性歌曲。"}},{"pos":"PHRASE 短语","cn":"属于自己的；关于自己的","en":"If you say that someone has a particular thing of their own, you mean that that thing belongs or relates to them, rather than to other people.","ex":{"en":"You see, we have a problem of our own","cn":"你知道，我们也有自己的问题。"}},{"pos":"PHRASE 短语","cn":"特有的；独有的","en":"If someone or something has a particular quality or characteristic of their own, that quality or characteristic is especially theirs, rather than being shared by other things or people of that type.","ex":{"en":"Groups have a personality of their own","cn":"每支乐队都有自己独特的风格。"}},{"pos":"PHRASE 短语","cn":"单独地；独自地","en":"When you are on your own, you are alone.","ex":{"en":"He lives on his own","cn":"他独自一人生活。"}},{"pos":"PHRASE 短语","cn":"独立地；依靠自己地","en":"If you do something on your own, you do it without any help from other people.","ex":{"en":"I work best on my own.","cn":"我独立工作的时候效果最好。"}},{"pos":"PHRASE 短语","cn":"傲慢；目中无人；颐指气使","en":"If you say that someone does something as if they own the place or like they own the place, you are critical of them because they do it in a very arrogant way.","ex":{"en":"He struts around town like he owns the place.","cn":"他大摇大摆地在镇上四处晃悠，好像这是他的地盘。"}},{"pos":"","cn":"","en":"to hold your own→see: ;"},{"pos":"","cn":"","en":"相关词组：own up"}]},"examples":[{"en":"When the traffic's this bad, a bicycle really comes into its own.","cn":"在交通如此拥堵的时候，自行车就显出了它的价值。"},{"en":"Our children are grown up and have children of their own.","cn":"我们的子女都已长大成人，有了自己的孩子。"}]},"officer":{"media":{"uk":"media/uk/officer__gb_1.mp3","us":"media/us/officer__us_1.mp3"},"oxford":{"phon":"ˈɒfɪsə(r)","pos":"noun","senses":[{"en":"a person who is in a position of authority in the armed forces","cn":"军官","ex":{"en":"army/military/naval officers","cn":"陆军军官；军官；海军军官"}},{"en":"a member of the police","cn":"警察；警员","ex":{"en":"the officer in charge of the case","cn":"负责本案的警察"}},{"en":"a title for a police officer","cn":"警察的头衔","lab":"North American English","ex":{"en":"Officer Dibble","cn":"迪布尔警官"}},{"en":"a person who is in a position of authority in the government or a large organization","cn":"（政府或大机构的）官员，高级职员","ex":{"en":"an environmental health officer","cn":"环境卫生官员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"军官","en":"In the armed forces, an officer is a person in a position of authority.","ex":{"en":"...a retired British army officer","cn":"退役的英国陆军军官"}},{"pos":"N-COUNT 可数名词","cn":"（机构的）高级职员；（尤指政府机构的）官员，公务员","en":"An officer is a person who has a responsible position in an organization, especially a government organization.","ex":{"en":"...a local authority education officer.","cn":"当地政府的教育官员"}},{"pos":"N-COUNT 可数名词","cn":"警察；警官","en":"Members of the police force can be referred to as officers .","ex":{"en":"...senior officers in the West Midlands police force","cn":"西米德兰兹郡警队的高级警官"}}]},"examples":[{"en":"The matter was passed on to me, as your commanding officer.","cn":"作为你的指挥官，这件事转到了我这里。"},{"en":"Yes, officer, I saw what happened.","cn":"是，警察先生，我看到了发生的事。"}]},"optimum":{"oxford":{"phon":"ˈɒptɪməm","pos":"adjective","senses":[{"en":"the best possible; producing the best possible results","cn":"最佳的；最适宜的","ex":{"en":"the optimum use of resources","cn":"对资源的充分利用"}},{"en":"the best possible result, set of conditions, etc.","cn":"最佳结果；最好的条件","g":"[singular]","ex":{"en":"For efficient fuel consumption a speed of 60 mph is about the optimum.","cn":"时速60英里节油效果大致最佳。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最优的；最佳的；最适宜的","en":"The optimum or optimal level or state of something is the best level or state that it could achieve.","ex":{"en":"Aim to do some physical activity three times a week for optimum health.","cn":"为了达到最佳的健康状况，要力争每周进行3次身体锻炼。"}}]},"media":{"uk":"media/uk/optimum__gb_1.mp3","us":"media/us/optimum__us_1.mp3"},"examples":[{"en":"the optimum conditions for effective learning","cn":"保证学习效果的最佳条件"},{"en":"the optimum use of resources","cn":"对资源的充分利用"}]},"oversight":{"media":{"uk":"media/uk/oversight__gb_1.mp3","us":"media/us/oversight__us_1.mp3"},"oxford":{"phon":"ˈəʊvəsaɪt","pos":"noun","senses":[{"en":"the fact of making a mistake because you forget to do something or you do not notice something","cn":"疏忽；忽略；失察","g":"[countable, uncountable]","ex":{"en":"I didn't mean to leave her name off the list; it was an oversight.","cn":"我不是有意在名单上漏掉她的名字的，这是个疏忽。"}},{"en":"the state of being in charge of somebody/something","cn":"负责；照管","g":"[uncountable]","lab":"formal","ex":{"en":"The committee has oversight of finance and general policy.","cn":"该委员会负责处理财政和一般性政策。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"疏忽；忽略；失察","en":"If there has been an oversight, someone has forgotten to do something which they should have done.","ex":{"en":"William was angered and embarrassed by his oversight","cn":"威廉因为自己的疏忽而羞愤交加。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"照管；监督；负责","en":"If someone has oversight of a process or system, they are responsible for making sure that it works efficiently and correctly.","ex":{"en":"...a new system, where there'll be greater oversight of doctors","cn":"加强医生监管的新体制"}}]},"examples":[{"en":"I didn't mean to leave her name off the list; it was an oversight.","cn":"我不是有意在名单上漏掉她的名字的，这是个疏忽。"},{"en":"The committee has oversight of finance and general policy.","cn":"委员会负责处理财政和综合政策。"}]},"ornament":{"media":{"uk":"media/uk/ornament__gb_1.mp3","us":"media/us/ornament__us_1.mp3"},"oxford":{"phon":"ˈɔːnəmənt","pos":"noun","senses":[{"en":"an object that is used as decoration in a room, garden, etc. rather than for a particular purpose","cn":"装饰品","g":"[countable]","lab":"especially British English","ex":{"en":"a glass/silver ornament","cn":"玻璃/银饰品"}},{"en":"an object that is worn as jewellery","cn":"首饰；饰物","g":"[countable]","lab":"formal","ex":{"en":"Archaeologists have uncovered necklaces, pendants and other personal ornaments from the third century.","cn":"考古学家发现了3世纪的项链、垂饰和其他个人饰物。"}},{"en":"the use of objects, designs, etc. as decoration","cn":"装饰；摆设；点缀","g":"[uncountable]","lab":"formal","ex":{"en":"The clock is simply for ornament; it doesn't work any more.","cn":"这架时钟纯属摆设，它再也不走了。"}},{"en":"a person or thing whose good qualities improve something","cn":"为…增添光彩的人（或事物）","lab":"formal","ex":{"en":"The building is an ornament to the city.","cn":"这座建筑物为整个城市增色不少。"}},{"en":"features that are added when playing individual notes to make them more beautiful or interesting","cn":"装饰音","g":"[plural]","lab":"music","ex":{"en":"ornaments such as trills and mordents","cn":"颤音和摩登特等装饰音"}},{"en":"to add decoration to something","cn":"装饰；点缀；美化","ex":{"en":"a room richly ornamented with carving","cn":"雕饰得富丽堂皇的屋子"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（家中或花园里的）装饰物，装饰品，点缀品","en":"An ornament is an attractive object that you display in your home or in your garden.","ex":{"en":"...a shelf containing a few photographs and ornaments.","cn":"摆放着几张照片和些许装饰品的架子"}},{"pos":"N-COUNT 可数名词","cn":"首饰；饰物","en":"Pieces of jewellery are sometimes referred to as ornaments .","ex":{"en":"I guessed he was the chief because he wore more gold ornaments than the others.","cn":"我估计他是酋长，因为他戴的金饰最多。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（建筑或家具的）装饰物，装饰图案","en":"Decorations and patterns on a building or a piece of furniture can be referred to as ornament .","ex":{"en":"...walls of glass overlaid with ornament.","cn":"贴着装饰物的玻璃墙"}}]},"examples":[{"en":"The clock is simply for ornament; it doesn't work any more.","cn":"这架时钟纯属摆设，它再也不走了。"},{"en":"The building is an ornament to the city.","cn":"这座建筑物为整个城市增色不少。"}]},"offended":{"oxford":{"phon":"əˈfendɪd","pos":"adjective","senses":[{"en":"feeling upset because of something said or done that is rude or embarrassing","cn":"得罪；冒犯","ex":{"en":"Alice looked rather offended.","cn":"艾丽斯一副受到冒犯而不快的样子。"}}]},"media":{"uk":"media/uk/offended__gb_1.mp3","us":"media/us/offended__us_1.mp3"},"examples":[{"en":"Alice looked rather offended.","cn":"艾丽斯显得愤愤不已。"}],"base":"offend"},"ordering":{"media":{"uk":"media/uk/ordering__gb_1.mp3","us":"media/us/ordering__us_1.mp3"},"oxford":{"phon":"ˈɔːdərɪŋ","pos":"noun","senses":[{"en":"the way in which something is ordered or arranged; the act of putting something into an order","cn":"次序；组合；排列","ex":{"en":"Many possible orderings may exist.","cn":"组合方式可能有许多种。"}}]},"examples":[{"en":"Many possible orderings may exist.","cn":"组合方式可能有许多种。"},{"en":"the successful ordering of complex data","cn":"复杂数据的成功排列"}],"base":"order"},"oppose":{"media":{"uk":"media/uk/oppose__gb_1.mp3","us":"media/us/oppose__us_1.mp3"},"oxford":{"phon":"əˈpəʊz","pos":"verb","senses":[{"en":"to disagree strongly with somebody’s plan, policy, etc. and try to change it or prevent it from succeeding","cn":"反对（计划、政策等）；抵制；阻挠","ex":{"en":"This party would bitterly oppose the re-introduction of the death penalty.","cn":"该党会强烈反对恢复死刑。"}},{"en":"to compete with somebody in a contest","cn":"（在竞赛中）与…对垒，与…角逐","ex":{"en":"He intends to oppose the prime minister in the leadership election.","cn":"在领导层选举中，他欲与首相一决高下。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"反对；阻挠","en":"If you oppose someone or oppose their plans or ideas, you disagree with what they want to do and try to prevent them from doing it.","ex":{"en":"Mr Taylor was not bitter towards those who had opposed him","cn":"泰勒先生对那些曾反对过他的人并未怀恨在心。"}}]},"examples":[{"en":"He intends to oppose the prime minister in the leadership election.","cn":"在领导层选举中，他欲与首相一决高下。"},{"en":"He threw all those that opposed him into prison.","cn":"他把所有反对他的人都投进了监狱。"}]},"over-the-counter":{"oxford":{"phon":"ˌəʊvə ðə ˈkaʊntə(r)","pos":"adjective","senses":[{"en":"that can be obtained without a prescription (= a written order from a doctor)","cn":"无需处方可买到的；非处方的"},{"en":"not appearing in an official stock exchange list","cn":"场外交易的","lab":"business, North American English，，"}]},"media":{"uk":"media/uk/over_the_counter_1_gb_1.mp3","us":"media/us/over_the_counter_1_us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"omnipresent":{"media":{"uk":"media/uk/omnipresent__gb_1.mp3","us":"media/us/omnipresent__us_1.mp3"},"oxford":{"phon":"ˌɒmnɪˈpreznt","pos":"adjective","senses":[{"en":"present everywhere","cn":"无所不在的；遍及各处的","ex":{"en":"These days the media are omnipresent.","cn":"现在新闻媒体无处不在。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无所不在的；普遍存在的","en":"Something that is omnipresent is present everywhere or seems to be always present.","ex":{"en":"The sound of sirens was an omnipresent background noise in New York","cn":"在纽约，警报声是无处不在的背景噪音。"}}]},"examples":[{"en":"These days the media are omnipresent.","cn":"现在新闻媒体无处不在。"}]},"one":{"media":{"uk":"media/uk/one__gb_1.mp3","us":"media/us/one__us_1.mp3"},"oxford":{"phon":"wʌn","pos":"number, determiner","senses":[{"en":"the number 1","cn":"一","ex":{"en":"Do you want one or two?","cn":"你要一个还是两个？"}},{"en":"used in formal language or for emphasis before hundred, thousand, etc., or before a unit of measurement","cn":"（正式用语或表示强调，用在 hundred、thousand 等或度量单位之前）一","ex":{"en":"It cost one hundred and fifty pounds.","cn":"那东西花了一百五十英镑。"}},{"en":"used for emphasis to mean ‘a single’ or ‘just one’","cn":"（表示强调）单独一个，仅仅一个","ex":{"en":"There's only one thing we can do.","cn":"我们能做的只有一件事。"}},{"en":"a person or thing, especially when they are part of a group","cn":"（尤指一组中的）一个人，一件事物","ex":{"en":"One of my friends lives in Brighton.","cn":"我有一个朋友住在布赖顿。"}},{"en":"used for emphasis to mean ‘the only one’ or ‘the most important one’","cn":"（表示强调）唯一的一个，最重要的一个","ex":{"en":"He's the one person I can trust.","cn":"他是我唯一可以信赖的人。"}},{"en":"used when you are talking about a time in the past or the future, without actually saying which one","cn":"（用于一般地谈论过去或将来的某个时间）","ex":{"en":"I saw her one afternoon last week.","cn":"我在上周的一个下午见到了她。"}},{"en":"the same","cn":"同一个","ex":{"en":"They all went off in one direction.","cn":"他们都朝同一个方向走了。"}},{"en":"used for emphasis instead of a or an","cn":"（代替 a 或 an，表示强调）","lab":"informal, especially North American English，，","ex":{"en":"That was one hell of a game!","cn":"那一场比赛简直不得了！"}},{"en":"used with a person’s name to show that the speaker does not know the person","cn":"（与人名连用，表示说话人不认识的人）某一个","lab":"formal or old-fashioned","ex":{"en":"He worked as an assistant to one Mr Ming.","cn":"他给一位明先生当助手。"}},{"en":"used to avoid repeating a noun, when you are referring to somebody/something that has already been mentioned, or that the person you are speaking to knows about","cn":"（用来避免重复已提过的或是听者已知的事物的名称）","lab":"British English","ex":{"en":"I'd like an ice cream. Are you having one, too?","cn":"我想买份冰激凌，你也要一份吗？"},"pos":"pronoun"},{"en":"used when you are identifying the person or thing you are talking about","cn":"（用于辨别所谈的人或事）","ex":{"en":"Our house is the one next to the school.","cn":"我家的房子就是学校旁边的那座。"},"pos":"pronoun"},{"en":"a person or thing belonging to a particular group","cn":"其中的一个人（或事物）","ex":{"en":"It's a present for one of my children.","cn":"这是送给我的一个孩子的礼物。"},"pos":"pronoun"},{"en":"a person of the type mentioned","cn":"（某种类型的）人","ex":{"en":"10 o’clock is too late for the little ones.","cn":"十点钟对那些小家伙来说就太晚了。"},"pos":"pronoun"},{"en":"used to mean ‘people in general’ or ‘I’, when the speaker is referring to himself or herself","cn":"人们；本人","lab":"formal","ex":{"en":"One should never criticize if one is not sure of one's facts.","cn":"一个人如果对自己掌握的事实没有把握，就绝不该随便批评。"},"pos":"pronoun"},{"en":"a person whose behaviour is funny or surprising","cn":"（举止）滑稽可笑的人，令人惊奇的人","lab":"old-fashioned, especially British English，，","ex":{"en":"Oh, you are a one!","cn":"哈！你这个活宝！"},"pos":"pronoun"},{"en":"the joke","cn":"玩笑；笑话","ex":{"en":"Have you heard the one about the Englishman, the Irishman and the Scotsman?","cn":"你听没听过那个关于英格兰人、爱尔兰人和苏格兰人的笑话？"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"（数字）1","en":"One is the number 1.","ex":{"en":"They had three sons and one daughter.","cn":"他们有3个儿子，1个女儿。"}},{"pos":"ADJ 形容词","cn":"唯一的；仅有的","en":"If you say that someone or something is the one person or thing of a particular kind, you are emphasizing that they are the only person or thing of that kind.","ex":{"en":"They had alienated the one man who knew the business","cn":"他们弄僵了同那个唯一懂行的人之间的关系。"}},{"pos":"DET 限定词","cn":"（用于代替a以强调之后的名词）","en":"One can be used instead of 'a' to emphasize the following noun.","ex":{"en":"There is one thing I would like to know—What is it about Tim that you find so irresistible?","cn":"有一件事我很想知道——蒂姆到底哪一点让你对他如此倾心？"}},{"pos":"DET 限定词","cn":"（用于代替a以强调之后的形容词或短语）","en":"You can use one instead of 'a' to emphasize the following adjective or expression.","ex":{"en":"If we ever get married we'll have one terrific wedding","cn":"如果我们哪一天结婚的话，一定会有一个棒极了的婚礼。"}},{"pos":"DET 限定词","cn":"（用于人名前，表示未曾相识或听闻的）某一个","en":"You can use one in front of someone's name to indicate that you have not met them or heard of them before.","ex":{"en":"It seems that the fifth man is one John Cairncross.","cn":"第五位好像是一个名叫约翰·凯恩克罗斯的人。"}},{"pos":"DET 限定词","cn":"（表示与其他的作比较）这一个","en":"You can use one to refer to the first of two or more things that you are comparing.","ex":{"en":"Prices vary from one shop to another","cn":"各家商店价格不同。"}},{"pos":"PRON 代词","cn":"（用于代替名词，指代某类明确的人或事物）","en":"You can use one or ones instead of a noun when it is clear what type of thing or person you are referring to and you are describing them or giving more information about them.","ex":{"en":"They are selling their house to move to a smaller one","cn":"他们正打算卖掉房子，然后搬到一个小一点的住处。"}},{"pos":"PRON 代词","cn":"（泛指）人们","en":"You use ones to refer to people in general.","ex":{"en":"We are the only ones who know.","cn":"我们是唯一的知情者。"}},{"pos":"PRON 代词","cn":"（用于代替名词词组，表示刚提到过的事物）","en":"You can use one instead of a noun group when you have just mentioned something and you want to describe it or give more information about it.","ex":{"en":"His response is one of anger and frustration","cn":"他的回答充满了愤怒和懊丧。"}},{"pos":"DET 限定词","cn":"（特指一群人或事物中的）一人，一个","en":"You can use one when you have been talking or writing about a group of people or things and you want to say something about a particular member of the group.","ex":{"en":"'A college degree isn't enough', said one honors student.","cn":"“光有一个大学学位还不够，”一位优等生说。"}},{"pos":"QUANT 数量词","cn":"（同类事物或人中）（最…之）一","en":"You use one in expressions such as 'one of the biggest airports' or 'one of the most experienced players' to indicate that something or someone is bigger or more experienced than most other things or people of the same kind.","ex":{"en":"Subaru is one of the smallest Japanese car makers.","cn":"斯巴鲁是日本最小的汽车制造商之一。"}},{"pos":"DET 限定词","cn":"（过去或将来的）某一（时刻）","en":"You can use one when referring to a time in the past or in the future. For example, if you say that you did something one day, you mean that you did it on a day in the past. one day→see: ;","ex":{"en":"How would you like to have dinner one night, just you and me?","cn":"哪天晚上一起吃饭怎么样？就咱俩。"}},{"pos":"PRON 代词","cn":"（指代问题、笑话、评论、讨论的主题等）一个","en":"You can use one to refer to a question, joke, remark, or subject of discussion.","ex":{"en":"This is a tricky one to answer","cn":"这是个难以回答的问题。"}},{"pos":"PRON 代词","cn":"(一杯)酒","en":"You can use one to refer to an alcoholic drink.","ex":{"en":"Other members of the committee drifted in for a quick one before closing time.","cn":"委员会的其他成员陆续走了进来，想要趁关门前喝上一杯。"}},{"pos":"PRON 代词","cn":"（泛指包括自己的人，可作句子的主语或宾语）一个人，任何人","en":"You use one to make statements about people in general which also apply to themselves. One can be used as the subject or object of a sentence.","ex":{"en":"If one looks at the longer run, a lot of positive things are happening","cn":"如果把目光放长远些，就会发现很多积极的事情正在发生。"}},{"pos":"PHRASE 短语","cn":"一起；一致地","en":"If a group of people does something as one, all the people do the same thing at the same time or in the same way.","ex":{"en":"The 40,000 crowd rose as one.","cn":"40,000人全体起立。"}},{"pos":"PHRASE 短语","cn":"喜欢（或赞成、乐于）…的人","en":"If you say that someone is one for or is a one for something, you mean that they like or approve of it or enjoy doing it.","ex":{"en":"I'm not one for political discussions","cn":"我不是个热衷于谈论政治的人。"}},{"pos":"PHRASE 短语","cn":"（强调某人与众不同的反应或行为方式）举个例说","en":"You can use for one to emphasize that a particular person is definitely reacting or behaving in a particular way, even if other people are not.","ex":{"en":"I, for one, hope you don't get the job.","cn":"就我而言，我并不希望你得到那份工作。"}},{"pos":"PHRASE 短语","cn":"（表示强调）很多","en":"You can use expressions such as a hundred and one ,a thousand and one, and a million and one to emphasize that you are talking about a large number of things or people.","ex":{"en":"There are a hundred and one ways in which you can raise money.","cn":"筹钱的办法有很多。"}},{"pos":"PHRASE 短语","cn":"集（若干部分或功能）为一体","en":"You can use in one to indicate that something is a single unit, but is made up of several different parts or has several different functions.","ex":{"en":"...a love story and an adventure all in one","cn":"集爱情和冒险于一体的故事"}},{"pos":"PHRASE 短语","cn":"三三两两地；零零落落地","en":"You can use in ones and twos to indicate that people do things or something happens gradually and in small groups.","ex":{"en":"They lose interest and start drifting away in ones and twos.","cn":"他们没了兴趣，开始三三两两地走开了。"}},{"pos":"PHRASE 短语","cn":"一个接一个地；接连地；陆续地","en":"You use one after the other or one after another to say that actions or events happen with very little time between them.","ex":{"en":"My three guitars broke one after the other","cn":"我的3把吉他陆续都坏了。"}},{"pos":"PHRASE 短语","cn":"（用于节目中介绍演员、歌手或其他名人）绝无仅有的，独一无二的","en":"The one and only can be used in front of the name of an actor, singer, or other famous person when they are being introduced on a show.","ex":{"en":"...one of the greatest ever rock performers, the one and only Tina Turner.","cn":"史上最伟大的摇滚乐手之一，举世无双的蒂娜·特纳"}},{"pos":"PHRASE 短语","cn":"逐个地；依次地","en":"You can use one by one to indicate that people do things or that things happen in sequence, not all at the same time.","ex":{"en":"We went into the room one by one","cn":"我们挨个儿走进房间。"}},{"pos":"PHRASE 短语","cn":"（一组事物或人之中的）或者这个或者那个，有一个","en":"You use one or other to refer to one or more things or people in a group, when it does not matter which particular one or ones are thought of or chosen.","ex":{"en":"One or other of the two women was wrong.","cn":"这两个女人当中有一个人错了。"}},{"pos":"PHRASE 短语","cn":"一两个；几个","en":"One or two means a few.","ex":{"en":"We may make one or two changes","cn":"我们可以作一两处改动。"}},{"pos":"PHRASE 短语","cn":"不大可能（做…)的人","en":"If you say that someone is not one to do something, you think that it is very unlikely that they would do it because it is not their normal behaviour.","ex":{"en":"I'm not one to waste time on just anyone.","cn":"我可不是个随便浪费时间在任何人身上的人。"}},{"pos":"PHRASE 短语","cn":"略胜…一筹；占…的上风","en":"If you try to get one up on someone, you try to gain an advantage over them.","ex":{"en":"...the competitive kind who will see this as the opportunity to be one up on you.","cn":"具有竞争意识、将此视作占据上风的契机的那种人"}},{"pos":"","cn":"","en":"one and all→see: ; one another→see: ; one thing after another→see: ; to pull a fast one→see: ; of one mind→see: ; in one piece→see: ; put one over on→see: ;"}]},"examples":[{"en":"The Scottish legal system is not the same as the English system, is better than … as the English one.","cn":"用 The Scottish legal system is not the same as the English system（苏格兰法制与英格兰法制不同）胜于用 ... as the English one。"},{"en":"It's a public relations office, a press office and a private office all in one.","cn":"那儿既是公关办公室，也是新闻办公室，又是私人办公室：三位一体。"}]},"organizations":{"lemma":"organization"},"obsessed":{"oxford":{"phon":"əbˈses","pos":"verb","senses":[{"en":"to completely fill your mind so that you cannot think of anything else, in a way that is not normal","cn":"使痴迷；使迷恋；使着迷"},{"en":"to be always talking or worrying about a particular thing, especially when this annoys other people","cn":"唠叨；挂牵；念念不忘"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对…）着迷的;（受…）困扰的；（为…）心神不宁的","en":"If someone is obsessed with a person or thing, they keep thinking about them and find it difficult to think about anything else.","ex":{"en":"He was obsessed with American gangster movies","cn":"他迷上了美国黑帮片。"}}]}},"oboes":{"lemma":"oboe"},"outperformed":{"oxford":{"phon":"ˌaʊtpəˈfɔːm","pos":"verb","senses":[{"en":"to achieve better results than sb/sth （","cn":"效益上）超过，胜过"}]}},"offices":{"lemma":"office"},"observations":{"lemma":"observation"},"officials":{"lemma":"official"},"observing":{"lemma":"observe"},"obeyed":{"lemma":"obey"},"oceans":{"lemma":"ocean"},"occupations":{"lemma":"occupation"},"owned":{"lemma":"own"},"options":{"lemma":"option"},"opens":{"lemma":"open"},"organisation":{"lemma":"organization"},"owners":{"lemma":"owner"},"operas":{"lemma":"opera"},"orchards":{"oxford":{"phon":"ˈɔːtʃəd","pos":"noun","senses":[{"en":"a piece of land, normally separated from the surrounding area, in which fruit trees are grown","cn":"果园"}]}},"operations":{"lemma":"operation"},"offers":{"lemma":"offer"},"opened":{"lemma":"open"},"outhouses":{"oxford":{"phon":"ˈaʊthaʊs","pos":"noun","senses":[{"en":"( BrE ) a small building, such as a shed , outside a main building （","cn":"主建筑的）外围建筑，附属建筑"},{"en":"( especially NAmE ) a toilet in a small building of its own","cn":"屋外厕所"}]}},"overseen":{"lemma":"oversee"},"overalls":{"lemma":"overall","media":{"img":["media/thumb/overalls.jpg"]}},"overlapping":{"lemma":"overlap"},"occurs":{"lemma":"occur"},"outpaced":{"oxford":{"phon":"ˌaʊtˈpeɪs","pos":"verb","senses":[{"en":"to go, rise, improve, etc. faster than sb/sth （","cn":"在速度上）超过；比 … 快"}]}},"objectives":{"lemma":"objective"},"opposites":{"lemma":"opposite"},"objects":{"lemma":"object"},"obscured":{"lemma":"obscure"},"outfitters":{"lemma":"outfitter"},"organisations":{"lemma":"organization"},"occasions":{"lemma":"occasion"},"ought":{"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事道义上正确，尤用于提出或征求建议或意见）应当，应该","en":"You use ought to to mean that it is morally right to do a particular thing or that it is morally right for a particular situation to exist, especially when giving or asking for advice or opinions.","ex":{"en":"Mark, you've got a good wife. You ought to take care of her","cn":"马克，你娶了个好妻子，应该好好待她。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事可行或重要，尤用于提出或征求建议或意见）应当，应该","en":"You use ought to when saying that you think it is a good idea and important for you or someone else to do a particular thing, especially when giving or asking for advice or opinions.","ex":{"en":"You don't have to be alone with him and I don't think you ought to be","cn":"你不必单独跟他呆在一起，而且我认为你也不该这样。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事确实，或预计某事发生或已经发生）应该/应该已经","en":"You use ought to to indicate that you expect something to be true or to happen. You use ought to have to indicate that you expect something to have happened already.","ex":{"en":"'This ought to be fun,' he told Alex, eyes gleaming.","cn":"“这应该会很有趣！”他对亚历克斯说，两眼闪闪发光。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（表示某事本应如此，但实际情况未必）应该","en":"You use ought to to indicate that you think that something should be the case, but might not be.","ex":{"en":"By rights the Social Democrats ought to be the favourites in the election. But nothing looks less certain","cn":"社会民主党按理应该最有希望赢得这次选举，但一切从未如此不确定过。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（表示从已知情况推测某事已经发生，但不确定）应该","en":"You use ought to to indicate that you think that something has happened because of what you know about the situation, but you are not certain.","ex":{"en":"He ought to have reached the house some time ago.","cn":"他应该早就到房子那儿了。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（与过去分词连用，表示预期的事未发生或预计的情况并非如此）本该，本当","en":"You use ought to have with a past participle to indicate that something was expected to happen or be the case, but it did not happen or was not the case.","ex":{"en":"Basically the system ought to have worked","cn":"其实这套系统本应发挥作用的。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（与过去分词连用，表示未做本应该做的事情）本该，本当","en":"You use ought to have with a past participle to indicate that although it was best or correct for someone to do something in the past, they did not actually do it.","ex":{"en":"I realize I ought to have told you about it","cn":"我意识到自己本该把这件事告诉你的。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（礼貌地告知某人自己必须做某事）该，得","en":"You use ought to when politely telling someone that you must do something, for example that you must leave.","ex":{"en":"I really ought to be getting back now","cn":"现在我真得回去了。"}}]}},"oppressors":{"oxford":{"phon":"əˈpresə(r)","pos":"noun","senses":[{"en":"a person or group of people that treats sb in a cruel and unfair way, especially by not giving them the same rights, etc. as other people","cn":"压迫者；残暴的统治者；暴君"}]}},"oldest":{"lemma":"old"},"offsetting":{"lemma":"offset"},"observed":{"lemma":"observe"},"ones":{"lemma":"one"},"oxidized":{"oxford":{"phon":"ˈɒksɪdaɪz","pos":"verb","senses":[{"en":"( chemistry","cn":"化 ) to remove one or more electrons from a substance, or to combine or to make sth combine with oxygen , especially when"}]}},"opted":{"oxford":{"phon":"ɒpt","pos":"verb","senses":[{"en":"to choose to take or not to take a particular course of action","cn":"选择；挑选"},{"en":"to choose to be part of a system or an agreement","cn":"决定加入；选择参与"}]}},"okay":{"oxford":{"phon":"əʊˈkeɪ","pos":"exclamation","senses":[{"en":"yes; all right","cn":"对；好；行"},{"en":"used to attract sb's attention or to introduce a comment （","cn":"用以引起注意或引入话题）好了，对了"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（表示令人满意或可以接受）不错的，可以的","en":"If you say that something is okay, you find it satisfactory or acceptable.","ex":{"en":"...a shooting range where it's OK to use weapons","cn":"可以使用武器的射击场"}},{"pos":"ADJ 形容词","cn":"（人）安全的，健康的，无恙的","en":"If you say that someone is okay, you mean that they are safe and well.","ex":{"en":"Check that the baby's okay","cn":"看看孩子是否还好。"}},{"pos":"CONVENTION 惯用语","cn":"（表示同意）好的","en":"You can say 'Okay' to show that you agree to something.","ex":{"en":"'Just tell him Sir Kenneth would like to talk to him.' — 'OK.'","cn":"“就跟他说肯尼思爵士想跟他谈谈。”——“好的。”"}},{"pos":"CONVENTION 惯用语","cn":"（询问对方是否领会或同意）好吗，行吗，明白吗","en":"You can say 'Okay?' to check whether the person you are talking to understands what you have said and accepts it.","ex":{"en":"Add them together, divide by five, and you've got the average. Okay?","cn":"把它们相加再除以5就是平均数，明白吗？"}},{"pos":"CONVENTION 惯用语","cn":"（表示希望转换话题或做别的事情）好了","en":"You can use okay to indicate that you want to start talking about something else or doing something else.","ex":{"en":"OK. Now, let's talk some business","cn":"好了，我们现在言归正传吧。"}},{"pos":"CONVENTION 惯用语","cn":"（不情愿地表示接受对方观点以制止其争辩）得了，行了","en":"You can use okay to stop someone arguing with you by showing that you accept the point they are making, though you do not necessarily regard it as very important.","ex":{"en":"Okay, there is a slight difference","cn":"行了，是略有不同。"}},{"pos":"VERB 动词","cn":"批准；同意；允许","en":"If someone in authority okays something, they officially agree to it or allow it to happen.","ex":{"en":"His doctor wouldn't OK the trip","cn":"医生不会同意他去旅行。"}}]}},"officers":{"lemma":"officer"},"operators":{"lemma":"operator"},"others":{"lemma":"other"},"outcomes":{"lemma":"outcome"},"opinions":{"lemma":"opinion"},"outsized":{"oxford":{"phon":"ˈaʊtsaɪz","pos":"adj.","senses":[{"en":"larger than the usual size","cn":"较大的；超过一般型号的"},{"en":"designed for large people","cn":"特体的；特大号的"}]}},"origins":{"lemma":"origin"},"opportunities":{"lemma":"opportunity"},"offered":{"lemma":"offer"},"ornamented":{"lemma":"ornament"},"obstructs":{"lemma":"obstruct"},"occurred":{"lemma":"occur"},"overvalues":{"oxford":{"phon":"ˌəʊvəˈvæljuː","pos":"verb","senses":[{"en":"to put too high a value on sth","cn":"估计过高；过于重视"}]}},"overlooking":{"lemma":"overlook"},"older":{"lemma":"old"},"observers":{"lemma":"observer"},"obscuring":{"lemma":"obscure"},"otters":{"oxford":{"phon":"ˈɒtə(r)","pos":"noun","senses":[{"en":"a small animal that has four webbed feet (= with skin between the toes), a tail and thick brown fur. Otters live in rivers and eat fish.","cn":"水獭"}]}},"outnumbered":{"lemma":"outnumber"},"outlet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经销店；专营店","en":"An outlet is a shop or organization which sells the goods made by a particular manufacturer.","ex":{"en":"...the largest retail outlet in the city.","cn":"该市最大的零售商店"}},{"pos":"N-COUNT 可数名词","cn":"廉价商品经销店；折扣店","en":"An outlet or an outlet store is a place which sells slightly damaged or outdated goods from a particular manufacturer, or goods that it made in greater quantities than needed.","ex":{"en":"...the factory outlet store in Belmont.","cn":"位于贝尔蒙特的厂家直销型折扣店"}},{"pos":"N-COUNT 可数名词","cn":"（情感的）发泄途径；（思想的）表达方式","en":"If someone has an outlet for their feelings or ideas, they have a means of expressing and releasing them.","ex":{"en":"Her father had found an outlet for his ambition in his work.","cn":"她父亲在工作中找到了施展抱负的机会。"}},{"pos":"N-COUNT 可数名词","cn":"出口；排放管","en":"An outlet is a hole or pipe through which liquid or air can flow away.","ex":{"en":"...a warm air outlet.","cn":"热气出口"}},{"pos":"N-COUNT 可数名词","cn":"（通常指墙上的）电源插座","en":"An outlet is a place, usually in a wall, where you can connect electrical devices to the electricity supply."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building or place where things are sold","cn":""},{"en":"a small shop that sells fashionable clothes or other objects","cn":""},{"en":"a very large shop, especially one that is built outside the centre of a city","cn":""}]},"collocations":{"phrases":["ADJ. specialist | high-street, local | commercial, distribution, retail, sales | DIY, fast-food, etc.","PREP. ~ for a retail outlet for exotic plants 2 means of releasing energy/strong feeling/talents","ADJ. emotional | creative","VERB + OUTLET have | find | provide (sb with) Sport provided an outlet for his energy. | need","PREP. ~ for She needs an outlet for her talents. 3 pipe/hole","ADJ. electrical, gas, sewage, socket, waste, water","OUTLET + NOUN hose, pipe"]},"media":{"uk":"media/ldoce/hwd/bre/c/outlet0205.mp3","us":"media/ldoce/hwd/ame/4/outlet.mp3"},"examples":[{"en":"She needed to find an outlet for her many talents and interests.","cn":"她多才多艺、兴趣广泛，需要找个施展的机会。"},{"en":"The business has 34 retail outlets in this state alone.","cn":"那家商号仅在本州就有 34 个零售店。"}],"oxford":{"phon":"ˈaʊtlet","pos":"noun","senses":[{"en":"a shop or an organization that sells goods made by a particular company or of a particular type","cn":"专营店；经销店","ex":{"en":"The business has 34 retail outlets in this state alone.","cn":"那家商号仅在本州就有 34 个零售店。"}},{"en":"a shop that sells goods of a particular make at reduced prices","cn":"（某品牌的）折扣店","ex":{"en":"the Nike outlet in the outlet mall","cn":"折扣品商场里的耐克折扣店"}},{"en":"a way of expressing or making good use of strong feelings, ideas or energy","cn":"（感情、思想、精力发泄的）出路；表现机会","ex":{"en":"She needed to find an outlet for her many talents and interests.","cn":"她多才多艺、兴趣广泛，需要找个施展的机会。"}},{"en":"a pipe or hole through which liquid or gas can flow out","cn":"出口；排放管","ex":{"en":"a sewage outlet","cn":"污水排放口"}},{"en":"a device in a wall that you put a plug (= a small plastic object with two or three metal pins) into in order to connect electrical equipment to the power supply of a building","cn":"（电源）插座","lab":"both North American English","ex":{"en":"The appliance can be connected to any standard outlet.","cn":"这件电器可以连接到任一标准电源插口。"}}]}},"overweight":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"太胖的；超重的","en":"Someone who is overweight weighs more than is considered healthy or attractive. →see usage note at:","ex":{"en":"Being even moderately overweight increases your risk of developing high blood pressure.","cn":"即使是轻度超重也会增加患高血压的风险。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having too much flesh on your body. It is rude to tell someone that they are fat. It is also better not to use any of these words when talking directly to someone about their body","cn":""},{"en":"weighing more than you should","cn":""},{"en":"used when saying that someone has a big body. Large is more common than big in written English","cn":""}]},"collocations":{"phrases":["VERBS be, look You don't look overweight. | become, get Don't let yourself get overweight.","ADV. extremely, grossly, heavily, seriously, very | a bit, a little, rather, slightly","PHRASES a few pounds, two stone, etc. overweight"]},"media":{"uk":"media/ldoce/hwd/bre/8/overweight0205.mp3","us":"media/ldoce/hwd/ame/5/overweight.mp3"},"examples":[{"en":"She was only a few pounds overweight.","cn":"她只是超重几磅而已。"},{"en":"overweight baggage","cn":"超重的行李"}],"oxford":{"phon":"ˌəʊvəˈweɪt","pos":"adjective","senses":[{"en":"too heavy, in a way that may be unhealthy","cn":"超重的；过重的","lab":"British English","ex":{"en":"She was only a few pounds overweight.","cn":"她只是超重几磅而已。"}},{"en":"above an allowed weight","cn":"超过限制重量的；过重的","ex":{"en":"overweight baggage","cn":"超重的行李"}}]}},"operator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电话接线员","en":"An operator is a person who connects telephone calls at a telephone exchange or in a place such as an office or hotel.","ex":{"en":"He dialled the operator and put in a call for Rome.","cn":"他拨了接线员的号，让他接通一个到罗马的电话。"}},{"pos":"N-COUNT 可数名词","cn":"（机器）操作员，技工","en":"An operator is a person who is employed to operate or control a machine.","ex":{"en":"...computer operators.","cn":"计算机操作员"}},{"pos":"N-COUNT 可数名词","cn":"（企业的）经营者；运营公司","en":"An operator is a person or a company that runs a business.","ex":{"en":"...'Tele-Communications', the nation's largest cable TV operator.","cn":"全国最大的有线电视运营商“电视通信公司”"}},{"pos":"N-COUNT 可数名词","cn":"精明圆滑的人；善于取巧的人","en":"If you call someone a good operator, you mean that they are skilful at achieving what they want, often in a slightly dishonest way.","ex":{"en":"He was a smart operator. Don't underestimate him.","cn":"他这个人精明圆滑，可别小瞧了他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works on a telephone switchboard , who you can call for help","cn":"电话接线员"},{"en":"someone who operates a machine or piece of equipment 〔","cn":"机器或设备的〕操作者﹐操作员"},{"en":"a person or company that operates a particular business","cn":"经营者﹔公司"}]},"collocations":{"phrases":["ADJ. switchboard, telephone","OPERATOR + VERB connect sb, put sb through I asked the operator to put me through to her office. 2 person who works a machine, etc.","ADJ. experienced, skilled | unskilled | machine, plant | computer, lathe, radio, word processor, etc. 3 person/company that does particular ","ADJ. big, small | private | holiday, tour, travel | cable (television), satellite, telecommunications, etc. | airline, bus, coach, ferry 4 s","ADJ. shrewd, slick, smooth"]},"media":{"uk":"media/ldoce/hwd/bre/5/operator0205.mp3","us":"media/ldoce/hwd/ame/e/operator.mp3"},"examples":[{"en":"a smooth/slick/shrewd operator","cn":"一个八面玲珑/油嘴滑舌/工于心计的取巧者"},{"en":"a computer/machine operator","cn":"电脑/机器操作员"}],"oxford":{"phon":"ˈɒpəreɪtə(r)","pos":"noun","senses":[{"en":"a person who operates equipment or a machine","cn":"操作人员；技工","ex":{"en":"a computer/machine operator","cn":"电脑／机器操作员"}},{"en":"a person or company that runs a particular business","cn":"（某企业的）经营者，专业公司","ex":{"en":"a tour operator","cn":"经营旅游业者"}},{"en":"a person who works on the phone switchboard of a large company or organization, especially at a telephone exchange","cn":"电话员；接线员","lab":"British English, old-fashioned，，","ex":{"en":"Dial 100 and ask for the operator.","cn":"拨 100 找接线员。"}},{"en":"a person who shows skill at getting what they want, especially when this involves behaving in a dishonest way","cn":"投机取巧者；善于钻营的人；骗子","lab":"informal, especially disapproving，，","ex":{"en":"a smooth/slick/shrewd operator","cn":"一个八面玲珑／油嘴滑舌／工于心计的取巧者"}},{"en":"a symbol or function which represents an operation in mathematics","cn":"算子","lab":"mathematics"}]}},"outsider":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某个团体或组织）外部的人","en":"An outsider is someone who does not belong to a particular group or organization.","ex":{"en":"The most likely outcome may be to subcontract much of the work to an outsider.","cn":"最可能的结果是将大量的工作分包出去。"}},{"pos":"N-COUNT 可数名词","cn":"（不为某一团体所接受或感觉不属其中的）外人","en":"An outsider is someone who is not accepted by a particular group, or who feels that they do not belong in it.","ex":{"en":"Malone, a cop, felt as much an outsider as any of them.","cn":"马隆是个警察，他跟他们一样都觉得自己像个外人。"}},{"pos":"N-COUNT 可数名词","cn":"（在竞赛中）不大可能获胜的人（或队伍）","en":"In a competition, an outsider is a competitor who is unlikely to win.","ex":{"en":"He was an outsider in the race to be the new UN Secretary-General.","cn":"在新一任联合国秘书长的角逐中，他的胜算很小。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be in a position where you are likely to lose a game, competition, election or war because you are not doing as well as your opponent","cn":""},{"en":"to be losing a game, competition, or election","cn":""},{"en":"to be losing a game or competition, or election - used especially in news reports","cn":""}]},"collocations":{"phrases":["ADJ. complete | political, social","VERB + OUTSIDER feel I felt a complete outsider.","PREP. ~ to an outsider to the group 2 competitor who will probably not win","ADJ. complete, rank","PREP. ~ in The firm has gone from being an outsider in the market to being a market leader."]},"media":{"uk":"media/ldoce/hwd/bre/0/outsider0205.mp3","us":"media/ldoce/hwd/ame/c/outsider.mp3"},"examples":[{"en":"To everyone's surprise, the post went to a rank outsider (= a complete outsider ).","cn":"出人意料的是，那个职位竟然落到一个毫不起眼的人头上。"},{"en":"The race was won by a 20–1 outsider.","cn":"比赛获胜者是个不被看好、20 赔 1 的赛马。"}],"oxford":{"phon":"ˌaʊtˈsaɪdə(r)","pos":"noun","senses":[{"en":"a person who is not accepted as a member of a society, group, etc.","cn":"外人；局外人","ex":{"en":"Here she felt she would always be an outsider.","cn":"她在这里总觉得是个外人。"}},{"en":"a person who is not part of a particular organization or profession","cn":"（组织、行业）外部的人；外来者","ex":{"en":"They have decided to hire outsiders for some of the key positions.","cn":"他们决定在某些关键职位上聘任外来人员。"}},{"en":"a person or an animal taking part in a race or competition that is not expected to win","cn":"（比赛中）不被看好的人（或动物）","ex":{"en":"The race was won by a rank outsider (= a complete outsider).","cn":"跑步比赛由一名大冷门选手获胜。"}}]}},"ohio":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the midwest of the US, known especially for its engineering, coal mining, and farming. Its largest city is Cleveland.","cn":""},{"en":"a long river in the central US, which used to carry a lot of industrial goods","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000009144.mp3","us":"media/ldoce/hwd/ame/8/p028-000009144.mp3"},"oxford":{"phon":"əʊˈhaɪəʊ","pos":"","senses":[{"en":"a north-eastern US state, also called the Buckeye State (and its people Buckeyes). The capital and largest city is Columbus. It is mainly an industrial state and produces steel, motor vehicles and parts, especially in Cleveland, as well as jet engines, tools and rubber products. Agricultural products include soya beans, corn, milk and grapes. Both the Rock and Roll Hall of Fame and Pro Football Hall of Fame are in Ohio.","cn":"俄亥俄（美国东北部的州，首府和最大城市哥伦布）"}]}},"overturn":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）翻转；（使）倾覆；（使）倒下","en":"If something overturns or if you overturn it, it turns upside down or on its side.","ex":{"en":"The lorry veered out of control, overturned and smashed into a wall","cn":"卡车突然失控，翻倒撞上了一堵墙。"}},{"pos":"VERB 动词","cn":"推翻，撤销（判决）","en":"If someone in authority overturns a legal decision, they officially decide that that decision is incorrect or not valid.","ex":{"en":"When the Russian parliament overturned his decision, he backed down","cn":"俄罗斯议会推翻了他的决定，他只好作罢。"}},{"pos":"VERB 动词","cn":"颠覆，破坏（政府或体系）","en":"To overturn a government or system means to remove it or destroy it.","ex":{"en":"He accused his opponents of wanting to overturn the government.","cn":"他指责反对派企图颠覆政府。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to completely change something, especially so that it is much better","cn":""},{"en":"to make something become a completely different thing or make someone become a completely different kind of person","cn":""},{"en":"to completely and permanently change the way people do something or think about something, especially because of a new idea or invention","cn":""}]},"collocations":{"phrases":["ADV. completely She completely overturned my preconceptions about film stars.","VERB + OVERTURN seek to, try to seeking to overturn his conviction for armed robbery | fail to","PHRASES be easily overturned This argument seems convincing, but is easily overturned."]},"media":{"uk":"media/ldoce/hwd/bre/d/overturn0205.mp3","us":"media/ldoce/hwd/ame/8/overturn.mp3"},"examples":[{"en":"He stood up quickly, overturning his chair.","cn":"他猛然站起来，弄翻了椅子。"},{"en":"His sentence was overturned by the appeal court.","cn":"上诉法庭撤销了对他的判决。"}],"oxford":{"phon":"ˌəʊvəˈtɜːn","pos":"verb","senses":[{"en":"if something overturns, or if somebody overturns it, it turns into a position in which the top of it is where the bottom of it normally is or on its side","cn":"倾倒；倾覆；翻掉","g":"[intransitive, transitive]","ex":{"en":"The car skidded and overturned.","cn":"汽车打滑翻倒了。"}},{"en":"to officially decide that a legal decision, etc. is not correct, and to make it no longer legally recognized","cn":"推翻，撤销（判决等）","g":"[transitive]","ex":{"en":"to overturn a decision/conviction/verdict","cn":"撤销决定／定罪／裁决"}},{"en":"to show that a belief or an idea is not correct","cn":"（思想上）颠覆，彻底改变","ex":{"en":"She completely overturned my preconceptions about film stars.","cn":"她彻底打破了我对电影明星的成见。"}}]}},"orthodox":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正统的；规范的；广为接受的","en":"Orthodox beliefs, methods, or systems are ones which are accepted or used by most people.","ex":{"en":"Payne gained a reputation for sound, if orthodox, views","cn":"虽然观点正统，但佩恩合乎情理的见解还是令他为人称道。"}},{"pos":"ADJ 形容词","cn":"（人）正统派的，传统的，循规蹈矩的","en":"If you describe someone as orthodox, you mean that they hold the older and more traditional ideas of their religion or party.","ex":{"en":"...orthodox Jews.","cn":"正统派的犹太教徒"}},{"pos":"ADJ 形容词","cn":"东正教（会）的","en":"The Orthodox churches are Christian churches in Eastern Europe which separated from the western church in the eleventh century.","ex":{"en":"...the Greek Orthodox Church.","cn":"希腊东正教会"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing strongly in a religion and obeying its rules","cn":""},{"en":"having a very strong belief in a religion","cn":""},{"en":"believing in the traditional beliefs, laws, and practices of a religion","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Orthodox practices or beliefs are generally accepted as true or correct. If you are an orthodox vegetarian, you never, ever eat meat––not like those people who have chicken once in awhile, or even––gasp!––bacon."}]},"collocations":{"phrases":["VERBS be His ideas are all fairly orthodox.","ADV. highly, strictly, very This is the strictly orthodox view. I am not a very orthodox kind of counsellor. | fairly"]},"media":{"uk":"media/ldoce/hwd/bre/c/orthodox0205.mp3","us":"media/ldoce/hwd/ame/4/orthodox.mp3"},"examples":[{"en":"an orthodox Jew","cn":"正统的犹太教徒"},{"en":"orthodox medicine","cn":"传统医学"}],"oxford":{"phon":"ˈɔːθədɒks","pos":"adjective","senses":[{"en":"generally accepted or approved of; following generally accepted beliefs","cn":"普遍接受的；正统的；规范的","ex":{"en":"orthodox medicine","cn":"正统医学"}},{"en":"following closely the traditional beliefs and practices of a religion","cn":"正统信仰的；正宗教义的","ex":{"en":"an Orthodox Jew","cn":"正统的犹太教徒"}},{"en":"belonging to or connected with the Orthodox Church","cn":"正教的；东正教派的"}]}},"obstruct":{"collins":{"senses":[{"pos":"VERB 动词","cn":"阻塞，堵塞（道路）","en":"If something obstructs a road or path, it blocks it, stopping people or vehicles getting past.","ex":{"en":"Tractors and container lorries have completely obstructed the road.","cn":"拖拉机和集装箱货车已经将这条路完全堵死了。"}},{"pos":"VERB 动词","cn":"阻止，妨碍（通行）","en":"To obstruct someone or something means to make it difficult for them to move forward by blocking their path.","ex":{"en":"A number of local people have been arrested for trying to obstruct lorries loaded with logs","cn":"一些当地人因试图阻止满载原木的卡车通行而被逮捕。"}},{"pos":"VERB 动词","cn":"阻挠，妨碍（进展或进程）","en":"To obstruct progress or a process means to prevent it from happening properly.","ex":{"en":"The authorities are obstructing a United Nations investigation.","cn":"当局正在阻挠联合国的调查。"}},{"pos":"VERB 动词","cn":"遮住，挡住（视线）","en":"If someone or something obstructs your view, they are positioned between you and the thing you are trying to look at, stopping you from seeing it properly.","ex":{"en":"Claire positioned herself so as not to obstruct David's line of sight.","cn":"克莱尔为了不挡住戴维的视线挪了一下位置。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something such as a law or an official order to prevent someone from doing something that they have been planning to do","cn":""},{"en":"to try to prevent someone from doing something by deliberately making it much more difficult for them","cn":""},{"en":"to prevent someone from doing something, especially something that they very much want to do because it is personally important to them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you obstruct something, you block it. If you’re gobbling down your pizza, a chunk of crust you didn’t chew so well might obstruct your airway and you'll choke."}]},"collocations":{"phrases":["ADV. deliberately, wilfully (law) wilfully obstructing a police officer in the execution of his duty","PREP. in"]},"media":{"uk":"media/ldoce/hwd/bre/e/obstruct0205.mp3","us":"media/ldoce/hwd/ame/5/obstruct.mp3"},"examples":[{"en":"You can't park here, you're obstructing my driveway.","cn":"你不能在这里停车，你挡住了我家的车道。"},{"en":"First check that the accident victim doesn't have an obstructed airway.","cn":"首先要确保事故受伤者的气道通畅。"}],"oxford":{"phon":"əbˈstrʌkt","pos":"verb","senses":[{"en":"to block a road, an entrance, a passage, etc. so that somebody/something cannot get through, see past, etc.","cn":"阻挡；阻塞；遮断","ex":{"en":"You can't park here, you're obstructing my driveway.","cn":"你不能在这里停车，你挡住了我家的车道。"}},{"en":"to prevent somebody/something from doing something or making progress, especially when this is done deliberately","cn":"（故意）妨碍，阻挠，阻碍","ex":{"en":"They were charged with obstructing the police in the course of their duty.","cn":"他们被指控妨碍警察执行公务。"}}]}},"orientated":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a British word for oriented oriented","cn":"的英式说法"}]},"collocations":{"phrases":["VERBS be, seem | become | remain","ADV. strongly, very | totally | sufficiently | correctly Make sure all the components remain correctly orientated. | academically, industria","PREP. to/towards The service is not sufficiently orientated to the needs of those who use it.","PHRASES career/profit orientated She's very career orientated and not really interested in having a family."]},"media":{"uk":"media/ldoce/hwd/bre/8/ld44orientated.mp3","us":"media/ldoce/hwd/ame/8/ld44orientated.mp3"}},"ointment":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"油膏；软膏；药膏","en":"An ointment is a smooth thick substance that is put on sore skin or a wound to help it heal.","ex":{"en":"A range of ointments and creams is available for the treatment of eczema","cn":"有一系列治疗湿疹的油膏和乳膏可以买到。"}},{"pos":"PHRASE 短语","cn":"美中不足之处；败兴的人（或事物）；煞风景的人（或事物）","en":"If you describe someone or something as a fly in the ointment, you think they spoil a situation and prevent it being as successful as you had hoped.","ex":{"en":"Rachel seems to be the one fly in the ointment of Caroline's smooth life.","cn":"蕾切尔似乎是卡罗琳一帆风顺的生活中唯一的麻烦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft cream that you rub into your skin, especially as a medical treatment","cn":"油膏﹐软膏﹐药膏"}]},"collocations":{"phrases":["QUANT. tube","VERB + OINTMENT apply, put on, rub on He put some ointment on the cut."]},"media":{"uk":"media/ldoce/hwd/bre/4/ointment0205.mp3","us":"media/ldoce/hwd/ame/f/ointment.mp3"},"examples":[{"en":"antiseptic ointment","cn":"抗菌软膏"}],"oxford":{"phon":"ˈɔɪntmənt","pos":"noun","senses":[{"en":"a smooth substance that you rub on your skin to make a wound or painful place get better or stop hurting","cn":"药膏；软膏；油膏","ex":{"en":"antiseptic ointment","cn":"抗菌软膏"}}]}},"obscurity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无名；默默无闻","en":"Obscurity is the state of being known by only a few people.","ex":{"en":"For the lucky few, there's the chance of being plucked from obscurity and thrown into the glamorous world of modelling","cn":"只有极少数幸运儿才有机会从籍籍无名中脱颖而出，进入光鲜亮丽的模特圈。"}},{"pos":"N-VAR 可变名词","cn":"晦涩；费解；难懂的事","en":"Obscurity is the quality of being difficult to understand. An obscurity is something that is difficult to understand.","ex":{"en":"'How can that be?' asked Hunt, irritated by the obscurity of Henry's reply","cn":"“怎么会那样呢？”亨特问道，亨利含糊费解的回答让他恼火。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of not being known or remembered","cn":"无名﹐默默无闻"},{"en":"something that is difficult to understand, or the quality of being difficult to understand","cn":"费解的事物﹔费解﹐晦涩"}]},"vocab":{"pos":"n","senses":[{"en":"One meaning of obscurity is nobody knowing who you are, and another definition is something that is hard to understand because it’s too complex or unclear."}]},"collocations":{"phrases":["ADJ. total | comparative, relative | political, professional | impenetrable poems of impenetrable obscurity","VERB + OBSCURITY fade into, sink into, slip into | be plucked from, emerge from After many years, his scientific work emerged from obscurity","PREP. in ~ He spent his early life in relative obscurity."]},"media":{"uk":"media/ldoce/hwd/bre/0/obscurity0205.mp3","us":"media/ldoce/hwd/ame/7/obscurity.mp3"},"examples":[{"en":"The actress was only 17 when she was plucked from obscurity and made a star.","cn":"这个演员从无名少女一跃成为明星时年仅 17 岁。"},{"en":"The course teaches students to avoid ambiguity and obscurity of expression.","cn":"这门课程教学生避免表达上的模棱两可、含混不清。"}],"oxford":{"phon":"əbˈskjʊərəti","pos":"noun","senses":[{"en":"the state in which somebody/something is not well known or has been forgotten","cn":"默默无闻；无名","g":"[uncountable]","ex":{"en":"The actress was only 17 when she was plucked from obscurity and made a star.","cn":"这个演员受到提携从无名少女一跃成为明星时年仅 17 岁。"}},{"en":"the fact of being difficult to understand; something that is difficult to understand","cn":"费解；晦涩；难懂的事","g":"[uncountable, countable, usually plural]","ex":{"en":"The course teaches students to avoid ambiguity and obscurity of expression.","cn":"这门课程教学生避免表达上的模棱两可、含混不清。"}},{"en":"the state of being dark","cn":"昏暗；黑暗","g":"[uncountable]","lab":"literary"}]}},"overgrown":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"杂草丛生的；植被蔓生的","en":"If a garden or other place is overgrown, it is covered with a lot of untidy plants because it has not been looked after.","ex":{"en":"We hurried on until we reached a courtyard overgrown with weeds","cn":"我们匆匆往前走，来到一个野草丛生的院子。"}},{"pos":"ADJ 形容词","cn":"（成年人）不成熟的，孩子气的","en":"If you describe an adult as an overgrown child, you mean that their behaviour and attitudes are like those of a child, and that you dislike this.","ex":{"en":"...a bunch of overgrown kids","cn":"一帮大孩子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered with plants that have grown in an uncontrolled way","cn":"植物蔓生的﹐杂草丛生的"},{"en":"when grass or plants are overgrown, they have grown in an uncontrolled way 〔","cn":"杂草或植物〕乱长的﹐丛生的"},{"en":"an adult who behaves like a child – used to show disapproval","cn":"大男生/大孩子〔用于形容孩子气的成人﹐含贬义〕"}]},"collocations":{"phrases":["VERBS be, look | become, get","ADV. extremely, thickly, very | completely The path was completely overgrown.","PREP. with The canal bank was thickly overgrown with last year's brambles."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeovergrown.mp3","us":"media/ldoce/hwd/ame/f/overgrown.mp3"},"examples":[{"en":"They act like a pair of overgrown children (= they are adults but they behave like children).","cn":"他俩的举动就像一对大孩子。"},{"en":"The garden's completely overgrown with weeds.","cn":"花园里长满了杂草。"}],"oxford":{"phon":"ˌəʊvəˈɡrəʊn","pos":"adjective","senses":[{"en":"covered with plants that have been allowed to grow wild and have not been controlled","cn":"植物蔓生的；杂草丛生的","ex":{"en":"an overgrown path","cn":"长满野草的小径"}},{"en":"that has grown too large","cn":"过度发展的；长得过大的","lab":"often disapproving","ex":{"en":"an overgrown village","cn":"膨胀过大的村庄"}}]}},"opium":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鸦片","en":"Opium is a powerful drug made from the juice or sap of a type of poppy. Opium is used in medicines that relieve pain or help someone sleep."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a powerful illegal drug made from poppy seeds. Drugs made from opium are used to reduce severe pain.","cn":"鸦片"}]},"collocations":{"phrases":["VERB + OPIUM smoke","OPIUM + NOUN poppy | den • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeopium.mp3","us":"media/ldoce/hwd/ame/5/opium.mp3"},"oxford":{"phon":"ˈəʊpiəm","pos":"noun","senses":[{"en":"a powerful drug made from the juice of a type of poppy (= a kind of flower), used in the past in medicines to reduce pain and help people sleep. Some people take opium illegally for pleasure and can become addicted to it.","cn":"鸦片","ex":{"en":"opium poppies","cn":"罂粟"}}]}},"obsolete":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的；废弃的；淘汰的","en":"Something that is obsolete is no longer needed because something better has been invented.","ex":{"en":"So much equipment becomes obsolete almost as soon as it's made.","cn":"这么多设备几乎一生产出来就要被淘汰。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not considered modern or fashionable – used about styles of clothes, furniture etc, or about words and ideas","cn":""},{"en":"not containing the most recent information and therefore not useful","cn":""},{"en":"used about machines, equipment, or methods that are old-fashioned and have been replaced by better, more recent ones","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective obsolete for something that is out of date. As the Rolling Stones song \"Out of Time\" goes, \"You're obsolete , my baby, my poor old-fashioned baby.\""}]},"collocations":{"phrases":["VERBS be | become | make sth, render sth Their work is now rendered obsolete by machines.","ADV. totally | increasingly | largely | almost, practically, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/2/obsolete0205.mp3","us":"media/ldoce/hwd/ame/c/obsolete.mp3"},"examples":[{"en":"With technological changes many traditional skills have become obsolete.","cn":"随着技术的革新，许多传统技艺已被淘汰。"},{"en":"obsolete technology","cn":"过时技术"}],"oxford":{"phon":"ˈɒbsəliːt","pos":"adjective","senses":[{"en":"no longer used because something new has been invented","cn":"淘汰的；废弃的；过时的","ex":{"en":"obsolete technology","cn":"过时技术"}}]}},"overdue":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（变化或事件）早该发生的","en":"If you say that a change or an event is overdue, you mean that you think it should have happened before now.","ex":{"en":"This debate is long overdue","cn":"这场辩论早该进行了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（钱款）到期未付的，拖欠的","en":"Overdue sums of money have not been paid, even though it is later than the date on which they should have been paid.","ex":{"en":"Teachers have joined a strike aimed at forcing the government to pay overdue salaries and allowances.","cn":"教师加入了旨在迫使政府支付拖欠薪水和津贴的罢工。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（图书馆的书）逾期未还的","en":"An overdue library book has not been returned to the library, even though the date on which it should have been returned has passed."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"arriving or happening after the time that was expected or arranged","cn":""},{"en":"not arriving or doing something at the time that was expected or arranged","cn":""},{"en":"not done or happening by the expected time – used especially about payments that are late or library books that should have been returned","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's overdue should have happened or been dealt with a long time ago, like the long overdue recognition for the people who rescued motorists in last winter's big snowstorm."}]},"collocations":{"phrases":["VERBS be | become","ADV. long These reforms are long overdue.","PREP. for This system is overdue for reform.","PHRASES months/weeks/years overdue These changes are years overdue."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeoverdue.mp3","us":"media/ldoce/hwd/ame/8/overdue.mp3"},"examples":[{"en":"Her baby is two weeks overdue.","cn":"她的胎儿已超过预产期两周了。"},{"en":"A book like this is long overdue.","cn":"像这样的书早就该有人出版了。"}],"oxford":{"phon":"ˌəʊvəˈdjuː","pos":"adjective","senses":[{"en":"not paid, done, returned, etc. by the required or expected time","cn":"（到期）未付的，未做的，未还的；过期的","ex":{"en":"an overdue payment/library book","cn":"逾期的欠款；逾期未还图书馆的书"}},{"en":"that should have happened or been done before now","cn":"早该发生的；早应完成的","ex":{"en":"overdue reforms","cn":"迟来的改革"}}]}},"overhaul":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大修；彻底检修；全面检查","en":"If a piece of equipment is overhauled, it is cleaned, checked thoroughly, and repaired if necessary.","ex":{"en":"They had ensured the plumbing was overhauled a year ago","cn":"他们曾保证水管一年前彻底检修过。"}},{"pos":"VERB 动词","cn":"对…进行彻底革新；全面修订","en":"If you overhaul a system or method, you examine it carefully and make many changes in it in order to improve it.","ex":{"en":"The government said it wanted to overhaul the employment training scheme to make it cost effective","cn":"政府表示希望彻底改革就业培训计划以实现低成本高效益。"}},{"pos":"VERB 动词","cn":"（尤指在体育比赛中）赶上，超过，超越","en":"If someone overhauls a person who is ahead of them, especially in a sports competition, they pass them or become more successful than them.","ex":{"en":"Argentina need to beat Peru by at least four goals to overhaul Brazil and reach the final itself","cn":"阿根廷队至少要赢秘鲁队4球才能超越巴西队进入决赛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you repair something that is broken or not working properly, you work on it so that it is in good condition again","cn":""},{"en":"to repair a machine or piece of equipment that is broken or not working properly","cn":""},{"en":"to repair something that is broken or not working, or something that has a hole in it. In American English mend is usually used about clothing","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"To overhaul is to completely renovate, making major changes in order to repair. A few shutters and a new coat of paint won't come close to fixing that old, boarded-up house — it needs a complete overhaul ."}]},"collocations":{"phrases":["ADV. drastically, radically Within a year the party had drastically overhauled its structure. | completely, thoroughly The plan was complete"]},"media":{"uk":"media/ldoce/hwd/bre/f/overhaul_v0205.mp3","us":"media/ldoce/hwd/ame/1/l3overhaul.mp3"},"examples":[{"en":"He managed to overhaul the leader on the final lap.","cn":"他在最后一圈发力超过了领先的选手。"},{"en":"The engine has been completely overhauled.","cn":"发动机已彻底检修过了。"}],"oxford":{"phon":"ˈəʊvəhɔːl","pos":"noun","senses":[{"en":"an examination of a machine or system, including doing repairs on it or making changes to it","cn":"检修；大修；改造","ex":{"en":"a complete/major overhaul","cn":"彻底检修；大修"}},{"en":"to examine every part of a machine, system, etc. and make any necessary changes or repairs","cn":"彻底检修","ex":{"en":"The engine has been completely overhauled.","cn":"发动机已彻底检修过了。"},"pos":"verb"},{"en":"to come from behind a person you are competing against in a race and go past them","cn":"赶上，超过（赛跑对手）","ex":{"en":"He managed to overhaul the leader on the final lap.","cn":"他在最后一圈发力超过了领先的选手。"},"pos":"verb"}]}},"onslaught":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"攻击；袭击;猛攻","en":"An onslaught on someone or something is a very violent, forceful attack against them.","ex":{"en":"The attackers launched another vicious onslaught on their victim","cn":"袭击者再度凶残地攻击受害人。"}},{"pos":"N-COUNT 可数名词","cn":"（常指难以应付的）大批，大量","en":"If you refer to an onslaught of something, you mean that there is a large amount of it, often so that it is very difficult to deal with.","ex":{"en":"The onslaught of orders should keep aircraft manufacturers busy for some time.","cn":"纷至沓来的订单应该会让飞机制造商忙碌一段时间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an act of using weapons against an enemy in a war","cn":""},{"en":"an occasion when an army enters a country and tries to take control of it","cn":""},{"en":"a short attack on a place by soldiers or planes, intended to cause damage but not take control","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Onslaught is a military term that refers to an attack against an enemy. It's safe to say that no one wants to be caught on the receiving end of an onslaught , because there will be lots of danger, destruction and probably death."}]},"collocations":{"phrases":["ADJ. sudden She could not withstand such a sudden onslaught. | first, initial | latest | renewed | verbal","VERB + ONSLAUGHT face to face the verbal onslaught of an angry teenager | resist, survive, withstand | launch, mount","PREP. ~ against/on a renewed onslaught against the proposed bill | ~ from the latest onslaught from the Russian team"]},"media":{"uk":"media/ldoce/hwd/bre/c/onslaught0205.mp3","us":"media/ldoce/hwd/ame/f/onslaught.mp3"},"examples":[{"en":"The town survives the onslaught of tourists every summer.","cn":"每年夏天，这座小城都要熬过一段旅游者蜂拥而至的苦日子。"},{"en":"the enemy onslaught on our military forces","cn":"敌军对我军的进攻"}],"oxford":{"phon":"ˈɒnslɔːt","pos":"noun","senses":[{"en":"a strong or violent attack","cn":"攻击；猛攻","lab":"figurative","ex":{"en":"His approach was met with a vicious onslaught.","cn":"他的方法遭到了严厉的批评。"}}]}},"offender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"犯罪者；违法者；罪犯","en":"An offender is a person who has committed a crime.","ex":{"en":"The authorities often know that sex offenders will attack again when they are released.","cn":"当局一般都知道性犯罪者在获释后往往会再次犯案。"}},{"pos":"N-COUNT 可数名词","cn":"造成问题的人（或事物）","en":"You can refer to someone or something which you think is causing a problem as an offender .","ex":{"en":"The contraceptive pill is the worst offender, but it is not the only drug to deplete the body's vitamin levels.","cn":"避孕药的危害最大，但是它并不是唯一一种消耗体内维生素的药物。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is involved in illegal activities or has been proved guilty of a crime. Criminal is used especially about someone who often does things that are illegal","cn":""},{"en":"someone who breaks the law","cn":""},{"en":"a dishonest person, especially one who steals money and who you cannot trust","cn":""}]},"collocations":{"phrases":["ADJ. alleged | convicted | first As a first offender, he received a lenient sentence. | persistent | adult, juvenile, young | sex","VERB + OFFENDER sentence 2 sb/sth that causes trouble","ADJ. main, worst As regards pollution, old diesel-engined vehicles are the worst offenders."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeoffender.mp3","us":"media/ldoce/hwd/ame/1/offender.mp3"},"examples":[{"en":"When it comes to pollution, the chemical industry is a major offender.","cn":"谈到环境污染问题，化工产业是一大祸害。"},{"en":"a persistent/serious/violent, etc. offender","cn":"惯犯、重犯、暴力犯等"}],"oxford":{"phon":"əˈfendə(r)","pos":"noun","senses":[{"en":"a person who commits a crime","cn":"犯罪者；违法者；罪犯","lab":"rather formal","ex":{"en":"a persistent/serious/violent, etc. offender","cn":"惯犯、重犯、暴力犯等"}},{"en":"a person or thing that does something wrong","cn":"妨害…的人（或事物）","ex":{"en":"The report on sexual discrimination at work shows that some of the worst offenders are women.","cn":"关于工作场所性别歧视的报告显示，一些最严重的犯罪者是女性。"}}]}},"obliterate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"消灭;毁掉;清除","en":"If something obliterates an object or place, it destroys it completely.","ex":{"en":"Their warheads are enough to obliterate the world several times over","cn":"他们拥有的弹头足以将世界毁灭好几次。"}},{"pos":"VERB 动词","cn":"抹除，忘却（回忆等）","en":"If you obliterate something such as a memory, emotion, or thought, you remove it completely from your mind.","ex":{"en":"There was time enough to obliterate memories of how things once were for him.","cn":"时间足以抹去他对过去经历的记忆。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage something so badly that it no longer exists or cannot be used or repaired","cn":""},{"en":"to damage a large area very badly and destroy many things in it","cn":""},{"en":"to completely destroy a building, either deliberately or by accident","cn":""}]},"vocab":{"pos":"v adj","senses":[{"en":"When you see obliterate , think of evil alien invaders that zap a planet with a destructive ray. In one blast, the planet and all of the people on it are vaporized. The planet is truly obliterated , or completely wiped out."}]},"collocations":{"phrases":["ADV. completely, entirely, totally The village was totally obliterated by the bomb. | almost, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/7/obliterate0205.mp3","us":"media/ldoce/hwd/ame/c/obliterate.mp3"},"examples":[{"en":"Everything that happened that night was obliterated from his memory.","cn":"那天夜里发生的一切都从他的记忆中消失了。"},{"en":"The building was completely obliterated by the bomb.","cn":"炸弹把那座建筑物彻底摧毁了。"}],"oxford":{"phon":"əˈblɪtəreɪt","pos":"verb","senses":[{"en":"to remove all signs of something, either by destroying or covering it completely","cn":"毁掉；覆盖；清除","ex":{"en":"The building was completely obliterated by the bomb.","cn":"炸弹把那座建筑物彻底摧毁了。"}}]}},"omit":{"collins":{"senses":[{"pos":"VERB 动词","cn":"省略；删节；排除；遗漏","en":"If you omit something, you do not include it in an activity or piece of work, deliberately or accidentally.","ex":{"en":"Omit the salt in this recipe","cn":"省略菜谱中放盐这一步。"}},{"pos":"VERB 动词","cn":"未（做）；没有（做）","en":"If you omit to do something, you do not do it.","ex":{"en":"His new girlfriend had omitted to tell him she was married.","cn":"他的新女友未把自己已婚的事实告诉他。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately not include someone or something, especially in a way that seems wrong or unfair","cn":""},{"en":"to not include something, especially a piece of information, either deliberately or because you forget","cn":""},{"en":"to not include someone or something, either deliberately or accidentally. Leave out is more common in everyday English than exclude or omit","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you omit one member of the class when you're handing out valentines, it's going to make that person feel terrible. To omit something is to leave it out, to forget or overlook it."}]},"collocations":{"phrases":["ADV. altogether, completely, totally | accidentally, inadvertently | deliberately | conspicuously | controversially He was controversially o","PREP. from Some important details were deliberately omitted from the report."]},"media":{"uk":"media/ldoce/hwd/bre/e/omit0205.mp3","us":"media/ldoce/hwd/ame/7/omit.mp3"},"examples":[{"en":"People were surprised that Smith was omitted from the team.","cn":"人们感到惊讶，史密斯竟未列入该队。"},{"en":"If you are a student, you can omit questions 16–18.","cn":"学生可以免做 16–18 题。"}],"oxford":{"phon":"əˈmɪt","pos":"verb","senses":[{"en":"to not include something/somebody, either deliberately or because you have forgotten it/them","cn":"删除；忽略；漏掉；遗漏","ex":{"en":"If you are a student, you can omit questions 16–18.","cn":"学生可以免答 16–18 题。"}},{"en":"to not do or fail to do something","cn":"不做；未能做","ex":{"en":"She omitted to mention that they were staying the night.","cn":"她没说他们当晚要留宿的事。"}}]}},"orthodoxy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"正统观念；普遍接受的观念","en":"An orthodoxy is an accepted view about something.","ex":{"en":"These ideas rapidly became the new orthodoxy in linguistics","cn":"这些观点迅速成为语言学中新的正统观念。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（宗教、政党或哲学的）传统看法，正统信仰","en":"The old, traditional beliefs of a religion, political party, or philosophy can be referred to as orthodoxy.","ex":{"en":"...the latest step in a purge of liberals and a return to political orthodoxy.","cn":"肃清自由派、回归政治正统理念的最新举措"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an idea or set of ideas that is accepted by most people to be correct and right","cn":"正统观念﹐普遍接受的观点"}]},"vocab":{"pos":"n","senses":[{"en":"A widely accepted belief or theory is an orthodoxy . You could call the scientific theory of gravity an orthodoxy , since it's generally considered to be an established fact."}]},"collocations":{"phrases":["ADJ. rigid, strict | prevailing | Catholic, Christian, etc. | communist, liberal, etc. | party | economic, scientific, etc."]},"media":{"uk":"media/ldoce/hwd/bre/3/orthodoxy0205.mp3","us":"media/ldoce/hwd/ame/4/laadorthodoxy.mp3"},"examples":[{"en":"an economist arguing against the current financial orthodoxy","cn":"一位批驳现行正统金融观念的经济学家"},{"en":"He challenged the political orthodoxy of his time.","cn":"他对同时代的正统政治观念提出了质疑。"}],"oxford":{"phon":"ˈɔːθədɒksi","pos":"noun","senses":[{"en":"an idea or view that is generally accepted","cn":"正统观念；普遍接受的观点","g":"[countable, uncountable]","lab":"formal","ex":{"en":"an economist arguing against the current financial orthodoxy","cn":"一位批驳现行正统金融观念的经济学家"}},{"en":"the traditional beliefs or practices of a religion, etc.","cn":"正统的信仰（或做法）","g":"[uncountable, countable, usually plural]"},{"en":"the Orthodox Church, its beliefs and practices","cn":"正教会；正教信仰与做法","g":"[uncountable]"}]}},"orbit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（天体等运行的）轨道","en":"An orbit is the curved path in space that is followed by an object going round and round a planet, moon, or star.","ex":{"en":"Mars and Earth have orbits which change with time","cn":"火星与地球的运行轨道随着时间而变化。"}},{"pos":"VERB 动词","cn":"环绕…的轨道运行","en":"If something such as a satellite orbits a planet, moon, or sun, it moves around it in a continuous, curving path.","ex":{"en":"In 1957 the Soviet Union launched the first satellite to orbit the earth.","cn":"1957年，苏联发射了第一颗绕地卫星。"}},{"pos":"N-SING 单数名词","cn":"（影响所及的）范围，领域，圈子","en":"The orbit of a particular person, group, or institution is the area over which they have influence.","ex":{"en":"In the late 1970s Laos fell within the orbit of Vietnam and the Soviet Union.","cn":"20世纪70年代末，老挝被纳入了越南和苏联的势力范围。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"use this after verbs of movement, to show that someone or something is moving in a circle or moving around something","cn":""},{"en":"if someone or something moves in circles , they move around in a circle several times","cn":""},{"en":"to move around someone or something in a circle","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n 4 n","senses":[{"en":"To orbit is to follow a circular or elliptical path around a central body. Usually a planet, moon or satellite is described as orbiting , but a child who has too much sugar can sometimes orbit around his parents in an annoying fashion."}]},"collocations":{"phrases":["ADJ. circular, elliptical | eccentric Mercury's orbit is fairly eccentric. | stable | planetary","VERB + ORBIT enter, go into | put/send sth into | complete, make The spaceship made an orbit of the moon.","PREP. in ~ The satellite will remain in orbit for several years. | ~ around/round the moon's orbit around the earth"]},"media":{"uk":"media/ldoce/hwd/bre/4/orbit_n0205.mp3","us":"media/ldoce/hwd/ame/f/orbit1.mp3"},"examples":[{"en":"A new satellite has been put into orbit around the earth.","cn":"一颗新的人造卫星被送上了环绕地球的轨道。"},{"en":"The earth takes a year to orbit the sun.","cn":"地球绕太阳一周要一年的时间。"}],"oxford":{"phon":"ˈɔːbɪt","pos":"noun","senses":[{"en":"a curved path followed by a planet or an object as it moves around another planet, star, moon, etc.","cn":"（天体等运行的）轨道","g":"[countable, uncountable]","ex":{"en":"the earth’s orbit around the sun","cn":"地球环绕太阳的轨道"}},{"en":"an area that a particular person, organization, etc. deals with or is able to influence","cn":"（人、组织等的）影响范围，势力范围","g":"[singular]","ex":{"en":"to come/fall/be within somebody’s orbit","cn":"进入／属于某人的势力范围"}},{"en":"to move in an orbit (= a curved path) around a much larger object, especially a planet, star, etc.","cn":"沿轨道运行；围绕…运动","ex":{"en":"Stars near the edge of the galaxy orbit more slowly.","cn":"靠近星系边缘的恒星绕轨道运行的速度较慢。"},"pos":"verb"}]}},"observant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"善于观察的；观察力敏锐的","en":"Someone who is observant pays a lot of attention to things and notices more about them than most people do.","ex":{"en":"That's a marvellous description, Mrs Drummond. You're unusually observant","cn":"您的描述令人惊叹，德拉蒙德太太，您真是独具慧眼。"}},{"pos":"ADJ 形容词","cn":"严格遵守教规的","en":"An observant follower of a religion performs all the duties that his or her religion requires.","ex":{"en":"...a profoundly observant Islamic country.","cn":"严守教规的伊斯兰国家"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at noticing things","cn":""},{"en":"good at noticing and understanding situations or people's feelings","cn":""},{"en":"if you do not miss much or do not miss a trick or a thing , you notice a lot about what is happening and what other people are doing or feeling","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If you're observant , you’re paying close attention to the details. If you're really observant , you would notice the little blob of mustard on your boss's jacket and brush it off for him before he goes to his business dinner."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. acutely, highly, very She was intelligent and highly observant. | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/4/observant0205.mp3","us":"media/ldoce/hwd/ame/a/observant.mp3"},"examples":[{"en":"Observant walkers may see red deer along this stretch of the road.","cn":"观察敏锐的步行者能在这一路段看到赤鹿。"},{"en":"How very observant of you!","cn":"你真有眼力！"}],"oxford":{"phon":"əbˈzɜːvənt","pos":"adjective","senses":[{"en":"good at noticing things around you","cn":"善于观察的；观察力敏锐的","ex":{"en":"Observant walkers may see red deer along this stretch of the road.","cn":"观察敏锐的步行者能在这一路段看到赤鹿。"}},{"en":"careful to obey religious laws and customs","cn":"谨慎遵守教规和习俗的","lab":"formal"}]}},"omen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"征兆；预兆；兆头","en":"If you say that something is an omen, you think it indicates what is likely to happen in the future and whether it will be good or bad.","ex":{"en":"Her appearance at this moment is an omen of disaster","cn":"她在此刻出现预示着一场灾难。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event or fact that shows that something is true or that something is happening","cn":""},{"en":"something, especially someone's behaviour or what they say, that makes you believe that something is probably happening or has probably happened","cn":""},{"en":"facts, objects etc that show that something exists or is true","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An omen is an event or happening that you take as sign of something to come. It’s believed to be a bad omen if a black cat crosses your path or if it rains on your wedding day."}]},"collocations":{"phrases":["ADJ. good | bad, evil, ill They took the storm as a bad omen.","VERB + OMEN take sth as","PREP. ~ for The sunny weather was a good omen for the holiday. | ~ of an omen of death"]},"media":{"uk":"media/ldoce/hwd/bre/0/omen0205.mp3","us":"media/ldoce/hwd/ame/a/omen.mp3"},"examples":[{"en":"The omens for their future success are not good.","cn":"他们未来成功的预兆不祥。"},{"en":"a good/bad omen","cn":"吉祥的/不祥的预兆"}],"oxford":{"phon":"ˈəʊmən","pos":"noun","senses":[{"en":"a sign of what is going to happen in the future","cn":"预兆；前兆；征兆","ex":{"en":"a good/bad omen","cn":"吉祥的／不祥的预兆"}}]}},"orlando":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in Florida, US, which attracts large numbers of tourists, mainly because of disney world and the Epcot Center","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/p028-000009353.mp3","us":"media/ldoce/hwd/ame/0/p028-000009353.mp3"},"oxford":{"phon":"ɔːˈlændəʊ","pos":"","senses":[{"en":"a US city in central Florida, known as an international entertainment centre. It was a quiet farming town until the 1970s but its attractions now include Disney World, Sea World, Universal Studios and Disney-MGM Studios. Orlando is the centre of an agricultural area which produces a lot of fruit. It also has a US Navy base and industries producing electronic products.","cn":"奥兰多（美国佛罗里达州城市，著名的旅游胜地）"}]}},"obstacle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"障碍物","en":"An obstacle is an object that makes it difficult for you to go where you want to go, because it is in your way.","ex":{"en":"Most competition cars will only roll over if they hit an obstacle","cn":"大多数赛车只有在撞上障碍物时才会翻车。"}},{"pos":"N-COUNT 可数名词","cn":"障碍；困难；阻碍","en":"You can refer to anything that makes it difficult for you to do something as an obstacle .","ex":{"en":"Overcrowding remains a large obstacle to improving conditions","cn":"过分拥挤仍然是改善环境的一大障碍。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When the road is blocked ahead of you, that blockage is an obstacle that keeps you from getting where you want to go."}]},"collocations":{"phrases":["ADJ. big, chief, main, major | enormous, formidable, serious The attitude of the unions is a serious obstacle. | impossible, insuperable, in","VERB + OBSTACLE pose, prove, remain | come across, encounter | overcome, remove, surmount He was determined to overcome all obstacles in his","PREP. ~ for Lack of childcare provision can be a major obstacle for women wishing to work. | ~ to The huge distances involved have proved an","PHRASES an obstacle in the path/way (of sb/sth) The release of prisoners remains an obstacle in the path of a peace agreement."]},"media":{"uk":"media/ldoce/hwd/bre/4/obstacle_las2_br.mp3","us":"media/ldoce/hwd/ame/b/obstacle.mp3"},"examples":[{"en":"So far, we have managed to overcome all the obstacles that have been placed in our path.","cn":"到目前为止，我们已设法克服了我们路上的一切障碍。"},{"en":"The area was full of streams and bogs and other natural obstacles.","cn":"此地遍布小溪、泥潭和其他天然障碍。"}],"oxford":{"phon":"ˈɒbstəkl","pos":"noun","senses":[{"en":"a situation, an event, etc. that makes it difficult for you to do or achieve something","cn":"障碍；阻碍；绊脚石","ex":{"en":"So far, we have managed to overcome all the obstacles that have been placed in our path.","cn":"到目前为止，我们已设法排除了前进道路上的一切人为障碍。"}},{"en":"an object that is in your way and that makes it difficult for you to move forward","cn":"障碍物；绊脚石","ex":{"en":"The area was full of streams and bogs and other natural obstacles.","cn":"此地遍布小溪、泥潭和其他天然障碍。"}},{"en":"a fence, etc. for a horse to jump over","cn":"障碍栅栏；障碍","ex":{"en":"This huge open ditch forms the biggest obstacle on the course.","cn":"这条巨大的明沟成为途中最大的障碍。"}}]}},"orphan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"孤儿","en":"An orphan is a child whose parents are dead.","ex":{"en":"I'm an orphan and pretty much grew up on my own.","cn":"我是个孤儿，差不多是靠自己长大的。"}},{"pos":"V-PASSIVE 被动动词","cn":"使成为孤儿","en":"If a child is orphaned, their parents die, or their remaining parent dies.","ex":{"en":"Jones was orphaned at the age of ten, and taken in by next-door neighbours","cn":"琼斯10岁时成为孤儿，被隔壁的邻居收养。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a child whose parents are both dead","cn":"孤儿"},{"en":"if you lose a close relative or friend, they die","cn":""},{"en":"if you are widowed , your husband or wife dies","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"An orphan is someone who has lost both parents. Usually, we think of sad little children when we think of orphans , but anyone whose parents have both died is an orphan ."}]},"collocations":{"phrases":["ADJ. little | poor a poor little orphan | war","VERB + ORPHAN be left She was left an orphan at the age of five. | adopt","ORPHAN + NOUN boy, girl"]},"media":{"uk":"media/ldoce/hwd/bre/4/orphan_n0205.mp3","us":"media/ldoce/hwd/ame/f/orphan1.mp3"},"examples":[{"en":"He was an orphan and lived with his uncle.","cn":"他是个孤儿，和他叔叔一起生活。"},{"en":"She was orphaned in the war.","cn":"战争使她成为孤儿。"}],"oxford":{"phon":"ˈɔːfn","pos":"noun","senses":[{"en":"a child whose parents are dead","cn":"孤儿","ex":{"en":"He was an orphan and lived with his uncle.","cn":"他是个孤儿，和他叔叔一起生活。"}},{"en":"to make a child an orphan","cn":"使成为孤儿","ex":{"en":"She was orphaned in the war.","cn":"战争使她成为孤儿。"},"pos":"verb"}]}},"ovation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"热烈欢迎；热烈鼓掌","en":"An ovation is a large amount of applause from an audience for a particular performer or speaker.","ex":{"en":"They had lost by a wide margin, but their supporters gave them a defiant, loyal ovation.","cn":"他们以较大的差距败北，但支持者们还是给予了热烈的掌声，以示对对手的不服和对他们的忠诚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to hit your hands together loudly and quickly to show that you approve of and are pleased with a play, someone's performance, someone's actions etc","cn":""},{"en":"if people applaud , they clap excitedly, and often for a long time, in order to show how much they liked something or to show their support for someone","cn":""},{"en":"to give a loud, happy shout expressing admiration, approval, and often excitement, for example at a sports event or after a speech","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hear that applause and cries of \"Bravo\"? Your audience is giving you an ovation , or praise for a great performance."}]},"collocations":{"phrases":["ADJ. enthusiastic, huge, long, loud, rapturous, thunderous | standing The audience gave her a standing ovation for her performance.","VERB + OVATION give sb | get, receive He received the longest ovation of the evening. | bring, earn, win","PREP. to an ~ He came off the field to a huge ovation. | ~ from The final piece won her a rapturous ovation from the audience."]},"media":{"uk":"media/ldoce/hwd/bre/b/ovation0205.mp3","us":"media/ldoce/hwd/ame/7/ovation.mp3"},"examples":[{"en":"The soloist got a ten-minute standing ovation (= in which people stand up from their seats).","cn":"独奏演员受到了长达十分钟的起立鼓掌欢呼。"},{"en":"to give sb a huge/rapturous/rousing ovation","cn":"对某人万分的/狂热的/热烈的欢迎"}],"oxford":{"phon":"əʊˈveɪʃn","pos":"noun","senses":[{"en":"enthusiastic clapping by an audience as a sign of their approval","cn":"热烈鼓掌；热烈欢迎","ex":{"en":"to give somebody a huge/rapturous/rousing ovation","cn":"对某人表示万分的／狂热的／热烈的欢迎"}}]}},"overture":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（歌剧、戏剧等的）序曲，前奏曲","en":"An overture is a piece of music, often one that is the introduction to an opera or play.","ex":{"en":"The programme opened with the overture to Wagner's Flying Dutchman.","cn":"节目以瓦格纳的歌剧《漂泊的荷兰人》的序曲开场。"}},{"pos":"N-COUNT 可数名词","cn":"（友好或求爱的）主动表示，姿态，提议","en":"If you make overtures to someone, you behave in a friendly or romantic way towards them.","ex":{"en":"He had lately begun to make clumsy yet endearing overtures of friendship","cn":"最近他开始主动表示友好，样子笨拙却又招人喜爱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short piece of music written as an introduction to a long piece of music, especially an opera 〔","cn":"尤指歌剧的〕序曲﹐前奏曲"},{"en":"an attempt to begin a friendly relationship with a person, country etc 〔","cn":"试图与某人﹑某国等建立友好关系的〕主动表示﹐姿态"},{"en":"if an event is an overture to a more important event, it happens just before it and makes you expect it","cn":"是一个序幕〔表示某事是另一更为重要之事的开端〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An overture is a piece of music played by an orchestra at the beginning of an opera or play. When an overture begins, the actors take their places and wait for the curtain to rise."}]},"collocations":{"phrases":["ADJ. friendly | diplomatic, peace, sexual","VERB + OVERTURE make | receive | respond to | reject, spurn She spurned his overtures of love.","PREP. ~s of overtures of friendship | ~s to He made friendly overtures to his new neighbours. 2 piece of music","ADJ. operatic, symphonic","PREP. ~ to the overture to Mozart's &lsquo;Don Giovanni&rsquo;"]},"media":{"uk":"media/ldoce/hwd/bre/a/overture0205.mp3","us":"media/ldoce/hwd/ame/8/overture.mp3"},"examples":[{"en":"Prokofiev's overture to ‘Romeo and Juliet’","cn":"普罗科菲耶夫的《罗密欧与朱丽叶》的序曲"},{"en":"He began making overtures to a number of merchant banks.","cn":"他开始主动同一些投资银行接触。"}],"oxford":{"phon":"ˈəʊvətʃʊə(r)","pos":"noun","senses":[{"en":"a piece of music written as an introduction to an opera or a ballet","cn":"（歌剧或芭蕾舞的）序曲，前奏曲","ex":{"en":"Prokofiev’s overture to ‘Romeo and Juliet’","cn":"普罗科菲耶夫《罗密欧与朱丽叶》序曲"}},{"en":"a suggestion or an action by which somebody tries to make friends, start a business relationship, have discussions, etc. with somebody else","cn":"友好姿态；建议","g":"[usually plural]","ex":{"en":"He began making overtures to a number of merchant banks.","cn":"他开始主动同一些投资银行接触。"}}]}},"operative":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"运作（或运转）着的；起作用的；产生影响的","en":"A system or service that is operative is working or having an effect.","ex":{"en":"The commercial telephone service was no longer operative","cn":"商业电话服务已不再运营。"}},{"pos":"N-COUNT 可数名词","cn":"工人；（尤指）技工，操作员","en":"An operative is a worker, especially one who does work with their hands.","ex":{"en":"In an automated car plant there is not a human operative to be seen.","cn":"在自动化汽车制造厂看不到一个工人。"}},{"pos":"N-COUNT 可数名词","cn":"特工；间谍；密探；情报人员","en":"An operative is someone who works for a government agency such as the intelligence service.","ex":{"en":"Naturally the CIA wants to protect its operatives.","cn":"美国中央情报局当然想保护其特工。"}},{"pos":"PHRASE 短语","cn":"关键词","en":"If you describe a word as the operative word, you want to draw attention to it because you think it is important or exactly true in a particular situation.","ex":{"en":"As long as the operative word is 'greed', you can't count on people keeping the costs down","cn":"只要“贪婪”仍是一切的出发点，就别指望人们会降低成本。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"working and able to be used","cn":"运作中的﹐工作着的﹔可使用的"},{"en":"used when you repeat a word from a previous sentence to draw attention to its importance","cn":"最重要的词﹐关键词〔用于重复前一句中的某个词﹐使人注意其重要性〕"},{"en":"relating to a medical operation","cn":"与医疗手术有关的"}]},"vocab":{"pos":"1 adj 2 adj 3 n","senses":[{"en":"Bond, James Bond, is perhaps the most famous fictional operative of our time. Martini-drinking, globe-trotting, and womanizing aside, let us not forget his primary role as a government secret agent — collecting intelligence and bringing down the world's enemies."}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. fully The new system will not become fully operative until next year."]},"media":{"uk":"media/ldoce/hwd/bre/d/operative_n0205.mp3","us":"media/ldoce/hwd/ame/f/operative1.mp3"},"examples":[{"en":"I was in love with her — ‘was’ being the operative word.","cn":"在 I was in love with her 这句话中，was 是关键词。"},{"en":"The station will be fully operative again in January.","cn":"该站将于一月份全部恢复运营。"}],"oxford":{"phon":"ˈɒpərətɪv","pos":"noun","senses":[{"en":"a worker, especially one who works with their hands","cn":"工作人员；（尤指）技术工人，操作员","lab":"specialist","ex":{"en":"a factory operative","cn":"工厂工人"}},{"en":"a person who does secret work, especially for a government organization","cn":"密探；（尤指政府的）特工人员","lab":"especially North American English","ex":{"en":"an intelligence operative","cn":"情报人员"}},{"en":"ready to be used; in use","cn":"可使用；在使用中","g":"[not usually before noun]","ex":{"en":"This law becomes operative immediately.","cn":"本法规即时生效。"},"pos":"adjective"},{"en":"connected with a medical operation","cn":"手术的","g":"[only before noun]","lab":"medical","ex":{"en":"operative treatment","cn":"手术治疗"},"pos":"adjective"}]}},"occupant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（建筑物、房间等的）居住者，使用者","en":"The occupants of a building or room are the people who live or work there.","ex":{"en":"Most of the occupants had left before the fire broke out","cn":"大部分住户在火灾发生前就已经离开。"}},{"pos":"N-PLURAL 复数名词","cn":"（某一时刻房间、交通工具、床等的）占用者","en":"You can refer to the people who are in a place such as a room, vehicle, or bed at a particular time as the occupants.","ex":{"en":"He wanted the occupants of the vehicle to get out","cn":"他想让车上的乘客下车。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a country or town or area, or the number of people who live in it","cn":""},{"en":"someone who lives in a particular area of a town, a particular street or building etc","cn":""},{"en":"one of the people who live in a place, especially in a town or city or in an area of a country","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An occupant is someone who lives or stays at a place for awhile. A lot of your junk mail is addressed \"To occupant \" because the sender doesn't know who lives at your address."}]},"collocations":{"phrases":["ADJ. current, former, next, original, present, previous | sole The sole occupant of the car was an elderly man."]},"media":{"uk":"media/ldoce/hwd/bre/f/occupant0205.mp3","us":"media/ldoce/hwd/ame/6/occupant.mp3"},"examples":[{"en":"The car was badly damaged but the occupants were unhurt.","cn":"汽车严重损坏，但车内人员安然无恙。"},{"en":"All outstanding bills will be paid by the previous occupants.","cn":"一切未支付的账单将由前住户偿付。"}],"oxford":{"phon":"ˈɒkjəpənt","pos":"noun","senses":[{"en":"a person who lives or works in a particular house, room, building, etc.","cn":"（房屋、建筑等的）使用者，居住者","ex":{"en":"All outstanding bills will be paid by the previous occupants.","cn":"所有未支付的账单都将由前住户偿付。"}},{"en":"a person who is in a vehicle, seat, etc. at a particular time","cn":"（汽车等内的）乘坐者，占用者","ex":{"en":"The car was badly damaged but the occupants were unhurt.","cn":"汽车严重损坏，但车内人员安然无恙。"}}]}},"overtone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"弦外之音；言外之意；暗示","en":"If something has overtones of a particular thing or quality, it suggests that thing or quality but does not openly express it.","ex":{"en":"The strike has taken on overtones of a civil rights campaign","cn":"罢工带上了民权运动的意味。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"signs of an emotion or attitude that is not expressed directly 〔","cn":"情感或态度〕含蓄的表示﹐暗示﹐弦外之音"},{"en":"a higher musical note that sounds together with the main note","cn":"泛音"}]},"collocations":{"phrases":["ADJ. strong a play with strong religious overtones | serious | negative The word &lsquo;cheap&rsquo; has negative overtones. | emotional, mo","VERB + OVERTONE carry, have | take on The organization's cultural activities took on political overtones."]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41overtone.mp3","us":"media/ldoce/hwd/ame/8/overtone.mp3"},"examples":[{"en":"There were political overtones to the point he was making.","cn":"他的论点有政治寓意。"},{"en":"There were overtones of anger in his voice.","cn":"他的语气里含着怒意。"}],"oxford":{"phon":"ˈəʊvətəʊn","pos":"noun","senses":[{"en":"an attitude or an emotion that is suggested and is not expressed in a direct way","cn":"弦外之音；言外之意；暗示","ex":{"en":"There were political overtones to the point he was making.","cn":"他的论点有政治寓意。"}}]}},"overthrow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"推翻；打倒；将…赶下台","en":"When a government or leader is overthrown, they are removed from power by force.","ex":{"en":"That government was overthrown in a military coup three years ago.","cn":"那个政府在3年前的军事政变中被推翻。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get rid of a leader, someone in authority etc","cn":""},{"en":"to take power away from a leader or government, especially by force","cn":""},{"en":"force a leader out of his or her position of power","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"When you overthrow a ruler or a regime, you throw them out, usually by force. If you're a rebel you may plan to overthrow the current government and install a new regime."}]},"collocations":{"phrases":["ADJ. attempted | violent","VERB + OVERTHROW bring about, lead to | plot","PREP. ~ of to bring about the overthrow of the military dictatorship"]},"media":{"uk":"media/ldoce/hwd/bre/d/overthrow_v0205.mp3","us":"media/ldoce/hwd/ame/c/l3overthrow.mp3"},"examples":[{"en":"The president was overthrown in a military coup.","cn":"总统在军事政变中被赶下台。"},{"en":"Rebels were already making plans to overthrow the government.","cn":"反叛者已在密谋颠覆政府。"}],"oxford":{"phon":"ˌəʊvəˈθrəʊ","pos":"verb","senses":[{"en":"to remove a leader or a government from a position of power by force","cn":"推翻；打倒；赶下台","ex":{"en":"The president was overthrown in a military coup.","cn":"总统在军事政变中被赶下台。"}},{"en":"the act of taking power by force from a leader or government","cn":"推翻；打倒","ex":{"en":"He was president until his overthrow in 1995.","cn":"他一直担任总统，直到 1995 年被推翻。"},"pos":"noun"}]}},"obscene":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"淫秽的；猥亵的；暴力的","en":"If you describe something as obscene, you mean it offends you because it relates to sex or violence in a way that you think is unpleasant and shocking.","ex":{"en":"I'm not prudish but I think these photographs are obscene","cn":"我并不是个守旧的人，但是我认为这些照片不堪入目。"}},{"pos":"ADJ 形容词","cn":"(法律上指书刊、图片、电影等)淫秽的，色情的，暴力的","en":"In legal contexts, books, pictures, or films which are judged obscene are illegal because they deal with sex or violence in a way that is considered offensive to the general public.","ex":{"en":"A city magistrate ruled that the novel was obscene and copies should be destroyed","cn":"一位市执法官裁定该小说为色情作品，应当全数销毁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可憎的；令人厌恶的;道德败坏的","en":"If you describe something as obscene, you disapprove of it very strongly and consider it to be offensive or immoral.","ex":{"en":"It was obscene to spend millions producing unwanted food","cn":"耗资数百万去生产一些不需要的食品，真是令人发指。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"obscene words or pictures are about sex and are very offensive","cn":""},{"en":"dirty books, jokes, films etc are about sex - use this especially to show that you think these are unpleasant","cn":""},{"en":"clothes that are indecent show parts of the body that are usually covered; actions or movements that are indecent are sexual, but in a way many people think is not pleasant or acceptable","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Obscene describes something that is morally offensive in a sexual way. If you pick up the phone and hear heavy breathing, you're the recipient of an obscene phone call."}]},"collocations":{"phrases":["VERBS be, look | declare sth, deem sth, judge sth The book was declared obscene.","ADV. really | utterly | almost | allegedly"]},"media":{"uk":"media/ldoce/hwd/bre/5/obscene0205.mp3","us":"media/ldoce/hwd/ame/a/obscene.mp3"},"examples":[{"en":"It's obscene to spend so much on food when millions are starving.","cn":"当数以百万的人忍饥挨饿时，饮食上挥霍无度是天理难容的。"},{"en":"He earns an obscene amount of money.","cn":"他捞了一大笔昧心钱。"}],"oxford":{"phon":"əbˈsiːn","pos":"adjective","senses":[{"en":"connected with sex in a way that most people find offensive","cn":"淫秽的；猥亵的；下流的","ex":{"en":"obscene gestures/language/books","cn":"淫秽的姿势／语言／书籍"}},{"en":"extremely large in size or amount in a way that most people find unacceptable and offensive","cn":"（数量等）大得惊人的，骇人听闻的","ex":{"en":"He earns an obscene amount of money.","cn":"他赚钱多得吓人。"}}]}},"optician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"眼镜商；验光配镜师","en":"An optician is someone whose job involves testing people's sight, and making or selling glasses and contact lenses."},{"pos":"N-COUNT 可数名词","cn":"眼镜店","en":"An optician or an optician's is a shop where you can have your eyes tested and buy glasses and contact lenses.","ex":{"en":"Some may need specialist treatment at the optician's.","cn":"有些人可能需要到眼镜店进行专业验光。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who tests people’s eyes and sells glass es in a shop 〔","cn":"眼镜店的〕验光师﹐验光配镜技师﹔眼镜商"},{"en":"someone who makes lens es for glass es","cn":"镜片制造商"}]},"vocab":{"pos":"n","senses":[{"en":"The person who makes your eye glasses is an optician . They work in the back room of the glasses shop, or at a factory, fabricating the lenses and attaching them to the frames."}]},"collocations":{"phrases":["ADJ. dispensing, ophthalmic A dispensing optician supplies glasses, but doesn't test your eyes.","PHRASES at/to the optician's I've got to go to the optician's tomorrow. • Note at DOCTOR (for verbs)"]},"media":{"img":["media/ldoce/img/optician.jpg"],"uk":"media/ldoce/hwd/bre/c/optician0205.mp3","us":"media/ldoce/hwd/ame/5/optician.mp3"},"examples":[{"en":"to go to the optician's","cn":"去眼镜店"}],"oxford":{"phon":"ɒpˈtɪʃn","pos":"noun","senses":[{"en":"a person whose job is to examine people’s eyes and to recommend and sell glasses","cn":"眼镜商；验光师","lab":"both British English"},{"en":"a person whose job is to make and supply glasses, but who does not test people's eyes","cn":"配镜师","lab":"especially North American English"},{"en":"the shop where an optician works","cn":"眼镜店","ex":{"en":"to go to the optician’s","cn":"去配眼镜"}},{"en":"a person who makes lenses, glasses, etc.","cn":"光学仪器制造者"}]}},"oar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桨；橹","en":"Oars are long poles with a wide, flat blade at one end which are used for rowing a boat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to try to influence a situation that you should not be involved in, for example by telling someone what to do or giving them advice that they do not want","cn":""},{"en":"to interfere in a situation that you do not understand or know enough about, and that someone else is responsible for dealing with","cn":""},{"en":"to ask questions about someone else's private life and give them advice they do not want, in a way that annoys them","cn":""}]},"collocations":{"phrases":["VERB + OAR take We each took an oar. | pull on We pulled hard on the oars. | ship We shipped the oars to get through the narrow opening."]},"media":{"img":["media/ldoce/img/oars.jpg","media/thumb/oar.jpg"],"uk":"media/ldoce/hwd/bre/0/oar0205.mp3","us":"media/ldoce/hwd/ame/c/oar.mp3"},"examples":[{"en":"He pulled as hard as he could on the oars.","cn":"他拼命地划桨。"},{"en":"We were getting along fine until you stuck your oar in.","cn":"在你掺和进来之前﹐我们一直好好的。"}],"oxford":{"phon":"ɔː(r)","pos":"noun","senses":[{"en":"a long pole with a flat part at one end that is used for rowing a boat","cn":"船桨；桨","ex":{"en":"He pulled as hard as he could on the oars.","cn":"他拼命地划桨。"}}]}},"outrage":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使震怒;激怒","en":"If you are outraged by something, it makes you extremely shocked and angry.","ex":{"en":"Many people have been outraged by some of the things that have been said","cn":"其中的一些言论激怒了很多人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"愤慨；义愤","en":"Outrage is an intense feeling of anger and shock.","ex":{"en":"The decision provoked outrage from women and human rights groups","cn":"这一决定激起了妇女和人权组织的强烈愤慨。"}},{"pos":"N-COUNT 可数名词","cn":"暴行；骇人听闻的事件","en":"You can refer to an act or event which you find very shocking as an outrage .","ex":{"en":"The latest outrage was to have been a co-ordinated gun and bomb attack on the station","cn":"最近的一起暴行是同时动用了枪支和炸弹的对车站的袭击。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong feeling of anger","cn":""},{"en":"a very strong feeling of anger that is difficult to control or is expressed very suddenly or violently","cn":""},{"en":"extreme anger and shock because you think something is unfair or wrong","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you consider how people are treated in airports an outrage , you get really angry over airport security or the price of airport food. Six dollars for a piece of pizza? What an outrage !"}]},"collocations":{"phrases":["ADJ. genuine | widespread | international | public | moral Media reports generated moral outrage.","VERB + OUTRAGE be greeted with, cause, generate, provoke, spark The news was greeted with outrage. | feel | express, voice Shopkeepers voice","OUTRAGE + VERB be directed at sb/sth Much of the outrage was directed at foreign nationals.","PREP. in ~ The guests all shouted in outrage. | with ~ She was trembling with outrage. | ~ at Campaigners have expressed outrage at the deci","PHRASES cries/howls of outrage The announcement provoked howls of outrage. | a feeling/sense of outrage 2 cruel/shocking act","VERB + OUTRAGE commit, perpetrate the outrages committed by the invading army","PREP. ~ against The new law on pensions is an outrage against the elderly."]},"media":{"uk":"media/ldoce/hwd/bre/e/outrage_v0205.mp3","us":"media/ldoce/hwd/ame/f/outrage1.mp3"},"examples":[{"en":"No one has yet claimed responsibility for this latest bomb outrage.","cn":"迄今还没有人宣称对最近的爆炸暴行负责。"},{"en":"Environmentalists have expressed outrage at the ruling.","cn":"环境保护主义者对这一裁决表示愤慨。"}],"oxford":{"phon":"ˈaʊtreɪdʒ","pos":"noun","senses":[{"en":"a strong feeling of shock and anger","cn":"愤怒；义愤；愤慨","g":"[uncountable]","ex":{"en":"The judge's remarks caused public outrage.","cn":"裁判的话引起了公愤。"}},{"en":"an act or event that is violent, cruel or very wrong and that shocks people or makes them very angry","cn":"暴行；骇人听闻的事","g":"[countable]","ex":{"en":"No one has yet claimed responsibility for this latest terrorist outrage.","cn":"迄今还没有人宣称对最近的恐怖主义暴行负责。"}},{"en":"to make somebody very shocked and angry","cn":"使震怒；激怒","ex":{"en":"He was outraged at the way he had been treated.","cn":"他对所遭受的待遇感到非常愤怒。"},"pos":"verb"},{"en":"a former British organization that worked for the rights of LGBT people. OutRage! started in 1990 and became well known for its use of direct action which it often combined with humour, as in the ‘Queer St Valentine's Day Carnival’. One of OutRage's best-known campaigners was the author and political activist Peter Tatchell. OutRage! closed down in 2011.","cn":"曾为英国同性恋，双性恋和变性者权利工作的前英国组织。暴行！成立于1990年，以“直接行动”（通常与幽默相结合）而闻名，例如“ Queer St Valentine's Day Carnival”。作者和政治活动家彼得·塔切尔（Peter Tatchell）是OutRage最著名的活动家之一。暴行！在2011年关闭。","pos":""}]}},"objection":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不喜欢;反对;异议","en":"If you make or raise an objection to something, you say that you do not like it or agree with it.","ex":{"en":"Some managers have recently raised objection to the PFA handling these negotiations","cn":"一些主教练最近就英格兰职业足球运动员协会负责这些谈判提出了异议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恼火；烦心","en":"If you say that you have no objection to something, you mean that you are not annoyed or bothered by it.","ex":{"en":"I have no objection to banks making money","cn":"我对银行营利并不抵触。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An objection is a way of saying \"No!\" to something. People offer objections to things they oppose."}]},"collocations":{"phrases":["ADJ. serious, strenuous, strong | valid | main, major, principal | fundamental | common","VERB + OBJECTION lodge, make, raise, state | have I'd like to open a window, unless anyone has any objections. | meet, overcome | withdraw","PREP. over the ~s of She was appointed over the objections of certain members of the board. | ~ against a common objection against nuclear p"]},"media":{"uk":"media/ldoce/hwd/bre/7/objection0205.mp3","us":"media/ldoce/hwd/ame/3/objection.mp3"},"examples":[{"en":"The proposal will go ahead despite strong objections from the public.","cn":"尽管公众强烈反对，这项提案仍将付诸实施。"},{"en":"The main objection to the plan was that it would cost too much.","cn":"反对这个计划的主要理由是费用过高。"}],"oxford":{"phon":"əbˈdʒekʃn","pos":"noun","senses":[{"en":"a reason why you do not like or are opposed to something; a statement about this","cn":"反对的理由；反对；异议","ex":{"en":"I'd like to come too, if you have no objection.","cn":"如果你不反对，我也想来。"}}]}},"orgy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指纵欲的）狂欢聚会","en":"An orgy is a party in which people behave in a very uncontrolled way, especially one involving sexual activity.","ex":{"en":"It was reminiscent of a scene from a Roman orgy.","cn":"这一幕让人想起古罗马荒淫的狂欢宴会。"}},{"pos":"N-COUNT 可数名词","cn":"放纵；无节制","en":"You can refer to an activity as an orgy of that activity to emphasize that it is done to an excessive extent.","ex":{"en":"One eyewitness said the rioters were engaged in an orgy of destruction","cn":"一位目击者称暴徒肆无忌惮地到处进行破坏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to have sex with many different people over a period of time, usually without having a serious relationship with any of them","cn":""},{"en":"when someone has sex with someone without intending to have a serious relationship with them, especially when they do this many times","cn":""},{"en":"someone who is promiscuous has sex with many different people, usually without having a serious relationship with any of them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you have an orgy of presents or snacks or even new ideas, you have so many it's almost obscene. In this figurative use, orgy means an event where there is just too much of a good thing!"}]},"collocations":{"phrases":["ADJ. drunken, sex/sexual","VERB + ORGY have","PREP. ~ of an orgy of looting and vandalism"]},"media":{"uk":"media/ldoce/hwd/bre/6/orgy0205.mp3","us":"media/ldoce/hwd/ame/2/orgy.mp3"},"examples":[{"en":"The rebels went on an orgy of killing.","cn":"叛乱者肆意杀人。"},{"en":"a drunken orgy","cn":"纵酒狂欢会"}],"oxford":{"phon":"ˈɔːdʒi","pos":"noun","senses":[{"en":"a party at which there is a lot of eating, drinking and sexual activity","cn":"淫乐的聚会；狂欢会","ex":{"en":"a drunken orgy","cn":"纵酒狂欢会"}},{"en":"an extreme amount of a particular activity","cn":"放纵；放荡","lab":"disapproving","ex":{"en":"The rebels went on an orgy of killing.","cn":"叛乱者肆意杀人。"}}]}},"overjoyed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欣喜若狂的；万分高兴的","en":"If you are overjoyed, you are extremely pleased about something.","ex":{"en":"Shelley was overjoyed to see me","cn":"谢利见到我万分高兴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very happy because something good has happened","cn":""},{"en":"very happy and excited about something","cn":""},{"en":"very happy because you have heard some good news","cn":""}]},"collocations":{"phrases":["VERBS be, look, seem, sound","ADV. less than, not exactly She was not exactly overjoyed to see us again.","PREP. about They're all overjoyed about it. | at overjoyed at the thought of having a son | by We are overjoyed by this decision. | with Mr "]},"media":{"uk":"media/ldoce/hwd/bre/9/overjoyed0205.mp3","us":"media/ldoce/hwd/ame/6/overjoyed.mp3"},"examples":[{"en":"We were overjoyed to hear their good news.","cn":"听到他们的好消息，我们都大喜过望。"},{"en":"She was overjoyed that her article had been published.","cn":"她的文章发表了，这使她高兴极了。"}],"oxford":{"phon":"ˌəʊvəˈdʒɔɪd","pos":"adjective","senses":[{"en":"extremely happy or pleased","cn":"非常高兴；欣喜若狂","ex":{"en":"He was overjoyed at my success.","cn":"我的成功使他欣喜若狂。"}}]}},"ottawa":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of Canada, in the southeast of the country. One third of its people are French-speaking.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000009388.mp3","us":"media/ldoce/hwd/ame/2/p028-000009388.mp3"},"oxford":{"phon":"ˈɒtəwə","pos":"","senses":[{"en":"the capital city of Canada, situated in south-eastern Ontario on the Ottawa River","cn":"渥太华（加拿大首都，位于安大略东南部，渥太华河畔）"}]}},"ornate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"装饰华丽的；修饰繁复的","en":"An ornate building, piece of furniture, or object is decorated with complicated patterns or shapes.","ex":{"en":"...an ornate iron staircase.","cn":"装饰华丽的铁艺楼梯"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"fancy clothes, patterns etc have a lot of decoration or bright colours - use this especially when you think something has too much decoration","cn":""},{"en":"an ornate object, picture, or part of a building has a lot of expensive or complicated decoration on it","cn":""},{"en":"carefully and skilfully decorated with a lot of small details","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is ornate — whether it's a ball gown, a set of dishes, or a poem — it seems to be covered in ornaments. It's lavish, flowery, or heavily adorned."}]},"collocations":{"phrases":["VERBS be","ADV. highly, richly, very | quite, rather"]},"media":{"img":["media/ldoce/img/ldoce_244.png"],"uk":"media/ldoce/hwd/bre/5/ornate0205.mp3","us":"media/ldoce/hwd/ame/d/ornate.mp3"},"examples":[{"en":"a mirror in an ornate gold frame","cn":"镶着豪华金框的镜子"},{"en":"ornately carved chairs","cn":"精雕细刻的椅子"}],"oxford":{"phon":"ɔːˈneɪt","pos":"adjective","senses":[{"en":"covered with a lot of decoration, especially when this involves very small or complicated designs","cn":"华美的；富丽的；豪华的","ex":{"en":"a mirror in an ornate gold frame","cn":"镶着雕饰金框的镜子"}}]}},"ozone":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"臭氧","en":"Ozone is a colourless gas which is a form of oxygen. There is a layer of ozone high above the earth's surface.","ex":{"en":"Ozone is best known for its role in screening the Earth from harmful ultraviolet rays from the Sun","cn":"臭氧最广为人知的作用是保护地球免受太阳紫外线的伤害。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a poisonous blue gas that is a type of oxygen","cn":"臭氧"},{"en":"air near the sea, thought to be fresher and healthier 〔","cn":"近海处的〕清新空气"}]},"vocab":{"pos":"n","senses":[{"en":"Ozone is a colorless toxic gas formed from oxygen by an electrical discharge. It’s that stuff in the sky that comes between you and the sun."}]},"collocations":{"phrases":["VERB + OZONE deplete, destroy","OZONE + NOUN levels | depletion, destruction, loss | hole | pollution","PHRASES the loss of/reduction in ozone the discovery of massive springtime reductions in ozone over Antarctica"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41ozone.mp3","us":"media/ldoce/hwd/ame/3/ozone.mp3"},"oxford":{"phon":"ˈəʊzəʊn","pos":"noun","senses":[{"en":"a poisonous gas with a strong smell that is a form of oxygen","cn":"臭氧","lab":"chemistry","ex":{"en":"Ozone is formed when an electric spark is passed through oxygen.","cn":"电火花遇到氧气会产生臭氧。"}},{"en":"air near the sea that smells fresh and pure","cn":"海边的清新空气","lab":"British English, informal，，"}]}},"ombudsman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调查官；巡视官；申诉专员","en":"The ombudsman is an independent official who has been appointed to investigate complaints that people make against the government or public organizations.","ex":{"en":"The leaflet explains how to complain to the banking ombudsman.","cn":"这份传单介绍了如何向银行意见调查官投诉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who deals with complaints made by ordinary people against the government, banks, insurance companies etc","cn":"民情调查员﹐巡视官﹐申诉专员〔专门处理民众对政府﹑银行﹑保险公司等投诉的人〕"}]},"vocab":{"pos":"n","senses":[{"en":"In the U.S., your congressman is considered your unofficial ombudsman or the state official who investigates and makes sure the government is acting in the best interest of its citizens."}]},"collocations":{"phrases":["ADJ. consumer, insurance, local government, pensions A pensions ombudsman has been appointed.","VERB + OMBUDSMAN appoint"]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41ombudsman.mp3","us":"media/ldoce/hwd/ame/c/ombudsman.mp3"},"oxford":{"phon":"ˈɒmbʊdzmən","pos":"noun","senses":[{"en":"an official whose job is to examine and report on complaints made by ordinary people about companies, the government or public authorities","cn":"政府巡查员（政府处理民众诉愿的官员）","ex":{"en":"A pensions ombudsman has been appointed.","cn":"已任命一名养老金监察专员。"}}]}},"overdose":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（药物等的）过量；致死（或中毒）剂量","en":"If someone takes an overdose of a drug, they take more of it than is safe.","ex":{"en":"Each year, one in 100 girls aged 15-19 takes an overdose","cn":"每年，每100名15至19岁的少女中就有1位嗑药过量。"}},{"pos":"VERB 动词","cn":"过量服用（药物）；过量吸食（毒品）","en":"If someone overdoses on a drug, they take more of it than is safe.","ex":{"en":"He'd overdosed on heroin","cn":"他曾过量吸食海洛因。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指有害物的）过量，过多","en":"You can refer to too much of something, especially something harmful, as an overdose.","ex":{"en":"An overdose of sun, sea, sand and chlorine can give lighter hair a green tinge.","cn":"过量接触阳光、海水、沙粒和氯气会使浅色头发略呈绿色。"}},{"pos":"VERB 动词","cn":"过多拥有；沉溺","en":"You can say that someone overdoses on something if they have or do too much of it.","ex":{"en":"The city, he concluded, had overdosed on design.","cn":"他的结论是这座城市过分重视规划设计了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to take a dangerously large amount of a drug, usually deliberately","cn":""},{"en":"to take a dangerously large amount of a particular drug, usually by accident","cn":""},{"en":"to take a dangerously large amount of a drug, usually deliberately","cn":""}]},"collocations":{"phrases":["ADJ. large, massive | drug/drugs, heroin, paracetamol, etc. | fatal | accidental","VERB + OVERDOSE take | die from/of","PREP. ~ of She took an overdose of paracetamol."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeoverdose.mp3","us":"media/ldoce/hwd/ame/5/overdose.mp3"},"examples":[{"en":"She took a massive overdose of sleeping pills.","cn":"她服用了过量的安眠药。"},{"en":"( figurative ) I had overdosed on sun.","cn":"我晒太阳的时间过长了。"}],"oxford":{"phon":"ˈəʊvədəʊs","pos":"noun","senses":[{"en":"too much of a drug taken at one time, so that it is dangerous","cn":"（一次用药）过量；剂量过大","ex":{"en":"a drug/drugs overdose","cn":"药物剂量过大"}},{"en":"to take too much of a drug at one time, so that it is dangerous","cn":"一次用药过量","lab":"figurative","ex":{"en":"He had overdosed on heroin.","cn":"他过量服用了海洛因。"},"pos":"verb"}]}},"obstruction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路障；障碍（物）","en":"An obstruction is something that blocks a road or path.","ex":{"en":"John was irritated by drivers parking near his house and causing an obstruction.","cn":"约翰对那些在他家附近泊车堵住通道的司机感到恼火。"}},{"pos":"N-VAR 可变名词","cn":"（体内的）梗阻","en":"An obstruction is something that blocks a passage in your body.","ex":{"en":"The boy was suffering from a bowel obstruction and he died.","cn":"这个男孩因患肠梗阻死去了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（通常指对生意、法律或政府的）阻挠，妨碍","en":"Obstruction is the act of deliberately delaying something or preventing something from happening, usually in business, law, or government.","ex":{"en":"Mr Guest refused to let them in and now faces a criminal charge of obstruction.","cn":"格斯特先生因为将他们拒之门外，现在面临妨碍公务的刑事指控。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something blocks a road, passage, tube etc, or the thing that blocks it 〔","cn":"道路﹑通道﹑管道等的〕堵塞(物)﹐阻塞(物)"},{"en":"when someone or something prevents or delays a legal or political process 〔","cn":"对司法或政治程序的〕阻挠﹐妨碍；拖延"},{"en":"an offence in football, hockey etc in which a player gets between an opponent and the ball 〔","cn":"足球﹑曲棍球等比赛中的〕阻挡(犯规)"}]},"vocab":{"pos":"n","senses":[{"en":"An obstruction blocks things, like a roadblock prevents drivers to enter a street or a piece of food cuts off your windpipe."}]},"collocations":{"phrases":["ADJ. physical | unlawful, wilful (law) | bureaucratic The asylum seekers had to contend with continued bureaucratic obstruction.","VERB + OBSTRUCTION cause, create The lorry had been parked on the pavement, causing an obstruction. | clear, remove She had to have surgery "]},"media":{"uk":"media/ldoce/hwd/bre/9/obstruction0205.mp3","us":"media/ldoce/hwd/ame/3/obstruction.mp3"},"examples":[{"en":"He was arrested for obstruction of a police officer in the execution of his duty.","cn":"他因妨碍警察执行公务而被逮捕。"},{"en":"It is my job to make sure that all pathways are clear of obstructions.","cn":"保证所有的道路通畅是我的职责。"}],"oxford":{"phon":"əbˈstrʌkʃn","pos":"noun","senses":[{"en":"the fact of trying to prevent something/somebody from making progress","cn":"阻挡；阻碍；妨碍","g":"[uncountable, countable]","ex":{"en":"the obstruction of justice","cn":"妨碍司法公正"}},{"en":"the fact of blocking a road, an entrance, a passage, etc.","cn":"堵塞，阻挡（通道等）","g":"[uncountable, countable]","ex":{"en":"obstruction of the factory gates","cn":"对工厂大门的堵塞"}},{"en":"something that blocks a road, an entrance, etc.","cn":"路障；障碍；障碍物","g":"[countable]","ex":{"en":"It is my job to make sure that all pathways are clear of obstructions.","cn":"保证所有的道路通畅是我的职责。"}},{"en":"something that blocks a passage or tube in your body; a medical condition resulting from this","cn":"梗阻；阻塞；栓塞","g":"[countable, uncountable]","lab":"medical","ex":{"en":"He had an operation to remove an obstruction in his throat.","cn":"他做了手术，取出喉头的阻塞物。"}},{"en":"the offence of unfairly putting your body in front of a player of the other team so they cannot move to get the ball","cn":"（球类运动）阻挡犯规","g":"[uncountable]","lab":"sport"}]}},"obstructive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"故意刁难的；蓄意阻挠的","en":"If you say that someone is being obstructive, you think that they are deliberately causing difficulties for other people.","ex":{"en":"Mr Smith was obstructive and refused to follow correct procedure.","cn":"史密斯先生故意刁难，就是不肯照章办事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"trying to prevent someone from doing something, by deliberately making it difficult for them","cn":"蓄意阻挠的﹐故意妨碍的"},{"en":"relating to a blocked tube, passage etc in the body","cn":"梗阻的﹐阻塞的"}]},"collocations":{"phrases":["VERBS be | become","ADV. positively | quite | deliberately He doesn't really have an alternative suggestion; he's just being deliberately obstructive."]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41obstructive.mp3","us":"media/ldoce/hwd/ame/4/obstructive.mp3"},"examples":[{"en":"Of course she can do it. She's just being deliberately obstructive.","cn":"这事她当然能做。她只是在刻意阻挠罢了。"},{"en":"obstructive lung disease","cn":"肺阻塞疾病"}],"oxford":{"phon":"əbˈstrʌktɪv","pos":"adjective","senses":[{"en":"trying to prevent somebody/something from making progress","cn":"阻挠；妨碍；阻止","ex":{"en":"Of course she can do it. She's just being deliberately obstructive.","cn":"这事她当然能做。她只是在刻意阻挠罢了。"}},{"en":"connected with a passage, tube, etc. in your body that has become blocked","cn":"梗阻的；阻塞的；栓塞的","g":"[only before noun]","lab":"medical","ex":{"en":"obstructive lung disease","cn":"肺阻塞疾病"}}]}},"outskirts":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"市郊；郊区","en":"The outskirts of a city or town are the parts of it that are farthest away from its centre.","ex":{"en":"Hours later we reached the outskirts of New York.","cn":"我们几小时后到达了纽约市郊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of something that is furthest from its centre or nearest the place where it ends","cn":""},{"en":"the part of something that is near its left or right edge","cn":""},{"en":"the edge of something circular, especially the top of a cup or glass, or the outside edge of a pair of glasses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Some people like to live downtown. Others prefer the open spaces of the suburbs. But if you live in between the two, you are in the outskirts , the place where the city ends and the suburbs begin."}]},"collocations":{"phrases":["ADJ. sprawling | city | northern, etc.","VERB + OUTSKIRTS reach","PREP. in the ~ a school in the outskirts of Athens | on the ~ We live on the outskirts of Leeds. | through the ~ driving through the outskir"]},"media":{"uk":"media/ldoce/hwd/bre/1/outskirts0205.mp3","us":"media/ldoce/hwd/ame/e/outskirts.mp3"},"examples":[{"en":"They live on the outskirts of Milan.","cn":"他们住在米兰市郊。"},{"en":"They live on the outskirts of Paris.","cn":"他们住在巴黎的郊区。"}],"oxford":{"phon":"ˈaʊtskɜːts","pos":"noun","senses":[{"en":"the parts of a town or city that are furthest from the centre","cn":"（市镇的）边缘地带；市郊","ex":{"en":"They live on the outskirts of Milan.","cn":"他们住在米兰市郊。"}}]}},"onion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"洋葱；洋葱头","en":"An onion is a round vegetable with a brown skin that grows underground. It has many white layers on its inside which have a strong, sharp smell and taste.","ex":{"en":"Will you chop an onion up for me?","cn":"你能帮我把一个洋葱切碎吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round white vegetable with a brown, red, or white skin and many layers. Onions have a strong taste and smell","cn":"洋葱（头）"}]},"collocations":{"phrases":["ADJ. raw | pickled | spring, red, Spanish","VERB + ONION chop, peel, slice | brown, soften | cook, fry, saute | garnish sth with Garnish with a little chopped spring onion. | grow","ONION + NOUN ring | soup | skin | set | dome","PHRASES cheese and onion cheese and onion flavoured crisps | sage and onion sage and onion stuffing •"]},"media":{"img":["media/ldoce/img/onion.jpg","media/thumb/onion.jpg"],"uk":"media/ldoce/hwd/bre/1/onion0205.mp3","us":"media/ldoce/hwd/ame/d/onion.mp3"},"examples":[{"en":"Chop the onions finely.","cn":"把洋葱切碎。"},{"en":"French onion soup","cn":"法式洋葱汤"}],"oxford":{"phon":"ˈʌnjən","pos":"noun","senses":[{"en":"a round vegetable with many layers inside each other and a brown, red or white skin. Onions have a strong smell and taste.","cn":"洋葱；葱头","ex":{"en":"Chop the onions finely.","cn":"把洋葱切细。"}}]}},"overload":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使超载；使负载过重","en":"If you overload something such as a vehicle, you put more things or people into it than it was designed to carry.","ex":{"en":"Don't overload the boat or it will sink","cn":"别超载，否则船会沉。"}},{"pos":"VERB 动词","cn":"使负担过重；给予…过多的工作（或问题、信息等）","en":"To overload someone with work, problems, or information means to give them more work, problems, or information than they can cope with.","ex":{"en":"...an effective method that will not overload staff with yet more paperwork.","cn":"不会再以更多的文书工作加重员工负荷的有效办法"}},{"pos":"VERB 动词","cn":"使（电力系统）过载；使超过负荷","en":"If you overload an electrical system, you cause too much electricity to flow through it, and so damage it.","ex":{"en":"Never overload an electrical socket.","cn":"千万不要使电源插座过载。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be carrying a lot of things, so that you cannot carry any more","cn":""},{"en":"to be carrying or holding so many things that it is difficult to move or impossible to hold any more","cn":""},{"en":"if someone or something falls or moves unsteadily under the weight of of something, they do this because they are carrying something that is too heavy for them to support","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To overload is to load an excessive amount in or on something, such as an overload of electricity which shorts out the circuits. Overloading causes a \"Too much!\" situation."}]},"collocations":{"phrases":["PREP. with Their staff are heavily overloaded with work.","PHRASES be heavily/seriously overloaded"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeoverload.mp3","us":"media/ldoce/hwd/ame/9/overload.mp3"},"examples":[{"en":"In these days of technological change we all suffer from information overload.","cn":"在这科技日新月异的时代，过多的信息使人人都应接不暇。"},{"en":"Don't overload the students with information.","cn":"不要给学生灌输过多的知识。"}],"oxford":{"phon":"ˌəʊvəˈləʊd","pos":"verb","senses":[{"en":"to put too great a load on something","cn":"使超载；使负荷过重","ex":{"en":"an overloaded truck","cn":"一辆超载的卡车"}},{"en":"to give somebody too much of something","cn":"使…负担过重","ex":{"en":"He's overloaded with responsibilities.","cn":"他担负的责任过多。"}},{"en":"to put too great a demand on a computer, an electrical system, etc. causing it to fail","cn":"使（计算机）超载运行；使（电路）超负荷","ex":{"en":"The lights went out because the system was overloaded.","cn":"由于线路过载，电灯灭了。"}},{"en":"too much of something","cn":"过多；过量；超负荷","ex":{"en":"In these days of technological change we all suffer from information overload.","cn":"在这科技日新月异的时代，过多的信息使人人都应接不暇。"},"pos":"noun"}]}},"obituary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（报纸上或广播里的）讣告，讣闻","en":"Someone's obituary is an account of their life and character which is printed in a newspaper or broadcast soon after they die.","ex":{"en":"I read your brother's obituary in the Times.","cn":"我在《泰晤士报》上看到了你哥哥的讣告。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an article in a newspaper about the life of someone who has just died 〔","cn":"报纸上的〕讣告﹐讣闻﹐讣文"}]},"vocab":{"pos":"n","senses":[{"en":"An obituary is the notice of someone's death. It is placed in the newspaper to alert others to the death. It gives a background about the deceased's life, usually listing survivors and giving funeral information."}]},"collocations":{"phrases":["VERB + OBITUARY write | print, publish | read","OBITUARY + NOUN column, page"]},"media":{"uk":"media/ldoce/hwd/bre/6/obituary0205.mp3","us":"media/ldoce/hwd/ame/2/obituary.mp3"},"oxford":{"phon":"əˈbɪtʃuəri","pos":"noun","senses":[{"en":"an article about somebody’s life and achievements, that is printed in a newspaper soon after they have died","cn":"讣闻；讣告","ex":{"en":"an obituary column/notice","cn":"讣告栏/通知"}}]}},"omission":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"省略的东西;删节的东西；遗漏的东西","en":"An omission is something that has not been included or has not been done, either deliberately or accidentally.","ex":{"en":"The duke was surprised by his wife's omission from the guest list.","cn":"公爵对他的夫人未在获邀宾客之列感到意外。"}},{"pos":"N-VAR 可变名词","cn":"省略；删节；排除；遗漏；疏忽","en":"Omission is the act of not including a particular person or thing or of not doing something.","ex":{"en":"...the prosecution's seemingly malicious omission of recorded evidence.","cn":"控方似乎恶意将录下的证据排除在外的做法"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you do not include or do not do something","cn":"省略﹔删节﹔遗漏"},{"en":"something that has been omitted","cn":"省略的东西﹔遗漏的东西"}]},"vocab":{"pos":"n","senses":[{"en":"If you make an omission , you leave something out. If you are a restaurant reviewer and you give a glowing a new restaurant but fail to mention that you own half of it, that's a significant omission ."}]},"collocations":{"phrases":["ADJ. important, major, serious | complete | glaring, notable, obvious | curious, strange, surprising | deliberate | inadvertent","VERB + OMISSION correct, rectify, remedy","PREP. by ~ Several offences such as manslaughter may be committed by omission. | ~ from her omission from the guest list","PHRASES an act or omission The accident was not caused by any act or omission of the transport company. | errors and/or omissions, a sin of "]},"media":{"uk":"media/ldoce/hwd/bre/c/omission0205.mp3","us":"media/ldoce/hwd/ame/0/omission.mp3"},"examples":[{"en":"Everyone was surprised at her omission from the squad.","cn":"她未列入该小组使大家感到惊讶。"},{"en":"There were a number of errors and omissions in the article.","cn":"这篇文章中有多处错误和疏漏。"}],"oxford":{"phon":"əˈmɪʃn","pos":"noun","senses":[{"en":"the act of not including somebody/something or not doing something; the fact of not being included or done","cn":"省略；删除；免除","g":"[uncountable]","ex":{"en":"Everyone was surprised at her omission from the squad.","cn":"她未入选该小组使大家感到惊讶。"}},{"en":"a thing that has not been included or done","cn":"遗漏；疏忽","g":"[countable]","ex":{"en":"There were a number of errors and omissions in the article.","cn":"这篇文章中有多处错误和疏漏。"}}]}},"overcoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大衣；厚外套","en":"An overcoat is a thick warm coat that you wear in winter."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thick warm coat","cn":"大衣"}]},"collocations":{"phrases":["ADJ. long | heavy, thick | dark | tweed •"]},"media":{"uk":"media/ldoce/hwd/bre/3/overcoat0205.mp3","us":"media/ldoce/hwd/ame/a/overcoat.mp3","img":["media/thumb/overcoat.jpg"]},"oxford":{"phon":"ˈəʊvəkəʊt","pos":"noun","senses":[{"en":"a long warm coat worn in cold weather","cn":"长大衣"}]}},"ooze":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"渗出；冒出；分泌出","en":"When a thick or sticky liquid oozes from something or when something oozes it, the liquid flows slowly and in small quantities.","ex":{"en":"He saw there was a big hole in the back of the man's head, blood was still oozing from it","cn":"他看到这个男人后脑勺上有道大口子，血还在往外渗。"}},{"pos":"VERB 动词","cn":"凸显，洋溢（特性或特点）","en":"If you say that someone or something oozes a quality or characteristic, or oozes with it, you mean that they show it very strongly.","ex":{"en":"Outwardly, Graham will ooze all his old confidence","cn":"格雷厄姆表面上看起来会像过去一样满怀信心。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指河、湖、海底的）软泥，淤泥，泥浆","en":"You can refer to any thick, sticky, liquid substance as ooze, especially the mud at the bottom of a river, lake, or the sea.","ex":{"en":"...a primeval ooze","cn":"原始软泥"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if liquid flows, it moves in a steady continuous stream","cn":""},{"en":"to flow – used when saying that something flows in a particular direction","cn":""},{"en":"to flow out of something","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The beauty of the word ooze is not only that it's both a noun and a verb but also that the word sounds like what it means. The ooze on the bottom of the pond oozed between your toes."}]},"collocations":{"phrases":["ADV. slowly | out Cream oozed out at the sides.","PREP. from Blood oozed slowly from his wound. | out of, with (figurative) He was oozing with contempt for us."]},"media":{"uk":"media/ldoce/hwd/bre/3/ooze_n0205.mp3","us":"media/ldoce/hwd/ame/4/ooze1.mp3"},"examples":[{"en":"She walked into the party oozing confidence.","cn":"她信心十足地来到聚会上。"},{"en":"a plate of toast oozing butter","cn":"一盘渗着黄油的烤面包片"}],"oxford":{"phon":"uːz","pos":"verb","senses":[{"en":"if a thick liquid oozes from a place, or if something oozes a thick liquid, the liquid flows from the place slowly","cn":"（浓液体）渗出，慢慢流出","g":"[intransitive, transitive]","ex":{"en":"Blood oozed out of the wound.","cn":"血从伤口慢慢流出来。"}},{"en":"to show a particular quality or feeling strongly; (of a particular quality or feeling) to be shown strongly","cn":"洋溢着，充满（某种特质或情感）；（某种特质或情感）尽显，洋溢","g":"[transitive, intransitive]","ex":{"en":"She walked into the party oozing confidence.","cn":"她信心十足地来到聚会上。"}},{"en":"very soft mud, especially at the bottom of a lake or river","cn":"（河床、湖底的）泥浆，稀泥","g":"[uncountable]","pos":"noun"},{"en":"the very slow flow of a thick liquid","cn":"（浓液的）缓慢渗出","g":"[singular]","pos":"noun"}]}},"oversee":{"collins":{"senses":[{"pos":"VERB 动词","cn":"监督；监视；监管","en":"If someone in authority oversees a job or an activity, they make sure that it is done properly.","ex":{"en":"Use a surveyor or architect to oversee and inspect the different stages of the work.","cn":"请一位房产检视员或建筑师来监督并检查不同阶段的工作。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you are in charge of an activity or a group of people, you are the person who has the authority to control what happens, tell other people what to do etc","cn":""},{"en":"to be the person who makes the important decisions about what will happen in a business, organization, country etc","cn":""},{"en":"to be in charge of a business, especially one that is owned by someone else","cn":""}]},"collocations":{"phrases":["ADV. directly | personally He personally oversaw the design of all the rooms.","VERB + OVERSEE be appointed to, be created to, be set up to A committee has been appointed to oversee the work.","PHRASES be responsible for overseeing sth the committee that is responsible for overseeing the day-to-day implementation of this policy"]},"media":{"uk":"media/ldoce/hwd/bre/3/oversee0205.mp3","us":"media/ldoce/hwd/ame/5/oversee.mp3"},"examples":[{"en":"A team leader was appointed to oversee the project.","cn":"任命了一位组长来监管该工程。"}],"oxford":{"phon":"ˌəʊvəˈsiː","pos":"verb","senses":[{"en":"to watch somebody/something and make sure that a job or an activity is done correctly","cn":"监督；监视","ex":{"en":"United Nations observers oversaw the elections.","cn":"联合国观察员监督了选举。"}}]}},"overdraft":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"透支；透支额","en":"If you have an overdraft, you have spent more money than you have in your bank account, and so you are in debt to the bank.","ex":{"en":"When I left Cambridge I had a £10,000 overdraft","cn":"我离开剑桥时，透支了1万英镑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that is borrowed, especially from a bank or company, which you agree to pay back by the end of a period of time","cn":""},{"en":"a large amount of money that someone borrows from a bank or company to buy a house","cn":""},{"en":"money that you pay for borrowing money, especially that you pay every year or every month at a fixed rate","cn":""}]},"collocations":{"phrases":["ADJ. enormous, huge, large | agreed, authorized | unauthorized | free We offer a free &pound; 400 overdraft. | bank","VERB + OVERDRAFT have | get, take out | run up The president ran up a huge overdraft during her year in office. | arrange | extend, give sb,","OVERDRAFT + NOUN facility | limit"]},"media":{"uk":"media/ldoce/hwd/bre/8/overdraft0205.mp3","us":"media/ldoce/hwd/ame/4/overdraft.mp3"},"examples":[{"en":"to run up/pay off an overdraft","cn":"透支；付清透支"},{"en":"Many students have a free overdraft facility (= agreement with their bank to have an overdraft up to a particular limit ) .","cn":"许多学生都能享受免费透支服务。"}],"oxford":{"phon":"ˈəʊvədrɑːft","pos":"noun","senses":[{"en":"the amount of money that you owe to a bank when you have spent more money than is in your bank account; an arrangement that allows you to do this","cn":"透支额；透支安排","lab":"informal","ex":{"en":"She had run up an overdraft of £3 000.","cn":"她已经透支了 3 000 英镑"}}]}},"odour":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"气味","en":"An odour is a particular and distinctive smell.","ex":{"en":"The whole herb has a characteristic taste and odour","cn":"整株药草有种独特的味道和气味。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you can recognize by breathing in through your nose","cn":""},{"en":"something that you smell for a short time","cn":""},{"en":"a smell – used especially about the pleasant smell from flowers, plants, or fruit. Also used about the smell left by an animal","cn":""}]},"collocations":{"phrases":["ADJ. foul, obnoxious, offensive, unpleasant | musty, stale | heavy, pungent, strong | faint | sweet | characteristic, distinctive, familiar,","VERB + ODOUR emit, give off","ODOUR + VERB emanate from sth","PREP. ~ from odours from the local brewery"]},"media":{"uk":"media/ldoce/hwd/bre/5/odour0205.mp3","us":"media/ldoce/hwd/ame/c/laadodor.mp3"},"examples":[{"en":"the stale odour of cigarette smoke","cn":"香烟的臭味"},{"en":"( figurative ) the odour of suspicion","cn":"事情很可疑"}],"oxford":{"phon":"ˈəʊdə(r)","pos":"noun","senses":[{"en":"a smell, especially one that is unpleasant","cn":"（尤指难闻的）气味；臭味","lab":"figurative","ex":{"en":"a foul/musty/pungent, etc. odour","cn":"难闻的气味、难闻的霉味、刺鼻的气味等"}}]}},"obligation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"义务;责任","en":"If you have an obligation to do something, it is your duty to do that thing.","ex":{"en":"When teachers assign homework, students usually feel an obligation to do it","cn":"老师布置作业时，学生通常认为完成作业是一种义务。"}},{"pos":"N-VAR 可变名词","cn":"(照顾某人或保护某人利益的)义务，责任","en":"If you have an obligation to a person, it is your duty to look after them or protect their interests.","ex":{"en":"The United States will do that which is necessary to meet its obligations to its own citizens","cn":"美国将为自己的公民尽其应尽的义务。"}},{"pos":"PHRASE 短语","cn":"(广告中产品或服务)免费试用地，免费体验地","en":"In advertisements, if a product or a service is available without obligation, you do not have to pay for that product or service until you have tried it and are satisfied with it.","ex":{"en":"If you are selling your property, why not call us for a free valuation without obligation?","cn":"如果您打算出售房产，何不打电话让我们作免费估价呢？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do not have to do something, you can do it if you want, but you are not forced to do it, either by a rule or by another person, or by the situation you are in","cn":""},{"en":"say this to tell someone that it is not necessary for them to do something","cn":""},{"en":"if something is unnecessary or not necessary , it is not needed or there is no good reason for you to do it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An obligation is a duty. It's your obligation or responsibility to call your mom on Mother's Day. Sending flowers would be even better."}]},"collocations":{"phrases":["ADJ. contractual, legal, statutory | moral, social | financial | family I can't travel next month because of family obligations. | professio","VERB + OBLIGATION discharge, fulfil, meet The builders failed to meet their contractual obligations. | comply with, honour | have We have a ","OBLIGATION + VERB arise from sth obligations arising from your contract of employment","PREP. under an ~ I am under no obligation to tell you my name. | without ~ Our mortgage advice is given free and without obligation. | ~ to "]},"media":{"uk":"media/ldoce/hwd/bre/d/obligation0205.mp3","us":"media/ldoce/hwd/ame/a/obligation.mp3"},"examples":[{"en":"We will send you an estimate for the work without obligation (= you do not have to accept it).","cn":"我们将寄上工程报价，以作参考。"},{"en":"They reminded him of his contractual obligations.","cn":"他们提醒他注意合同规定的义务。"}],"oxford":{"phon":"ˌɒblɪˈɡeɪʃn","pos":"noun","senses":[{"en":"the state of being forced to do something because it is your duty, or because of a law, etc.","cn":"义务；职责；责任","g":"[uncountable]","ex":{"en":"You are under no obligation to buy anything.","cn":"你不必非买什么东西不可。"}},{"en":"something which you must do because you have promised, because of a law, etc.","cn":"（已承诺的或法律等规定的）义务，责任","g":"[countable]","ex":{"en":"legal/professional/financial obligations","cn":"法律／职业／财政义务"}}]}},"oblivion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无意识状态;沉睡;昏迷","en":"Oblivion is the state of not being aware of what is happening around you, for example because you are asleep or unconscious.","ex":{"en":"He just drank himself into oblivion","cn":"他喝得完全不省人事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"被遗忘的状态；湮没","en":"Oblivion is the state of having been forgotten or of no longer being considered important.","ex":{"en":"It seems that the so-called new theory is likely to sink into oblivion.","cn":"这所谓的新理论看来将很可能被人淡忘。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"被摧毁；被毁灭；被夷为平地","en":"If you say that something is bombed or blasted into oblivion, you are emphasizing that it is completely destroyed.","ex":{"en":"An entire poor section of town was bombed into oblivion.","cn":"城市的一整片贫民区被炸为了平地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is completely forgotten or no longer important","cn":"被完全忘却﹐被遗忘"},{"en":"the state of being unconscious or of not noticing what is happening","cn":"无意识[知觉]的状态﹔昏迷"}]},"vocab":{"pos":"n","senses":[{"en":"Oblivion is the state of being forgotten. If you slip into oblivion after selling one record, then your only hope is becoming a \"VH1 one-hit wonder.\""}]},"collocations":{"phrases":["ADJ. political","VERB + OBLIVION fade into, fall into, pass into, sink into, slide into | be rescued from, be saved from a minor masterpiece, saved from obli","PREP. in ~ He died in oblivion in a remote village."]},"media":{"uk":"media/ldoce/hwd/bre/b/oblivion0205.mp3","us":"media/ldoce/hwd/ame/f/oblivion.mp3"},"examples":[{"en":"An unexpected victory saved him from political oblivion.","cn":"一次意外的胜利使得他在政治上不再默默无闻。"},{"en":"Hundreds of homes were bombed into oblivion during the first weeks of the war.","cn":"在战争的最初几周内，数以百计的房屋被炸毁。"}],"oxford":{"phon":"əˈblɪviən","pos":"noun","senses":[{"en":"a state in which you are not aware of what is happening around you, usually because you are unconscious or asleep","cn":"无意识状态；沉睡；昏迷","ex":{"en":"He often drinks himself into oblivion.","cn":"他常常喝酒喝得不省人事。"}},{"en":"the state in which somebody/something has been forgotten and is no longer famous or important","cn":"被遗忘；被忘却；湮没","ex":{"en":"An unexpected victory saved him from political oblivion.","cn":"一次意外的胜利使得他在政治上不再默默无闻。"}},{"en":"a state in which something has been completely destroyed","cn":"被摧毁；被毁灭；被夷平","ex":{"en":"Hundreds of homes were bombed into oblivion during the first weeks of the war.","cn":"在战争的最初几周内，数以百计的房屋被炸毁。"}}]}},"overlook":{"collins":{"senses":[{"pos":"VERB 动词","cn":"俯瞰；俯视；眺望","en":"If a building or window overlooks a place, you can see the place clearly from the building or window.","ex":{"en":"Pretty and comfortable rooms overlook a flower-filled garden","cn":"漂亮舒适的房间俯视着花团锦簇的花园。"}},{"pos":"VERB 动词","cn":"忽略；忽视；未注意到","en":"If you overlook a fact or problem, you do not notice it, or do not realize how important it is.","ex":{"en":"We overlook all sorts of warning signals about our own health.","cn":"我们忽视有关自身健康的种种预警信号。"}},{"pos":"VERB 动词","cn":"宽容；宽恕","en":"If you overlook someone's faults or bad behaviour, you forgive them and take no action.","ex":{"en":"...satisfying relationships that enable them to overlook each other's faults.","cn":"能使他们互相包容对方缺点的舒心的关系"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to ignore something wrong that someone has done, especially because it is unimportant","cn":""},{"en":"to decide not to punish or criticize someone for doing something wrong, although you might do so if they do it again","cn":""},{"en":"if someone in authority turns a blind eye to illegal activity or bad behaviour, they ignore it and pretend they do not know about it","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"To overlook something is to fail to see it. When planning a party, it's best to write out a to-do list so that you don't overlook any details."}]},"collocations":{"phrases":["ADV. completely, entirely | largely | frequently, often | generally | conveniently Conveniently overlooking the fact that she wouldn't be ab","VERB + OVERLOOK cannot, cannot afford to, should not We should not overlook this possibility. | be inclined to, tend to Hospitals have tende","PHRASES be easily overlooked another fact which is all too easily overlooked | sth should not be overlooked The importance of this should no"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeoverlook.mp3","us":"media/ldoce/hwd/ame/5/overlook.mp3"},"examples":[{"en":"We could not afford to overlook such a serious offence.","cn":"对这样严重的违法行为，我们决不能视若无睹。"},{"en":"Our back yard is overlooked by several houses.","cn":"好几栋房子都看得见我家的后院。"}],"oxford":{"phon":"ˌəʊvəˈlʊk","pos":"verb","senses":[{"en":"to fail to see or notice something","cn":"忽略；未注意到","ex":{"en":"He seems to have overlooked one important fact.","cn":"他好像忽略了一个重要的事实。"}},{"en":"to see something wrong or bad but decide to ignore it","cn":"（对不良现象等）不予理会，视而不见","ex":{"en":"We could not afford to overlook such a serious offence.","cn":"对这样严重的违法行为，我们决不能视若无睹。"}},{"en":"if a building, etc. overlooks a place, you can see that place from the building","cn":"俯视；眺望","ex":{"en":"a restaurant overlooking the lake","cn":"一家濒湖餐厅"}},{"en":"to not consider somebody for a job or position, even though they might be suitable","cn":"（提拔等时）对（某人）不予考虑","ex":{"en":"She's been overlooked for promotion several times.","cn":"几次提职时都没有考虑她。"}}]}},"off-putting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（某物的特性或特定方面）令人讨厌的，惹人不快的，让人避而远之的","en":"If you describe a quality or feature of something as off-putting, you mean that it makes you dislike that thing or not want to get involved with it.","ex":{"en":"However, many customers found the smell of this product distinctly off-putting.","cn":"然而，很多顾客觉得该产品有一股异味，非常难闻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone’s behaviour or the appearance of something is off-putting, you do not like it or you think it is unattractive 〔","cn":"某人的举止或某物的外观〕令人气恼的﹐令人讨厌的"}]},"collocations":{"phrases":["VERBS be | find sth I find it very off-putting when people don't look me in the eye.","ADV. distinctly, very | a bit, a little, rather, slightly The noise was rather off-putting."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41off-putting.mp3","us":"media/ldoce/hwd/ame/1/ld41off-putting.mp3"},"examples":[{"en":"I find his manner very off-putting.","cn":"我觉得他的举止令人颇为厌恶。"},{"en":"Some women found the competitive style of the discussions off-putting.","cn":"有些女性觉得这种互不相让的讨论方式让人反感。"}],"oxford":{"phon":"ˈɒf pʊtɪŋ","pos":"adjective","senses":[{"en":"not pleasant, in a way that prevents you from liking somebody/something","cn":"令人烦恼的；令人讨厌的","ex":{"en":"I find his manner very off-putting.","cn":"我觉得他的举止令人颇为厌恶。"}}]}},"overestimate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"过高估计（数量、重要性等）","en":"If you say that someone overestimates something, you mean that they think it is greater in amount or importance than it really is.","ex":{"en":"With hindsight, he was overestimating their desire for peace.","cn":"事后看来，他高估了他们对和平的渴望。"}},{"pos":"VERB 动词","cn":"再怎么估量（都不为过）","en":"If you say that something cannot be overestimated, you are emphasizing that you think it is very important.","ex":{"en":"The importance of participating in the life of the country cannot be overestimated","cn":"参与国家生活的重要性再怎么说都不为过。"}},{"pos":"VERB 动词","cn":"过高评价（某人）","en":"If you overestimate someone, you think that they have more of a skill or quality than they really have.","ex":{"en":"I think you overestimate me, Fred.","cn":"我认为你高估我了，弗雷德。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to count something wrongly","cn":""},{"en":"to forget how many things or people you have already counted, when you are counting a lot of things over a long period","cn":""},{"en":"to wrongly guess an amount, price or number by making the total too high","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you're confident your favorite team will win the championship even though the star player is injured, you may want to reconsider: don't let your team spirit cause you to overestimate , or overvalue, the team's abilities."}]},"collocations":{"phrases":["ADV. considerably, greatly, grossly, seriously, vastly | consistently The Ministry of Finance consistently overestimated its budget deficits","VERB + OVERESTIMATE tend to | be easy to It is easy to overestimate the cost of this kind of research. | be difficult to, be hard to","PREP. by We overestimated the cost by about 2 per cent.","PHRASES sth cannot be overestimated The importance of this group cannot be overestimated."]},"media":{"uk":"media/ldoce/hwd/bre/0/overestimate_v0205.mp3","us":"media/ldoce/hwd/ame/a/l3overestimate.mp3"},"examples":[{"en":"The importance of these findings cannot be overestimated (= is very great).","cn":"这些发现的重要性是无法充分估量的。"},{"en":"They overestimated his ability when they promoted him.","cn":"他们提拔他的时候高估了他的能力。"}],"oxford":{"phon":"ˌəʊvərˈestɪmeɪt","pos":"verb","senses":[{"en":"to estimate something to be larger, better, more important, etc. than it really is","cn":"高估","ex":{"en":"They overestimated his ability when they promoted him.","cn":"他们提拔他的时候高估了他的能力。"}},{"en":"an estimate about the size, cost, etc. of something that is too high","cn":"过高的评估","ex":{"en":"I thought it would cost about £300, but luckily that turned out to be an overestimate.","cn":"我原以为它会花费大约 300 英镑，但幸运的是，事实证明这个数字被高估了。"},"pos":"noun"}]}},"overwhelm":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（情感、事件等）使不知所措，使难以承受","en":"If you are overwhelmed by a feeling or event, it affects you very strongly, and you do not know how to deal with it.","ex":{"en":"He was overwhelmed by a longing for times past","cn":"他一心渴望回到从前。"}},{"pos":"VERB 动词","cn":"征服；制服；击败","en":"If a group of people overwhelm a place or another group, they gain complete control or victory over them.","ex":{"en":"It was clear that one massive Allied offensive would overwhelm the weakened enemy.","cn":"毫无疑问，盟军一次大规模的进攻就会击溃已是强弩之末的敌军。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to completely defeat an enemy's army because your armed forces are much larger, have better equipment etc","cn":""},{"en":"to completely defeat an enemy's army because your armed forces are much larger, have better equipment etc","cn":""},{"en":"to completely defeat an enemy's army in a war and to destroy all their armed forces","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Overwhelm means “give a person too much of something.” If your friend agrees to feed your pet fish while you’re on vacation, don’t overwhelm her with requests by also asking her to do your laundry and wash the dishes."}]},"collocations":{"phrases":["ADV. completely, totally | almost | suddenly","VERB + OVERWHELM threaten to Deal with stress fast whenever it threatens to overwhelm you.","PREP. with The children pressed around him eagerly, overwhelming him with questions.","PHRASES be/feel overwhelmed (by/with sth) We were totally overwhelmed by the response to our appeal. She felt completely overwhelmed."]},"media":{"uk":"media/ldoce/hwd/bre/e/overwhelm0205.mp3","us":"media/ldoce/hwd/ame/d/overwhelm.mp3"},"examples":[{"en":"The beauty of the landscape overwhelmed me.","cn":"秀丽的风光令我深深地陶醉。"},{"en":"We were overwhelmed by requests for information.","cn":"各方的问讯使我们应接不暇。"}],"oxford":{"phon":"ˌəʊvəˈwelm","pos":"verb","senses":[{"en":"to have such a strong emotional effect on somebody that it is difficult for them to resist or know how to react","cn":"（感情或感觉）充溢，难以承受","ex":{"en":"She was overwhelmed by feelings of guilt.","cn":"她感到愧疚难当。"}},{"en":"to defeat somebody completely","cn":"彻底战胜；击败","ex":{"en":"The army was overwhelmed by the rebels.","cn":"军队被叛乱者完全击败了。"}},{"en":"to be so bad or so great that a person cannot deal with it; to give too much of a thing to a person","cn":"压垮；使应接不暇","ex":{"en":"We were overwhelmed by requests for information.","cn":"各方的问讯使我们应接不暇。"}},{"en":"to cover somebody/something completely","cn":"淹没；漫过","lab":"literary","ex":{"en":"The wave broke through the wall and overwhelmed the town.","cn":"海浪冲破了城墙，淹没了小镇。"}}]}},"oboe":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"双簧管","en":"An oboe is a musical instrument shaped like a tube which you play by blowing through a double reed in the top end."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wooden musical instrument like a narrow tube, which you play by blowing air through a reed","cn":"双簧管"}]},"media":{"uk":"media/ldoce/hwd/bre/b/oboe0205.mp3","us":"media/ldoce/hwd/ame/b/oboe.mp3","img":["media/thumb/oboe.jpg"]},"oxford":{"phon":"ˈəʊbəʊ","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group. It is like a pipe in shape and has a double reed at the top that you blow into.","cn":"双簧管"}]}},"obtainable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可得到的;可获得的;可实现的","en":"If something is obtainable, it is possible to get or achieve it.","ex":{"en":"The dried herb is obtainable from health shops.","cn":"这种干药草能在保健店里买到。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to be obtained","cn":"能得到的﹐可获得的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is obtainable , you can get your hands on it. Most information is easily obtainable or gettable on the internet these days. It's just a click away!"}]},"collocations":{"phrases":["VERBS be | become","ADV. easily, readily | commercially"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41obtainable.mp3","us":"media/ldoce/hwd/ame/1/obtainable.mp3"},"examples":[{"en":"Full details are obtainable from any post office.","cn":"详情可至任何邮局索取。"},{"en":"The form is obtainable at your local post office.","cn":"该表格可从当地邮局获取。"}],"oxford":{"phon":"əbˈteɪnəbl","pos":"adjective","senses":[{"en":"that can be obtained","cn":"可获得；可得到","ex":{"en":"Full details are obtainable from any post office.","cn":"详情可至任何邮局索取。"}}]}},"outnumber":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（在数量上）压倒，比…多","en":"If one group of people or things outnumbers another, the first group has more people or things in it than the second group.","ex":{"en":"...a town where men outnumber women four to one","cn":"男性比女性多3倍的城镇"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be more than a number or amount, especially a fixed number or limit - used especially in official reports or documents","cn":""},{"en":"if one type of person or thing outnumbers another, there are more of the first type than of the second","cn":""},{"en":"if profits, sales, income etc are up they are larger than at a time in the past","cn":""}]},"collocations":{"phrases":["ADV. considerably, easily, far, greatly, heavily, substantially, vastly Their failures vastly outnumber their successes. | almost | slightly","PREP. by The Czechs outnumbered the Slovaks by at least two to one.","PHRASES be hopelessly outnumbered The Spanish were hopelessly outnumbered in the battle."]},"media":{"uk":"media/ldoce/hwd/bre/4/outnumber0205.mp3","us":"media/ldoce/hwd/ame/6/outnumber.mp3"},"examples":[{"en":"In this profession, women outnumber men by two to one (= there are twice as many women as men).","cn":"在这个行业，女性人数是男性的两倍。"},{"en":"The demonstrators were heavily outnumbered by the police.","cn":"示威者人数远不及警察人数。"}],"oxford":{"phon":"ˌaʊtˈnʌmbə(r)","pos":"verb","senses":[{"en":"to be greater in number than somebody/something","cn":"（在数量上）压倒，比…多","ex":{"en":"The demonstrators were heavily outnumbered by the police.","cn":"示威者人数远不及警察人数。"}}]}},"overcast":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"多云的；阴沉的；阴天的","en":"If it is overcast, or if the sky or the day is overcast, the sky is completely covered with cloud and there is not much light.","ex":{"en":"For three days it was overcast","cn":"连续3天都是阴天。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with a lot of clouds","cn":""},{"en":"grey in colour, because there are dark clouds – used especially in written descriptions","cn":""},{"en":"dark and completely covered with clouds","cn":""}]},"collocations":{"phrases":["VERBS be, look | become The sky became heavily overcast. | remain, stay","ADV. heavily, very"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeovercast.mp3","us":"media/ldoce/hwd/ame/4/overcast.mp3"},"examples":[{"en":"Today it will be dull and overcast.","cn":"今天天气将阴伴多云。"},{"en":"an overcast sky/day","cn":"阴沉的天空/一天"}],"oxford":{"phon":"ˌəʊvəˈkɑːst","pos":"adjective","senses":[{"en":"covered with clouds; not bright","cn":"阴天的；多云的；阴暗的","ex":{"en":"an overcast sky/day","cn":"阴沉的天空／天气"}}]}},"owl":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猫头鹰；鸮","en":"An owl is a bird with a flat face, large eyes, and a small sharp beak. Most owls obtain their food by hunting small animals at night."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bird with large eyes that hunts at night","cn":"鸮，猫头鹰"}]},"collocations":{"phrases":["ADJ. wise | stuffed","OWL + VERB fly | hoot, screech | catch sth, prey on sth Owls prey on small rodents. | nest, roost","OWL + NOUN pellet"]},"media":{"img":["media/ldoce/img/owl.jpg"],"uk":"media/ldoce/hwd/bre/b/owl0205.mp3","us":"media/ldoce/hwd/ame/4/owl.mp3"},"examples":[{"en":"An owl hooted nearby.","cn":"一只猫头鹰在附近啼叫。"}],"oxford":{"phon":"aʊl","pos":"noun","senses":[{"en":"a bird of prey (= a bird that kills other creatures for food) with large round eyes, that hunts at night. Owls are traditionally thought to be wise.","cn":"猫头鹰，鸮（传统上认为是智慧的象征）","ex":{"en":"An owl hooted nearby.","cn":"一只猫头鹰在附近啼叫。"}}]}},"outcast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被排斥者；被抛弃者","en":"An outcast is someone who is not accepted by a group of people or by society.","ex":{"en":"He had always been an outcast, unwanted and alone","cn":"他一直都被视为异类，无人理睬，形单影只。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is not accepted by the people they live among, or who has been forced out of their home","cn":"被〔家庭﹑社会等〕遗弃[排斥]的人﹔被逐出者"}]},"vocab":{"pos":"n adj","senses":[{"en":"An outcast is someone who isn't wanted. To remember what outcast means, flip it around: outcasts have been cast out from somewhere."}]},"collocations":{"phrases":["ADJ. social He was treated as a social outcast.","VERB + OUTCAST make sb Her criminal past made her an outcast. | treat sb as/like","PREP. ~ from an outcast from society"]},"media":{"uk":"media/ldoce/hwd/bre/c/outcast0205.mp3","us":"media/ldoce/hwd/ame/1/outcast.mp3"},"examples":[{"en":"People with the disease were often treated as social outcasts.","cn":"患有这种疾病的人常被社会摈弃。"},{"en":"Smokers often feel as though they are being treated as social outcasts.","cn":"吸烟者常常觉得自己遭到社会排斥。"}],"oxford":{"phon":"ˈaʊtkɑːst","pos":"adjective","senses":[{"en":"not accepted by society or by a particular group","cn":"被抛弃的，被逐出的","ex":{"en":"He had been made to feel socially outcast.","cn":"他被迫感到自己被社会排斥。"}},{"en":"a person who is not accepted by society or by a particular group","cn":"边缘人，被抛弃者（被社会或特定群体排斥的人）","ex":{"en":"People with the disease were often treated as social outcasts.","cn":"患有这种疾病的人常被社会摈弃。"},"pos":"noun"}]}},"outlay":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（必要的）费用，开支","en":"Outlay is the amount of money that you have to spend in order to buy something or start a project.","ex":{"en":"Apart from the capital outlay of buying the machine, dishwashers can actually save you money","cn":"除了购置所用开支，洗碗机实际上能为你省钱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of money that is spent, especially by a government or other organization","cn":""},{"en":"the amount of money that a government, organization, or person spends during a particular period of time – used especially in official documents or reports","cn":""},{"en":"the money that a person or organization has to spend on heating, rent, wages etc","cn":""}]},"collocations":{"phrases":["ADJ. considerable, huge, large, massive | modest, small | initial The revenue from the farm could repay the initial outlay within three year","VERB + OUTLAY make | require The project would require little financial outlay. | recoup, recover | repay","PREP. ~ on The railway had made a considerable capital outlay on new rolling stock."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeoutlay.mp3","us":"media/ldoce/hwd/ame/d/outlay.mp3"},"examples":[{"en":"The business quickly repaid the initial outlay on advertising.","cn":"这家公司很快偿付了初期的广告费。"},{"en":"a massive financial/capital outlay","cn":"大量的财政/资本开支"}],"oxford":{"phon":"ˈaʊtleɪ","pos":"noun","senses":[{"en":"the money that you have to spend in order to start a new project","cn":"（启动新项目的）开支，费用","ex":{"en":"The business quickly repaid the initial outlay on advertising.","cn":"这家公司很快偿付了初期的广告费。"}}]}},"obligatory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（按照规定或法律）必须履行的，强制性的","en":"If something is obligatory, you must do it because of a rule or a law.","ex":{"en":"Most women will be offered an ultrasound scan during pregnancy, although it's not obligatory","cn":"大多数处于妊娠期的妇女将被建议接受超声波检查，不过这不是强制性的。"}},{"pos":"ADJ 形容词","cn":"习惯性的;礼节性的;随大溜的","en":"If you describe something as obligatory, you mean that it is done from habit or custom and not because the person involved has thought carefully about it or really means it.","ex":{"en":"His lips curved up in the obligatory smile, acknowledging the compliment","cn":"他嘴边礼节性地挤出一个微笑，以示对称赞致谢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to describe something that you need to have or do","cn":""},{"en":"very important and necessary, especially in order to be healthy, successful etc","cn":""},{"en":"extremely important and necessary, especially in order to avoid serious problems","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Obligatory describes something you do because you have to, not because you want to. When you buy a car, you have to fill out the obligatory forms. In many homes, saying please and thank you is obligatory ."}]},"collocations":{"phrases":["VERBS be | become | remain | make sth The college authorities have now made these classes obligatory.","ADV. almost, practically | legally","PREP. for It is obligatory for vets to be registered."]},"media":{"uk":"media/ldoce/hwd/bre/0/obligatory0205.mp3","us":"media/ldoce/hwd/ame/c/obligatory.mp3"},"examples":[{"en":"In the mid 60s he took the almost obligatory trip to India. * 60","cn":"年代中期，他也赶时髦到印度一游。"},{"en":"It is obligatory for all employees to wear protective clothing.","cn":"所有员工必须穿防护服装。"}],"oxford":{"phon":"əˈblɪɡətri","pos":"adjective","senses":[{"en":"that you must do because of the law, rules, etc.","cn":"（按法律、规定等）必须的，强制的","lab":"formal","ex":{"en":"The college authorities have now made these classes obligatory.","cn":"学院管理部门现已将这些课程列为必修课。"}},{"en":"that you do because you always do it, or other people in the same situation always do it","cn":"习惯性的；随大溜的；赶时髦的","lab":"often humorous","ex":{"en":"In the mid-60s he took the almost obligatory trip to India.","cn":"60 年代中期，他也赶时髦到印度一游。"}}]}},"outbreak":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（暴力活动、疾病等的）爆发，突然发生","en":"If there is an outbreak of something unpleasant, such as violence or a disease, it suddenly starts to happen.","ex":{"en":"The four-day festival ended a day early after an outbreak of violence involving hundreds of youths.","cn":"一场有数百名年轻人卷入的暴力活动发生后，为期4天的节庆活动被迫提前一天结束。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a lot of people suddenly start to get an illness at the same time","cn":""},{"en":"when a lot of people in an area or country get a disease, and it spreads very quickly","cn":""},{"en":"to start happening - use this about unpleasant things like fires, wars, or diseases","cn":""}]},"collocations":{"phrases":["ADJ. large, major, serious | fresh, further, new | occasional, periodic, sporadic | recurrent, repeated | sudden | cholera, salmonella, etc.","VERB + OUTBREAK lead to the events that led to the outbreak of World War I","OUTBREAK + VERB occur","PREP. ~ of A new outbreak of smallpox occurred in 1928.","PHRASES an outbreak of disease, an outbreak of rain, an outbreak of war/fighting/hostilities/violence"]},"media":{"uk":"media/ldoce/hwd/bre/0/outbreak0205.mp3","us":"media/ldoce/hwd/ame/e/outbreak.mp3"},"examples":[{"en":"Outbreaks of rain are expected in the afternoon.","cn":"下午将有暴雨。"},{"en":"the outbreak of war","cn":"战争的爆发"}],"oxford":{"phon":"ˈaʊtbreɪk","pos":"noun","senses":[{"en":"the sudden start of something unpleasant, especially violence or a disease","cn":"（暴力、疾病等坏事的）爆发，突然发生","lab":"British English","ex":{"en":"the outbreak of war","cn":"战争的爆发"}}]}},"overhear":{"collins":{"senses":[{"pos":"VERB 动词","cn":"偶然听到；无意中听到；偷听到","en":"If you overhear someone, you hear what they are saying when they are not talking to you and they do not know that you are listening.","ex":{"en":"I overheard two doctors discussing my case.","cn":"我无意中听到两位医生讨论我的病情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to know that a sound is being made, using your ears","cn":""},{"en":"to pay attention to something, using your ears","cn":""},{"en":"to hear something with difficulty","cn":""}]},"collocations":{"phrases":["ADV. accidentally","PHRASES couldn't help overhearing sth Excuse me for interrupting, but I couldn't help overhearing what you were saying."]},"media":{"uk":"media/ldoce/hwd/bre/5/overhear0205.mp3","us":"media/ldoce/hwd/ame/7/overhear.mp3"},"examples":[{"en":"I overheard a conversation between two boys on the bus.","cn":"我在公共汽车上无意中听到两个男孩的对话。"},{"en":"We talked quietly so as not to be overheard.","cn":"我们低声交谈，以免别人听到。"}],"oxford":{"phon":"ˌəʊvəˈhɪə(r)","pos":"verb","senses":[{"en":"to hear, especially by accident, a conversation in which you are not involved","cn":"偶然听到；无意中听到","ex":{"en":"I overheard a conversation between two boys on the bus.","cn":"我在公共汽车上无意中听到两个男孩的对话。"}}]}},"oblige":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(形势、规定或法律)强迫，迫使","en":"If you are obliged to do something, a situation, rule, or law makes it necessary for you to do that thing.","ex":{"en":"The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot","cn":"暴风雨愈发猛烈，我最终不得不弃车步行。"}},{"pos":"VERB 动词","cn":"施恩惠于；帮…的忙","en":"To oblige someone means to be helpful to them by doing what they have asked you to do.","ex":{"en":"If you ever need help with the babysitting, I'd be glad to oblige","cn":"如果你什么时候需要找人照看孩子，我很乐意帮忙。"}},{"pos":"CONVENTION 惯用语","cn":"感激不尽;不胜感激","en":"People sometimes use obliged in expressions such as 'much obliged' or 'I am obliged to you' when they want to indicate that they are very grateful for something.","ex":{"en":"Much obliged for your assistance","cn":"对您的帮助我不胜感激。"}},{"pos":"CONVENTION 惯用语","cn":"如蒙…将不胜感激;劳驾…好吗","en":"If you tell someone that you would be obliged or should be obliged if they would do something, you are telling them in a polite but firm way that you want them to do it.","ex":{"en":"I would be obliged if you could read it to us.","cn":"您若能把它读给大家听，我将不胜感激。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have to do something, because of a legal or professional rule","cn":""},{"en":"to have to do something - used especially in written notices and official documents","cn":""},{"en":"to have to do something because it is the duty of someone in your position to do it, or because you have officially agreed to do it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To oblige is to do something you have to, because you're bound by either good manners or the law."}]},"collocations":{"phrases":["ADV. duly The fans were looking for another goal and Owen duly obliged (= scored) . | kindly","VERB + OBLIGE be delighted to, be glad to, be (only too) happy to, be pleased to, be willing to The staff are always happy to oblige. | hast","PREP. by Will you oblige by filling in this form? | with Would you be willing to oblige us with some information?"]},"media":{"uk":"media/ldoce/hwd/bre/c/oblige0205.mp3","us":"media/ldoce/hwd/ame/1/oblige.mp3"},"examples":[{"en":"Call me if you need any help — I'd be happy to oblige.","cn":"若有需要，尽管给我打电话。我很乐意帮忙。"},{"en":"He suffered a serious injury that obliged him to give up work.","cn":"他受伤严重，不得已只好辞掉工作。"}],"oxford":{"phon":"əˈblaɪdʒ","pos":"verb","senses":[{"en":"to force somebody to do something, by law, because it is a duty, etc.","cn":"（以法律、义务等）强迫，迫使","g":"[transitive, usually passive]","ex":{"en":"Parents are obliged by law to send their children to school.","cn":"法律规定父母必须送子女入学。"}},{"en":"to help somebody by doing what they ask or what you know they want","cn":"（根据要求或需要）帮忙，效劳","g":"[intransitive, transitive]","ex":{"en":"Call me if you need any help—I'd be happy to oblige.","cn":"若有需要，尽管给我打电话。我很乐意帮忙。"}}]}},"orgasm":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"性高潮","en":"An orgasm is the moment of greatest pleasure and excitement in sexual activity."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the greatest point of sexual pleasure","cn":"性高潮"}]},"vocab":{"pos":"n","senses":[{"en":"An orgasm is a moment of intense pleasure that is the culmination of sex. People really enjoy orgasms ."}]},"collocations":{"phrases":["ADJ. female, male | multiple | simultaneous","VERB + ORGASM achieve, have, reach | fake, simulate"]},"media":{"uk":"media/ldoce/hwd/bre/f/orgasm0205.mp3","us":"media/ldoce/hwd/ame/3/orgasm.mp3"},"examples":[{"en":"to achieve/reach orgasm","cn":"达到性高潮"},{"en":"to have an orgasm","cn":"出现性高潮"}],"oxford":{"phon":"ˈɔːɡæzəm","pos":"noun","senses":[{"en":"the moment during sexual activity when feelings of sexual pleasure are at their strongest","cn":"性高潮","ex":{"en":"to achieve/reach orgasm","cn":"达到性高潮"}}]}},"ore":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"矿；矿石；矿砂","en":"Ore is rock or earth from which metal can be obtained.","ex":{"en":"...a huge iron ore mine.","cn":"巨大的铁矿山"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"rock or earth from which metal can be obtained","cn":"矿石﹐矿砂"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Ore is a rock that contains minerals like iron, gold, or lead. The seven dwarfs in the movie \"Snow White and the Seven Dwarfs\" worked mining ore ."}]},"collocations":{"phrases":["ADJ. rich | metal/metallic, mineral | copper, iron, uranium, etc.","QUANT. lode, vein | lump","VERB + ORE extract, mine | dress, extract sth from, refine, smelt smelting the ore with charcoal","ORE + NOUN deposits"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeore.mp3","us":"media/ldoce/hwd/ame/c/oar.mp3"},"examples":[{"en":"iron ore","cn":"铁矿石"},{"en":"veins of rich ore","cn":"富矿脉"}],"oxford":{"phon":"ɔː(r)","pos":"noun","senses":[{"en":"rock, earth, etc. from which metal can be obtained","cn":"矿石；矿砂；矿","ex":{"en":"iron ore","cn":"铁矿石"}}]}},"odds":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"机会；可能性；几率","en":"You refer to how likely something is to happen as the odds that it will happen.","ex":{"en":"What are the odds of finding a parking space right outside the door?","cn":"就在门口找到停车位的可能性有多大？"}},{"pos":"N-PLURAL 复数名词","cn":"（赌博中的）赔率","en":"In betting, odds are expressions with numbers such as '10 to 1' and '7 to 2' that show how likely something is thought to be, for example how likely a particular horse is to lose or win a race.","ex":{"en":"Gavin Jones, who put £25 on Eugene, at odds of 50 to 1, has won £1,250.","cn":"加文·琼斯以50比1的赔率赌尤金胜，他下注25英镑，赢了1,250英镑。"}},{"pos":"PHRASE 短语","cn":"（与…）不和；（与…）有矛盾；（与…）意见不一致","en":"If someone is at odds with someone else, or if two people are at odds, they are disagreeing or quarrelling with each other.","ex":{"en":"He was at odds with his Prime Minister","cn":"他与首相不和。"}},{"pos":"PHRASE 短语","cn":"（成功）可能性小，希望渺茫","en":"If you say that the odds are against something or someone, you mean that they are unlikely to succeed.","ex":{"en":"He reckoned the odds are against the scheme going ahead","cn":"他认为目前实施这项计划的希望渺茫。"}},{"pos":"PHRASE 短语","cn":"尽管面临重重困难;虽然可能性极小","en":"If something happens against all odds, it happens or succeeds although it seemed impossible or very unlikely.","ex":{"en":"Some women do manage to achieve business success against all odds","cn":"尽管困难重重，一些女性还是在商场上获得了成功。"}},{"pos":"PHRASE 短语","cn":"（某人）很可能取得成功","en":"If you say that the odds are in someone's favour, you mean that they are likely to succeed in what they are doing.","ex":{"en":"His troops will only engage in a ground battle when all the odds are in their favour.","cn":"他的部队只有在胜券在握的时候才打地面战。"}},{"pos":"PHR-ERG","cn":"使更有希望/使不大可能；机会增加/机会减少","en":"To shorten the odds on something happening means to make it more likely to happen. To lengthen the odds means to make it less likely to happen. You can also say that the odds shorten or lengthen .","ex":{"en":"His reception there shortened the odds that he might be the next Tory leader.","cn":"他在那里得到的反应使他更有望成为英国保守党下一任领导人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to have something that makes you more likely to succeed than other people","cn":""},{"en":"if someone is at an advantage , they have experience or qualities which make them more likely to succeed in doing something or more likely to do something well","cn":""},{"en":"used to say that someone has a big advantage in a competition, election etc so that they are very likely to win","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The odds are the chances that something will happen. If you flip a coin, the odds are 50-50 you'll get heads."}]},"collocations":{"phrases":["ADJ. considerable, great, high, impossible, insuperable, overwhelming, terrible She struggled against terrible odds to overcome her illness.","VERB + ODDS offer, quote | lay I'll lay odds we never see him again. | reduce, shorten | beat, defy, overcome She defied the odds to beat th","ODDS + VERB shorten | lengthen","PREP. against the ~ The film is a heart-warming tale of triumph against the odds. | ~ against The odds against their survival have lengthene","PHRASES against all (the) odds Against all the odds, we managed to get through to the final."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeodds.mp3","us":"media/ldoce/hwd/ame/3/odds.mp3"},"examples":[{"en":"These findings are at odds with what is going on in the rest of the country.","cn":"这些研究结果与国内其他地区的实际情况并不相符。"},{"en":"Against all (the) odds, he made a full recovery.","cn":"在凶多吉少的情形下，他终于完全康复了。"}],"oxford":{"phon":"ɒdz","pos":"noun","senses":[{"en":"the degree to which something is likely to happen","cn":"（事物发生的）可能性，概率，机会","ex":{"en":"The odds are very much in our favour (= we are likely to succeed).","cn":"我方胜算的概率极大。"}},{"en":"something that makes it seem impossible to do or achieve something","cn":"不利条件；掣肘的事情；逆境","ex":{"en":"They secured a victory in the face of overwhelming odds.","cn":"尽管情况非常不利，他们仍得到了胜利。"}},{"en":"the connection between two numbers that shows how much money somebody will receive if they win a bet","cn":"投注赔率","lab":"figurative","ex":{"en":"odds of ten to one (= ten times the amount of money that has been bet by somebody will be paid to them if they win)","cn":"十比一的赔率"}}]}},"ornamental":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（摆在某处）作装饰的","en":"Ornamental things have no practical function but are put in a place because they look attractive.","ex":{"en":"...ornamental trees.","cn":"观赏树"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"装饰性的；美观的","en":"Something that is ornamental is attractive and decorative.","ex":{"en":"...ornamental plaster mouldings.","cn":"装饰性石膏线脚"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"things that you use to decorate a place, object, piece of furniture etc especially for a special occasion","cn":""},{"en":"designs and patterns used to decorate buildings, clothes, or furniture","cn":""},{"en":"an object, often something fairly small, that is used in a room or house to make it look more attractive","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. highly, very a plant which is highly ornamental in flower | purely The turrets are purely ornamental."]},"media":{"img":["media/ldoce/img/ornamental.jpg"],"uk":"media/ldoce/hwd/bre/9/ornamental0205.mp3","us":"media/ldoce/hwd/ame/e/ornamental.mp3"},"examples":[{"en":"The chimney pots are purely ornamental.","cn":"这些烟囱管帽纯属装饰。"},{"en":"an ornamental fountain","cn":"装饰性喷泉"}],"oxford":{"phon":"ˌɔːnəˈmentl","pos":"adjective","senses":[{"en":"used as decoration rather than for a practical purpose","cn":"装饰性的；点缀的","ex":{"en":"an ornamental fountain","cn":"装饰性喷泉"}}]}},"offside":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（足球、曲棍球等比赛中）越位的","en":"In games such as football or hockey, when an attacking player is offside, they have broken the rules by being nearer to the goal than a defending player when the ball is passed to them.","ex":{"en":"The goal was disallowed because Wark was offside.","cn":"由于沃克越位在先，这个进球被判无效。"}},{"pos":"ADJ 形容词","cn":"（美式橄榄球中）越位的","en":"In American football, a player is offside if they cross the line of scrimmage before a play begins."},{"pos":"N-SING 单数名词","cn":"（车辆在靠左交通中的）右侧，外侧，远离路边的一侧","en":"The offside of a vehicle is the side that is farthest from the edge of the road when the vehicle is being driven normally.","ex":{"en":"The driver of the car lowered his offside front window.","cn":"司机摇下前排右侧的玻璃窗。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in a position, usually ahead of the ball, where you are not allowed to play the ball in sports such as soccer and hockey 〔","cn":"足球、曲棍球等运动中〕越位(的)"},{"en":"the side of a car that is nearest to the middle of the road when you are driving it 〔","cn":"汽车的〕右侧﹐右边﹔外侧"}]},"collocations":{"phrases":["VERBS be, look | catch sb, rule sb an attempt to catch an opponent offside He was ruled offside by the referee."]},"media":{"uk":"media/ldoce/hwd/bre/e/offside_adj0205.mp3","us":"media/ldoce/hwd/ame/9/l3offside.mp3"},"examples":[{"en":"He was offside when he scored.","cn":"他将球攻进门时已越位了。"},{"en":"The goal was disallowed for offside.","cn":"因为越位，进球无效。"}],"oxford":{"phon":"ˌɒfˈsaɪd","pos":"adjective","senses":[{"en":"in some sports, for example football (soccer) and ice hockey, a player is offside if they are in a position, usually ahead of the ball, that is not allowed","cn":"（足球、曲棍球等体育运动中）越位的","lab":"US English also","ex":{"en":"He was offside when he scored.","cn":"他进球时已越位了。"}},{"en":"on the side of a vehicle that is furthest from the edge of the road","cn":"（车辆）外侧的，右侧的","lab":"British English","ex":{"en":"the offside mirror","cn":"右侧镜"}},{"en":"the fact of being offside in a game such as football (soccer) or ice hockey","cn":"（足球、冰球等体育运动中的）越位","lab":"US English also","ex":{"en":"The goal was disallowed for offside.","cn":"因为越位，进球无效。"},"pos":"noun"},{"en":"the side of a vehicle that is furthest from the edge of the road","cn":"（车辆的）外侧，远侧，右侧","lab":"British English","ex":{"en":"The offside was damaged.","cn":"车辆外侧受损。"},"pos":"noun"},{"en":"in a position, usually ahead of the ball, that is not allowed","cn":"越位","ex":{"en":"He was ruled offside by the referee.","cn":"他被裁判判为越位。"},"pos":"adverb"}]}},"outing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指集体）远足，短途旅行","en":"An outing is a short enjoyable trip, usually with a group of people, away from your home, school, or place of work.","ex":{"en":"One evening, she made a rare outing to the local discotheque.","cn":"她有天晚上破天荒地去了一次当地的迪斯科舞厅。"}},{"pos":"N-COUNT 可数名词","cn":"体育比赛","en":"In sport, an outing is an occasion when a player competes in a particular contest or competition.","ex":{"en":"Playing against Zebre in England's first outing, he suffered a whiplash injury to his neck.","cn":"在英格兰队首次对阵热布里的比赛中，他颈部受了挥鞭伤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to visit a beach, an area of countryside, a town etc for pleasure and come back home on the same day","cn":""},{"en":"a visit to a beach, an area of countryside, a town etc when you go there and come back the same day","cn":""},{"en":"a journey that someone makes each day to work, especially when they live a fairly long way away from their work","cn":""}]},"collocations":{"phrases":["ADJ. little | special | day's, summer, weekend | annual | family, school, social","VERB + OUTING be/go on","PREP. ~ from The children were on a day's outing from school. | ~ to a family outing to the seaside"]},"media":{"uk":"media/ldoce/hwd/bre/5/outing0205.mp3","us":"media/ldoce/hwd/ame/f/outing.mp3"},"examples":[{"en":"We went on an outing to London.","cn":"我们游览了伦敦。"},{"en":"a family outing","cn":"全家远足"}],"oxford":{"phon":"ˈaʊtɪŋ","pos":"noun","senses":[{"en":"a trip that you go on for pleasure or education, usually with a group of people and lasting no more than one day","cn":"（集体）出外游玩（或学习等）；远足","g":"[countable]","lab":"British English","ex":{"en":"a family outing","cn":"全家远足"}},{"en":"an occasion when somebody takes part in a competition","cn":"参赛；比赛","g":"[countable]","lab":"sport, informal，，"},{"en":"the practice of naming people as gay or lesbian in public, when they would prefer to keep this information private","cn":"（违背同性恋者本人意愿）对（其）身份的公开挑明","g":"[uncountable, countable]"}]},"base":"out"},"outburst":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指愤怒等感情的）爆发，迸发","en":"An outburst of an emotion, especially anger, is a sudden strong expression of that emotion.","ex":{"en":"...an outburst of anger.","cn":"勃然大怒"}},{"pos":"N-COUNT 可数名词","cn":"（暴力活动的）突发","en":"An outburst of violent activity is a sudden period of this activity.","ex":{"en":"Five people were reported killed today in a fresh outburst of violence.","cn":"据报道在今天最新发生的暴乱中有5人丧生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone, especially a child, has or throws a tantrum , they shout angrily and cry, especially because they cannot have what they want","cn":""},{"en":"to start a loud angry argument with someone, especially in a public place and in a way that is embarrassing","cn":""},{"en":"a sudden expression of very strong angry feelings, especially because you cannot control your anger any longer","cn":""}]},"collocations":{"phrases":["ADJ. sudden | spontaneous | occasional her occasional outbursts of temper | angry, furious, violent | emotional, hysterical, passionate","PREP. ~ against A player was cautioned for his angry outburst against the referee. | ~ of an outburst of anger/laughter/temper/violence"]},"media":{"uk":"media/ldoce/hwd/bre/d/outburst0205.mp3","us":"media/ldoce/hwd/ame/f/outburst.mp3"},"examples":[{"en":"She was alarmed by his violent outburst.","cn":"他暴跳如雷，令她惊恐万状。"},{"en":"an outburst of racism","cn":"种族主义的突然高涨"}],"oxford":{"phon":"ˈaʊtbɜːst","pos":"noun","senses":[{"en":"a sudden strong expression of an emotion","cn":"（感情的）爆发，迸发","ex":{"en":"an outburst of anger","cn":"突然大怒"}},{"en":"a sudden increase in a particular activity or attitude","cn":"（活动的）激增；（态度的）激化","ex":{"en":"an outburst of racism","cn":"种族主义的突然高涨"}}]}},"obscure":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无名的；鲜为人知的；默默无闻的","en":"If something or someone is obscure, they are unknown, or are known by only a few people.","ex":{"en":"The origin of the custom is obscure","cn":"这一习俗的起源鲜为人知。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（通常指因内容繁琐）晦涩的，费解的，难懂的","en":"Something that is obscure is difficult to understand or deal with, usually because it involves so many parts or details.","ex":{"en":"The contracts are written in obscure language","cn":"这些合同的语言晦涩难懂。"}},{"pos":"VERB 动词","cn":"遮掩；遮蔽；使模糊不清","en":"If one thing obscures another, it prevents it from being seen or heard properly.","ex":{"en":"Trees obscured his vision; he couldn't see much of the Square's southern half","cn":"树木遮挡了他的视线，南半广场的一大部分他都无法看清。"}},{"pos":"VERB 动词","cn":"使晦涩；使费解；使难懂","en":"To obscure something means to make it difficult to understand.","ex":{"en":"...the jargon that frequently obscures educational writing","cn":"经常让普教著作变得艰深晦涩的术语"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all famous","cn":""},{"en":"someone or something that is obscure is known about only by a few people, because they belong to a group, place, or subject that not many people know about or are interested in","cn":""},{"en":"someone who is very ordinary and not at all famous or important","cn":""}]},"vocab":{"pos":"1 adj v 2 adj 3 v","senses":[{"en":"If something is obscure , it's vague and hard to see. Be careful if you're driving in heavy rain — the painted lines can be obscure ."}]},"collocations":{"phrases":["ADV. completely, totally | almost | largely | half, partially, partly, slightly, somewhat | deliberately All trace of his working-class back","VERB + OBSCURE serve to, tend to The emphasis on social integration often served to obscure the real differences within the community. | all","PREP. behind/beneath The moo n was obscured behind a wall o f cloud .","PHRASES obscure the fact that &hellip; These figures obscure the fact tha t a lot of older people live in grea t poverty. | obscure sth from"]},"media":{"uk":"media/ldoce/hwd/bre/2/obscure_v0205.mp3","us":"media/ldoce/hwd/ame/7/obscure1.mp3"},"examples":[{"en":"He was born around 1650 but his origins remain obscure.","cn":"他生于 1650 年前后，但身世不详。"},{"en":"We mustn't let these minor details obscure the main issue.","cn":"我们不能让枝节问题掩盖主要问题。"}],"oxford":{"phon":"əbˈskjʊə(r)","pos":"adjective","senses":[{"en":"not well known","cn":"无名的；鲜为人知的","ex":{"en":"an obscure German poet","cn":"一个名不见经传的德国诗人"}},{"en":"difficult to understand","cn":"费解的；难以理解的","ex":{"en":"I found her lecture very obscure.","cn":"我觉得她的讲座非常费解。"}},{"en":"to make it difficult to see, hear or understand something","cn":"使模糊；使隐晦；使费解","ex":{"en":"The view was obscured by fog.","cn":"雾中景色朦胧。"},"pos":"verb"}]}},"oath":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指对个人或国家的）誓言，誓约","en":"An oath is a formal promise, especially a promise to be loyal to a person or country.","ex":{"en":"He took an oath of loyalty to the government","cn":"他宣誓效忠政府。"}},{"pos":"N-SING 单数名词","cn":"（在法庭上承诺说实话的）誓言","en":"In a court of law, when someone takes the oath, they make a formal promise to tell the truth. You can say that someone is on oath or under oath when they have made this promise.","ex":{"en":"His girlfriend had gone into the witness box and taken the oath","cn":"他的女朋友进入证人席并立了誓。"}},{"pos":"N-COUNT 可数名词","cn":"（表示愤怒、震惊的）咒骂，诅咒","en":"An oath is an offensive or emphatic word or expression which you use when you are angry or shocked.","ex":{"en":"Wellor let out a foul oath and hurled himself upon him.","cn":"韦勒骂了一句粗话，然后向他猛扑过去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that you will definitely do or provide something, which may not be reliable","cn":""},{"en":"a public or official promise to do a particular thing in the future","cn":""},{"en":"a very serious promise to do something or not to do something that you choose to make","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An oath is a promise. If you want to borrow your brother's car, you may have to swear a solemn oath that you will bring it back unharmed."}]},"collocations":{"phrases":["ADJ. sacred, solemn | Hippocratic a doctor's Hippocratic oath","VERB + OATH swear, take He took an oath of allegiance to his adopted country. | break, violate","PREP. ~ of an oath of allegiance/loyalty 2 in a court of law","VERB + OATH administer Only a judge is allowed to administer the oath.","PREP. on ~ He swore on oath that he had never seen me before. | under ~ Witnesses must testify under oath. 3 swear word","ADJ. obscene","QUANT. stream, string He muttered a stream of oaths.","VERB + OATH mutter, utter"]},"media":{"uk":"media/ldoce/hwd/bre/b/oath0205.mp3","us":"media/ldoce/hwd/ame/8/oath.mp3"},"examples":[{"en":"She heard the sound of breaking glass, followed by a muttered oath.","cn":"她听到打碎玻璃的响声，接着是低声的咒骂。"},{"en":"Before giving evidence, witnesses in court have to take the oath (= promise to tell the truth).","cn":"作证之前，证人必须当庭宣誓据实作证。"}],"oxford":{"phon":"əʊθ","pos":"noun","senses":[{"en":"a formal promise to do something or a formal statement that something is true","cn":"宣誓；誓言","lab":"especially North American English","ex":{"en":"to take/swear an oath of allegiance","cn":"宣誓效忠"}},{"en":"an offensive word or phrase used to express anger, surprise, etc.; a swear word","cn":"（表示愤怒、惊异等的）咒骂，诅咒的话","lab":"old-fashioned","ex":{"en":"She heard the sound of breaking glass, followed by a muttered oath.","cn":"她听到打碎玻璃的响声，接着是低声的咒骂。"}}]}},"optional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可选择的；非强制的","en":"If something is optional, you can choose whether or not you do it or have it.","ex":{"en":"A holiday isn't an optional extra. In this stressful, frantic world it's a must","cn":"休假并非可有可无。在这个紧张而忙碌的世界，它是必不可少的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is optional, you can choose whether to do it or not","cn":""},{"en":"done because you want to do it and not because you have to – used especially about things that you do because you think they will help other people or be useful","cn":""},{"en":"if you do not have to do something, you can do it if you want, but you are not forced to do it, either by a rule or by another person, or by the situation you are in","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you can choose whether or not to do something, it is optional . Extra credit is always optional , death and taxes are not."}]},"collocations":{"phrases":["VERBS be","ADV. entirely, purely The extra language classes are entirely optional."]},"media":{"uk":"media/ldoce/hwd/bre/2/optional0205.mp3","us":"media/ldoce/hwd/ame/1/optional.mp3"},"examples":[{"en":"This model comes with a number of optional extras (= things you can choose to have but which you will have to pay extra for).","cn":"这一型号有一系列可供选择的附件，价格另计。"},{"en":"Certain courses are compulsory; others are optional.","cn":"有些课程是必修的，其他是选修的。"}],"oxford":{"phon":"ˈɒpʃənl","pos":"adjective","senses":[{"en":"that you can choose to do or have if you want to","cn":"可选择的；选修的","ex":{"en":"Certain courses are compulsory; others are optional.","cn":"有些课程是必修的，另一些是选修的。"}}]}}});
